const jiraDialogSecrets = await page.evaluate(async () => {
  const fill = () => {
    el("jira-site-url").value = "https://acme.atlassian.net";
    el("jira-identity").value = "hana@acme.com";
    el("jira-token").value = "top-secret";
    el("jira-token").dispatchEvent(new Event("input", { bubbles: true }));
  };
  openJiraConnectDialog();
  fill();
  el("jira-connect-cancel").click();
  const afterCancel = {
    hidden: jiraConnectScrim.hidden,
    identity: el("jira-identity").value,
    token: el("jira-token").value,
  };

  window.__ANSWER__.jira_connect = () => ({
    connected: true,
    active_site_id: "s1",
    selected_site_id: "s1",
    credential_error: null,
    credential_protection: "native",
    sites: [{
      id: "s1",
      site_url: "https://acme.atlassian.net",
      email: "hana@acme.com",
      display_name: "Hana",
      account_id: "hana",
      auth_type: "cloud",
      credential: "available",
    }],
  });
  openJiraConnectDialog();
  fill();
  el("jira-connect-submit").click();
  await new Promise((done) => setTimeout(done, 80));
  const afterSuccess = {
    hidden: jiraConnectScrim.hidden,
    identity: el("jira-identity").value,
    token: el("jira-token").value,
    error: el("jira-connect-error").textContent,
  };

  window.__ANSWER__.jira_connect = () => {
    throw new Error("credential refused");
  };
  openJiraConnectDialog();
  fill();
  el("jira-connect-submit").click();
  await new Promise((done) => setTimeout(done, 80));
  const afterFailure = {
    hidden: jiraConnectScrim.hidden,
    token: el("jira-token").value,
    errorShown: !el("jira-connect-error").hidden,
  };
  closeJiraConnectDialog();
  delete window.__ANSWER__.jira_connect;
  return { afterCancel, afterSuccess, afterFailure };
});
ok(
  "cancelling Jira connection clears the hidden identity and token",
  jiraDialogSecrets.afterCancel.hidden
    && jiraDialogSecrets.afterCancel.identity === ""
    && jiraDialogSecrets.afterCancel.token === "",
  JSON.stringify(jiraDialogSecrets),
);
ok(
  "a successful Jira connection clears the hidden token and form state",
  jiraDialogSecrets.afterSuccess.hidden
    && jiraDialogSecrets.afterSuccess.identity === ""
    && jiraDialogSecrets.afterSuccess.token === ""
    && jiraDialogSecrets.afterSuccess.error === "",
  JSON.stringify(jiraDialogSecrets),
);
ok(
  "a failed Jira connection keeps the token visible to the form for retry",
  !jiraDialogSecrets.afterFailure.hidden
    && jiraDialogSecrets.afterFailure.token === "top-secret"
    && jiraDialogSecrets.afterFailure.errorShown,
  JSON.stringify(jiraDialogSecrets),
);

/* 연결 다이얼로그의 말(1-g49, Orca jira-connect-dialog 실측): 고른 종류가
 * 설명문·라벨·플레이스홀더·도움말을 고르고, 확인하는 동안은 다이얼로그
 * 전체가 숨을 죽여 어느 손으로도 닫히지 않으며, 오류는 다음 손질이 지운다. */
const jiraDialogSpeaks = await page.evaluate(async () => {
  const seen = {};
  openJiraConnectDialog();
  seen.cloudFace =
    el("jira-connect-copy").textContent ===
      t("task.jira.copyCloud", "Jira Cloud 사이트 URL과 Atlassian 이메일, API 토큰으로 이슈를 봅니다.") &&
    el("jira-site-url-label").textContent ===
      t("task.jira.siteUrlCloud", "Jira Cloud 사이트 URL") &&
    el("jira-identity").placeholder === "you@example.com" &&
    el("jira-token").placeholder === t("task.jira.tokenPlaceholder", "Atlassian API 토큰") &&
    !el("jira-help-cloud").hidden &&
    el("jira-help-server").hidden &&
    el("jira-help-basic").hidden;
  el("jira-instance-type").querySelector('[data-value="server"]').click();
  seen.serverFace =
    el("jira-connect-copy").textContent ===
      t("task.jira.copyServer", "자체 호스팅 Jira의 기본 URL과 개인 액세스 토큰으로 이슈를 봅니다.") &&
    el("jira-site-url-label").textContent === t("task.jira.siteUrl", "Jira 사이트 URL") &&
    el("jira-token").placeholder === t("task.jira.patPlaceholder", "Jira 개인 액세스 토큰") &&
    !el("jira-help-server").hidden &&
    el("jira-help-cloud").hidden;
  el("jira-auth-method").querySelector('[data-value="basic"]').click();
  seen.basicFace =
    el("jira-connect-copy").textContent ===
      t("task.jira.copyBasic", "자체 호스팅 Jira의 기본 URL과 사용자 이름·비밀번호로 이슈를 봅니다.") &&
    el("jira-identity").placeholder === t("task.jira.usernamePlaceholder", "사용자 이름") &&
    el("jira-token").placeholder === t("task.jira.passwordPlaceholder", "Jira 계정 비밀번호") &&
    !el("jira-help-basic").hidden &&
    el("jira-help-server").hidden;
  // 오류는 토큰 칸의 것으로 말해지고(aria), 다음 손질이 지운다.
  el("jira-instance-type").querySelector('[data-value="cloud"]').click();
  el("jira-site-url").value = "https://acme.atlassian.net";
  el("jira-identity").value = "hana@acme.com";
  el("jira-token").value = "bad";
  el("jira-token").dispatchEvent(new Event("input", { bubbles: true }));
  window.__ANSWER__.jira_connect = () => {
    throw new Error("credential refused");
  };
  el("jira-connect-submit").click();
  await new Promise((done) => setTimeout(done, 80));
  seen.errorAria =
    !el("jira-connect-error").hidden &&
    el("jira-token").getAttribute("aria-invalid") === "true" &&
    el("jira-token").getAttribute("aria-describedby") === "jira-connect-error";
  el("jira-token").value = "better";
  el("jira-token").dispatchEvent(new Event("input", { bubbles: true }));
  seen.editSweepsError =
    el("jira-connect-error").hidden &&
    el("jira-token").getAttribute("aria-invalid") === null;
  // 확인 중의 잠금 — 답이 오지 않는 연결을 걸어 두고 재본다.
  let free = null;
  window.__ANSWER__.jira_connect = () => new Promise((done) => (free = done));
  el("jira-connect-submit").click();
  await new Promise((done) => setTimeout(done, 60));
  seen.verifyingHolds =
    el("jira-connect-submit").querySelector(".jira-connect-spin").hidden === false &&
    el("jira-site-url").disabled &&
    el("jira-token").disabled &&
    el("jira-instance-type").querySelector(".segment-btn").disabled &&
    el("jira-connect-cancel").disabled;
  el("jira-connect-cancel").click();
  jiraConnectScrim.dispatchEvent(new MouseEvent("mousedown"));
  seen.verifyingStays = jiraConnectScrim.hidden === false;
  free({
    connected: true,
    active_site_id: "s1",
    selected_site_id: "s1",
    credential_error: null,
    credential_protection: "native",
    sites: [{
      id: "s1",
      site_url: "https://acme.atlassian.net",
      email: "hana@acme.com",
      display_name: "Hana",
      account_id: "hana",
      auth_type: "cloud",
      credential: "available",
    }],
  });
  await new Promise((done) => setTimeout(done, 80));
  seen.doneCloses =
    jiraConnectScrim.hidden === true && el("jira-site-url").disabled === false;
  delete window.__ANSWER__.jira_connect;
  return seen;
});
ok(
  "the Jira dialog speaks the chosen mode, holds its breath while verifying, and sweeps errors on edit",
  jiraDialogSpeaks.cloudFace && jiraDialogSpeaks.serverFace && jiraDialogSpeaks.basicFace &&
    jiraDialogSpeaks.errorAria && jiraDialogSpeaks.editSweepsError &&
    jiraDialogSpeaks.verifyingHolds && jiraDialogSpeaks.verifyingStays &&
    jiraDialogSpeaks.doneCloses,
  JSON.stringify(jiraDialogSpeaks),
);
await page.evaluate(() => {
  setWorktreeForm(false);
  window.__JIRA_STATUS__ = undefined;
  window.__JIRA_ISSUES__ = undefined;
});

