// ---- Warp YAML theme import ----
const importedTerminalThemes = await page.evaluate(async () => {
  const settle = () => new Promise((done) => setTimeout(done, 50));
  const custom = {
    id: "warp:ocean-night:0123456789ab",
    name: "Ocean Night",
    source: "warp",
    mode: "dark",
    terminal: {
      background: "#123456",
      foreground: "#fefefe",
      red: "#aa1122",
      blue: "#2244aa",
    },
    importedAtMs: 1,
    sourceLabel: "ocean.yaml",
    unsupportedFeatures: ["background image not supported"],
  };
  const patches = [];
  window.__ANSWER__.preview_warp_terminal_themes = ({ source }) => ({
    themes: source === "auto" ? [custom] : [],
    skipped: [{ label: "broken.yaml", reason: "invalid_yaml" }],
  });
  window.__ANSWER__.patch_terminal_prefs = (args) => {
    patches.push(JSON.parse(JSON.stringify(args.patch)));
    return null;
  };
  setTheme("dark");
  setSettingsOpen(true);
  showSettingsPane("terminal");
  const importButton = document.getElementById("term-theme-import-auto");
  importButton.focus();
  importButton.click();
  await settle();
  const preview = {
    open: !document.getElementById("term-theme-import-scrim").hidden,
    checked: document.querySelectorAll("[data-import-theme-id]:checked").length,
    name: document.querySelector(".terminal-theme-preview-name")?.textContent,
    meta: document.querySelector(".terminal-theme-preview-meta")?.textContent,
    skipped: document.getElementById("term-theme-preview-skipped").textContent,
  };
  document.getElementById("term-theme-import-apply").click();
  await settle();
  importButton.click();
  await settle();
  document.getElementById("term-theme-import-apply").click();
  await settle();
  const value = `custom:${custom.id}`;
  const dark = document.getElementById("term-theme-dark");
  const installed = {
    dialogClosed: document.getElementById("term-theme-import-scrim").hidden,
    customCount: termPrefs.custom_themes.length,
    option: [...dark.options].some((option) => option.value === value),
    listed: document.querySelector("[data-remove-custom-theme]")?.dataset.removeCustomTheme,
    returnFocus: document.activeElement?.id,
  };
  dark.value = value;
  dark.dispatchEvent(new Event("change", { bubbles: true }));
  await settle();
  const root = getComputedStyle(document.documentElement);
  const painted = {
    selected: dark.value,
    background: root.getPropertyValue("--term-screen-bg").trim(),
    foreground: root.getPropertyValue("--term-screen-fg").trim(),
    red: root.getPropertyValue("--term-1").trim(),
    blue: root.getPropertyValue("--term-4").trim(),
  };
  document.querySelector("[data-remove-custom-theme]").click();
  await settle();
  const removed = {
    customCount: termPrefs.custom_themes.length,
    selected: termPrefs.theme_dark,
    option: [...dark.options].some((option) => option.value === value),
  };
  delete window.__ANSWER__.preview_warp_terminal_themes;
  delete window.__ANSWER__.patch_terminal_prefs;
  return { preview, installed, painted, removed, patches };
});
ok(
  "Warp YAML previews, imports, paints, and removes through one typed terminal-theme owner",
  importedTerminalThemes.preview.open === true &&
    importedTerminalThemes.preview.checked === 1 &&
    importedTerminalThemes.preview.name === "Ocean Night" &&
    importedTerminalThemes.preview.meta.includes("ocean.yaml") &&
    importedTerminalThemes.preview.meta.includes("Unsupported effects omitted") &&
    importedTerminalThemes.preview.skipped.includes("1") &&
    importedTerminalThemes.installed.dialogClosed === true &&
    importedTerminalThemes.installed.customCount === 1 &&
    importedTerminalThemes.installed.option === true &&
    importedTerminalThemes.installed.listed === "warp:ocean-night:0123456789ab" &&
    importedTerminalThemes.installed.returnFocus === "term-theme-import-auto" &&
    JSON.stringify(importedTerminalThemes.painted) === JSON.stringify({
      selected: "custom:warp:ocean-night:0123456789ab",
      background: "#123456",
      foreground: "#fefefe",
      red: "#aa1122",
      blue: "#2244aa",
    }) &&
    importedTerminalThemes.removed.customCount === 0 &&
    importedTerminalThemes.removed.selected === "Ghostty Default Style Dark" &&
    importedTerminalThemes.removed.option === false &&
    importedTerminalThemes.patches.some((patch) => patch.kind === "import_custom_themes") &&
    importedTerminalThemes.patches.some((patch) => patch.kind === "theme_dark") &&
    importedTerminalThemes.patches.some((patch) => patch.kind === "remove_custom_theme"),
  JSON.stringify(importedTerminalThemes),
);

