  seen.cursorOpacityBounds = [cursorOpacity.min, cursorOpacity.max, cursorOpacity.step];
  seen.paddingDefaults = [paddingX.value, paddingY.value];
  seen.paddingXBounds = [paddingX.min, paddingX.max, paddingX.step];
  seen.paddingYBounds = [paddingY.min, paddingY.max, paddingY.step];
  seen.opacityBounds = [inactiveOpacity.min, inactiveOpacity.max, inactiveOpacity.step];
  seen.dividerBounds = [dividerThickness.min, dividerThickness.max, dividerThickness.step];
  seen.dividerColorDefaults = {
    dark: dividerColorDark.value,
    light: dividerColorLight.value,
    darkSwatch: document.getElementById("term-divider-color-dark-swatch").value,
    lightSwatch: document.getElementById("term-divider-color-light-swatch").value,
  };
  seen.parkedCursorBox = [window.__B__.view.caret.style.width, window.__B__.view.caret.style.height];
  const dividerColorResizes = {
    term: window.__COUNTS__.term_resize ?? 0,
    lane: window.__COUNTS__.resize_lane ?? 0,
  };
  dividerColorDark.value = "#123456";
  dividerColorDark.dispatchEvent(new Event("change", { bubbles: true }));
  dividerColorLight.value = "#abcdef";
  dividerColorLight.dispatchEvent(new Event("change", { bubbles: true }));
  await new Promise((done) => setTimeout(done, 40));
  const grip = document.querySelector(".pane-grip");
  const priorTheme = root.dataset.theme;
  root.dataset.theme = "dark";
  applyTerminalPalette();
  const darkDivider = getComputedStyle(grip, "::after").backgroundColor;
  root.dataset.theme = "light";
  applyTerminalPalette();
  const lightDivider = getComputedStyle(grip, "::after").backgroundColor;
  root.dataset.theme = priorTheme;
  applyTerminalPalette();
  seen.dividerColorsApplied = {
    dark: read("--term-divider-color-dark"),
    light: read("--term-divider-color-light"),
    darkDivider,
    lightDivider,
    termResizes: (window.__COUNTS__.term_resize ?? 0) - dividerColorResizes.term,
    laneResizes: (window.__COUNTS__.resize_lane ?? 0) - dividerColorResizes.lane,
  };
  const resizes = {
    term: window.__COUNTS__.term_resize ?? 0,
    lane: window.__COUNTS__.resize_lane ?? 0,
  };
  cursorStyle.value = "bar";
  cursorStyle.dispatchEvent(new Event("change", { bubbles: true }));
  cursorOpacity.value = "0.4";
  cursorOpacity.dispatchEvent(new Event("change", { bubbles: true }));
  inactiveOpacity.value = "0.6";
