const longBased = await page.evaluate(() => {
  const row = document.querySelector('.wt-row[data-worktree-path="/tmp/based-long-wt/t-1140"]');
  const line = row?.querySelector(".wt-branch");
  const name = row?.querySelector(".wt-branch-name");
  const chip = row?.querySelector(".wt-base");
  if (!line || !name || !chip) return { there: false };
  const box = line.getBoundingClientRect();
  const chipBox = chip.getBoundingClientRect();
  // The branch IS this card's title, so the title is the half that says it
  // and gives way (2026-09-15 nav redesign: a name is said once); the branch
  // line keeps only the base chip, whole.
  const title = row.querySelector(".wt-title");
  return {
    there: true,
    elided: name.hidden && title.scrollWidth > title.clientWidth + 1,
    chipWords: chip.textContent,
    // And the chip is whole, inside the line it rides.
    chipWidth: Math.round(chipBox.width),
    chipRight: Math.round(box.right - chipBox.right),
    chipInside: chipBox.right <= box.right + 1 && chipBox.width > 0,
  };
});
