const worktreeWorkerDepth = await page.evaluate(() => {
  const main = document.querySelector('.wt-row[data-worktree-path="/tmp/moved-to"]');
  const row = document.querySelector('.wt-row[data-worktree-path="/tmp/moved-to-wt/side"]');
  const node = row?.closest(".wt-node");
  const agents = node?.querySelector(".wt-agents");
  if (!main || !row || !node || !agents) return { there: false };
  const root = document.createElement("button");
  root.className = "wt-agent";
  root.textContent = "root worker";
  const child = document.createElement("button");
  child.className = "wt-agent";
  child.style.setProperty("--card-depth", "1");
  child.textContent = "nested helper";
  agents.replaceChildren(root, child);
  agents.hidden = false;
  // This witness measures the target ownership recipe, not the first frame
  // of its 200ms colour transition. Motion has a separate computed-style
  // contract below; leaving it enabled here races the transparent rest
  // border and reports a false layout failure on a fast browser.
  node.style.transition = "none";
  node.classList.add("has-agents");
  const nodeBox = node.getBoundingClientRect();
  const rootBox = root.getBoundingClientRect();
  const childBox = child.getBoundingClientRect();
  const mainTitle = main.querySelector(".wt-title").getBoundingClientRect();
  const sideTitle = row.querySelector(".wt-title").getBoundingClientRect();
  const indent = Number.parseFloat(
    getComputedStyle(document.documentElement).getPropertyValue("--nav-indent"),
  );
  const border = getComputedStyle(node).borderTopColor;
  agents.replaceChildren();
  agents.hidden = true;
  node.classList.remove("has-agents");
  node.style.removeProperty("transition");
  return {
    there: true,
    siblingTitlesAligned: Math.abs(mainTitle.left - sideTitle.left) < 0.5,
    rootInside:
      rootBox.left > nodeBox.left &&
      rootBox.right < nodeBox.right &&
      rootBox.top > nodeBox.top &&
      rootBox.bottom < nodeBox.bottom,
    childStep: childBox.left - rootBox.left,
    indent,
    boundaryVisible: !/rgba\(0, 0, 0, 0\)|transparent/.test(border),
    border,
  };
});
ok(
  "worktrees stay sibling-aligned while workers and helpers step inside their owning card",
  worktreeWorkerDepth.there &&
    worktreeWorkerDepth.siblingTitlesAligned &&
    worktreeWorkerDepth.rootInside &&
    Math.abs(worktreeWorkerDepth.childStep - worktreeWorkerDepth.indent) < 0.5 &&
    worktreeWorkerDepth.boundaryVisible,
  JSON.stringify(worktreeWorkerDepth),
);

// The card's own rule says 200ms — Orca's measured `duration-200` — but the
