// Orca's arrows walk `worktreeNavHistory` — ONE stack holding workspaces and
// the two page views (store-BgJxB0hr.js:30138-30252) — not the files the
// right panel has shown. 작업 and 자동화 record stops; 뒤로 returns to the
// workspace terminal; walking back and then going somewhere new drops the
// forward half; and the arrows are hidden on the settings page
// (App-BaqTRjaA.js:37167-37169: terminal | tasks | automations only).
await page.evaluate(async () => {
  // Stateful, because the window re-reads the catalog after every activation
  // and derives `activeWorktreePath` from the `active` flags — a fixture that
  // never moves its flag quietly undoes every switch.
  window.__NAV_ACTIVE__ = "/tmp/moved-to";
  window.__ANSWER__.project_catalog = () => [{
    name: "moved-to",
    path: "/tmp/moved-to",
    worktrees: [
      { path: "/tmp/moved-to", branch: "main", is_main: true,
        active: window.__NAV_ACTIVE__ === "/tmp/moved-to", is_folder: false },
      { path: "/tmp/moved-to-wt/side", branch: "feature/side", is_main: false,
        active: window.__NAV_ACTIVE__ === "/tmp/moved-to-wt/side", is_folder: false },
    ],
  }];
  window.__ANSWER__.set_active_worktree = (args) => {
    window.__NAV_ACTIVE__ = args.path;
    return args.path.endsWith("/side") ? "feature/side" : "main";
  };
  window.__ANSWER__.read_text_file = () => ({ text: "hello", version: "v1" });
  // Earlier tests may have left drafts; a dirty document blocks activation
  // behind the save dialog, which nothing here is testing.
  for (const tab of tabs) if (tab.draft !== undefined) tab.draft = tab.text;
  await refreshWorktrees();
});
