/* ---- a terminal tab divides into panes --------------------------------- */

/* Orca's terminal tab is not one shell. Its layout per tab is a tree of
 * `{type:"leaf"}` and `{type:"split", direction, first, second, ratio}` born
 * at exactly half (App-BaqTRjaA.js:3492-3560), and ⌘D / ⌘⇧D on macOS are the
 * measured defaults that make one (plugin-manifest-Dq3wpxrr.js:5676-5710).
 *
 * Driven through the actions rather than through synthetic ⌘D: a headless
 * keydown reaches the document, and what is under test here is the layout the
 * action produces, not the dispatcher that already has its own gates. */
await page.evaluate(() => {
  // A terminal tab of its own to divide, so nothing earlier in this file is
  // measuring a stage this section left split.
  for (const tab of tabs.filter((held) => held.kind === "term")) closeTab(tab.id);
});
await page.waitForTimeout(60);
await page.evaluate(() => openTermTab());
await page.waitForTimeout(120);

const oneP = await page.evaluate(() => {
  const tab = currentTab();
  return { kind: tab?.kind, leaves: paneLeaves(tab.layout).length, root: tab.layout.type };
});
ok(
  "a terminal tab starts as one pane, which is a tree of one leaf",
  oneP.kind === "term" && oneP.leaves === 1 && oneP.root === "leaf",
  JSON.stringify(oneP),
);

await page.evaluate(() => splitActivePane("vertical"));
await page.waitForTimeout(150);

const split = await page.evaluate(() => {
  const tab = currentTab();
  const host = document.querySelector(".panes:not([hidden]) .pane-split");
  const slots = [...(host?.querySelectorAll(":scope > .pane-slot") ?? [])];
  return {
    type: tab.layout.type,
    direction: tab.layout.direction,
    // Absent, not 0.5. A number here would mean somebody moved this divider.
    ratio: tab.layout.ratio ?? null,
    reads: paneRatio(tab.layout),
    leaves: paneLeaves(tab.layout),
    active: tab.activePane,
    typedTo: keyboardTarget()?.term ?? null,
    row: host?.classList.contains("is-vertical") ?? false,
    widths: slots.map((slot) => Math.round(slot.getBoundingClientRect().width)),
    grips: host?.querySelectorAll(":scope > .pane-grip").length ?? 0,
  };
});
ok(
  "splitting right divides the tab in half, as a row",
  split.type === "split" &&
    split.direction === "vertical" &&
    split.ratio === null &&
    split.reads === 0.5 &&
    split.leaves.length === 2 &&
    split.row &&
    split.grips === 1 &&
    Math.abs(split.widths[0] - split.widths[1]) <= 1,
  JSON.stringify(split),
);
ok(
  "the new pane takes the keyboard, and typing follows it rather than the tab",
  split.active === split.leaves[1] && split.typedTo === split.leaves[1],
  JSON.stringify({ active: split.active, typedTo: split.typedTo, leaves: split.leaves }),
);

/* A pane that is on screen is a pane that paints.
 *
 * This one is here because the layout gates above all passed while the split
 * drew nothing at all: every screen was built `hidden` and moved into its
 * slot, and nothing ever cleared the flag — so the panes measured, sized and
 * divided correctly and stayed black. A view paints only while its own host
 * is visible, and the stage is what has to say so. Caught by looking at the
 * window, which is why looking at the window is part of the gate. */
const painting = await page.evaluate(() => {
  const shown = document.querySelector(".panes:not([hidden])");
  const inShown = [...shown.querySelectorAll(".pane-slot")].map(
    (slot) => termViews.get(Number(slot.dataset.term))?.host.hidden,
  );
  // And a tab that is not on the stage quiets its shells, which is what keeps
  // background terminals off the thread delivering the next keystroke.
  const other = [...paneHosts.values()].filter((host) => host.hidden);
  const inHidden = other.flatMap((host) =>
    [...host.querySelectorAll(".pane-slot")].map(
      (slot) => termViews.get(Number(slot.dataset.term))?.host.hidden,
    ),
  );
  return {
    inShown,
    inHidden,
  };
});
ok(
  "every pane on the stage is a pane that paints",
  painting.inShown.length > 1 &&
    painting.inShown.every((hidden) => hidden === false) &&
    painting.inHidden.every((hidden) => hidden === true),
  JSON.stringify(painting),
);

const terminalAppearance = await page.evaluate(async () => {
  const tab = currentTab();
  const host = document.querySelector(".panes:not([hidden]) .pane-split");
  const slots = [...host.querySelectorAll(":scope > .pane-slot")];
  const active = slots.find((slot) => slot.classList.contains("is-active"));
  const inactive = slots.find((slot) => !slot.classList.contains("is-active"));
  const activeCaret = active.querySelector(".term-caret");
  const inactiveCaret = inactive.querySelector(".term-caret");
  const grip = host.querySelector(":scope > .pane-grip");
  const pseudo = (node) => getComputedStyle(node, "::after");
  // The strip itself is the hit target now — Orca sizes the divider element
  // to the whole reach and lets the panes flex around it, so the first read
  // is the grip's own width rather than an overlay's.
  const seen = {
    defaultOpacity: [getComputedStyle(active).opacity, getComputedStyle(inactive).opacity],
    inactiveBlockOutline: pseudo(inactiveCaret).boxShadow,
    activeBlockOutline: pseudo(activeCaret).boxShadow,
    defaultGrip: [getComputedStyle(grip).width, pseudo(grip).width],
  };
  const resizes = {
    term: window.__COUNTS__.term_resize ?? 0,
    lane: window.__COUNTS__.resize_lane ?? 0,
  };
  setTermPrefs({ cursor_style: "bar" });
  setTermPrefs({ inactive_pane_opacity: 0.5 });
  setTermPrefs({ divider_thickness_px: 7 });
  await new Promise((done) => setTimeout(done, 180));
  seen.bar = {
    widths: [pseudo(activeCaret).width, pseudo(inactiveCaret).width],
    shadows: [pseudo(activeCaret).boxShadow, pseudo(inactiveCaret).boxShadow],
    opacity: [getComputedStyle(active).opacity, getComputedStyle(inactive).opacity],
    grip: [getComputedStyle(grip).width, pseudo(grip).width],
  };
  setTermPrefs({ cursor_style: "underline" });
  await new Promise((done) => setTimeout(done, 40));
  seen.underline = {
    heights: [pseudo(activeCaret).height, pseudo(inactiveCaret).height],
    shadows: [pseudo(activeCaret).boxShadow, pseudo(inactiveCaret).boxShadow],
  };
  seen.resizeDelta = {
    term: (window.__COUNTS__.term_resize ?? 0) - resizes.term,
    lane: (window.__COUNTS__.resize_lane ?? 0) - resizes.lane,
  };
  setTermPrefs({ cursor_style: "block" });
  setTermPrefs({ inactive_pane_opacity: 0.9 });
  setTermPrefs({ divider_thickness_px: 3 });
  await new Promise((done) => setTimeout(done, 180));
  return seen;
});
ok(
  "terminal appearance styles split panes live without changing the pty grid",
  JSON.stringify(terminalAppearance.defaultOpacity) === JSON.stringify(["1", "0.9"]) &&
    terminalAppearance.inactiveBlockOutline !== "none" &&
    terminalAppearance.activeBlockOutline === "none" &&
    JSON.stringify(terminalAppearance.defaultGrip) === JSON.stringify(["9px", "3px"]) &&
    terminalAppearance.bar.widths[0] === terminalAppearance.bar.widths[1] &&
    terminalAppearance.bar.widths[0] !== "auto" &&
    terminalAppearance.bar.shadows.every((shadow) => shadow === "none") &&
    JSON.stringify(terminalAppearance.bar.opacity) === JSON.stringify(["1", "0.5"]) &&
    JSON.stringify(terminalAppearance.bar.grip) === JSON.stringify(["13px", "7px"]) &&
    terminalAppearance.underline.heights[0] === terminalAppearance.underline.heights[1] &&
    terminalAppearance.underline.heights[0] !== "auto" &&
    terminalAppearance.underline.shadows.every((shadow) => shadow === "none") &&
    terminalAppearance.resizeDelta.term === 0 && terminalAppearance.resizeDelta.lane === 0,
  JSON.stringify(terminalAppearance),
);

/* The split is a gutter, not a painted-on line.
 *
 * Orca's divider takes real layout room — a "Ghostty-style" flex-none strip
 * the panes flex around (`createDivider`,
 * src/renderer/src/lib/pane-manager/pane-divider.ts) — and the strip paints
 * nothing: the visible bar is its ::after, rounded 1px, overshooting each
 * end by half the hit so intersecting splits "visually connect (├ not |-)"
 * (`applyDividerStyles`; terminal.css:106-148), on the terminal theme's own
 * ground (`splitBackground: paneBackground` → `applyRootBackground`). While
 * a drag runs the strip wears `is-dragging`, so whatever colour stands holds
 * even when the pointer runs ahead of the divider. */
const paneGutter = await page.evaluate(() => {
  const host = document.querySelector(".panes:not([hidden])");
  const split = host.querySelector(".pane-split");
  const grip = split.querySelector(":scope > .pane-grip");
  const slots = [...split.querySelectorAll(":scope > .pane-slot")];
  const after = getComputedStyle(grip, "::after");
  const gripBox = grip.getBoundingClientRect();
  const slotBoxes = slots.map((slot) => slot.getBoundingClientRect());
  const splitBox = split.getBoundingClientRect();
  const probe = document.createElement("div");
  probe.style.background = "var(--term-screen-bg)";
  host.appendChild(probe);
  const screenGround = getComputedStyle(probe).backgroundColor;
  probe.remove();
  const seen = {
    stripRoom: Math.round(gripBox.width),
    roomsAddUp:
      Math.abs(slotBoxes[0].width + gripBox.width + slotBoxes[1].width - splitBox.width) <= 1,
    shellGap: Math.round(slotBoxes[1].left - slotBoxes[0].right),
    stripPaint: getComputedStyle(grip).backgroundColor,
    rounded: after.borderRadius,
    overshoot: [after.top, after.bottom],
    // Orca's own 100ms ease on the bar's colour (terminal.css:119), not this
    // window's shared motion list.
    eases: [after.transitionProperty, after.transitionDuration],
    ground: [getComputedStyle(host).backgroundColor, screenGround, getComputedStyle(host).overflow],
    restColor: after.backgroundColor,
  };
  grip.dispatchEvent(new MouseEvent("mousedown", {
    bubbles: true, cancelable: true,
    clientX: gripBox.left + 1, clientY: gripBox.top + 1,
  }));
  seen.dragging = {
    marked: grip.classList.contains("is-dragging"),
    body: document.body.classList.contains("is-dragging-pane"),
    lit: getComputedStyle(grip, "::after").backgroundColor,
  };
  window.dispatchEvent(new MouseEvent("mouseup", { bubbles: true }));
  seen.released = {
    marked: grip.classList.contains("is-dragging"),
    body: document.body.classList.contains("is-dragging-pane"),
  };
  return seen;
});
ok(
  "the divider owns a nine-pixel gutter, and its rounded bar overshoots and holds its colour through a drag",
  paneGutter.stripRoom === 9 &&
    paneGutter.roomsAddUp &&
    paneGutter.shellGap === 9 &&
    paneGutter.stripPaint === "rgba(0, 0, 0, 0)" &&
    paneGutter.rounded === "1px" &&
    paneGutter.overshoot.every((edge) => edge === "-4.5px") &&
    paneGutter.eases[0].includes("background") &&
    paneGutter.eases[1].startsWith("0.1s") &&
    paneGutter.ground[0] === paneGutter.ground[1] &&
    paneGutter.ground[0] !== "rgba(0, 0, 0, 0)" &&
    paneGutter.ground[2] === "hidden" &&
    paneGutter.dragging.marked &&
    paneGutter.dragging.body &&
    // Orca's strong colour passes the same normalizeColor as the base, so
    // hover and drag change NOTHING visibly (TerminalPane.tsx:2874-2880) —
    // the mark is worn, the colour holds.
    paneGutter.dragging.lit === paneGutter.restColor &&
    !paneGutter.released.marked &&
    !paneGutter.released.body,
  JSON.stringify(paneGutter),
);

/* 갯수에 따라 등분, 정확한 크기로 — a division re-evens the whole tree, so
 * after two more splits three columns stand at a third each instead of
 * Orca's halving cascade (1/2, 1/4, 1/4 …down to slivers), which the person
 * named broken twice. Driven through `splitActivePane` so the road a real
 * ⌘D takes is the road measured, and read back from BOTH the ratios the
 * file will remember and the widths the eye actually gets. */
const evenSplit = await page.evaluate(async () => {
  const tab = [...tabs].reverse().find((one) => one.kind === "term");
  setActiveTab(tab.id);
  const keep = { layout: tab.layout, active: tab.activePane };
  const had = paneLeaves(keep.layout).length;
  let minted = 900;
  const openBefore = window.__ANSWER__.open_term_tab;
  window.__ANSWER__.open_term_tab = () => (minted += 1);
  await splitActivePane("vertical");
  await splitActivePane("vertical");
  // The property itself: a tree the division just left is ALREADY even, so
  // running the balance again moves nothing. Whatever pane count this suite
  // walked in with, that assertion cannot be gamed by a lucky fixture.
  const stillEven = !equalizePanes(tab.layout);
  const widths = [...paneHosts.get(tab.id).querySelectorAll(".pane-slot")]
    .map((slot) => slot.getBoundingClientRect().width);
  const leaves = paneLeaves(tab.layout);
  // Put the room back the way it was found: the minted shells never existed,
  // so their views must not outlive this measurement.
  tab.layout = keep.layout;
  tab.activePane = keep.active;
  for (const term of leaves) {
    if (term > 900) dropTermView(term);
  }
  renderPanes(tab);
  updateStage();
  if (openBefore === undefined) delete window.__ANSWER__.open_term_tab;
  else window.__ANSWER__.open_term_tab = openBefore;
  return { stillEven, widths, count: leaves.length, had };
});
ok(
  "a division leaves every pane the same size — even shares, not a halving cascade",
  evenSplit.count === evenSplit.had + 2 &&
    evenSplit.stillEven &&
    evenSplit.widths.length === evenSplit.count &&
    // The grips take real room between the slots, so the outermost panes
    // measure up to one gutter wider than the inner ones — a nine-pixel
    // allowance, never the halving cascade's hundreds.
    Math.max(...evenSplit.widths) - Math.min(...evenSplit.widths) <= 9,
  JSON.stringify(evenSplit),
);

/* 반응형: a uniform row that would overflow the room wraps as a grid — four
 * panes on a 640px host stand in two ranks instead of four slivers — and the
 * same layout back in real room returns to the split renderer, dividers and
 * all. Driven through `renderPanes` with the width forced, because the mode
 * is a fact about the host's room and the harness's stage is whatever
 * earlier tests left it. */
const reflow = await page.evaluate(async () => {
  const tab = [...tabs].reverse().find((one) => one.kind === "term");
  setActiveTab(tab.id);
  const keep = { layout: tab.layout, active: tab.activePane };
  let minted = 950;
  const openBefore = window.__ANSWER__.open_term_tab;
  window.__ANSWER__.open_term_tab = () => (minted += 1);
  await splitActivePane("vertical");
  await splitActivePane("vertical");
  const host = paneHosts.get(tab.id);
  const width = host.style.width;
  host.style.width = "640px";
  renderPanes(tab);
  const narrow = {
    mode: host.dataset.paneMode,
    grid: Boolean(host.querySelector(".panes-grid")),
    ranks: new Set(
      [...host.querySelectorAll(".pane-slot")].map((slot) => slot.offsetTop),
    ).size,
  };
  host.style.width = "2000px";
  renderPanes(tab);
  const wide = {
    mode: host.dataset.paneMode,
    split: Boolean(host.querySelector(".pane-split")),
    grip: Boolean(host.querySelector(".pane-grip")),
  };
  host.style.width = width;
  const leaves = paneLeaves(tab.layout);
  tab.layout = keep.layout;
  tab.activePane = keep.active;
  for (const term of leaves) {
    if (term > 950) dropTermView(term);
  }
  renderPanes(tab);
  updateStage();
  if (openBefore === undefined) delete window.__ANSWER__.open_term_tab;
  else window.__ANSWER__.open_term_tab = openBefore;
  return { narrow, wide, count: leaves.length };
});
ok(
  "a row that overflows a small screen wraps to ranks, and takes its dividers back in real room",
  reflow.count >= 4 &&
    reflow.narrow.mode === "grid" &&
    reflow.narrow.grid &&
    reflow.narrow.ranks >= 2 &&
    reflow.wide.mode === "split" &&
    reflow.wide.split &&
    reflow.wide.grip,
  JSON.stringify(reflow),
);

const terminalPointerWhileTyping = await page.evaluate(async () => {
  const tab = [...tabs].reverse().find((one) => one.kind === "term");
  setActiveTab(tab.id);
  const term = activePaneOf(tab);
  const target = { kind: "term", term };
  const view = terminalViewForTarget(target);
  const resizeBefore = {
    term: window.__COUNTS__.term_resize ?? 0,
    lane: window.__COUNTS__.resize_lane ?? 0,
  };
  routeText("visible-default");
  const defaultVisible = !view.host.classList.contains("is-pointer-hidden");

  setTermPrefs({ hide_mouse_while_typing: true });
  routeText("hide-after-text");
  const textHidden = view.host.classList.contains("is-pointer-hidden") &&
    getComputedStyle(view.host).cursor === "none";
  view.host.dispatchEvent(new MouseEvent("mousemove", { bubbles: true }));
  const moveRevealed = !view.host.classList.contains("is-pointer-hidden");

  view.apply({
    rows: [], scrolled_lines: 0, cursor: [0, 0], title: null,
    alt_screen: false, size: [24, 80], full: false, cursor_visible: true,
    mouse_tracking: "off", mouse_sgr: false, bell: false,
  });
  const outputStayedVisible = !view.host.classList.contains("is-pointer-hidden");

  const sink = document.getElementById("key-sink");
  sink.focus();
  sink.dispatchEvent(new KeyboardEvent("keydown", {
    key: "ArrowLeft", code: "ArrowLeft", bubbles: true, cancelable: true,
  }));
  const keyHidden = view.host.classList.contains("is-pointer-hidden");
  view.host.dispatchEvent(new MouseEvent("mousemove", { bubbles: true }));
  await pasteTextAt(target, "hide-after-paste");
  const pasteHidden = view.host.classList.contains("is-pointer-hidden");

  setTermPrefs({ hide_mouse_while_typing: false });
  const disableRevealed = !view.host.classList.contains("is-pointer-hidden");
  return {
    defaultVisible,
    textHidden,
    moveRevealed,
    outputStayedVisible,
    keyHidden,
    pasteHidden,
    disableRevealed,
    resizeDelta: {
      term: (window.__COUNTS__.term_resize ?? 0) - resizeBefore.term,
      lane: (window.__COUNTS__.resize_lane ?? 0) - resizeBefore.lane,
    },
  };
});
ok(
  "terminal input hides only its pointer until movement or disabling the setting",
  terminalPointerWhileTyping.defaultVisible && terminalPointerWhileTyping.textHidden &&
    terminalPointerWhileTyping.moveRevealed && terminalPointerWhileTyping.outputStayedVisible &&
    terminalPointerWhileTyping.keyHidden && terminalPointerWhileTyping.pasteHidden &&
    terminalPointerWhileTyping.disableRevealed &&
    terminalPointerWhileTyping.resizeDelta.term === 0 &&
    terminalPointerWhileTyping.resizeDelta.lane === 0,
  JSON.stringify(terminalPointerWhileTyping),
);

/* The count in the status bar is shells, not tabs — one tab is now two
 * processes, and the number a person glances at has to say so. */
// Read against the model rather than against a Korean word: an earlier
// section leaves the window in whichever language it was testing, and a gate
// that only passes in one of them is a gate that will fail for the next
// person who adds a locale test above it.
const counted = await page.evaluate(() => ({
  text: document.getElementById("sb-count").textContent,
  shells: tabs
    .filter((tab) => tab.kind === "term")
    .reduce((total, tab) => total + paneLeaves(tab.layout).length, 0),
  tabsHolding: tabs.filter((tab) => tab.kind === "term").length,
  // What the bar counts beside the tabs' shells: lanes, agents running with no
  // tab, and the floating panel's shell — which an earlier section opened and
  // hid, and which keeps running behind its hidden panel.
  besides: order.length + detachedAgents.size + Number(floatTermRunning),
}));
ok(
  "the status bar counts the shells, not the tabs holding them",
  counted.shells === 2 && counted.tabsHolding === 1 &&
    Number(counted.text) === counted.shells + counted.besides,
  JSON.stringify(counted),
);

/* Down is the other axis, and the tree nests rather than flattening. */
await page.evaluate(() => splitActivePane("horizontal"));
await page.waitForTimeout(150);
const nested = await page.evaluate(() => {
  const tab = currentTab();
  return {
    outer: tab.layout.direction,
    inner: tab.layout.second?.direction ?? null,
    leaves: paneLeaves(tab.layout).length,
    column: document.querySelector(".panes:not([hidden]) .pane-split.is-horizontal") !== null,
  };
});
ok(
  "splitting down again nests inside the pane that was split",
  nested.outer === "vertical" && nested.inner === "horizontal" && nested.leaves === 3 && nested.column,
  JSON.stringify(nested),
);

/* Walking the panes wraps, in the order they are drawn. */
const walked = await page.evaluate(() => {
  const tab = currentTab();
  const order = paneLeaves(tab.layout);
  const seen = [];
  for (let step = 0; step < 4; step += 1) {
    focusPane(1);
    seen.push(currentTab().activePane);
  }
  return { order, seen };
});
ok(
  "⌘] walks the panes in the order they are drawn, and wraps",
  walked.seen.length === 4 && walked.seen[3] === walked.seen[0],
  JSON.stringify(walked),
);

/* Closing a pane collapses the split to the pane that is left — it does not
 * leave a branch with a hole in it (`prunePaneLayout`). */
const collapsed = await page.evaluate(async () => {
  const tab = currentTab();
  const before = paneLeaves(tab.layout).length;
  const going = tab.activePane;
  closeActivePane();
  await new Promise((done) => setTimeout(done, 30));
  const after = currentTab();
  return {
    before,
    going,
    leaves: paneLeaves(after.layout),
    stillATab: tabs.some((held) => held.id === after.id),
    closed: window.__CLOSED_TERMS__ ?? null,
  };
});
ok(
  "closing a pane collapses the split onto the pane that is left",
  collapsed.before === 3 &&
    collapsed.leaves.length === 2 &&
    !collapsed.leaves.includes(collapsed.going) &&
    collapsed.stillATab,
  JSON.stringify(collapsed),
);

/* ⌘W means the pane while there is more than one, and the tab once there is
 * not — Orca's terminal answers the chord first and the strip answers it when
 * the terminal has nothing left to close. */
const lastOne = await page.evaluate(async () => {
  const before = paneLeaves(currentTab().layout).length;
  const answered = closeActivePane();
  await new Promise((done) => setTimeout(done, 30));
  const mid = currentTab();
  return {
    before,
    answered,
    left: paneLeaves(mid.layout).length,
    refusesWithOne: closeActivePane(),
  };
});
ok(
  "⌘W closes the pane until there is one, then stops answering for the tab",
  lastOne.before === 2 && lastOne.answered && lastOne.left === 1 && lastOne.refusesWithOne === false,
  JSON.stringify(lastOne),
);

/* A shell that ends on its own takes its pane, not the tab that held it. */
await page.evaluate(() => splitActivePane("vertical"));
await page.waitForTimeout(150);
const afterExit = await page.evaluate(async () => {
  const tab = currentTab();
  const going = tab.activePane;
  const staying = paneLeaves(tab.layout).filter((term) => term !== going);
  for (const handler of window.__LISTENERS__["term:exited"] ?? []) {
    handler({ payload: { term: going } });
  }
  const now = tabs.find((held) => held.id === tab.id) ?? null;
  return {
    going,
    tabSurvived: now !== null,
    leaves: now ? paneLeaves(now.layout) : [],
    expected: staying,
  };
});
ok(
  "a shell that exits takes its pane with it and leaves the tab standing",
  afterExit.tabSurvived &&
    afterExit.leaves.length === 1 &&
    afterExit.leaves[0] === afterExit.expected[0],
  JSON.stringify(afterExit),
);

/* ---- the menu a tab raises --------------------------------------------- */

const tabMenu = await page.evaluate(() => {
  const tab = currentTab();
  const strip = paneTabs(tab.pane);
  tabMenuAt(tab, 40, 40, null);
  const menu = document.getElementById("sidebar-menu");
  const rows = [...menu.querySelectorAll(".sidebar-menu-item")].map((row) => ({
    label: row.querySelector(".sidebar-menu-label").textContent,
    disabled: row.disabled,
  }));
  const focused = document.activeElement?.classList.contains("sidebar-menu-item");
  closeSidebarMenu();
  return {
    rows,
    focused,
    // Asked of the same catalog the menu reads, so this passes in whatever
    // language an earlier section left the window speaking.
    said: {
      right: t("terminal.splitRight", "터미널 오른쪽으로 분할"),
      down: t("terminal.splitDown", "터미널 아래로 분할"),
      pin: t("tab.pin", "탭 고정"),
      close: t("tab.close", "탭 닫기"),
    },
    // The measured disabled rules, evaluated against the strip as it actually
    // stands rather than against a strip this test assumed.
    expect: {
      others: strip.length <= 1,
      right: strip.indexOf(tab) >= strip.length - 1,
      left: strip.indexOf(tab) <= 0,
    },
  };
});
ok(
  "a terminal tab's menu offers both splits, then the pin, then the closes",
  tabMenu.rows[0].label === tabMenu.said.right &&
    tabMenu.rows[1].label === tabMenu.said.down &&
    tabMenu.rows[2].label === tabMenu.said.pin &&
    tabMenu.rows[3].label === tabMenu.said.close,
  JSON.stringify(tabMenu.rows.map((row) => row.label)),
);
ok(
  "a close with nothing to close is drawn and disabled, not hidden",
  tabMenu.rows.length === 8 &&
    tabMenu.rows[4].disabled === tabMenu.expect.others &&
    tabMenu.rows[5].disabled === false &&
    tabMenu.rows[6].disabled === tabMenu.expect.right &&
    tabMenu.rows[7].disabled === tabMenu.expect.left,
  JSON.stringify({ rows: tabMenu.rows, expect: tabMenu.expect }),
);
ok(
  "the menu opens onto a row that can be chosen, never a disabled one",
  tabMenu.focused === true,
  JSON.stringify({ focused: tabMenu.focused }),
);

/* ---- the activity row says which panel is open -------------------------- */

/* Four icons carrying `role="tab"` and not one `aria-selected` between them.
 * Every other tablist in this window sets it, so this was the single row
 * where a person not looking at the screen could not tell what was open. The
 * fourth icon was never a tab at all — it toggles the floating terminal,
 * which this column never shows — so it is a toggle and says so. */
const activity = await page.evaluate(() => {
  const read = () => ({
    files: document.getElementById("activity-files-tab").getAttribute("aria-selected"),
    scm: document.getElementById("activity-scm-tab").getAttribute("aria-selected"),
    search: document.getElementById("activity-search-tab").getAttribute("aria-selected"),
  });
  document.getElementById("activity-files-tab").click();
  const onNames = { ...read(), mode: fileSearchMode };
  // The door labelled 내용 검색 has to arrive asking about contents. It used
  // to open the panel and focus the field without touching the mode, so it
  // asked whichever question was asked last.
  document.getElementById("activity-search-tab").click();
  const onText = { ...read(), mode: fileSearchMode };
  document.getElementById("activity-scm-tab").click();
  const onScm = read();
  return {
    onNames,
    onText,
    onScm,
    // A tablist may only hold tabs, so the toggle sits beside it rather than
    // in it. Scoped to this row: the stage's `.tabstrip` carries the same
    // defect — it is a tablist holding the `＋` button — and moving that one
    // out reaches the drag handlers, the `:has(> .tabstrip)` rules and the
    // strip's own i18n, so it is its own change rather than a rider on this
    // one. Widen this selector to the document when it lands.
    strays: document.querySelectorAll('.activity-tabs [role="tablist"] > :not([role="tab"])').length,
    toggleIsNotATab: document.getElementById("activity-term-tab").getAttribute("role"),
    pressedWhenShut: document.getElementById("activity-term-tab").getAttribute("aria-pressed"),
  };
});
ok(
  "each door in the activity row arrives asking its own question",
  activity.onNames.mode === "name" && activity.onText.mode === "text",
  JSON.stringify({ names: activity.onNames.mode, text: activity.onText.mode }),
);
ok(
  "the activity row says which of its panels is open",
  activity.onNames.files === "true" &&
    activity.onNames.search === "false" &&
    activity.onText.search === "true" &&
    activity.onText.files === "false" &&
    activity.onScm.scm === "true" &&
    activity.onScm.files === "false" &&
    activity.onScm.search === "false",
  JSON.stringify(activity),
);
ok(
  "the floating terminal's icon is a toggle, not a tab that can never be chosen",
  activity.toggleIsNotATab === null &&
    activity.pressedWhenShut === "false" &&
    activity.strays === 0,
  JSON.stringify({
    role: activity.toggleIsNotATab,
    pressed: activity.pressedWhenShut,
    strays: activity.strays,
  }),
);

