  seen.shown = !document.getElementById("space-picked").hidden;
  seen.says = document.getElementById("space-picked-label").textContent;
  seen.button = document.getElementById("space-remove").textContent;
  // 모두 선택은 삭제 준비가 된 것만 잡는다 — 나머지는 체크박스가 없는 것과 같다.
  document.getElementById("space-pick-all").click();
