ok(
  "the back button gives the window back, and the door now carries the figure",
  spaceBack.closed &&
    spaceBack.cancels === 0 &&
    spaceBack.compact === "회수 가능 1.50 GB / 전체 3.73 GB" &&
    spaceBack.popClosed,
  JSON.stringify(spaceBack),
);

/* ---- 브랜치 standing 하나가 버튼 하나를 정한다 --------------------------
 *
 * Orca의 결정표(resolveSourceControlPrimaryActionDecision, SourceControl-
 * xYgEJ0Pk.js:14110) — 이제 커밋 상자 아래 **하나의 프라이머리 버튼**이 전부
 * 읽는다: 미발행 → 게시, ahead&&behind → 원격이 내 커밋의 옛 사본만 들고
 * 있으면 강제 푸시로 **승격**, 아니면 동기화, behind만 → 풀, ahead만 → 푸시.
 * 최신이고 트리가 비고 리뷰가 없으면 다음 동작인 PR 만들기가 서고, 리뷰가
 * 서 있으면 비활성 커밋이 최신 상태를 입는다. 승격의 안전장치는
 * patch-equivalence 하나뿐이라 이 표가 어긋나면 남의 작업 위로 리스가 걸린다. */
const leaseLabels = await page.evaluate(async () => {
  // The decision reads the INDEX before the standing, so the table's remote
  // half is only reachable over a clean tree and an empty message — reset
  // both so this test measures the half it names.
  window.__ANSWER__.scm_status = () => ({ changed: [], ignored: [] });
  const message = document.getElementById("commit-message");
  message.value = "";
  message.dispatchEvent(new Event("input"));
  await refreshScm();
  const read = async (status) => {
    window.__ANSWER__.upstream_status = () => status;
    await refreshUpstream();
    const go = document.getElementById("scm-primary");
    return {
      label: document.getElementById("scm-primary-label").textContent,
      title: go.dataset.tip,
      disabled: go.disabled,
      glyph: document.getElementById("scm-primary-glyph").getAttribute("href"),
    };
  };
  const diverged = (equivalent) => ({
    upstream: "origin/work",
    ahead: 2,
    behind: 3,
    behind_commits_are_patch_equivalent: equivalent,
  });
  const seen = {
    publish: await read({
      upstream: null, ahead: 2, behind: 0, behind_commits_are_patch_equivalent: null,
    }),
    force: await read(diverged(true)),
    sync: await read(diverged(false)),
    // 재지 않은 물음은 `null`이고, 느슨하게 읽으면 여기서 승격이 새어 나온다.
    unmeasured: await read(diverged(null)),
    pull: await read({
      upstream: "origin/work", ahead: 0, behind: 3, behind_commits_are_patch_equivalent: null,
    }),
    push: await read({
      upstream: "origin/work", ahead: 2, behind: 0, behind_commits_are_patch_equivalent: null,
    }),
    current: await read({
      upstream: "origin/work", ahead: 0, behind: 0, behind_commits_are_patch_equivalent: null,
    }),
  };
  // 리뷰가 서 있으면 PR 문이 접히고, 남는 진실은 비활성 커밋이다. 리뷰는
  // 체크아웃과 **브랜치** 둘로 가둬져 있으므로 대상까지 세워야 서 있다.
  const keptCompare = scmCompareContext;
  scmCompareContext = { head: "work", base_ref: "main", source: null, options: [] };
  scmReview = { worktree: activeWorktreePath, branch: "work", number: 7, state: "open" };
  scmReviewAt = scmReviewTarget();
  paintScm();
  seen.reviewed = {
    label: document.getElementById("scm-primary-label").textContent,
    disabled: document.getElementById("scm-primary").disabled,
  };
  scmReview = null;
  scmReviewAt = null;
  scmCompareContext = keptCompare;
  paintScm();
  return seen;
});
ok(
  "미발행 브랜치의 버튼은 게시라고 말한다",
  leaseLabels.publish.label === "브랜치 게시" &&
    !leaseLabels.publish.disabled &&
    leaseLabels.publish.glyph === "#i-cloud-up",
  JSON.stringify(leaseLabels.publish),
);
ok(
  "원격이 옛 사본만 들고 있으면 버튼이 강제 푸시로 승격한다",
  leaseLabels.force.label === "강제 푸시 (2)" &&
    leaseLabels.force.title.includes("리스를 걸어") &&
    leaseLabels.force.title.includes("origin/work") &&
    leaseLabels.force.glyph === "#i-arrow-up",
  JSON.stringify(leaseLabels.force),
);
ok(
  "진짜 발산이면 동기화로 강등되고, 재지 않은 물음도 마찬가지다",
  leaseLabels.sync.label === "동기화 (↓3 ↑2)" &&
    leaseLabels.unmeasured.label === "동기화 (↓3 ↑2)",
  JSON.stringify([leaseLabels.sync, leaseLabels.unmeasured]),
);
ok(
  "behind만이면 풀, ahead만이면 푸시 — 그리고 풀은 Orca대로 글리프가 없다",
  leaseLabels.pull.label === "풀 (3)" &&
    leaseLabels.pull.glyph === "" &&
    leaseLabels.push.label === "푸시 (2)" &&
    leaseLabels.push.glyph === "#i-arrow-up",
  JSON.stringify([leaseLabels.pull, leaseLabels.push]),
);
ok(
  "최신이고 깨끗하면 다음 동작인 PR 만들기가 서고, 리뷰가 서 있으면 비활성 커밋이 남는다",
  leaseLabels.current.label === "PR 만들기" &&
    !leaseLabels.current.disabled &&
    leaseLabels.current.glyph === "#i-pr-arrow" &&
    leaseLabels.reviewed.label === "커밋" &&
    leaseLabels.reviewed.disabled,
  JSON.stringify([leaseLabels.current, leaseLabels.reviewed]),
);

// 승격된 버튼이 실제로 리스를 걸어 미는가.
const leasePush = await page.evaluate(async () => {
  const pushes = [];
  window.__ANSWER__.scm_push = (args) => {
    pushes.push(JSON.parse(JSON.stringify(args ?? {})));
    return null;
  };
  window.__ANSWER__.upstream_status = () => ({
    upstream: "origin/work", ahead: 2, behind: 3, behind_commits_are_patch_equivalent: true,
  });
  await refreshUpstream();
  document.getElementById("scm-primary").click();
  await new Promise((done) => setTimeout(done, 160));
  delete window.__ANSWER__.scm_push;
  return pushes;
});
ok(
  "승격된 버튼은 리스를 건 푸시 한 번을 보낸다",
  leasePush.length === 1 && leasePush[0].forceWithLease === true,
  JSON.stringify(leasePush),
);

/* 거부가 곧 재판정이다. 리스가 어긋났다는 것은 이 창이 판단한 기준선이 낡았다는
 * 뜻이므로, 페치하고 standing을 다시 읽는다 — 그 답 위에서 버튼이 스스로
 * 강등된다. 이 루프가 없으면 사람은 같은 거부를 무한히 다시 만난다. */
const leaseRefused = await page.evaluate(async () => {
  const seen = {};
  let fetched = 0;
  let asked = 0;
  window.__ANSWER__.scm_fetch = () => {
    fetched += 1;
    return null;
  };
  window.__ANSWER__.scm_push = () => {
    throw { kind: "stale-lease", text: " ! [rejected] work -> work (stale info)" };
  };
  // 첫 판정은 승격, 페치 뒤의 재조회부터는 강등이다.
  window.__ANSWER__.upstream_status = () => ({
    upstream: "origin/work",
    ahead: 2,
    behind: 3,
    behind_commits_are_patch_equivalent: (asked += 1) <= 1,
  });
  await refreshUpstream();
  seen.before = document.getElementById("scm-primary-label").textContent;
  document.getElementById("scm-primary").click();
  await new Promise((done) => setTimeout(done, 240));
  seen.fetched = fetched;
  seen.after = document.getElementById("scm-primary-label").textContent;
  const line = document.getElementById("scm-sync-error");
  seen.alert = line.textContent;
  seen.shown = !line.hidden;
  seen.role = line.getAttribute("role");
  delete window.__ANSWER__.scm_push;
  delete window.__ANSWER__.scm_fetch;
  delete window.__ANSWER__.upstream_status;
  return seen;
});
ok(
  "거부된 리스는 페치와 재조회를 부르고, 버튼은 그 답 위에서 동기화로 강등된다",
  leaseRefused.before === "강제 푸시 (2)" &&
    leaseRefused.fetched === 1 &&
    leaseRefused.after === "동기화 (↓3 ↑2)" &&
    leaseRefused.shown &&
    leaseRefused.role === "alert" &&
    leaseRefused.alert.startsWith("강제 푸시가 거부되었습니다"),
  JSON.stringify(leaseRefused),
);

/* ---- 결정표의 인덱스 절반 (Orca resolveSourceControlPrimaryActionDecision) --
 *
 * standing보다 먼저 서는 세 낯: 스테이지할 것만 있으면 **모두 스테이지**(켜짐,
 * 클릭이 stage_paths로 그 경로들을 그대로 싣는다), 스테이지만 있고 말이 없으면
 * 비활성 커밋이 이유를 입고, 말이 서면 켜져서 정말 커밋한다. */
const primaryTable = await page.evaluate(async () => {
  const seen = {};
  window.__ANSWER__.upstream_status = () =>
    ({ upstream: "origin/work", ahead: 0, behind: 0, behind_commits_are_patch_equivalent: null });
  const staged = [];
  window.__ANSWER__.stage_paths = (args) => (staged.push([...args.paths]), null);
  window.__ANSWER__.scm_status = () => ({
    changed: [
      { path: "a.rs", code: " M", staged: false, changed: true, origin: null },
      { path: "b.rs", code: "??", staged: false, changed: true, origin: null },
    ],
    ignored: [],
  });
  setActivityItem("scm");
  await refreshScm();
  const primary = document.getElementById("scm-primary");
  const label = () => document.getElementById("scm-primary-label").textContent;
  seen.stageFace =
    label() === t("sourceControl.stageAll", "모두 스테이지") &&
    !primary.disabled &&
    document.getElementById("scm-primary-glyph").getAttribute("href") === "#i-plus";
  primary.click();
  await new Promise((done) => setTimeout(done, 80));
  seen.stagedPaths = staged;
  window.__ANSWER__.scm_status = () => ({
    changed: [{ path: "a.rs", code: "M ", staged: true, changed: false, origin: null }],
    ignored: [],
  });
  await refreshScm();
  seen.needsWords =
    label() === t("sourceControl.commitAction", "커밋") &&
    primary.disabled &&
    primary.dataset.tip === t("sourceControl.enterMessage", "commit 메시지를 입력하세요");
  const message = document.getElementById("commit-message");
  message.value = "한 줄";
  message.dispatchEvent(new Event("input"));
  seen.armedByWords = !primary.disabled;
  let committed = null;
  window.__ANSWER__.commit_staged = (args) => {
    committed = args.message;
    window.__ANSWER__.scm_status = () => ({ changed: [], ignored: [] });
    return "abc1234";
  };
  primary.click();
  await new Promise((done) => setTimeout(done, 160));
  seen.committed = committed;
  delete window.__ANSWER__.commit_staged;
  delete window.__ANSWER__.stage_paths;
  delete window.__ANSWER__.upstream_status;
  return seen;
});
ok(
  "인덱스 절반: 모두 스테이지 → 말 없는 커밋은 닫히고 → 말이 서면 커밋한다",
  primaryTable.stageFace &&
    JSON.stringify(primaryTable.stagedPaths) === JSON.stringify([["a.rs", "b.rs"]]) &&
    primaryTable.needsWords &&
    primaryTable.armedByWords &&
    primaryTable.committed === "한 줄",
  JSON.stringify(primaryTable),
);

/* ---- 커밋·원격 메뉴 (Orca resolveDropdownItems) ------------------------------
 *
 * 실측 순서 그대로 열한 항목과 구분선 하나 — 충돌 연산 중에만 파괴적 Abort가
 * 구분선 뒤에 선다. 리스 승격감이면 Commit & Push의 라벨부터 강제가 되고,
 * 그 행은 커밋을 세운 뒤 리스를 건 푸시로 걷는다(runCompoundCommitAction). */
const scmMenu = await page.evaluate(async () => {
  const seen = {};
  window.__ANSWER__.scm_status = () => ({
    changed: [{ path: "a.rs", code: "M ", staged: true, changed: false, origin: null }],
    ignored: [],
  });
  window.__ANSWER__.upstream_status = () =>
    ({ upstream: "origin/work", ahead: 2, behind: 3, behind_commits_are_patch_equivalent: true });
  const message = document.getElementById("commit-message");
  message.value = "compound";
  message.dispatchEvent(new Event("input"));
  await refreshScm();
  await refreshUpstream();
  const open = () => {
    document.getElementById("scm-primary-more").click();
    return [...document.querySelectorAll("#scm-primary-menu-body .term-menu-row")];
  };
  let rows = open();
  seen.order = rows.map((one) => one.dataset.kind);
  seen.rules = document.querySelectorAll("#scm-primary-menu-body .note-pop-rule").length;
  seen.leaseLabel = rows
    .find((one) => one.dataset.kind === "commit_push")
    ?.textContent.startsWith(t("sourceControl.commitForcePush", "커밋 & 강제 푸시"));
  seen.syncShutByLease =
    rows.find((one) => one.dataset.kind === "sync")?.disabled === true &&
    rows.find((one) => one.dataset.kind === "commit_sync")?.disabled === true;
  seen.publishShut =
    rows.find((one) => one.dataset.kind === "publish")?.disabled === true &&
    rows
      .find((one) => one.dataset.kind === "publish")
      ?.textContent.includes(t("sourceControl.alreadyPublished", "브랜치가 이미 게시되어 있습니다"));
  // 컴파운드: 커밋이 선 다음, 리스 승격감이므로 강제 푸시로 걷는다.
  const walked = [];
  window.__ANSWER__.commit_staged = (args) => (walked.push(["commit", args.message]), "abc1234");
  window.__ANSWER__.scm_push = (args) => (walked.push(["push", args.forceWithLease]), null);
  rows.find((one) => one.dataset.kind === "commit_push").click();
  await new Promise((done) => setTimeout(done, 200));
  seen.walked = walked;
  seen.closedAfterPick = document.getElementById("scm-primary-menu").hidden ||
    document.getElementById("scm-primary-menu").classList.contains("is-closing");
  delete window.__ANSWER__.commit_staged;
  delete window.__ANSWER__.scm_push;
  // 충돌 연산 중에만 서는 Abort — 파괴적 잉크까지.
  window.__ANSWER__.scm_status = () => ({
    changed: [
      { path: "war.rs", code: "UU", staged: false, changed: true, origin: null, conflict: "Both modified" },
    ],
    ignored: [],
    operation: "rebase",
  });
  window.__ANSWER__.conflict_card = () => ({
    operation: "rebase", label: "Rebase conflicts", count: 1, canAbort: true, prompt: "resolve",
  });
  message.value = "";
  message.dispatchEvent(new Event("input"));
  await refreshScm();
  rows = open();
  seen.abortRow = rows.at(-1)?.dataset.kind === "abort" &&
    rows.at(-1)?.classList.contains("is-halt") &&
    rows.at(-1)?.textContent.includes(t("sourceControl.abortRebase", "리베이스 중단"));
  seen.rulesWithAbort = document.querySelectorAll("#scm-primary-menu-body .note-pop-rule").length;
  let aborted = null;
  window.__ANSWER__.abort_conflict_operation = (args) => {
    aborted = args.operation;
    window.__ANSWER__.scm_status = () => ({ changed: [], ignored: [] });
    return null;
  };
  rows.at(-1).click();
  await new Promise((done) => setTimeout(done, 160));
  seen.aborted = aborted;
  delete window.__ANSWER__.abort_conflict_operation;
  delete window.__ANSWER__.conflict_card;
  delete window.__ANSWER__.upstream_status;
  return seen;
});
ok(
  "메뉴는 실측 열한 항목을 실측 순서로 세우고, Abort는 충돌 연산 중에만 선다",
  JSON.stringify(scmMenu.order) ===
    JSON.stringify([
      "commit", "commit_push", "commit_sync",
      "push", "force_push", "create_pr", "pull", "fast_forward", "sync", "fetch", "publish",
    ]) &&
    scmMenu.rules === 1 &&
    scmMenu.leaseLabel &&
    scmMenu.syncShutByLease &&
    scmMenu.publishShut &&
    JSON.stringify(scmMenu.walked) ===
      JSON.stringify([["commit", "compound"], ["push", true]]) &&
    scmMenu.closedAfterPick &&
    scmMenu.abortRow &&
    scmMenu.rulesWithAbort === 2 &&
    scmMenu.aborted === "rebase",
  JSON.stringify(scmMenu),
);

/* ---- 섹션 헤드: 수·접기·벌크 손 (Orca SectionHeader) ------------------------ */
const scmSections = await page.evaluate(async () => {
  const seen = {};
  window.__ANSWER__.scm_status = () => ({
    changed: [
      { path: "src/a.rs", code: " M", staged: false, changed: true, origin: null },
      { path: "src/b.rs", code: "M ", staged: true, changed: false, origin: null },
      { path: "loose/c.txt", code: "??", staged: false, changed: true, origin: null },
      { path: "loose/d.txt", code: "??", staged: false, changed: true, origin: null },
    ],
    ignored: [],
  });
  await refreshScm();
  const count = (id) => document.getElementById(id).textContent;
  seen.counts = [count("scm-changed-count"), count("scm-staged-count"), count("scm-untracked-count")];
  document.getElementById("scm-changed-fold").click();
  seen.folded =
    document.getElementById("scm-changed").hidden &&
    document.getElementById("scm-changed-fold").getAttribute("aria-expanded") === "false" &&
    document.querySelectorAll("#scm-changed .scm-row").length === 0;
  document.getElementById("scm-changed-fold").click();
  seen.reopened = document.querySelectorAll("#scm-changed .scm-row").length === 1;
  const asked = [];
  window.__ANSWER__.unstage_paths = (args) => (asked.push(["unstage", ...args.paths]), null);
  window.__ANSWER__.stage_paths = (args) => (asked.push(["stage", ...args.paths]), null);
  document.getElementById("scm-staged-unstage-all").click();
  await new Promise((done) => setTimeout(done, 60));
  document.getElementById("scm-changed-stage-all").click();
  await new Promise((done) => setTimeout(done, 60));
  seen.asked = asked;
  // 추적되지 않은 전부 삭제는 실측 카피의 다이얼로그를 지나서만 걷는다.
  const doomed = [];
  window.__ANSWER__.delete_untracked = (args) => (doomed.push([...args.paths]), null);
  document.getElementById("scm-untracked-delete-all").click();
  seen.dialogUp = !document.getElementById("scm-discard-scrim").hidden;
  seen.dialogTitle = document.getElementById("scm-discard-title").textContent ===
    t("sourceControl.deleteManyTitle", "추적되지 않은 파일 {{n}}개를 삭제할까요?", { n: 2 });
  seen.dialogFiles = document.getElementById("scm-discard-files").textContent ===
    t("sourceControl.filesCount", "파일 {{n}}개", { n: 2 });
  seen.goSays = document.getElementById("scm-discard-go").textContent ===
    t("sourceControl.confirmDeleteMany", "{{n}}개 삭제", { n: 2 });
  seen.quietBeforeConfirm = doomed.length === 0;
  document.getElementById("scm-discard-go").click();
  await new Promise((done) => setTimeout(done, 80));
  seen.deleted = doomed;
  seen.dialogDown = document.getElementById("scm-discard-scrim").hidden;
  // 취소의 길: 아무것도 걷지 않는다.
  document.getElementById("scm-changed-discard-all").click();
  document.getElementById("scm-discard-cancel").click();
  seen.cancelledQuiet = doomed.length === 1;
  delete window.__ANSWER__.unstage_paths;
  delete window.__ANSWER__.stage_paths;
  delete window.__ANSWER__.delete_untracked;
  return seen;
});
ok(
  "섹션 헤드는 수를 세고 접히며, 벌크 손은 제 구역의 경로를 싣고 삭제는 다이얼로그를 지난다",
  JSON.stringify(scmSections.counts) === JSON.stringify(["1", "1", "2"]) &&
    scmSections.folded &&
    scmSections.reopened &&
    JSON.stringify(scmSections.asked) ===
      JSON.stringify([["unstage", "src/b.rs"], ["stage", "src/a.rs"]]) &&
    scmSections.dialogUp &&
    scmSections.dialogTitle &&
    scmSections.dialogFiles &&
    scmSections.goSays &&
    scmSections.quietBeforeConfirm &&
    JSON.stringify(scmSections.deleted) === JSON.stringify([["loose/c.txt", "loose/d.txt"]]) &&
    scmSections.dialogDown &&
    scmSections.cancelledQuiet,
  JSON.stringify(scmSections),
);

/* ---- 행의 손: 폐기·복원·삭제·스테이지 (Orca UncommittedEntryRow) ------------ */
const scmHands = await page.evaluate(async () => {
  const seen = {};
  window.__ANSWER__.scm_status = () => ({
    changed: [
      { path: "src/mod.rs", code: " M", staged: false, changed: true, origin: null },
      { path: "src/gone.rs", code: " D", staged: false, changed: true, origin: null },
      { path: "src/idx.rs", code: "M ", staged: true, changed: false, origin: null },
      { path: "new.txt", code: "??", staged: false, changed: true, origin: null },
      { path: "war.rs", code: "UU", staged: false, changed: true, origin: null, conflict: "Both modified" },
    ],
    ignored: [],
  });
  await refreshScm();
  const hands = (root) =>
    [...document.querySelectorAll(`${root} .scm-row`)].map((row) =>
      [...row.querySelectorAll(".scm-act")].map((one) => one.getAttribute("aria-label")));
  seen.handsMatch =
    JSON.stringify(hands("#scm-changed")) ===
      JSON.stringify([
        [t("sourceControl.discardChanges", "변경사항 취소"), t("sourceControl.stage", "스테이지에 올리기")],
        [t("sourceControl.restoreFile", "파일 복원"), t("sourceControl.stage", "스테이지에 올리기")],
      ]) &&
    JSON.stringify(hands("#scm-staged")) ===
      JSON.stringify([[t("sourceControl.unstage", "스테이지에서 내리기")]]) &&
    JSON.stringify(hands("#scm-untracked")) ===
      JSON.stringify([
        [t("sourceControl.deleteUntrackedFile", "추적되지 않은 파일 삭제"), t("sourceControl.stage", "스테이지에 올리기")],
      ]) &&
    JSON.stringify(hands("#scm-conflicts")) === JSON.stringify([[]]);
  const dropped = [];
  window.__ANSWER__.discard_paths = (args) => (dropped.push([...args.paths]), null);
  document.querySelector("#scm-changed .scm-row .scm-act").click();
  seen.entryTitle = document.getElementById("scm-discard-title").textContent ===
    t("sourceControl.discardEntryTitle", "\"{{name}}\"의 변경을 폐기할까요?", { name: "mod.rs" });
  seen.noFilesBox = document.getElementById("scm-discard-files").hidden;
  seen.goFocused = document.activeElement === document.getElementById("scm-discard-go");
  document.getElementById("scm-discard-go").click();
  await new Promise((done) => setTimeout(done, 80));
  seen.dropped = dropped;
  delete window.__ANSWER__.discard_paths;
  delete window.__ANSWER__.scm_status;
  await refreshScm();
  return seen;
});
ok(
  "행의 손은 종류대로 서고, 폐기는 파일의 이름을 부르며 묻고서야 걷는다",
  scmHands.handsMatch &&
    scmHands.entryTitle &&
    scmHands.noFilesBox &&
    scmHands.goFocused &&
    JSON.stringify(scmHands.dropped) === JSON.stringify([["src/mod.rs"]]),
  JSON.stringify(scmHands),
);

/* ---- 캡 배너 (Orca TooManyChangesBanner) ------------------------------------
 *
 * 백엔드가 잘랐다고 답하면 앰버 카드가 백엔드의 limit을 그대로 인용해 서고,
 * 다시 시도는 딱 한 번 uncapped로 다시 묻는다 — 그 다음의 평범한 새로고침은
 * 도로 캡을 쓴다(Orca resolveGitStatusLimit(0)의 길). */
// A prior discard can still finish its refresh after the 80 ms fixture wait.
// Give this exact request-count assertion its own window, as the ledger probe does.
const scmCappedPage = await browser.newPage();
await standBackend(scmCappedPage);
await scmCappedPage.goto(`${origin}/index.html`);
await scmCappedPage.waitForFunction(() => typeof BOUND !== "undefined" && BOUND.size > 0);
await scmCappedPage.evaluate(async () => { setActivityItem("scm"); await refreshScm(); });
const scmCappedBanner = await scmCappedPage.evaluate(async () => {
  const seen = {};
  const askedWith = [];
  const one = { path: "a.rs", code: " M", staged: false, changed: true, origin: null };
  window.__ANSWER__.scm_status = (args) => {
    askedWith.push(Boolean(args?.uncapped));
    return args?.uncapped
      ? { changed: [one], ignored: [], capped: false, total: 1500, limit: 1000 }
      : { changed: [one], ignored: [], capped: true, total: 1500, limit: 1000 };
  };
  await refreshScm();
  const card = document.getElementById("scm-capped");
  seen.up = !card.hidden;
  seen.words = document.getElementById("scm-capped-word").textContent ===
    t("sourceControl.capped", "변경 사항이 너무 많이 감지되었습니다. 처음 {{n}}개만 표시됩니다.", {
      n: (1000).toLocaleString(),
    });
  document.getElementById("scm-capped-retry").click();
  await new Promise((done) => setTimeout(done, 100));
  seen.askedWith = askedWith;
  seen.down = card.hidden;
  window.__ANSWER__.scm_status = () => ({ changed: [], ignored: [] });
  const message = document.getElementById("commit-message");
  message.value = "";
  message.dispatchEvent(new Event("input"));
  await refreshScm();
  setActivityItem("files");
  return seen;
});
ok(
  "캡은 백엔드의 판정과 숫자로 서고, 다시 시도는 한 번만 uncapped로 묻는다",
  scmCappedBanner.up &&
    scmCappedBanner.words &&
    JSON.stringify(scmCappedBanner.askedWith) === JSON.stringify([false, true]) &&
    scmCappedBanner.down,
  JSON.stringify(scmCappedBanner),
);
await scmCappedPage.close();

/* ---- 스트리밍 폭풍 아래에서 창이 실제로 한 일 (1-ep) ----------------------
 *
 * 신고는 "에이전트 여럿이 쏟아 내는 동안 타이핑이 너무 심하게 밀린다"였고,
 * 두 축이 그것을 만든다. 하나는 **아무도 보고 있지 않은 셸의 프레임**을
 * 웹뷰가 계속 뜯어야 했던 것이고, 하나는 훅 하나가 도착할 때마다 탭·카드·
 * 배지·보드를 각각 다시 그린 것이다. 여기서는 그 둘을 센다.
 *
 * 프레임을 배달하는 쪽은 목이 아니라 **백엔드의 문 그대로**다: 펌프는 창이
 * `set_watched_terms`로 선언한 집합에 든 셸의 프레임만 내보내므로(main.rs
 * `pump_loop`), 이 하네스도 창이 말한 그 집합만 배달한다. 선언이 없으면
 * 전부 배달되고, 그것이 이 표의 "이전" 열이다 — 목이 스스로 지어낸 숫자가
 * 아니라, 게이트가 없을 때 실제로 벌어지던 일이다. 게이트가 Rust 쪽에
 * 실제로 있다는 것은 Rust 게이트가 따로 못박는다. */
// Only the burst belongs in this count. A worktree-stamp poll can request a
// second card paint inside the 300ms observation window, independently of
// the hooks. Use the harness's existing poller park and drain prior work.
const stormPollerState = await page.evaluate(() => {
  const state = { held: window.__HOLD_POLLERS__, paneAgents: window.__POLLERS__.has("pane_agents") };
  // The burst's own badge snapshot must still answer; only unrelated clocks
  // are parked. This command is also used by a periodic state repair.
  window.__POLLERS__.delete("pane_agents");
  return state;
});
await holdPollers(true);
await page.evaluate(() => window.__SETTLED__());
const storm = await page.evaluate(async () => {
  const seen = {};
  // 앞선 시험들이 남긴 것을 먼저 치운다 — 폭풍은 이 넷만의 것이어야 한다.
  // 창의 30초 심장(경과 낱말 박자)은 재운다: 심장이 두드릴 것이 남아 있으면
  // 카드를 한 번 두드리고 `pane_agents`를 한 번 묻는데, 앞선 시험들이 남긴
  // 위상에서 박동이 이 계수 창에 떨어지는 위상 룰렛이 있었다 — 시험을 하나
  // 더할 때마다 위상이 옮겨져 초록과 붉음이 뒤바뀌었다. 심장이 멈추고 나면
  // 폭풍의 첫 훅이 다시 깨우더라도 위상 0에서 시작하므로 첫 박동은 30초 뒤 —
  // 이 300ms 계수 창 바깥이다.
  //
  // 멈췄는지는 심장 자신에게 묻는다(`agentClockWanted`). 이 자리는 한때 "세
  // 맵"을 비우는 목록이었는데, 심장의 판정이 넷째 맵(`paneAgents`)과 레인
  // 헬퍼까지 읽게 된 뒤에도 목록은 그대로였고, 앞선 시나리오가 화면 없는
  // codex 판 하나(term 7803)를 남기자 심장은 옛 위상으로 계속 뛰었다 — v1.3.103
  // 레인에서 카드 2·`pane_agents` 하나 더, 세 번에 두 번. 그래서 치우기는 창이
  // 끝난 셸을 잊는 문(`dropTermView`)과 레인을 비우는 문을 지나고, 심장이 여전히
  // 뛸 이유가 있으면 아래 판정이 그 자리에서 빨갛게 말한다.
  hookStates.clear();
  paneModels.clear();
  paneSessions.clear();
  for (const tab of [...tabs]) dropTab(tab.id);
  for (const term of new Set([...termViews.keys(), ...paneAgents.keys()])) dropTermView(term);
  for (const session of [...laneSubagents.keys()]) clearLaneSubagents(session);
  agentClock.sync();
  seen.clockQuiet = !agentClockWanted();
  setTermVisible(false);
  await new Promise((done) => setTimeout(done, 60));

  // 뒤에 선 셋과, 앞에 선 하나. 마지막에 연 탭이 무대에 오른다.
  const behind = [
    await openTermTab({ placement: "tab" }),
    await openTermTab({ placement: "tab" }),
    await openTermTab({ placement: "tab" }),
  ];
  const front = await openTermTab({ placement: "tab" });
  const all = [...behind, front];
  await new Promise((done) => setTimeout(done, 120));
  seen.hidden = behind.every((term) => termViews.get(term)?.host.hidden === true);
  seen.front = termViews.get(front)?.host.hidden === false;

  // 다시 그린 횟수는 함수 자체를 감싸서 센다. `shell.js`는 고전 스크립트라
  // 최상위 선언이 전역 바인딩이고, 내부 호출도 이 바인딩을 지난다.
  const counted = { tabs: 0, cards: 0, frames: 0 };
  const realTabs = window.renderTabs;
  const realCards = window.paintWorktreeAgents;
  window.renderTabs = (...rest) => (counted.tabs += 1, realTabs(...rest));
  window.paintWorktreeAgents = (...rest) => (counted.cards += 1, realCards(...rest));

  const row = (text) => ({ index: 0, cells: [...text].map((ch) => ({ ch })) });
  const delta = (n) => ({
    rows: [row(`... 줄 ${n}`)],
    scrolled_lines: 0,
    cursor: [0, 0],
    title: null,
    alt_screen: false,
    size: [24, 80],
    full: false,
    cursor_visible: true,
    mouse_tracking: "off",
    mouse_sgr: false,
    bell: false,
    view_offset: 0,
    scrollback_len: 0,
  });
  const feed = (term, payload) => {
    if (window.__WATCHED_TERMS__ && !window.__WATCHED_TERMS__.has(term)) return Promise.resolve();
    counted.frames += 1;
    return window.__TERM_FEED__(term, payload);
  };
  const hook = (term, state) => {
    for (const handler of window.__LISTENERS__["hook:agent"] ?? []) {
      handler({ payload: { term, state, agent: "claude", session: null, resumable: false } });
    }
  };
  const STATES = ["working", "needs-attention", "done", "working", "needs-attention"];

  const priorStamp = worktreeStamp;
  const priorStampAnswer = window.__ANSWER__.worktree_stamp;
  worktreeStamp = "storm-before";
  window.__ANSWER__.worktree_stamp = () => "storm-during";
  window.__COUNTS__ = {};
  counted.frames = 0;
  counted.tabs = 0;
  counted.cards = 0;
  // 뒤에 선 셋이 각각 예순 프레임, 그 사이사이에 훅 스무 번. 한 덩어리로
  // 흘린다 — IPC 한 번이 여러 이벤트를 함께 게워 내는 모습이 그것이고,
  // 프레임 하나 안에 몇 번이 도착하든 화면은 한 번만 그려져야 한다.
  for (let n = 0; n < 60; n += 1) {
    for (const term of behind) feed(term, delta(n));
    if (n % 3 === 0) {
      const at = n / 3;
      hook(all[at % all.length], STATES[Math.floor(at / all.length) % STATES.length]);
    }
  }
  // Force the independent poll into the measured window: forgetting to
  // park it must fail deterministically, not only at a lucky timer phase.
  void lookForCheckoutsNobodyAskedFor();
  await new Promise((done) => setTimeout(done, 300));

  seen.framesParsed = counted.frames;
  seen.tabRepaints = counted.tabs;
  seen.cardRepaints = counted.cards;
  seen.finalStates = all.map((term) => hookStates.get(term));
  seen.badgeAsks = window.__COUNTS__.board_snapshot ?? 0;
  seen.roundTrips = Object.values(window.__COUNTS__).reduce((sum, one) => sum + one, 0);

  // 앞에 선 셸의 프레임은 여전히 온다. 게이트가 화면을 끄는 것이었다면 이
  // 줄이 그것을 잡는다.
  const before = counted.frames;
  await feed(front, delta(999));
  await new Promise((done) => setTimeout(done, 40));
  seen.frontStillPaints = counted.frames - before === 1 &&
    termViews.get(front)?.pre.textContent.includes("줄 999");

  worktreeStamp = priorStamp;
  if (priorStampAnswer) window.__ANSWER__.worktree_stamp = priorStampAnswer;
  else delete window.__ANSWER__.worktree_stamp;
  window.renderTabs = realTabs;
  window.paintWorktreeAgents = realCards;
  for (const tab of [...tabs]) dropTab(tab.id);
  for (const at of [...termViews.keys()]) dropTermView(at);
  return seen;
});
ok(
  "아무도 보고 있지 않은 셸의 프레임은 창까지 오지 않는다",
  storm.hidden && storm.front && storm.framesParsed === 0 && storm.frontStillPaints,
  JSON.stringify(storm),
);
ok(
  "폭풍을 세는 동안 창의 경과 시계는 멈춰 있다 — 박동이 계수 창에 떨어지는 위상 룰렛이 없다",
  storm.clockQuiet,
  JSON.stringify(storm),
);
ok(
  "훅이 스무 번 와도 한 프레임에 한 번씩만 다시 그린다",
  storm.tabRepaints === 1 && storm.cardRepaints === 1 && storm.badgeAsks === 1 &&
    storm.finalStates.every((state) => state === "needs-attention"),
  JSON.stringify(storm),
);
await page.evaluate((state) => { if (state.paneAgents) window.__POLLERS__.add("pane_agents"); }, stormPollerState);
await holdPollers(stormPollerState.held);

/* ---- 다시 앞에 선 화면은 바닥부터 받는다 (1-ep) --------------------------
 *
 * 프레임을 멈춘 값이 여기서 치러진다: 배경에 있던 뷰의 모델은 떠날 때 모습
 * 그대로이므로, 돌아온 탭은 지금의 화면을 한 장 받아야 한다. 순서가 이 시험의
 * 요점이다 — **읽는다는 선언이 먼저 닿아야** 백엔드가 이 창을 바닥을 빚진
 * 독자로 세우고, 그 뒤의 당김이 그 빚을 화면 전체로 갚는다. 그 사이에 난
 * 변경은 사라지는 대신 바닥 뒤에 이어진다(`FrameReaders::declare`). */
const revealing = await page.evaluate(async () => {
  const seen = {};
  for (const tab of [...tabs]) dropTab(tab.id);
  for (const at of [...termViews.keys()]) dropTermView(at);
  await new Promise((done) => setTimeout(done, 80));

  const behind = await openTermTab({ placement: "tab" });
  const behindTab = tabOfTerm(behind).id;
  await openTermTab({ placement: "tab" });
  await new Promise((done) => setTimeout(done, 120));
  seen.hidden = termViews.get(behind)?.host.hidden === true;
  seen.notDeclared = !(window.__WATCHED_TERMS__ ?? new Set()).has(behind);

  const wasSnapshot = window.__SNAPSHOT_TEXT__;
  window.__SNAPSHOT_TEXT__ = "그동안 밀린 화면";
  window.__ORDER__ = [];
  setActiveTab(behindTab);
  await new Promise((done) => setTimeout(done, 200));
  seen.order = window.__ORDER__.filter(
    (one) => one === "set_watched_terms" || one === "term_pull",
  );
  window.__ORDER__ = null;
  window.__SNAPSHOT_TEXT__ = wasSnapshot;

  seen.declaredNow = (window.__WATCHED_TERMS__ ?? new Set()).has(behind);
  seen.caughtUp = termViews.get(behind)?.pre.textContent.includes("그동안 밀린 화면");
  for (const tab of [...tabs]) dropTab(tab.id);
  for (const at of [...termViews.keys()]) dropTermView(at);
  return seen;
});
ok(
  "배경에 있던 화면은 앞에 서면서 먼저 감시를 선언하고, 그 다음 당김에서 바닥을 받는다",
  revealing.hidden &&
    revealing.notDeclared &&
    revealing.declaredNow &&
    revealing.order[0] === "set_watched_terms" &&
    revealing.order.includes("term_pull") &&
    revealing.caughtUp,
  JSON.stringify(revealing),
);

/* A reveal's floor and what the shell printed meanwhile arrive as ONE answer.
 * The pull that pays a newly read shell its floor can still be in the air
 * while the shell keeps printing; those frames belong AFTER the floor, in the
 * order they were printed, and the old picture stays on screen for that one
 * round trip. Painted once: the answer is several frames of one screen, and a
 * frame no person could have seen costs no DOM work. */
const streamingReveal = await page.evaluate(async () => {
  const seen = {};
  for (const tab of [...tabs]) dropTab(tab.id);
  for (const at of [...termViews.keys()]) dropTermView(at);
  await new Promise((done) => setTimeout(done, 80));

  const line = (index, text) => ({
    index,
    cells: [...text.padEnd(24, " ")].map((ch) => ({ ch })),
  });
  const frame = (rows, full = true, scrolledLines = 0) => ({
    rows,
    scrolled_lines: scrolledLines,
    cursor: [2, 0],
    title: null,
    alt_screen: false,
    size: [3, 24],
    full,
    cursor_visible: true,
    mouse_tracking: "off",
    mouse_sgr: false,
    focus_reporting: false,
    bell: false,
    view_offset: 0,
    scrollback_len: 0,
  });
  const feed = (term, delta) => window.__TERM_FEED__(term, delta);
  const painted = (term) => [...termViews.get(term).pre.querySelectorAll(":scope > .term-row")]
    .map((row) => row.textContent.trimEnd());

  const term = await openTermTab({ placement: "tab" });
  const termTab = tabOfTerm(term).id;
  await new Promise((done) => setTimeout(done, 100));
  await feed(term, frame([line(0, "ancient 0"), line(1, "ancient 1"), line(2, "ancient 2")]));
  const ancient = painted(term);

  await openTermTab({ placement: "tab" });
  await new Promise((done) => setTimeout(done, 100));
  window.__ANSWER__.term_snapshot = (args) => (args.term === term
    ? frame([line(0, "snapshot 0"), line(1, "snapshot 1"), line(2, "snapshot 2")])
    : null);
  // The reveal's pull, held in the air. Released, it answers with whatever
  // the backend holds by then — the floor, and every frame fed since.
  let releasePull = null;
  window.__ANSWER__.term_pull = (args) => new Promise((resolve) => {
    releasePull = () => {
      delete window.__ANSWER__.term_pull;
      resolve(window.__TAURI__.core.invoke("term_pull", args));
    };
  });
  const view = termViews.get(term);
  const applyFrames = view.applyFrames;
  const paints = [];
  view.applyFrames = (frames) => {
    paints.push(frames.length);
    return applyFrames(frames);
  };
  setActiveTab(termTab);
  for (let wait = 0; releasePull === null && wait < 50; wait += 1) {
    await new Promise((done) => setTimeout(done, 2));
  }

  const printed = [
    feed(term, frame([line(2, "delta one")], false, 1)),
    feed(term, frame([line(2, "delta two")], false, 1)),
  ];
  seen.unchangedWhilePending = JSON.stringify(painted(term)) === JSON.stringify(ancient);
  releasePull?.();
  await Promise.all(printed);
  seen.final = painted(term);
  seen.expected = ["snapshot 2", "delta one", "delta two"];
  seen.paints = paints;

  view.applyFrames = applyFrames;
  delete window.__ANSWER__.term_pull;
  delete window.__ANSWER__.term_snapshot;
  for (const tab of [...tabs]) dropTab(tab.id);
  for (const at of [...termViews.keys()]) dropTermView(at);
  return seen;
});
ok(
  "a streaming reveal paints its floor and the frames printed meanwhile as one answer, in order, once",
  streamingReveal.unchangedWhilePending &&
    JSON.stringify(streamingReveal.final) === JSON.stringify(streamingReveal.expected) &&
    JSON.stringify(streamingReveal.paints) === "[3]",
  JSON.stringify(streamingReveal),
);

/* A pull that fails may have cost frames the backend already took for it, so
 * the next one asks for every screen whole (`resync`) — and it comes on the
 * next display frame, not at the next notice: a shell that has gone still
 * sends no notice, and its screen would keep the hole. The retry of a failure
 * does not retry itself; a backend that keeps refusing is asked again only
 * when it says there is something to take. */
const failedPull = await page.evaluate(async () => {
  for (const tab of [...tabs]) dropTab(tab.id);
  for (const at of [...termViews.keys()]) dropTermView(at);
  await new Promise((done) => setTimeout(done, 80));

  const term = await openTermTab({ placement: "tab" });
  const termTab = tabOfTerm(term).id;
  await new Promise((done) => setTimeout(done, 100));
  await openTermTab({ placement: "tab" });
  await new Promise((done) => setTimeout(done, 100));

  window.__ANSWER__.term_snapshot = (args) => (args.term !== term ? null : {
    rows: [{ index: 0, cells: [..."resync found the floor"].map((ch) => ({ ch })) }],
    scrolled_lines: 0,
    cursor: [0, 0],
    title: null,
    alt_screen: false,
    size: [3, 24],
    full: true,
    cursor_visible: true,
    mouse_tracking: "off",
    mouse_sgr: false,
    focus_reporting: false,
    bell: false,
    view_offset: 0,
    scrollback_len: 0,
  });
  // Every pull's `resync`, in order; the first is refused.
  const asked = [];
  const pull = (args) => {
    asked.push(args?.resync === true);
    if (asked.length === 1) throw new Error("refused: term_pull");
    delete window.__ANSWER__.term_pull;
    try {
      return window.__TAURI__.core.invoke("term_pull", args);
    } finally {
      window.__ANSWER__.term_pull = pull;
    }
  };
  window.__ANSWER__.term_pull = pull;
  setActiveTab(termTab);
  await new Promise((done) => setTimeout(done, 150));
  const answer = {
    asked: asked.slice(0, 2),
    screen: termViews.get(term)?.pre.textContent ?? "",
  };

  // Now a backend that refuses every time, told once that there are frames.
  const refused = [];
  window.__ANSWER__.term_pull = (args) => {
    refused.push(args?.resync === true);
    throw new Error("refused: term_pull");
  };
  for (const hear of window.__LISTENERS__[`term:dirty:${WINDOW_LABEL}`] ?? []) hear({ payload: null });
  await new Promise((done) => setTimeout(done, 150));
  answer.refused = refused;
  delete window.__ANSWER__.term_pull;
  // The hole the refusals left is the next pull's to fill.
  for (const hear of window.__LISTENERS__[`term:dirty:${WINDOW_LABEL}`] ?? []) hear({ payload: null });
  await new Promise((done) => setTimeout(done, 60));

  delete window.__ANSWER__.term_snapshot;
  for (const tab of [...tabs]) dropTab(tab.id);
  for (const at of [...termViews.keys()]) dropTermView(at);
  return answer;
});
ok(
  "a failed pull asks again on the next display frame for every screen whole, and paints that floor",
  JSON.stringify(failedPull.asked) === "[false,true]" &&
    failedPull.screen.includes("resync found the floor"),
  JSON.stringify(failedPull),
);
ok(
  "and a backend that keeps refusing is asked twice per notice, not in a loop",
  JSON.stringify(failedPull.refused) === "[false,true]",
  JSON.stringify(failedPull),
);

/* A declaration made while a pull is in the air is answered by the very next
 * pull, at once — not on a display frame. A hidden window has no display
 * frames, and every later declaration queues behind this one (`watchTail`):
 * waiting for a frame there is a window that never reads another shell. The
 * hidden window is modelled as the one thing it is to this code, a
 * `requestAnimationFrame` that does not come back. */
const declaredWhileHidden = await page.evaluate(async () => {
  for (const tab of [...tabs]) dropTab(tab.id);
  for (const at of [...termViews.keys()]) dropTermView(at);
  await new Promise((done) => setTimeout(done, 80));

  const shown = await openTermTab({ placement: "tab" });
  await syncWatchedTerms();
  // A flowing screen's pull, held in the air.
  let releasePull = null;
  window.__ANSWER__.term_pull = (args) => new Promise((resolve) => {
    releasePull = () => {
      delete window.__ANSWER__.term_pull;
      resolve(window.__TAURI__.core.invoke("term_pull", args));
    };
  });
  const printed = window.__TERM_FEED__(shown, {
    rows: [{ index: 0, cells: [..."still printing"].map((ch) => ({ ch })) }],
    scrolled_lines: 0, cursor: [0, 0], title: null, alt_screen: false, size: [3, 24],
    full: true, cursor_visible: true, mouse_tracking: "off", mouse_sgr: false,
    focus_reporting: false, bell: false, view_offset: 0, scrollback_len: 0,
  });
  for (let wait = 0; releasePull === null && wait < 50; wait += 1) {
    await new Promise((done) => setTimeout(done, 2));
  }

  // The window goes where no display frame comes, and reads another shell.
  const frames = window.requestAnimationFrame;
  const withheld = [];
  window.requestAnimationFrame = (callback) => withheld.push(callback);
  let settled = false;
  try {
    const second = await openTermTab({ placement: "tab" });
    const declared = syncWatchedTerms().then(() => {
      settled = true;
    });
    releasePull?.();
    await Promise.race([declared, new Promise((done) => setTimeout(done, 300))]);
    return { held: releasePull !== null, settled, second, reading: [...watchedTerms] };
  } finally {
    window.requestAnimationFrame = frames;
    for (const callback of withheld.splice(0)) frames(callback);
    await printed;
    for (const tab of [...tabs]) dropTab(tab.id);
    for (const at of [...termViews.keys()]) dropTermView(at);
  }
});
ok(
  "a declaration made while a pull is in the air settles without waiting for a display frame",
  declaredWhileHidden.held && declaredWhileHidden.settled,
  JSON.stringify(declaredWhileHidden),
);

/* ---- 앞에 선 화면 하나가 치르는 값 (1-ew) --------------------------------
 *
 * 1-ep이 껐던 것은 **아무도 보고 있지 않은** 셸의 값이었다. 여기서 재는 것은
 * 그 다음 질문이다: 사람이 실제로 **보고 있는** 셸 하나에 에이전트가 쏟아부을
 * 때, 그 한 장이 이 창에서 얼마짜리인가.
 *
 * 하네스가 짓는 폭풍은 실제 에이전트가 그리는 모양을 흉내 낸다 — 300장,
 * 장마다 20~40줄이 바뀌고, 대부분의 장이 한두 줄씩 밀려 올라가며, 줄 안에는
 * SGR 색 구간과 두 칸을 먹는 한글이 섞인다. 값은 세 갈래로 나누어 잰다:
 *
 *   - **바이트**: 한 장의 JSON이 몇 자인가. IPC가 나르는 것이 이것이다.
 *   - **parse**: 그 JSON을 객체로 되돌리는 데 든 시간. 창이 그리기 **전에**
 *     이미 치른 값이고, 프레임 수를 줄이는 것 말고는 깎을 방법이 없는 값이다.
 *   - **apply**: 당김의 답을 받는 손(`applyTermFrames`) 전체 — 마우스 모드,
 *     제목, 격자 크기, 그리고 화면 그리기. 당김은 제 박자대로 오므로 흘린
 *     쪽의 시계로는 이 값을 잴 수 없다; 그 손 안에서 잰다.
 *
 * 그리고 DOM 쪽 두 가지: 새로 만든 `span`의 수(재사용이 듣고 있는가)와,
 * 폭풍 동안 강제된 레이아웃의 수(그리는 길에서 재면 안 된다).
 *
 * 마지막으로 폭풍 한가운데서 탭을 한 번 갈아탄다. 사람이 느끼는 "탭 전환이
 * 무겁다"는 바로 그 한 번이다.
 *
 * 숫자 자체는 기계마다 다르므로 **못박지 않는다** — 못박는 것은 모양이다:
 * 안 바뀐 줄은 다시 입히지 않는다, 그리는 길에서 레이아웃을 읽지 않는다.
 * 시간과 바이트는 `detail`로 찍혀 나가고, 그 값이 장부에 남는다. */
const BURST = { frames: 300, rows: 40, cols: 100, least: 20, most: 40 };

const burst = await page.evaluate(async (plan) => {
  const seen = {};
  for (const tab of [...tabs]) dropTab(tab.id);
  for (const at of [...termViews.keys()]) dropTermView(at);
  setTermVisible(false);
  await new Promise((done) => setTimeout(done, 60));

  // 뒤에 하나, 앞에 하나. 뒤의 것은 폭풍 한가운데서 갈아탈 자리다.
  const behind = await openTermTab({ placement: "tab" });
  const front = await openTermTab({ placement: "tab" });
  const behindTab = tabOfTerm(behind).id;
  const frontTab = tabOfTerm(front).id;
  await new Promise((done) => setTimeout(done, 160));
  seen.frontVisible = termViews.get(front)?.host.hidden === false;

  /* 씨앗을 박은 난수 — 같은 폭풍을 두 번 흘려야 "전"과 "후"가 같은 일을
   * 두고 하는 말이 된다. */
  let grain = 20260813;
  const rand = () => ((grain = (grain * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
  const WORDS = [
    "reading", "grid.rs", "apply", "터미널", "패턴을", "→", "ok", "1185",
    "crates/zerocode-pty/src/grid.rs", "…", "done", "실패", "0.42s",
  ];
  // 대부분의 칸은 아무 스타일도 달고 오지 않는다(`skip_serializing_if`), 그래서
  // 표의 앞쪽이 비어 있다 — 실제 화면의 비율이 그렇다.
  const PALETTE = [
    null, null, null, null,
    { fg: { indexed: 2 } },
    { fg: { indexed: 4 }, bold: true },
    { fg: { indexed: 1 } },
    { fg: { indexed: 7 }, bg: { indexed: 8 } },
    { fg: { rgb: [180, 140, 90] }, italic: true },
    { dim: true },
  ];
  const WIDE = /[가-힣぀-ヿ一-鿿]/;
  const lineOf = () => {
    const cells = [];
    while (cells.length < plan.cols) {
      const dress = PALETTE[Math.floor(rand() * PALETTE.length)];
      const word = WORDS[Math.floor(rand() * WORDS.length)];
      for (const ch of word) {
        if (cells.length >= plan.cols) break;
        // 칸마다 새 객체 — IPC가 건네는 것이 그것이다. 하나를 나눠 쓰면
        // `sameStyle`이 참조로 빠져나갈 길이 생겨 측정이 거짓말을 한다.
        cells.push(dress ? { ch, style: { ...dress } } : { ch });
        if (WIDE.test(ch) && cells.length < plan.cols) {
          cells.push(dress ? { ch: "\u0000", style: { ...dress } } : { ch: "\u0000" });
        }
      }
      if (cells.length < plan.cols) cells.push({ ch: " " });
    }
    return cells;
  };

  const payloads = [];
  let scrollback = 0;
  for (let n = 0; n < plan.frames; n += 1) {
    const changed = plan.least + Math.floor(rand() * (plan.most - plan.least + 1));
    const scrolled = rand() < 0.7 ? 1 + Math.floor(rand() * 2) : 0;
    scrollback += scrolled;
    const rows = [];
    for (let at = Math.max(0, plan.rows - changed); at < plan.rows; at += 1) {
      rows.push({ index: at, cells: lineOf() });
    }
    payloads.push(JSON.stringify({
      rows,
      scrolled_lines: scrolled,
      cursor: [plan.rows - 1, 12],
      title: null,
      alt_screen: false,
      size: [plan.rows, plan.cols],
      full: false,
      cursor_visible: true,
      mouse_tracking: "off",
      mouse_sgr: false,
      focus_reporting: false,
      bell: false,
      view_offset: 0,
      scrollback_len: scrollback,
    }));
  }
  seen.bytes = payloads.reduce((sum, one) => sum + one.length, 0);
  seen.frameBytes = Math.round(seen.bytes / payloads.length);

  const deliver = (term, delta) => window.__TERM_FEED__(term, delta);
  /* 한 장의 값은 두 토막이다: JSON을 객체로 되돌리는 시간과, 그 객체를 화면에
   * 붓는 시간. 따로 재는 이유는 깎을 수 있는 쪽이 서로 다르기 때문이다 —
   * 앞쪽은 장 수로만 줄고, 뒤쪽은 그리는 길로 준다.
   *
   * 붓는 쪽은 당김의 답을 받는 손 안에서 잰다. `painting`은 그 손 안에 있는
   * 동안만 참이라, 아래의 셈이 그리는 길 밖의 일을 세지 않는다.
   *
   * 장은 **하나씩** 흘리고 그 장이 칠해지기를 기다린다 — 화면이 펌프의 박자를
   * 따라가는 기계에서 폭풍이 오는 모양이 그것이다(당김 하나에 장 하나). 한꺼번에
   * 흘리면 창은 그 장들을 한 답으로 당겨 순 변화만 한 번 칠하므로(규칙 7), 그때
   * 재는 값은 한 장이 아니라 한 답의 값이고, 같은 폭풍을 두 번 부으면 순 변화가
   * 없어 DOM에 한 자도 안 쓴다. 느린 화면이 여러 장을 한 번에 가져가는 모양은
   * M2(`terminal-pacing.mjs`)가 잰다. */
  const applyTermFramesAsShipped = window.applyTermFrames;
  const meter = { apply: 0, painting: false };
  window.applyTermFrames = (...rest) => {
    const started = performance.now();
    meter.painting = true;
    try {
      return applyTermFramesAsShipped(...rest);
    } finally {
      meter.painting = false;
      meter.apply += performance.now() - started;
    }
  };
  const run = async (term, from, to) => {
    let parse = 0;
    const applied = meter.apply;
    for (let n = from; n < to; n += 1) {
      const opened = performance.now();
      const delta = JSON.parse(payloads[n]);
      parse += performance.now() - opened;
      await deliver(term, delta);
    }
    return { parse, apply: meter.apply - applied };
  };

  // 몸을 푼다. 첫 장은 span을 전부 짓는 장이라 정상 상태의 값이 아니다.
  await run(front, 0, 30);

  // ---- 1) 시간: 아무것도 감싸지 않은 채로 ----
  const first = await run(front, 0, Math.floor(plan.frames / 2));
  // ---- 2) 폭풍 한가운데의 탭 전환 한 번 ----
  const leaving = performance.now();
  setActiveTab(behindTab);
  seen.switchAway = performance.now() - leaving;
  const coming = performance.now();
  setActiveTab(frontTab);
  seen.switchBack = performance.now() - coming;
  // 두 전환의 선언이 닿은 뒤에 폭풍을 잇는다 — 아무 창도 읽지 않는 셸의
  // 프레임은 백엔드에서 멈춘다.
  await syncWatchedTerms();
  const second = await run(front, Math.floor(plan.frames / 2), plan.frames);
  seen.parseMs = first.parse + second.parse;
  seen.applyMs = first.apply + second.apply;

  /* ---- 남은 값이 어디에 있는지 ----
   *
   * 한 갈래만 남겨 둔다. 이 슬라이스가 레일의 강제 레이아웃을 찾을 때 쓴
   * 나머지 갈래들(숨긴 뷰·대체 화면·민무늬 칸)은 답이 나왔으니 치웠다. 「두 장을
   * 한 장으로 합쳤다면」의 값을 재던 갈래도 치웠다 — 그것은 하지 않기로 한 일의
   * 값이었는데, 당기는 길에서는 화면이 늦은 만큼 그리드가 합쳐 주는 것이 곧 길
   * 자체다(docs/design/terminal-display-paced-frames-20260917.md). */
  const probe = {};
  {
    // 줄 내용이 그대로일 때의 값 — `runsOf`/`marksOf`/`sameRun`은 다 돌지만
    // DOM에는 한 자도 안 쓴다. 남은 값을 "짓는 쪽"과 "쓰는 쪽"으로 가른다.
    const still = JSON.parse(payloads[7]);
    still.scrolled_lines = 0;
    const text = JSON.stringify(still);
    const held = payloads.slice();
    payloads.length = 0;
    for (let n = 0; n < plan.frames; n += 1) payloads.push(text);
    await run(front, 0, 2);
    probe.building = (await run(front, 0, plan.frames)).apply;
    payloads.length = 0;
    payloads.push(...held);
    await run(front, 0, 1);
  }
  probe.full = (await run(front, 0, plan.frames)).apply;
  seen.probe = probe;

  // ---- 3) 셈: 만든 span, 강제된 레이아웃, DOM에 쓴 횟수 ----
  const realCreate = document.createElement;
  let madeSpans = 0;
  // 그리는 길 안이거나(`meter.painting`) 아래의 전환 한 번 안에서만 센다.
  let switching = false;
  const counted = () => meter.painting || switching;
  document.createElement = function (tag, ...rest) {
    if (tag === "span" && counted()) madeSpans += 1;
    return realCreate.call(this, tag, ...rest);
  };
  let layouts = 0;
  const realRect = Element.prototype.getBoundingClientRect;
  Element.prototype.getBoundingClientRect = function (...rest) {
    if (counted()) layouts += 1;
    return realRect.apply(this, rest);
  };
  const boxed = [
    [HTMLElement.prototype, "offsetWidth"], [HTMLElement.prototype, "offsetHeight"],
    [HTMLElement.prototype, "offsetTop"], [HTMLElement.prototype, "offsetLeft"],
    [Element.prototype, "clientWidth"], [Element.prototype, "clientHeight"],
    [Element.prototype, "scrollTop"], [Element.prototype, "scrollHeight"],
  ].map(([owner, name]) => {
    const held = Object.getOwnPropertyDescriptor(owner, name);
    Object.defineProperty(owner, name, {
      ...held,
      get() {
        if (counted()) layouts += 1;
        return held.get.call(this);
      },
    });
    return [owner, name, held];
  });
  let styleReads = 0;
  const realStyles = window.getComputedStyle;
  window.getComputedStyle = (...rest) => {
    if (counted()) styleReads += 1;
    return realStyles.apply(window, rest);
  };
  const writes = { childList: 0, attributes: 0, characterData: 0 };
  const watcher = new MutationObserver((records) => {
    for (const record of records) writes[record.type] += 1;
  });
  watcher.observe(termViews.get(front).pre, {
    childList: true,
    attributes: true,
    characterData: true,
    subtree: true,
  });
  await run(front, 0, plan.frames);
  for (const record of watcher.takeRecords()) writes[record.type] += 1;
  watcher.disconnect();
  /* 그리고 폭풍 한가운데의 탭 전환 한 번을, 이번에는 세면서. 전환이 무거운
   * 이유는 흘러간 시간이 아니라 그 순간 강제되는 레이아웃이다 — 방금 서른
   * 줄을 더럽혀 놓은 화면 위에서 재는 일이 몇 번인가. */
  // 폭풍이 스스로 강제한 레이아웃은 여기까지다 — 전환의 값은 따로 센다.
  seen.layouts = layouts;
  seen.styleReads = styleReads;
  await run(front, 0, 2);
  const beforeSwitch = { layouts, styleReads };
  switching = true;
  setActiveTab(behindTab);
  setActiveTab(frontTab);
  switching = false;
  seen.switchLayouts = layouts - beforeSwitch.layouts;
  seen.switchStyleReads = styleReads - beforeSwitch.styleReads;
  window.getComputedStyle = realStyles;
  for (const [owner, name, held] of boxed) Object.defineProperty(owner, name, held);
  Element.prototype.getBoundingClientRect = realRect;
  document.createElement = realCreate;
  await syncWatchedTerms();
  seen.madeSpans = madeSpans;
  seen.writes = writes;
  seen.spansNow = termViews.get(front).pre.querySelectorAll("span").length;

  /* ---- 안 바뀐 줄은 다시 입히지 않는다 ----
   *
   * 같은 장을 두 번 흘린다. 두 번째 장은 DOM에 단 한 자도 쓸 일이 없어야
   * 한다 — 이것이 선택 영역이 프레임을 넘어 살아남는 이유이자, 폭풍이 싼
   * 이유다. 숫자가 아니라 모양이므로 이것만 못박는다. */
  const twice = { first: 0, again: 0 };
  // Counted as they are delivered, too: a pull paints a task or two after the
  // frame was handed over, so the observer's own callback has seen most of
  // them by the time the delivery settles.
  let echoed = 0;
  const echo = new MutationObserver((records) => {
    echoed += records.length;
  });
  echo.observe(termViews.get(front).pre, {
    childList: true,
    attributes: true,
    characterData: true,
    subtree: true,
  });
  const still = JSON.parse(payloads[7]);
  still.scrolled_lines = 0;
  await deliver(front, still);
  twice.first = echoed + echo.takeRecords().length;
  echoed = 0;
  await deliver(front, JSON.parse(JSON.stringify(still)));
  twice.again = echoed + echo.takeRecords().length;
  echo.disconnect();
  seen.twice = twice;
  window.applyTermFrames = applyTermFramesAsShipped;

  for (const tab of [...tabs]) dropTab(tab.id);
  for (const at of [...termViews.keys()]) dropTermView(at);
  return seen;
}, BURST);
const burstNumbers = () =>
  `${burst.frames ?? BURST.frames}장 · ${(burst.bytes / 1024).toFixed(0)}KB(장당 ${burst.frameBytes}자) · ` +
  `parse ${burst.parseMs.toFixed(1)}ms · apply ${burst.applyMs.toFixed(1)}ms · ` +
  `span ${burst.madeSpans}개 지음(화면에 ${burst.spansNow}) · 레이아웃 ${burst.layouts} · ` +
  `getComputedStyle ${burst.styleReads} · 쓰기 ${JSON.stringify(burst.writes)} · ` +
  `전환 ${burst.switchAway.toFixed(1)}/${burst.switchBack.toFixed(1)}ms` +
  `(레이아웃 ${burst.switchLayouts}, 스타일 ${burst.switchStyleReads}) · ` +
  `짓는 쪽 ${burst.probe.building.toFixed(1)}ms / 한 판 ${burst.probe.full.toFixed(1)}ms`;
ok(
  "앞에 선 화면에 폭풍을 부어도 그리는 길에서 레이아웃을 읽지 않는다",
  // 그렸다는 것부터 확인한다. 뷰가 숨어 있으면 `apply`가 일찍 돌아가므로
  // 레이아웃 0은 저절로 참이 되고, 이 판은 아무 말도 하지 않은 것이 된다.
  burst.frontVisible &&
    burst.madeSpans > 0 &&
    burst.writes.childList > 0 &&
    burst.layouts === 0 &&
    burst.styleReads === 0,
  burstNumbers(),
);
ok(
  "똑같은 장이 두 번 와도 두 번째는 DOM에 한 자도 쓰지 않는다",
  burst.twice.first > 0 && burst.twice.again === 0,
  JSON.stringify(burst.twice),
);
ok(
  // 두 번 갈아타고 둘. 앞에 서는 뷰가 자기 격자를 한 번 재는 그 한 번이고,
  // 그 위에 레일이 얹히면 둘이 된다 — 레일의 값이 프레임마다에서 전환마다로
  // 내려온 것이 이 숫자다(전에는 넷).
  "폭풍 한가운데 탭을 갈아타는 값은 전환당 강제 레이아웃 한 번이다",
  burst.switchLayouts <= 2,
  `전환 두 번에 레이아웃 ${burst.switchLayouts}, getComputedStyle ${burst.switchStyleReads}`,
);

/* ---- the board pop-out --------------------------------------------------
 *
 * A second OS window holding the board alone (1-dz). What cannot be measured
 * from here is the window itself — the harness has no second OS window to
 * open — so what IS measured is everything either side of it: the main
 * window's door, the boot branch that turns the same document into the board
 * alone, and the two facts that cross between the windows.
 *
 * The pop-out page is loaded from the same `index.html` with `?surface=popout`,
 * which is exactly the URL `open_board_popout` hands the webview. */

const POPOUT_COLUMNS = [
  { bucket: "attention", cards: [
    { pane: "term:7", agent: "claude", state: "needs-attention", heading: "Claude",
      worktree: "feature/parse", project: "/repos/zerocode", task: "read TOML",
      unseen: true, changed_at: 1000, at: 1000 }] },
];

// The main window's door: one button in the board header, and it carries the
// window title in the language this window is speaking.
const popoutDoor = await page.evaluate(async (columns) => {
  window.__COLUMNS__ = columns;
  window.__PANES__ = [{ term: 7, agent: "claude", state: "needs-attention", at: 1000, resumable: true }];
  if (activeTabId === "board") dropTab("board");
  document.getElementById("nav-agents").click();
  await new Promise((done) => setTimeout(done, 200));
  const view = [...document.querySelectorAll("#board-view, .file-view")]
    .find((one) => one.querySelector(".agent-graph-layout") && !one.hidden);
  const button = view?.querySelector(".board-popout");
  const before = window.__COUNTS__.open_board_popout ?? 0;
  let asked = null;
  window.__ANSWER__.open_board_popout = (args) => {
    asked = args;
    return null;
  };
  button?.click();
  await new Promise((done) => setTimeout(done, 60));
  delete window.__ANSWER__.open_board_popout;
  return {
    label: button?.getAttribute("aria-label") ?? null,
    fired: (window.__COUNTS__.open_board_popout ?? 0) - before,
    title: asked?.title ?? null,
  };
}, POPOUT_COLUMNS);
ok(
  "the board header opens the pop-out, and the window title travels with the ask",
  // Korean, because that is the language this page is speaking by now — and
  // the title is the point: the backend has no catalog, so the window that
  // asks is the only place the name of the new window can come from.
  popoutDoor.label === "팝아웃으로 열기" &&
    popoutDoor.fired === 1 &&
    popoutDoor.title === "에이전트 그래프",
  JSON.stringify(popoutDoor),
);

// The two facts that cross between the windows, received by the main one.
const crossed = await page.evaluate(async () => {
  const seen = {};
  const term = await openTermTab();
  const tab = tabOfTerm(term);
  const other = tabs.find((one) => one.kind === "board");
  setActiveTab(other.id);
  acknowledgedPanes.delete(`term:${term}`);
  // "봤다" — the pop-out opened the card, so this window's unseen dot clears.
  for (const listener of window.__LISTENERS__["board:ack"] ?? []) {
    listener({ payload: { pane: `term:${term}` } });
  }
  seen.acked = (acknowledgedPanes.get(`term:${term}`) ?? 0) > 0;
  // "저기로 데려가 달라" — the pane's own tab comes to the front.
  for (const listener of window.__LISTENERS__["board:reveal"] ?? []) {
    listener({ payload: { pane: `term:${term}` } });
  }
  await new Promise((done) => setTimeout(done, 60));
  seen.staged = activeTabId === tab.id;
  dropTab(tab.id);
  return seen;
});
ok(
  "the two facts the pop-out sends land in the main window",
  crossed.acked && crossed.staged,
  JSON.stringify(crossed),
);

/* ---- 첫 실행: 마법사와 빈 화면 ------------------------------------------- */

// 뜨는 조건은 하나다. 닫힌 상태를 건네면 아무것도 열리지 않고, `closed_at`이
// 비어 있을 때만 열린다 — 이 창은 "처음인가"를 따로 계산하지 않는다.
const onbMount = await page.evaluate(async () => {
  const closed = {
    flow_version: 1,
    closed_at: 5,
    outcome: "completed",
    last_completed_step: 4,
    checklist: { chose_agent: false, dismissed: false },
  };
  const fresh = { ...closed, closed_at: null, outcome: null, last_completed_step: -1 };
  const seen = { onClosed: shouldShowOnboarding(closed), onFresh: shouldShowOnboarding(fresh) };
  seen.hiddenBefore = document.getElementById("onb-scrim").hidden;
  openOnboarding(fresh);
  await new Promise((done) => setTimeout(done, 120));
  seen.shown = !document.getElementById("onb-scrim").hidden;
  seen.steps = document.querySelectorAll("#onb-progress .onb-dot").length;
  seen.count = document.getElementById("onb-count").textContent.trim();
  seen.title = document.getElementById("onb-title").textContent.trim();
  seen.eyebrow = !document.getElementById("onb-eyebrow").hidden;
  seen.backHidden = document.getElementById("onb-back").hidden;
  seen.next = document.getElementById("onb-next").textContent.trim();
  return seen;
});
ok(
  "the wizard opens on a state that was never closed, and only on that",
  onbMount.onClosed === false &&
    onbMount.onFresh === true &&
    onbMount.hiddenBefore &&
    onbMount.shown &&
    onbMount.steps === 4 &&
    onbMount.count === "1 / 4" &&
    onbMount.eyebrow &&
    onbMount.backHidden &&
    onbMount.title.length > 0,
  JSON.stringify(onbMount),
);

// 연결된 GitHub CLI는 단계 하나를 지운다. 그러면 카운터도 줄어야 한다 —
// 건너뛴 단계를 세는 진행 표시는 사람이 갈 수 없는 자리를 약속한다.
const onbSkipped = await page.evaluate(async () => {
  window.__GH__ = "connected";
  await refreshGithubIntegration();
  paintOnboarding();
  await new Promise((done) => setTimeout(done, 40));
  const seen = {
    steps: document.querySelectorAll("#onb-progress .onb-dot").length,
    count: document.getElementById("onb-count").textContent.trim(),
  };
  window.__GH__ = "missing";
  await refreshGithubIntegration();
  paintOnboarding();
  return seen;
});
ok(
  "a step that does not apply is dropped from the count as well as the screen",
  onbSkipped.steps === 3 && onbSkipped.count === "1 / 3",
  JSON.stringify(onbSkipped),
);

// 한 단계를 지날 때마다 적힌다. 그리고 마지막 화면의 기본 버튼은 "계속"이
// 아니라 프로젝트를 부르는 문이다.
const onbWalk = await page.evaluate(async () => {
  window.__ONB_STEPS__ = [];
  const seen = {};
  const card = document.querySelector("#onb-body .onb-card");
  seen.agentCards = document.querySelectorAll("#onb-body .onb-card").length;
  // 누적이 아니라 이 클릭이 낸 값을 센다. 카운터는 창이 열린 뒤로 계속 쌓이고,
  // 앞선 시험들이 이미 같은 커맨드를 여러 번 불렀다.
  const choseBefore = window.__COUNTS__.set_default_agent ?? 0;
  card?.click();
  await new Promise((done) => setTimeout(done, 40));
  seen.chose = (window.__COUNTS__.set_default_agent ?? 0) - choseBefore;
  for (let round = 0; round < 3; round += 1) {
    document.getElementById("onb-next").click();
    await new Promise((done) => setTimeout(done, 60));
  }
  seen.saved = window.__ONB_STEPS__.map((one) => one.step);
  seen.choseAgentFlag = window.__ONB_STEPS__[0]?.choseAgent === true;
  seen.count = document.getElementById("onb-count").textContent.trim();
  seen.last = document.getElementById("onb-next").textContent.trim();
  seen.skipHidden = document.getElementById("onb-skip").hidden;
  return seen;
});
ok(
  "each step is written down as it is passed, and the last one names the project door",
  onbWalk.agentCards > 0 &&
    onbWalk.chose === 1 &&
    JSON.stringify(onbWalk.saved) === "[1,2,3]" &&
    onbWalk.choseAgentFlag &&
    onbWalk.count === "4 / 4" &&
    onbWalk.skipHidden &&
    onbWalk.last.length > 0,
  JSON.stringify(onbWalk),
);

// 끝내면 완료로 적히고, 곧바로 프로젝트를 고르는 창 — 창 안 폴더 브라우저
// (t-2982) — 으로 넘어간다. OS 패널은 묻지 않는다.
const onbFinish = await page.evaluate(async () => {
  const before = window.__COUNTS__.choose_paths ?? 0;
  document.getElementById("onb-next").click();
  await new Promise((done) => setTimeout(done, 150));
  const seen = {
    outcome: window.__ONB_CLOSED__,
    shut: document.getElementById("onb-scrim").hidden,
    browser: !document.getElementById("pb-scrim").hidden,
    asked: (window.__COUNTS__.choose_paths ?? 0) - before,
  };
  closePathBrowser([]);
  await new Promise((done) => setTimeout(done, 30));
  return seen;
});
ok(
  "finishing writes completed and hands over to the native project picker",
  onbFinish.outcome === "completed" && onbFinish.shut && !onbFinish.browser && onbFinish.asked === 1,
  JSON.stringify(onbFinish),
);

// 나가는 문은 확인을 지난다. Escape는 나가는 것이 아니라 묻는 것이고, 확인의
// 기본 초점은 계속하기 쪽이다.
const onbSkip = await page.evaluate(async () => {
  window.__ONB_CLOSED__ = null;
  openOnboarding({
    flow_version: 1,
    closed_at: null,
    outcome: null,
    last_completed_step: -1,
    checklist: { chose_agent: false, dismissed: false },
  });
  await new Promise((done) => setTimeout(done, 80));
  const seen = {};
  // 한 번만. 두 번 흘리면 두 번째가 방금 연 확인을 도로 닫는다 — 그 자체가
  // 이 두 분기가 순서대로 서 있다는 증거이긴 하다.
  window.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
  await new Promise((done) => setTimeout(done, 60));
  seen.asked = !document.getElementById("onb-skip-scrim").hidden;
  seen.stillOpen = !document.getElementById("onb-scrim").hidden;
  seen.focus = document.activeElement?.id ?? "";
  document.getElementById("onb-skip-no").click();
  await new Promise((done) => setTimeout(done, 60));
  seen.keptGoing = document.getElementById("onb-skip-scrim").hidden && !document.getElementById("onb-scrim").hidden;
  seen.closedByKeepGoing = window.__ONB_CLOSED__;
  document.getElementById("onb-scrim").dispatchEvent(new MouseEvent("mousedown", { bubbles: true }));
  await new Promise((done) => setTimeout(done, 60));
  seen.askedAgain = !document.getElementById("onb-skip-scrim").hidden;
  document.getElementById("onb-skip-yes").click();
  await new Promise((done) => setTimeout(done, 120));
  seen.outcome = window.__ONB_CLOSED__;
  seen.shut = document.getElementById("onb-scrim").hidden;
  return seen;
});
ok(
  "escape and the scrim ask before leaving, and leaving writes dismissed",
  onbSkip.asked &&
    onbSkip.stillOpen &&
    onbSkip.focus === "onb-skip-no" &&
    onbSkip.keptGoing &&
    onbSkip.closedByKeepGoing === null &&
    onbSkip.askedAgain &&
    onbSkip.outcome === "dismissed" &&
    onbSkip.shut,
  JSON.stringify(onbSkip),
);

// 다시 보기는 Alt를 눌러야 나온다. 평범한 클릭은 단축키 설정으로 간다.
const onbReopen = await page.evaluate(async () => {
  const keys = document.getElementById("foot-keys");
  keys.dispatchEvent(new MouseEvent("click", { bubbles: true, altKey: false }));
  await new Promise((done) => setTimeout(done, 60));
  const seen = { plainOpensSettings: !document.getElementById("settings-view").hidden };
  setSettingsOpen(false);
  keys.dispatchEvent(new MouseEvent("click", { bubbles: true, altKey: true }));
  await new Promise((done) => setTimeout(done, 60));
  const item = document.querySelector("#sidebar-menu .sidebar-menu-item");
  seen.hiddenItem = item?.textContent.trim() ?? "";
  item?.click();
  await new Promise((done) => setTimeout(done, 120));
  seen.reopened = !document.getElementById("onb-scrim").hidden;
  seen.asked = window.__COUNTS__.reopen_onboarding ?? 0;
  hideModal(document.getElementById("onb-skip-scrim"));
  hideModal(document.getElementById("onb-scrim"));
  return seen;
});
ok(
  "the way back into the wizard is behind alt, and a plain click still opens the shortcuts",
  onbReopen.plainOpensSettings &&
    onbReopen.hiddenItem.length > 0 &&
    onbReopen.asked === 1 &&
    onbReopen.reopened,
  JSON.stringify(onbReopen),
);

/* ---- 마법사 다음의 네 표면 --------------------------------------------- */

// 시작 체크리스트. 요점은 목록이 아니라 **완료가 저장되지 않는다**는 것이다 —
// 지금 상태에서 매번 파생되므로, 근거가 물러나면 초록 표시도 함께 물러난다.
const guideDerived = await page.evaluate(async () => {
  const seen = {};
  const mark = (id) => document.querySelector(`#guide-body [data-step="${id}"]`)?.dataset.done;
  // 앞선 시험들이 **진짜 제스처**로 지나간 자리들. diff를 열고 파일을 열고
  // 풀 리퀘스트를 만든 것은 전부 이 파일의 다른 시험이 한 일이고, 그 셋이 여기
  // 켜져 있다는 것이 배선이 화면 밖에서도 산다는 증거다.
  seen.organic = { ...window.__ONB__.checklist };
  for (const box of Object.keys(window.__ONB__.checklist)) {
    window.__ONB__.checklist[box] = false;
  }
  window.__CHOSE_AGENT__ = false;
  window.__ONB__.guide_dismissed = false;
  window.__ONB__.checklist.reviewed_diff = false;
  await refreshSetupGuide();
  seen.entryShown = !document.getElementById("guide-entry").hidden;
  seen.label = document.getElementById("guide-entry-label").textContent.trim();

  document.getElementById("guide-entry").click();
  await new Promise((done) => setTimeout(done, 60));
  seen.open = !document.getElementById("guide-scrim").hidden;
  seen.steps = document.querySelectorAll("#guide-body .guide-step").length;
  seen.sections = document.querySelectorAll("#guide-body .guide-section-head").length;
  seen.before = mark("review-diff");
  // 켜면 켜지고…
  window.__ONB__.checklist.reviewed_diff = true;
  await refreshSetupGuide();
  seen.after = mark("review-diff");
  // …근거가 사라지면 **되돌아간다**. 저장했다면 여기서 초록이 남는다.
  window.__ONB__.checklist.reviewed_diff = false;
  await refreshSetupGuide();
  seen.back = mark("review-diff");

  // 이 창은 프로젝트 하나에 main 하나만 알고 있으므로 그 둘은 아직 아니다.
  seen.twoProjects = mark("two-projects");
  seen.twoWorktrees = mark("two-worktrees");
  return seen;
});
ok(
  "the checklist is derived from what is true now, so a step goes back when its ground does",
  guideDerived.organic.reviewed_diff &&
    guideDerived.organic.opened_pr &&
    guideDerived.organic.opened_file &&
    guideDerived.entryShown &&
    guideDerived.open &&
    guideDerived.steps === 8 &&
    guideDerived.sections === 2 &&
    guideDerived.label.includes("0/8") &&
    guideDerived.before === "false" &&
    guideDerived.after === "true" &&
    guideDerived.back === "false" &&
    guideDerived.twoProjects === "false" &&
    guideDerived.twoWorktrees === "false",
  JSON.stringify(guideDerived),
);

// 치우면 사이드바에서 사라지고, 돌아오는 길은 도움말 메뉴다. 되돌릴 길 없는
// 숨기기는 숨기기가 아니라 삭제다.
const guideHidden = await page.evaluate(async () => {
  const seen = {};
  document.getElementById("guide-hide").click();
  await new Promise((done) => setTimeout(done, 80));
  seen.stored = window.__ONB__.guide_dismissed;
  seen.shut = document.getElementById("guide-scrim").hidden;
  seen.entryGone = document.getElementById("guide-entry").hidden;

  const help = document.getElementById("foot-guide");
  help.dispatchEvent(new MouseEvent("click", { bubbles: true }));
  await new Promise((done) => setTimeout(done, 60));
  seen.menu = [...document.querySelectorAll("#sidebar-menu .sidebar-menu-label")].map((one) =>
    one.textContent.trim(),
  );
  document.querySelectorAll("#sidebar-menu .sidebar-menu-item")[0]?.click();
  await new Promise((done) => setTimeout(done, 80));
  seen.reopened = !document.getElementById("guide-scrim").hidden;
  document.getElementById("guide-close").click();
  // 다음 시험들을 위해 되돌린다.
  window.__ONB__.guide_dismissed = false;
  await refreshSetupGuide();
  seen.entryBack = !document.getElementById("guide-entry").hidden;
  return seen;
});
ok(
  "hiding the checklist takes the sidebar line away and the help menu is the way back",
  guideHidden.stored &&
    guideHidden.shut &&
    guideHidden.entryGone &&
    guideHidden.menu.length === 2 &&
    guideHidden.reopened &&
    guideHidden.entryBack,
  JSON.stringify(guideHidden),
);

// 사람이 한 제스처가 칸을 켠다. 기둥 폭을 자기 손으로 정한 사람에게 폭 정하는
// 법을 가르치는 팁은 방해이므로, 그 사실은 팁의 자동 완료 조건이기도 하다.
const marked = await page.evaluate(async () => {
  window.__ONB__.checklist.shaped_sidebar = false;
  window.__ONB__.checklist.used_palette = false;
  const grip = document.getElementById("grip-sidebar");
  grip.dispatchEvent(new KeyboardEvent("keydown", { key: "ArrowLeft", bubbles: true }));
  await new Promise((done) => setTimeout(done, 60));
  const shaped = window.__ONB__.checklist.shaped_sidebar;
  openPalette("worktree");
  await new Promise((done) => setTimeout(done, 60));
  closePalette();
  // 모르는 이름은 백엔드가 거절한다 — 창의 오타가 진행도로 굳지 않는다.
  let refused = false;
  try {
    await window.__TAURI__.core.invoke("mark_onboarding", { mark: "rode_a_horse" });
  } catch {
    refused = true;
  }
  return { shaped, palette: window.__ONB__.checklist.used_palette, refused };
});
ok(
  "a real gesture is what writes a checklist box, and a name nothing answers to is refused",
  marked.shaped && marked.palette && marked.refused,
  JSON.stringify(marked),
);

// 코치마크. 백드롭이 없다는 것이 이 표면의 전부다 — 아래 화면이 그대로 눌려야
// "여기를 보세요" 다음에 실제로 거기를 누를 수 있다. 그리고 세션당 하나.
const coachmark = await page.evaluate(async () => {
  const seen = {};
  // 앞선 시험이 열어 둔 다이얼로그를 걷는다. 덮인 화면 위에는 코치마크가 뜨지
  // 않는 것이 규칙이고(그래서 그 규칙을 시험하려면 먼저 안 덮여 있어야 한다),
  // 이 파일은 페이지 하나를 끝까지 공유한다.
  for (const scrim of document.querySelectorAll(".scrim:not([hidden])")) scrim.hidden = true;
  window.__ONB__.tours_seen = [];
  window.__TOUR_REFUSALS__ = [];
  tourSpent = false;
  if (activeTabId === "board") dropTab("board");
  document.getElementById("nav-agents").click();
  await new Promise((done) => setTimeout(done, 250));
  seen.shown = !document.getElementById("tour").hidden;
  seen.title = document.getElementById("tour-title").textContent.trim();
  seen.count = document.getElementById("tour-count").textContent.trim();
  seen.backHidden = document.getElementById("tour-back").hidden;
  // 뜬 시점에 본 것으로 적힌다 — 완료가 아니라 최초 렌더가 기준이다.
  seen.marked = [...window.__ONB__.tours_seen];
  seen.rootPasses = getComputedStyle(document.getElementById("tour")).pointerEvents;
  seen.panelTakes = getComputedStyle(document.getElementById("tour-panel")).pointerEvents;
  // 말풍선이 자기 앵커 옆에 선다. 0,0에 붙어 있으면 자리를 재지 않은 것이다.
  const panel = document.getElementById("tour-panel").getBoundingClientRect();
  const anchor = document.querySelector('[data-tour-target="agent-graph"]').getBoundingClientRect();
  seen.placed = panel.width > 0 && panel.top !== 0 && Math.abs(panel.left - anchor.left) < window.innerWidth;

  document.getElementById("tour-next").click();
  await new Promise((done) => setTimeout(done, 60));
  seen.second = document.getElementById("tour-count").textContent.trim();
  seen.backShown = !document.getElementById("tour-back").hidden;
  seen.lastLabel = document.getElementById("tour-next").textContent.trim();
  document.getElementById("tour-next").click();
  await new Promise((done) => setTimeout(done, 60));
  seen.shut = document.getElementById("tour").hidden;

  // 두 번째 화면은 이 실행에서 이미 하나를 봤다는 이유로 거절된다.
  setTaskOpen(true);
  await new Promise((done) => setTimeout(done, 120));
  seen.refusals = [...window.__TOUR_REFUSALS__];
  seen.noSecond = document.getElementById("tour").hidden;
  setTaskOpen(false);
  return seen;
});
ok(
  "one coachmark a session, marked seen where it appeared, over a surface it never blocks",
  coachmark.shown &&
    coachmark.title.length > 0 &&
    coachmark.count === "1 / 2" &&
    coachmark.backHidden &&
    JSON.stringify(coachmark.marked) === '["board"]' &&
    coachmark.rootPasses === "none" &&
    coachmark.panelTakes === "auto" &&
    coachmark.placed &&
    coachmark.second === "2 / 2" &&
    coachmark.backShown &&
    coachmark.shut &&
    coachmark.refusals.includes("tasks:SessionSpent") &&
    coachmark.noSecond,
  JSON.stringify(coachmark),
);

// 앵커가 사라지면 스스로 고친다. 접힌 화면 하나가 투어를 죽여서도 안 되고,
// 아무것도 가리키지 않는 말풍선이 남아서도 안 된다.
const selfHealing = await page.evaluate(async () => {
  const seen = {};
  const columns = document.querySelector('[data-tour-target="agent-graph"]');
  seen.verbWhole = tourVerb(TOURS.board, 0);
  columns.hidden = true;
  // 첫 스텝의 앵커만 사라졌다 — 뒤에 갈 곳이 있으므로 전진이다.
  seen.verbAdvance = tourVerb(TOURS.board, 0);
  document.querySelector('[data-tour-target="board-search"]').hidden = true;
  // 둘 다 사라졌다 — 기다릴 것도 없으므로 종료다.
  seen.verbCancel = tourVerb(TOURS.board, 0);
  columns.hidden = false;
  document.querySelector('[data-tour-target="board-search"]').hidden = false;
  return seen;
});
ok(
  "a coachmark heals itself when its anchor goes: advance while there is somewhere to go, cancel when there is not",
  selfHealing.verbWhole === "render" &&
    selfHealing.verbAdvance === "advance" &&
    selfHealing.verbCancel === "cancel",
  JSON.stringify(selfHealing),
);

// 팁. 앱 오픈당 하나이고, 마법사가 떠 있던 실행은 통째로 봉인된다 — 마법사를
// 닫는 순간 다음 안내가 튀어나오면 첫 성공의 자리를 광고로 덮는 것이다.
const tips = await page.evaluate(async () => {
  const seen = {};
  for (const scrim of document.querySelectorAll(".scrim:not([hidden])")) scrim.hidden = true;
  const reset = () => {
    window.__ONB__.tips_seen = [];
    window.__ONB__.checklist.used_palette = false;
    window.__ONB__.checklist.shaped_sidebar = false;
    window.__ONB__.checklist.opened_file = false;
    tipSealed = false;
    tipSpent = false;
  };

  reset();
  window.__ONB__.closed_at = null;
  await maybeShowTip();
  seen.quietUnderWizard = document.getElementById("tip-scrim").hidden;
  seen.sealed = tipSealed;
  // 마법사를 닫아도 이 실행에서는 더 이상 뜨지 않는다.
  window.__ONB__.closed_at = 1;
  await maybeShowTip();
  seen.stillQuiet = document.getElementById("tip-scrim").hidden;

  // 다음 실행이라면 하나가 뜬다.
  reset();
  await maybeShowTip();
  seen.shown = !document.getElementById("tip-scrim").hidden;
  seen.title = document.getElementById("tip-title").textContent.trim();
  seen.marked = [...window.__ONB__.tips_seen];
  document.getElementById("tip-later").click();
  await new Promise((done) => setTimeout(done, 40));
  // 오픈당 하나 — 닫았다고 다음 것이 오지 않는다.
  await maybeShowTip();
  seen.onlyOne = document.getElementById("tip-scrim").hidden;

  // 이미 그 기능을 쓰고 있는 사람에게는 보여 주지 않고 조용히 끝낸다.
  reset();
  window.__ONB__.checklist.used_palette = true;
  window.__ONB__.checklist.shaped_sidebar = true;
  await maybeShowTip();
  seen.skippedTo = document.getElementById("tip-scrim").hidden
    ? null
    : document.getElementById("tip-title").textContent.trim();
  seen.settled = [...window.__ONB__.tips_seen].sort();
  document.getElementById("tip-later").click();
  reset();
  window.__ONB__.tips_seen = ["palette", "panels", "editor"];
  return seen;
});
ok(
  "a tip waits out the run the wizard ran in, then shows one — and never one the person already lives without",
  tips.quietUnderWizard &&
    tips.sealed &&
    tips.stillQuiet &&
    tips.shown &&
    tips.title.length > 0 &&
    JSON.stringify(tips.marked) === '["palette"]' &&
    tips.onlyOne &&
    tips.skippedTo !== null &&
    JSON.stringify(tips.settled) === '["editor","palette","panels"]',
  JSON.stringify(tips),
);

// 기능 투어. 자동으로 뜨는 길이 없다는 것이 이 표면의 계약이다 — 부팅에도,
// 화면 전환에도 뜨지 않고, 도움말의 한 항목만이 그것을 연다.
const featureWall = await page.evaluate(async () => {
  const seen = { hiddenAtBoot: document.getElementById("wall-scrim").hidden };
  window.__ONB__.wall_seen = [];
  const help = document.getElementById("foot-guide");
  help.dispatchEvent(new MouseEvent("click", { bubbles: true }));
  await new Promise((done) => setTimeout(done, 60));
  const items = [...document.querySelectorAll("#sidebar-menu .sidebar-menu-item")];
  seen.menu = items.map((one) => one.querySelector(".sidebar-menu-label")?.textContent.trim());
  items[1]?.click();
  await new Promise((done) => setTimeout(done, 80));
  seen.open = !document.getElementById("wall-scrim").hidden;
  seen.rail = document.querySelectorAll("#wall-rail .wall-rail-item").length;
  seen.title = document.querySelector(".wall-step-title")?.textContent.trim();
  seen.next = document.getElementById("wall-next").textContent.trim();
  // 들른 갈래가 적힌다 — 레일의 점이 뜻하는 것은 다 읽었는가가 아니라 들렀는가다.
  seen.seenFirst = [...window.__ONB__.wall_seen];
  document.querySelectorAll("#wall-rail .wall-rail-item")[3]?.click();
  await new Promise((done) => setTimeout(done, 60));
  seen.last = document.getElementById("wall-next").textContent.trim();
  seen.seenBoth = [...window.__ONB__.wall_seen];
  document.getElementById("wall-next").click();
  await new Promise((done) => setTimeout(done, 40));
  seen.shut = document.getElementById("wall-scrim").hidden;
  return seen;
});
ok(
  "the feature tour opens from the help menu alone and remembers which workflows were visited",
  featureWall.hiddenAtBoot &&
    featureWall.menu.length === 2 &&
    featureWall.open &&
    featureWall.rail === 4 &&
    featureWall.title.length > 0 &&
    featureWall.next !== featureWall.last &&
    JSON.stringify(featureWall.seenFirst) === '["workspaces"]' &&
    featureWall.seenBoth.length === 2 &&
    featureWall.shut,
  JSON.stringify(featureWall),
);

// 프로젝트가 하나도 없으면 빈 무대가 하는 말이 달라진다. 워크트리 버튼은
// 사라지지 않고 회색으로 남아 왜 눌리지 않는지 말한다.
const landing = await page.evaluate(async () => {
  window.__ANSWER__.project_catalog = () => [];
  await refreshWorktrees();
  await new Promise((done) => setTimeout(done, 80));
  const seen = {
    mark: document.querySelector(".placeholder .landing-wordmark")?.textContent ?? "",
    lede: document.querySelector(".placeholder .landing-lede")?.textContent ?? "",
    doors: [...document.querySelectorAll(".placeholder .landing-doors .btn")].map((one) => ({
      says: one.textContent.trim(),
      off: one.disabled,
      why: one.dataset.tip,
    })),
    noKeypress: !document.querySelector(".placeholder kbd"),
  };
  const before = window.__COUNTS__.choose_paths ?? 0;
  document.querySelector(".placeholder .landing-doors .btn")?.click();
  await new Promise((done) => setTimeout(done, 120));
  // The door opens the in-window browser (t-2982), never the OS panel.
  seen.asked = (window.__COUNTS__.choose_paths ?? 0) - before;
  seen.browser = !document.getElementById("pb-scrim").hidden;
  closePathBrowser([]);
  await new Promise((done) => setTimeout(done, 30));
  delete window.__ANSWER__.project_catalog;
  await refreshWorktrees();
  await new Promise((done) => setTimeout(done, 80));
  seen.goneWithAProject = !document.querySelector(".placeholder .landing-wordmark");
  return seen;
});
ok(
  "with no project at all the empty stage becomes the landing, and its second door says why it is off",
  landing.mark === "ZeroCode" &&
    landing.lede.length > 0 &&
    landing.doors.length === 2 &&
    landing.doors[0].off === false &&
    landing.doors[1].off === true &&
    landing.doors[1].why.length > 0 &&
    landing.noKeypress &&
    landing.asked === 1 &&
    !landing.browser &&
    landing.goneWithAProject,
  JSON.stringify(landing),
);

// 이 창이 그리는 툴팁. 네이티브 `title`은 운영체제가 그렸고, 그래서 제품에서
// 가장 자주 보이는 표면이 유일하게 우리 것이 아니었다. 위임 리스너 하나가
// `data-tip`을 읽어 반전 pill을 띄운다 — 지연을 두고 뜨고, 포인터가 떠나면
// 사라진다.
const tooltip = await page.evaluate(async () => {
  const settle = (ms) => new Promise((done) => setTimeout(done, ms));
  const anchor = document.getElementById("foot-settings");
  const tip = () => document.querySelector(".tooltip");
  const seen = { says: anchor.dataset.tip ?? "", noTitle: !anchor.hasAttribute("title") };
  // 아무 일도 없을 때는 없다.
  seen.quietAtRest = tip() === null || tip().hidden;
  anchor.dispatchEvent(new PointerEvent("pointerover", { bubbles: true }));
  // 지연이 지연인지. 700ms 앞에서는 아직 아무것도 없어야 한다 — 포인터가
  // 툴바를 가로지를 때마다 창이 깜빡이지 않는 이유가 이것이다.
  await settle(200);
  seen.waitsOut = tip() === null || tip().hidden;
  await settle(700);
  const shown = tip();
  seen.shown = shown !== null && !shown.hidden;
  seen.words = shown?.textContent ?? "";
  // 반전 pill: 창의 잉크가 바탕이 되고 바탕이 글자가 된다.
  const face = shown ? getComputedStyle(shown) : null;
  const ink = getComputedStyle(document.documentElement).getPropertyValue("--ink-chalk").trim();
  seen.inverted = face !== null &&
    face.backgroundColor !== "rgba(0, 0, 0, 0)" &&
    face.backgroundColor !== face.color;
  seen.hasInk = ink.length > 0;
  // 앵커를 떠나면 간다.
  anchor.dispatchEvent(new PointerEvent("pointerout", { bubbles: true, relatedTarget: document.body }));
  await settle(60);
  seen.hidden = tip() === null || tip().hidden;
  return seen;
});
ok(
  "the window draws its own tooltip: one delegated listener, an inverted pill, and a delay before it opens",
  tooltip.says.length > 0 &&
    tooltip.noTitle &&
    tooltip.quietAtRest &&
    tooltip.waitsOut &&
    tooltip.shown &&
    tooltip.words === tooltip.says &&
    tooltip.inverted &&
    tooltip.hidden,
  JSON.stringify(tooltip),
);

// 퇴장. `hidden`은 애니메이션이 돌기 전에 상자를 없애므로, 닫히는 동안 표면은
// `is-closing`을 걸치고 있다가 모션이 끝난 뒤에야 숨는다. 그 사이가 있어야
// 사라지는 것이 사고가 아니라 응답으로 읽힌다.
const leaving = await page.evaluate(async () => {
  const settle = (ms) => new Promise((done) => setTimeout(done, ms));
  const scrim = document.getElementById("qo-scrim");
  openPalette("file");
  await settle(60);
  const seen = { opened: !scrim.hidden, enterClass: scrim.classList.contains("is-closing") };
  closePalette();
  // 붙자마자: 아직 보이고, 표시가 걸려 있다.
  seen.marked = scrim.classList.contains("is-closing");
  seen.stillThere = !scrim.hidden;
  await settle(260);
  // 모션이 끝나면 실제로 숨고, 표시는 스스로 걷힌다.
  seen.gone = scrim.hidden;
  seen.unmarked = !scrim.classList.contains("is-closing");
  // 그리고 다시 열면 지난 퇴장이 새 등장을 도로 숨기지 않는다.
  openPalette("file");
  await settle(260);
  seen.reopened = !scrim.hidden;
  closePalette();
  await settle(260);
  return seen;
});
ok(
  "an overlay leaves through a marked exit, and a reopen survives the close still in flight",
  leaving.opened &&
    !leaving.enterClass &&
    leaving.marked &&
    leaving.stillThere &&
    leaving.gone &&
    leaving.unmarked &&
    leaving.reopened,
  JSON.stringify(leaving),
);

/* 오케스트레이션이 실제로 화면을 나눈다 — 조율자 하나에 팀원 넷.
 *
 * 사용자 리포트가 가리킨 바로 그 자리다: "에이전트들이 뜨면 실제로 터미널이
 * 여러 개로 분할되고 그게 보여야 한다." 백엔드가 `term:split`을 쏘면 창이
 * **에이전트가 지목한 판** 옆에 진짜 leaf를 만들어야 하고, 배치는 실측한
 * main-vertical이어야 한다 — 리더는 한 번만 잘리고 팀원들은 그 옆 열에 쌓인다.
 *
 * 목이 아니라 실제 레이아웃을 잰다: `.pane-slot`의 실제 사각형을 읽어 리더가
 * 왼쪽 절반을 그대로 갖고 있는지, 팀원 넷이 오른쪽 한 열에 세로로 쌓였는지
 * 확인한다. 트리만 보면 CSS가 죽어 있어도 통과한다. */
const teamed = await page.evaluate(async () => {
  const settle = () => new Promise((done) => setTimeout(done, 140));
  const fire = async (payload) => {
    for (const handler of window.__LISTENERS__["term:split"] ?? []) handler({ payload });
    await settle();
  };
  // 리더 하나가 자기 탭에 서 있다 — 조율자가 실제로 그렇게 서 있는 모습이다.
  const leaderTerm = await openTermTab({ placement: "tab" });
  await settle();
  const leader = tabs.find(
    (tab) => tab.kind === "term" && paneLeaves(tab.layout).includes(leaderTerm),
  );
  setActiveTab(leader.id);
  await settle();
  const seen = { before: paneLeaves(leader.layout).length, tabsBefore: tabs.length };
  // 첫 팀원: 리더를 좌우로 자른다.
  await fire({ parent: leaderTerm, term: 8801, direction: "vertical", agent: "claude" });
  // 나머지 셋: 실측 규칙대로 **열의 맨 아래**를 위아래로 자른다.
  await fire({ parent: 8801, term: 8802, direction: "horizontal", agent: "claude" });
  await fire({ parent: 8802, term: 8803, direction: "horizontal", agent: "claude" });
  await fire({ parent: 8803, term: 8804, direction: "horizontal", agent: "claude" });
  seen.leaves = paneLeaves(leader.layout);
  // 판 넷이 새 탭이 아니라 **한 탭 안의 분할**로 왔다.
  seen.tabsAfter = tabs.length;
  const box = (term) => {
    const node = paneHosts
      .get(leader.id)
      ?.querySelector(`.pane-slot[data-term="${term}"]`)
      ?.getBoundingClientRect();
    return node ? { x: Math.round(node.left), y: Math.round(node.top), w: Math.round(node.width), h: Math.round(node.height) } : null;
  };
  seen.boxes = Object.fromEntries(
    [leaderTerm, 8801, 8802, 8803, 8804].map((term) => [term, box(term)]),
  );
  // 판마다 자기 이름을 단다 — 다섯 판이 전부 리더의 탭 이름을 쓰면 누가
  // 누군지 알 수 없다.
  seen.titles = [8801, 8802, 8803, 8804].map((term) => paneTitleOf(leader, term));
  // 키보드는 마지막 팀원에게 가 있고, 무대는 그대로 리더의 탭이다.
  seen.active = leader.activePane;
  seen.stayedOnTab = activeTabId === leader.id;
  // 지목한 판을 향해 포커스가 옮겨간다 — 리더가 이름으로 부른 그 판.
  for (const handler of window.__LISTENERS__["term:focus-pane"] ?? []) handler({ payload: 8802 });
  await settle();
  seen.focused = leader.activePane;
  // 리더의 탭이 없으면 아무것도 만들지 않는다 — 조율자 없는 팀원을 무대에
  // 올리는 것보다 아무 일도 안 하는 편이 낫다.
  const before = tabs.length;
  await fire({ parent: 99999, term: 8899, direction: "vertical", agent: "claude" });
  seen.orphanMadeNothing = tabs.length === before && !tabs.some((tab) => tab.kind === "term" && paneLeaves(tab.layout).includes(8899));
  // 정리: 뒤따르는 시험들이 다섯 판짜리 탭 위에서 돌지 않게.
  for (const term of [8801, 8802, 8803, 8804]) {
    for (const handler of window.__LISTENERS__["term:exited"] ?? []) handler({ payload: { term } });
  }
  await settle();
  seen.pruned = paneLeaves(leader.layout).length;
  // 에이전트 없이 잘린 판은 제목 없이 온다 — 탭의 이름이 비쳐 보이는 실측
  // 폴백, OSC 제목이 오면 그것이 덮는다.
  await fire({ parent: leaderTerm, term: 8805, direction: "vertical" });
  seen.bareBarFalls = leader.paneTitles?.[8805] === undefined
    && paneTitleOf(leader, 8805) === "";
  for (const handler of window.__LISTENERS__["term:exited"] ?? []) {
    handler({ payload: { term: 8805 } });
  }
  await settle();
  closeTab(leader.id);
  await settle();
  return seen;
});
const leaderBox = teamed.boxes[Object.keys(teamed.boxes)[0]];
// 자동 에이전트 판은 메인 포함 세 개까지다: 리더와 첫 두 팀원만 보이는 판이고,
// 셋째부터는 워커 목록에 주차된다 (TEAM_VISIBLE_PANE_LIMIT, 위키
// automatic-teammates-switch-to-worker-view-above-three-panes). 넷을 소환하면
// 8801·8802가 리더 오른쪽 한 열에 쌓이고 8803·8804는 상자 없이 목록으로 간다.
const column = [8801, 8802].map((term) => teamed.boxes[term]);
const parked = [8803, 8804].map((term) => teamed.boxes[term]);
ok(
  "an orchestrating agent's teammates arrive as visible panes, stacked in one column beside the leader",
  teamed.before === 1 &&
    // 리더 + 보이는 팀원 둘 = 셋; 나머지 둘은 주차되어 판을 갖지 않는다.
    teamed.leaves.length === 3 &&
    parked.every((one) => one === null) &&
    // 새 탭이 아니라 분할이다.
    teamed.tabsAfter === teamed.tabsBefore &&
    // 리더는 딱 한 번 잘렸다: 폭의 절반을 갖고, 높이는 온전하다 — 열 전체를
    // 세로로 덮는지로 잰다.
    leaderBox.w > 0 &&
    column.every((one) => one && one.w > 0 && one.h > 0) &&
    Math.abs(leaderBox.w - column[0].w) <= 2 &&
    leaderBox.h > column[0].h &&
    leaderBox.y <= column[0].y &&
    leaderBox.y + leaderBox.h >= column[1].y + column[1].h - 4 &&
    // 보이는 팀원 둘은 리더의 오른쪽, 한 열에 세로로 쌓였다.
    column.every((one) => one.x > leaderBox.x + leaderBox.w - 4) &&
    new Set(column.map((one) => one.x)).size === 1 &&
    column[0].y < column[1].y &&
    // 보이는 판의 이름은 에이전트의 이름이다; 주차된 판은 아직 이름이 없다.
    teamed.titles.slice(0, 2).every((one) => one === teamed.titles[0] && one !== "" && !one.includes("%")) &&
    teamed.titles.slice(2).every((one) => one === "") &&
    teamed.bareBarFalls &&
    // 마지막 **보이는** 팀원이 캐럿을 갖되 무대는 옮겨가지 않았고, 이름으로
    // 부르면 그 판으로 옮겨간다.
    teamed.active === 8802 &&
    teamed.stayedOnTab &&
    teamed.focused === 8802 &&
    teamed.orphanMadeNothing &&
    teamed.pruned === 1,
  JSON.stringify(teamed),
);

// The boot branch. Same document, same script — only the board is raised, and
// nothing that belongs to the main window is started: no terminal is spawned,
// no tab strip is built, and the chrome around the stage is folded away.
const popoutPage = await browser.newPage({ viewport: { width: 960, height: 720 } });
const popoutFaults = [];
popoutPage.on("pageerror", (error) => popoutFaults.push(String(error)));
// Booted in English on purpose: the pop-out reads the same boot report as the
// main window, so this also proves the new markup's keys reach the catalog
// rather than standing at their Korean fallbacks in a second window.
await standBackend(popoutPage, { ...BOOT, locale: "en" });
await popoutPage.addInitScript((columns) => {
  window.__COLUMNS__ = columns;
  window.__PANES__ = [{ term: 7, agent: "claude", state: "needs-attention", at: 1000, resumable: true }];
}, POPOUT_COLUMNS);
await popoutPage.goto(`${origin}/index.html?surface=popout`);
await popoutPage.waitForSelector(".task-board-row");
await popoutPage.click('[data-board-mode="graph"]');
await popoutPage.waitForFunction(
  () => document.querySelectorAll("#board-view .board-card").length > 0,
);

const booted = await popoutPage.evaluate(() => {
  const hidden = (selector) => getComputedStyle(document.querySelector(selector)).display === "none";
  return {
    surface: document.documentElement.dataset.surface,
    boardShown: !document.getElementById("board-view").hidden,
    cards: document.querySelectorAll("#board-view .board-card").length,
    // The main window's own startup work never ran here.
    spawned: window.__COUNTS__.open_term_tab ?? 0,
    worktrees: window.__COUNTS__.list_worktrees ?? 0,
    badge: window.__COUNTS__.set_dock_badge ?? 0,
    tabs: document.getElementById("tabstrip").childElementCount,
    // The chrome is folded, including the button that would open this window.
    titlebar: hidden(".titlebar"),
    threads: hidden(".threads"),
    files: hidden(".files"),
    statusbar: hidden(".statusbar"),
    ownDoor: hidden("#board-popout"),
    // And the board itself is a real box filling the window.
    wide: Math.round(document.querySelector(".agent-graph-layout").getBoundingClientRect().width),
  };
});
ok(
  "the pop-out boots the board alone, out of the same document",
  booted.surface === "popout" &&
    booted.boardShown &&
    booted.cards === 1 &&
    booted.spawned === 0 &&
    booted.worktrees === 0 &&
    booted.badge === 0 &&
    booted.tabs === 0 &&
    booted.titlebar &&
    booted.threads &&
    booted.files &&
    booted.statusbar &&
    booted.ownDoor &&
    booted.wide > 800,
  JSON.stringify(booted),
);

// And it is LIVE off the backend, with no relay under it: the same event the
// main window repaints on reaches this window too, and the board re-asks Rust
// for its columns. What it must NOT do is drive the main window's dock badge —
// two windows counting the same number is how the badge and the list disagree.
const popoutLive = await popoutPage.evaluate(async (columns) => {
  const before = window.__COUNTS__.board_snapshot ?? 0;
  window.__COLUMNS__ = [
    ...columns,
    { bucket: "done", cards: [
      { pane: "term:8", agent: "codex", state: "done", heading: "Codex",
        worktree: "main", project: "/repos/zerocode", task: "끝",
        unseen: false, changed_at: 2000, at: 2000 }] },
  ];
  for (const listener of window.__LISTENERS__["hook:agent"] ?? []) {
    listener({ payload: { term: 8, state: "done", agent: "codex" } });
  }
  await new Promise((done) => setTimeout(done, 200));
  return {
    reasked: (window.__COUNTS__.board_snapshot ?? 0) - before,
    agents: document.querySelectorAll("#board-view .agent-graph-node.is-agent").length,
    badge: window.__COUNTS__.set_dock_badge ?? 0,
  };
}, POPOUT_COLUMNS);
ok(
  "the pop-out repaints off the backend's own events and never touches the dock badge",
  popoutLive.reasked > 0 && popoutLive.agents === 2 && popoutLive.badge === 0,
  JSON.stringify(popoutLive),
);

// A card click in the pop-out: the ack crosses to the main window, the live
// screen's floor is paid by the pull its declaration makes (a newborn view has
// no history of its own — and the floor is asked once, not again by the
// dialog), and the footer's door asks the main window to come forward rather
// than staging a tab this window does not have.
const popoutCard = await popoutPage.evaluate(async () => {
  const seen = {};
  window.__SNAPSHOT_TEXT__ = "seeded from the snapshot";
  window.__ANSWER__.ack_board_agent = (args) => {
    seen.ackedPane = args.pane;
    return null;
  };
  window.__ANSWER__.reveal_board_agent = (args) => {
    seen.revealedPane = args.pane;
    return null;
  };
  document.querySelector("#board-view .board-card").click();
  await new Promise((done) => setTimeout(done, 120));
  seen.opened = !document.getElementById("peek-scrim").hidden;
  seen.acked = window.__COUNTS__.ack_board_agent ?? 0;
  // The floor's pull, and the one look the cadence takes after a pull that
  // brought frames. A second ask for the floor would be a third.
  seen.pulled = window.__COUNTS__.term_pull ?? 0;
  seen.snapshots = window.__COUNTS__.term_snapshot ?? 0;
  seen.screen = document.querySelector("#peek-body .terminal .term")?.textContent ?? "";
  seen.closedNoticeHidden = document.getElementById("peek-closed").hidden;
  // Typing reaches the pty through the same door the main window types
  // through — the preview is a real terminal, not a picture of one.
  routeText("hi");
  seen.typed = window.__COUNTS__.term_text ?? 0;
  document.getElementById("peek-open").click();
  await new Promise((done) => setTimeout(done, 60));
  seen.revealed = window.__COUNTS__.reveal_board_agent ?? 0;
  seen.shut = document.getElementById("peek-scrim").hidden;
  delete window.__ANSWER__.ack_board_agent;
  delete window.__ANSWER__.reveal_board_agent;
  return seen;
});
ok(
  "a card in the pop-out shows the live screen, acks across, and its door reveals",
  popoutCard.opened &&
    popoutCard.acked === 1 &&
    popoutCard.ackedPane === "term:7" &&
    popoutCard.revealedPane === "term:7" &&
    popoutCard.pulled >= 1 && popoutCard.pulled <= 2 &&
    popoutCard.snapshots === 0 &&
    popoutCard.screen.includes("seeded from the snapshot") &&
    popoutCard.closedNoticeHidden &&
    popoutCard.typed === 1 &&
    popoutCard.revealed === 1 &&
    popoutCard.shut,
  JSON.stringify(popoutCard),
);

// A card whose shell is gone says so. An empty box does not explain itself,
// and the pop-out is exactly where a dead pane is most likely to be clicked.
const popoutDead = await popoutPage.evaluate(async () => {
  window.__DEAD_TERMS__ = [7];
  dropTermView(7);
  document.querySelector("#board-view .board-card").click();
  await new Promise((done) => setTimeout(done, 120));
  const notice = document.getElementById("peek-closed");
  return {
    said: !notice.hidden,
    words: notice.textContent.trim(),
    over: Math.round(notice.getBoundingClientRect().height),
  };
});
ok(
  "a card with no live shell says so instead of showing an empty box",
  popoutDead.said &&
    popoutDead.words === "No live terminal — this agent's pane has closed." &&
    popoutDead.over > 0,
  JSON.stringify(popoutDead),
);

ok("the pop-out raised no errors", popoutFaults.length === 0, popoutFaults.join(" | "));

/* ---- zo 없는 기계에서도 IDE는 IDE다 (독립 계약) --------------------------
 *
 * zo.rs 첫 줄의 계약: "It must open a folder, edit files, show diffs and run
 * a terminal on a machine that has never heard of `zo`." 부트의 zo 문이
 * `return`이던 시절, 이 기계는 워크트리도 첫 터미널도 받지 못했다 — 접히는
 * 것은 레인 표면 하나여야 한다. 네 번째 페이지가 그 기계다. */
const bareMachinePage = await browser.newPage({ viewport: { width: 1280, height: 860 } });
const bareMachineFaults = [];
bareMachinePage.on("pageerror", (error) => bareMachineFaults.push(String(error)));
await standBackend(bareMachinePage, { ...BOOT, zo: null, serve: "down", lanes: [] });
await bareMachinePage.goto(`${origin}/index.html`);
// `github_status`는 boot 꼬리(ensureGithubStatus)도 부른다 — zo 문이 `return`으로
// 돌아가면 여기 못 온다. project_catalog은 boot 밖 호출자가 있어 신호가 아니다.
await bareMachinePage.waitForFunction(() => (window.__COUNTS__?.github_status ?? 0) > 0, null, { timeout: 15000 });
const bareMachine = await bareMachinePage.evaluate(async () => {
  await new Promise((done) => setTimeout(done, 150));
  const seen = {
    // 레인 표면만 접힌다.
    zoFolded: zoAvailable === false,
    // 그리고 IDE는 선다: boot 꼬리까지 갔고(github_status는 그 꼬리도 부른다),
    // 터미널이 뜬다.
    askedWorktrees: (window.__COUNTS__.github_status ?? 0) > 0,
    stands: tabs.length >= 0 && document.getElementById("tabstrip") !== null,
  };
  // 터미널은 zo 없이도 터미널이다.
  await openTermTab();
  seen.termOpened = tabs.some((one) => one.kind === "term");
  // 레인 문은 조용히 물러난다 — 오류가 아니라 부재가 답이다.
  const lanesBefore = window.__COUNTS__.open_lane ?? 0;
  await openLane();
  seen.laneRefused = (window.__COUNTS__.open_lane ?? 0) === lanesBefore;
  return seen;
});
ok(
  "a machine that has never heard of zo still gets the whole IDE",
  bareMachine.zoFolded && bareMachine.askedWorktrees && bareMachine.stands
    && bareMachine.termOpened && bareMachine.laneRefused,
  JSON.stringify(bareMachine),
);
ok("the bare machine raised no errors", bareMachineFaults.length === 0, bareMachineFaults.join(" | "));
await bareMachinePage.close();

// ---- The titlebar drags every time, not just the first ----
//
// `start_dragging` hands the window to the OS, and that drag's mouseup never
// reaches the webview — so WebKit's click counter reads the NEXT press as a
// double-click's second tap, and every retry after the first drag fell into
// the maximize branch. The handler keeps its own clock now; two quick presses
// maximize, everything else drags, and a press after the interval drags again
// no matter what the browser's counter believes.
const titleDrag = await page.evaluate(async () => {
  window.__ORDER__ = [];
  const calls = () =>
    window.__ORDER__.filter((name) =>
      ["plugin:window|start_dragging", "plugin:window|internal_toggle_maximize"].includes(name),
    );
  const grip = document.querySelector("[data-drag-surface]");
  const press = (detail) =>
    grip.dispatchEvent(new MouseEvent("mousedown", { button: 0, bubbles: true, detail }));
  // The browser believes this is a triple-click (detail 3) — a lost mouseup
  // after a real drag makes exactly this lie. Our clock says: first press.
  press(3);
  const first = calls();
  await new Promise((done) => setTimeout(done, 400));
  press(2);
  const second = calls();
  // Two presses inside the interval — a real double-click — maximizes.
  press(1);
  const third = calls();
  // A control inside that same drag surface keeps the gesture. The tab-strip
  // plus is the live regression: if its mousedown reaches start_dragging, the
  // OS consumes mouseup and neither its click nor the terminal row can run.
  const add = document.querySelector(".tab-new");
  const beforeControl = calls().length;
  add?.dispatchEvent(new MouseEvent("mousedown", { button: 0, bubbles: true }));
  const controlKeptItsPress = Boolean(add) && calls().length === beforeControl;
  window.__ORDER__ = null;
  return { first, second, third, controlKeptItsPress };
});
ok(
  "a drag after a drag still drags — the handler's own clock beats the browser's click count",
  titleDrag.first.length === 1 &&
    titleDrag.first[0] === "plugin:window|start_dragging" &&
    titleDrag.second.length === 2 &&
    titleDrag.second[1] === "plugin:window|start_dragging" &&
    titleDrag.third.length === 3 &&
    titleDrag.third[2] === "plugin:window|internal_toggle_maximize" &&
    titleDrag.controlKeptItsPress,
  JSON.stringify(titleDrag),
);

// ---- The tab wears the program's own title ----
//
// The grid has parsed OSC 0/2 since it learned VT at all and ships the word
// on every delta — this window dropped it, so every tab said "터미널 N" no
// matter what was running inside. Orca's strip names a tab by what its
// terminal says it is doing. Three roads into one answer: the frame (live),
// `term:title` (hidden), and — asserted here — a person's own pane name
// still beating both. The strip takes the word on the agent-paint beat, not
// inside the frame handler (t-161): each road is read after one painted frame.
const titled = await page.evaluate(async () => {
  await openTermTab();
  const tab = [...tabs].reverse().find((one) => one.kind === "term");
  setActiveTab(tab.id);
  await new Promise((done) => setTimeout(done, 80));
  const label = () =>
    document.querySelector(`[data-tab="${tab.id}"] .tab-label`)?.textContent.trim();
  const numbered = label();
  await window.__TERM_FEED__(tab.term, {
          rows: [], scrolled_lines: 0, cursor: [0, 0], title: "vim grid.rs",
          alt_screen: false, size: [24, 80], full: false, cursor_visible: true,
          mouse_tracking: "off", mouse_sgr: false,
        },);
  await window.__PAINTED__();
  const spoken = label();
  for (const listener of window.__LISTENERS__["term:title"] ?? []) {
    listener({ payload: { term: tab.term, title: "cargo build" } });
  }
  await window.__PAINTED__();
  const renamed = label();
  setPaneTitle(tab, tab.term, "내가 지은 이름");
  const chosen = label();
  clearPaneTitle(tab, tab.term);
  dropTermView(tab.term);
  const cleared = termTitles.has(tab.term);
  dropTab(tab.id);
  return { numbered, term: tab.term, spoken, renamed, chosen, cleared };
});
ok(
  "the tab strip names a terminal by its program's OSC title, and a typed pane name still wins",
  // `numbered` is whatever the tab wore before the program spoke — an agent
  // name or a number, both fine; what matters is that the OSC word replaced
  // it, the hidden-shell event replaced that, the typed name beat them all,
  // and closing the shell cleared its word for the next occupant of the id.
  titled.numbered !== "vim grid.rs" &&
    titled.spoken === "vim grid.rs" &&
    titled.renamed === "cargo build" &&
    titled.chosen === "내가 지은 이름" &&
    titled.cleared === false,
  JSON.stringify(titled),
);

// ---- The caret holds solid under typing ----
//
// The blink kept its own clock through keystrokes, so a letter could land in
// the caret's dark phase and read as a missed beat — every real terminal
// rewinds the blink when the cursor moves under a KEYSTROKE and blinks only
// when idle. Two frames must not rewind it: one that does not move the
// cursor, and one that moves it under a program printing on its own — the
// rewind's `getAnimations()` is a style flush, and a stream moves the cursor
// on every frame (t-161). The echo of a typed key is what holds it still.
const caretBeat = await page.evaluate(async () => {
  await openTermTab();
  const tab = [...tabs].reverse().find((one) => one.kind === "term");
  setActiveTab(tab.id);
  await new Promise((done) => setTimeout(done, 80));
  const feed = (cursor) => window.__TERM_FEED__(tab.term, {
            rows: [], scrolled_lines: 0, cursor, title: null,
            alt_screen: false, size: [24, 80], full: false, cursor_visible: true,
            mouse_tracking: "off", mouse_sgr: false,
          },);
  await feed([0, 0]);
  await new Promise((done) => setTimeout(done, 40));
  const host = [...document.querySelectorAll("section.terminal--stage")].at(-1);
  const caret = host.querySelector(".term-caret");
  const beat = (caret.getAnimations?.() ?? [])[0];
  if (!beat) return { unsupported: true };
  // A program moving the cursor with nobody typing: the clock runs on.
  beat.currentTime = 700;
  await feed([0, 5]);
  const streamed = Number(beat.currentTime);
  // One typed letter, through the key sink's own road, then its echo.
  keySink.focus();
  keySink.dispatchEvent(new KeyboardEvent("keydown", {
    key: "a", code: "KeyA", bubbles: true, cancelable: true,
  }));
  keySink.value = "a";
  keySink.dispatchEvent(new InputEvent("input", { bubbles: true }));
  await new Promise((done) => setTimeout(done, 0));
  await feed([0, 6]);
  const moved = Number(beat.currentTime);
  beat.currentTime = 700;
  await feed([0, 6]);
  const still = Number(beat.currentTime);
  dropTermView(tab.term);
  dropTab(tab.id);
  return { streamed, moved, still };
});
ok(
  "a keystroke's echo rewinds the caret's blink; a stream's move and a still frame do not",
  // `currentTime`은 되쓴 값을 그대로 돌려주지 않는다 — 프레임 위상에 따라
  // 10^-13쯤 아래로 내려온다(실측 699.9999999999886). 경계 비교에는 그만큼의
  // 티끌을 준다.
  caretBeat.unsupported === true ||
    (caretBeat.streamed >= 700 - 1e-6 &&
      caretBeat.moved < 350 &&
      caretBeat.still >= 700 - 1e-6),
  JSON.stringify(caretBeat),
);

/* ---- the window gives back everything a shell borrowed (1-ev) -------------
 *
 * A registry that grows forever draws NOTHING. There is no frame it gets
 * wrong, no label that reads oddly, no assertion about the screen that can
 * catch it — the window simply gets heavier all day and the machine is on its
 * knees by the evening, which is the one failure this whole file was blind to.
 * So the assertion is about the bookkeeping itself: `__LEAKCHECK__` counts
 * every map keyed by a shell, a tab, a lane or a checkout, and thirty
 * terminals opened, fed, split and closed have to put the counts back exactly
 * where they were.
 *
 * Thirty rather than two because a leak of one entry per shell is invisible at
 * two and unmistakable at thirty, and because the close roads run in LOOPS —
 * a project switch, a removed checkout, an idle sweep all close many at once,
 * and a door that only works when it is walked through alone is a door that
 * does not work.
 *
 * Measured as a difference from where the run already stood, not against
 * zero: the tests above this one leave the window in whatever state they left
 * it, and a gate that demanded an empty window would be asserting the order of
 * this file rather than the behaviour of that one. */
const leaked = await page.evaluate(async () => {
  /* 시계는 세워 둔다 (t-2412 규칙 2). 이 판이 세는 것은 장부의 크기이고, 30초
   * 짜리 판 스냅샷 박자(`AGENT_RELATIVE_TIME_TICK_MS` → `pane_agents` →
   * `reconcilePaneAgentSnapshot`)는 `hookStates`·`hookStamps`에 줄을 하나 더
   * 놓는다 — 그 줄은 미리 보기가 남긴 것이 아니라 시계가 놓은 것인데, 위상이
   * 두 스냅샷 사이에 떨어지면 그 차이는 「새는 곳」으로 읽힌다(실측
   * `hookStates 0→1, hookStamps 1→2`). 이 판은 왕복 수를 세지 않으므로
   * 주차가 감추는 것도 없다. */
  window.__HOLD_POLLERS__ = true;
  const settle = () => new Promise((done) => setTimeout(done, 30));
  const frame = (term, extra = {}) => window.__TERM_FEED__(term, {
            rows: [{ index: 0, cells: [..."working…"].map((ch) => ({ ch })) }],
            scrolled_lines: 0, cursor: [0, 0], title: `run ${term}`,
            alt_screen: false, size: [24, 80], full: true, cursor_visible: true,
            // Named on the frame so `mouseModes` actually takes an entry —
            // the map is only written when the frame says what the program
            // wants, and a frame that says nothing would leave this whole
            // registry untested.
            mouse_tracking: "motion", mouse_sgr: true, focus_reporting: true,
            bell: true, view_offset: 0, scrollback_len: 0,
            ...extra,
          },);
  const tell = (name, payload) => {
    for (const listener of window.__LISTENERS__[name] ?? []) listener({ payload });
  };
  // 실행 페이지는 판과 같은 숨을 쉰다(`MIRROR_SETTLE_MS`) — 코디네이터가
  // 에이전트를 찔러 보는 짧은 실행들이 탭을 하나씩 가져가지 않도록. 그래서
  // 페이지를 기다릴 때는 고정된 밀리초가 아니라 **선 것**을 기다린다.
  const pageStands = async (id) => {
    for (let tries = 0; tries < 80; tries += 1) {
      if (tabs.some((one) => one.id === `worker:${id}`)) return true;
      await new Promise((done) => setTimeout(done, 25));
    }
    return false;
  };

  const before = window.__LEAKCHECK__();

  // ---- thirty shells, each one made to fill every map it can ----
  const opened = [];
  for (let at = 0; at < 30; at += 1) {
    const term = await openTermTab({ placement: "tab" });
    opened.push(term);
    // A screen, a title, and the pointer modes its program asked for — once
    // the window reads it, because a shell no window reads holds its frames
    // at the backend.
    await syncWatchedTerms();
    await frame(term);
    // What its agent last reported, and which conversation it is on.
    tell("hook:agent", {
      term, state: "working", agent: "claude",
      session: `session-${term}`, resumable: true,
    });
    // The helpers running inside it.
    tell("hook:subagent", {
      term, rows: [{ id: `helper-${term}`, name: "explore", state: "working" }],
    });
    // And what both of them are doing. Two cards per shell, and the helper's
    // is the one nothing else could ever name again: it is keyed by a string
    // built from an id this window will not see a second time, so a close that
    // forgot it would leave an entry no road in the process could remove.
    tell("hook:activity", {
      pane: `term:${term}`,
      activities: [{ seq: 0, activity: { verb: "bash", target: "cargo test", phase: "started" } }],
    });
    tell("hook:activity", {
      pane: `sub:${term}:helper-${term}`,
      activities: [{ seq: 0, activity: { verb: "grep", target: "leak", phase: "started" } }],
    });
    // And a teammate it opened, which is a second real pane in the same tab —
    // so the tab close has two shells to end and the lineage has an edge to
    // forget at each end of it.
    tell("term:split", {
      parent: term, term: term + 10_000, direction: "vertical", title: "helper",
    });
    await syncWatchedTerms();
    await frame(term + 10_000);
  }
  // And the bell, which only marks a shell nobody is looking at — so it is
  // rung now, with twenty-nine of the thirty behind the one on the stage,
  // rather than at the moment each tab was opened and active. It is news, so
  // it comes on its own line for every shell (`term:bell`), read or not.
  for (const term of opened) tell("term:bell", { term });
  await settle();
  const peak = window.__LEAKCHECK__();

  // ---- and all of them closed, the way a person closes them ----
  // With the running-close question answered in advance: every one of these
  // shells reports `working`, and thirty dialogs are not what this test
  // measures — the guard has its own test (1-ft).
  setConfirmCloseRunning(false);
  for (const tab of [...tabs]) if (tab.kind === "term") closeTab(tab.id);
  setConfirmCloseRunning(true);
  await settle();
  const after = window.__LEAKCHECK__();

  // ---- the board's preview, opened and shut on shells this window has no
  // tab for. That is every card in the pop-out, which has no stage at all: the
  // preview MAKES a screen to borrow, and shutting it used to leave the screen
  // parked under the stage with its repaint closure still registered.
  const peekBefore = window.__LEAKCHECK__();
  for (let at = 0; at < 8; at += 1) {
    const term = 90_000 + at;
    await openBoardPeek({ pane: `term:${term}`, heading: `card ${at}`, agent: "claude" }, term);
    await frame(term);
    closeBoardPeek();
  }
  await settle();
  const peekAfter = window.__LEAKCHECK__();

  // ---- the composer, opened and shut ----
  const composerBefore = window.__LEAKCHECK__();
  for (let at = 0; at < 5; at += 1) {
    await openComposer("review", "look at this", "검토");
    closeComposer();
  }
  await settle();
  const composerAfter = window.__LEAKCHECK__();

  // ---- and a workspace gone back and forth ----
  //
  // Both checkouts are visited once first, and the terminal each one opens on
  // arrival is opened there. Otherwise the first hop is measured carrying a
  // tab's worth of everything — which is a tab that is SUPPOSED to exist, and
  // reading it as a leak would be reading the window working.
  const A = "/tmp/zerocode-window-test";
  const B = "/tmp/zerocode-window-test-hop";
  let live = A;
  window.__ANSWER__.set_active_worktree = (args) => ((live = args.path), "main");
  window.__ANSWER__.project_catalog = () => [{
    name: "zerocode", path: A,
    worktrees: [
      { path: A, branch: "main", is_main: true, active: live === A, is_folder: false },
      { path: B, branch: "hop", is_main: false, active: live === B, is_folder: false },
    ],
  }];
  await activateWorktree(A);
  await activateWorktree(B);
  await activateWorktree(A);
  await settle();
  const hopBefore = window.__LEAKCHECK__();
  for (let at = 0; at < 4; at += 1) {
    await activateWorktree(B);
    await activateWorktree(A);
  }
  await settle();
  const hopAfter = window.__LEAKCHECK__();
  delete window.__ANSWER__.project_catalog;
  delete window.__ANSWER__.set_active_worktree;

  // ---- the sentences a repaint says into rows it just built ----
  //
  // Two hundred passes of a list that builds its own nodes. The count in the
  // set is allowed to rise — a handle is not an element — but not one entry
  // may BE an element, because that is the whole of the leak: a plain `Set`
  // kept every detached row of every repaint since boot.
  for (let at = 0; at < 200; at += 1) paintWorktreeBranchList();
  const spoken = window.__LEAKCHECK__();

  // `spokenNodes` is left out of every difference below and asserted on its
  // own. It is a set of HANDLES drained by the collector, so its size falls
  // and rises on a clock no test owns — the question worth asking of it is
  // whether any entry is an element, which is `spokenStrong`.
  const diff = (one, other) =>
    Object.fromEntries(
      Object.keys(other)
        .filter((key) => key !== "spokenNodes" && other[key] !== one[key])
        .map((key) => [key, `${one[key]}→${other[key]}`]),
    );
  window.__HOLD_POLLERS__ = false;
  window.__RELEASE_POLLERS__();
  return {
    grew: diff(before, peak),
    tabs: diff(before, after),
    peek: diff(peekBefore, peekAfter),
    composer: diff(composerBefore, composerAfter),
    hop: diff(hopBefore, hopAfter),
    spokenStrong: spoken.spokenStrong,
    spokenNodes: spoken.spokenNodes,
  };
});

// The rig has to have loaded the maps in the first place, or every assertion
// below is a tautology about a window that did nothing.
ok(
  "thirty shells fill the registries they are supposed to fill",
  ["termViews", "termTitles", "hookStates", "paneSessions", "paneSubagents",
   "paneActivities", "paneParents", "mouseModes", "bellRang", "watchedTerms"]
    .every((key) => key in leaked.grew),
  JSON.stringify(leaked.grew),
);
ok(
  "closing thirty terminals gives every per-shell registry back",
  Object.keys(leaked.tabs).length === 0,
  JSON.stringify(leaked.tabs),
);
ok(
  "the board's preview gives back every screen it made",
  // `acknowledgedPanes` is the exception and is meant to be: looking at a card
  // IS acknowledging it, and that fact belongs to the agent rather than to the
  // dialog — the pop-out has no other memory of what its owner has seen.
  Object.keys(leaked.peek).every((key) => key === "acknowledgedPanes"),
  JSON.stringify(leaked.peek),
);
ok(
  "opening and shutting the composer leaves nothing behind",
  Object.keys(leaked.composer).length === 0,
  JSON.stringify(leaked.composer),
);
ok(
  "walking into a workspace and back leaves nothing behind",
  Object.keys(leaked.hop).length === 0,
  JSON.stringify(leaked.hop),
);
ok(
  "the language registry holds handles on the rows it spoke into, never the rows",
  leaked.spokenStrong === 0,
  `${leaked.spokenStrong} of ${leaked.spokenNodes} entries are elements`,
);

/* The + palette's newcomers stand BESIDE what is being read — the stage's own
 * split, the drag-to-edge road's answer minted for the palette (live report
 * 2026-08-14). A restored session replays many opens and must NOT shatter the
 * stage, so `beside` is the palette's word alone. */
const besides = await page.evaluate(async () => {
  const seen = {};
  let minted = 0;
  window.__ANSWER__.open_browser_pane = () => `browser-s${(minted += 1)}`;
  window.__ANSWER__.browser_place = () => null;
  window.__ANSWER__.browser_navigate = () => null;
  const term = await openTermTab();
  await new Promise((done) => setTimeout(done, 60));
  const groupsBefore = stageGroups().length;
  const hostTab =
    tabs.find((one) => one.id === `term:${term}`) ??
    tabs.filter((one) => one.kind === "term").at(-1);
  const hostPane = hostTab?.pane ?? focusedPane;
  // 팔레트의 새 브라우저: 보고 있는 터미널 옆에 선다.
  await openBrowserTab("https://example.com/split", { beside: true });
  await new Promise((done) => setTimeout(done, 60));
  const browserTab = tabs.find((one) => one.id === "browser:browser-s1");
  seen.browserBeside =
    stageGroups().length === groupsBefore + 1 &&
    browserTab?.pane !== hostPane &&
    stageGroups().includes(browserTab?.pane);
  seen.browserRightward = (function stood(node) {
    if (node.type === "leaf") return false;
    if (
      node.direction === "horizontal" &&
      stageGroups(node.second)[0] === browserTab?.pane
    ) {
      return true;
    }
    return stood(node.first) || stood(node.second);
  })(stageTree());
  // 브라우저가 앞일 때 터미널을 열면 — 셸은 네이티브 페이지 안으로 타일될 수
  // 없으니 — 무대가 갈라져 옆에 선다.
  const groupsMid = stageGroups().length;
  const term2 = await openTermTab();
  await new Promise((done) => setTimeout(done, 60));
  const termTab2 = tabs.find((one) => one.id === `term:${term2}`);
  seen.termBesideBrowser =
    stageGroups().length === groupsMid + 1 &&
    termTab2?.pane !== browserTab?.pane &&
    stageGroups().includes(termTab2?.pane);
  // 복원·팝업의 열기는 갈라지지 않는다: beside 없는 open은 탭이다.
  const groupsHigh = stageGroups().length;
  await openBrowserTab("https://example.com/plain");
  await new Promise((done) => setTimeout(done, 60));
  seen.plainOpensTab = stageGroups().length === groupsHigh;
  // 오른쪽에 이미 자리가 있으면 무대는 더 갈라지지 않는다 — 새 서피스는 그
  // 자리에 탭으로 합류한다 (Orca findReusableRightSplitTarget 실측; 라이브
  // 보고 2026-08-14: "3분활로 열리는데 보기가 힘들어").
  setActiveTab(hostTab.id);
  const groupsFull = stageGroups().length;
  await openBrowserTab("https://example.com/join", { beside: true });
  await new Promise((done) => setTimeout(done, 60));
  const joined = tabs.find((one) => one.id === "browser:browser-s3");
  seen.joinedRight =
    stageGroups().length === groupsFull &&
    joined?.pane === browserTab?.pane &&
    activeTabIn(joined.pane)?.id === joined.id;
  const stageBox = stage.getBoundingClientRect();
  const richBox = groupOf(joined.pane)?.el?.getBoundingClientRect();
  const otherShares = stageGroups()
    .filter((group) => group !== joined.pane)
    .map((group) => groupOf(group).el.getBoundingClientRect().width / stageBox.width);
  seen.richBrowserShare = richBox.width / stageBox.width;
  seen.otherShares = otherShares;
  seen.richBrowserRebalanced =
    seen.richBrowserShare > 0.42 && otherShares.every((share) => share > 0.22);
  closeTab("browser:browser-s3");
  await new Promise((done) => setTimeout(done, 60));
  // 원초 그룹(0)의 마지막 탭이 먼저 떠나도 템플릿의 새시는 남는다 — 그
  // 리프가 접혀 나가면 #pane-0째로 문서에서 떨어져, 이후 모든 템플릿 조회가
  // null을 받는 잠복 버그가 있었다(2026-08-14 발견).
  closeTab(`term:${term}`);
  await new Promise((done) => setTimeout(done, 80));
  seen.chassisHeld =
    document.getElementById("vault-view") !== null && stageGroups().includes(0);
  // 나머지가 다 닫히면 무대는 태어나기 전 모습으로 접힌다.
  closeTab("browser:browser-s1");
  closeTab(`term:${term2}`);
  closeTab("browser:browser-s2");
  await new Promise((done) => setTimeout(done, 120));
  seen.folded = stageGroups().length === groupsBefore;
  seen.vaultAlive = document.getElementById("vault-view") !== null;
  for (const name of ["open_browser_pane", "browser_place", "browser_navigate"]) {
    delete window.__ANSWER__[name];
  }
  return seen;
});
/* 포인터가 이 DOM에 닿으면 키보드를 되찾는다 — 네이티브 판의 클릭은 여기
 * 오지 않으니, 온 클릭은 곧 "사람이 페이지를 떠났다"다. 브라우저 판이 없으면
 * 두드리지 않는다. */
const claims = await page.evaluate(async () => {
  const seen = {};
  const before = window.__COUNTS__.focus_main ?? 0;
  document.dispatchEvent(new PointerEvent("pointerdown", { bubbles: true }));
  await new Promise((done) => setTimeout(done, 30));
  seen.quietWithoutPane = (window.__COUNTS__.focus_main ?? 0) === before;
  window.__ANSWER__.open_browser_pane = () => "browser-k1";
  window.__ANSWER__.browser_place = () => null;
  await openBrowserTab("https://example.com/kbd");
  await new Promise((done) => setTimeout(done, 60));
  document.dispatchEvent(new PointerEvent("pointerdown", { bubbles: true }));
  await new Promise((done) => setTimeout(done, 30));
  seen.claimedWithPane = (window.__COUNTS__.focus_main ?? 0) === before + 1;
  closeTab("browser:browser-k1");
  await new Promise((done) => setTimeout(done, 60));
  delete window.__ANSWER__.open_browser_pane;
  delete window.__ANSWER__.browser_place;
  return seen;
});
ok(
  "a pointer in the window's own DOM claims the keyboard back from the native pane",
  claims.quietWithoutPane && claims.claimedWithPane,
  JSON.stringify(claims),
);

/* 포인터가 내려간 그룹이 곧 focusedPane — 스트립(상단)만이 아니라 판 몸통
 * 가운데를 찍어도 (라이브 보고 2026-08-14). */
const bodyFocus = await page.evaluate(async () => {
  const seen = {};
  window.__ANSWER__.open_browser_pane = () => "browser-f1";
  window.__ANSWER__.browser_place = () => null;
  const term = await openTermTab();
  await new Promise((done) => setTimeout(done, 60));
  const termPane = tabs.find((one) => one.id === `term:${term}`)?.pane ?? focusedPane;
  await openBrowserTab("https://example.com/focus", { beside: true });
  await new Promise((done) => setTimeout(done, 60));
  const browserPane = tabs.find((one) => one.id === "browser:browser-f1")?.pane;
  seen.startsOnBrowser = focusedPane === browserPane;
  // 터미널 판의 몸통(화면 호스트)을 찍는다 — 스트립이 아니라.
  const body = paneHosts.get(`term:${term}`) ?? groups.get(termPane)?.el;
  body.dispatchEvent(new PointerEvent("pointerdown", { bubbles: true }));
  await new Promise((done) => setTimeout(done, 30));
  seen.bodyClickFocusesTerm = focusedPane === termPane;
  // 키는 activeTabId로 흐르니, 몸통 클릭이 그 그룹의 앞 탭을 THE 활성 탭으로
  // 세워야 타이핑이 그 판에 닿는다.
  // openTermTab의 반환 번호가 기본 에이전트 flow에서 실제 탭 번호와 다를 수
  // 있어, 그룹의 앞 탭과 대조한다 — 요점은 "그 그룹의 탭이 THE 활성 탭"이다.
  seen.bodyClickActivatesTab =
    activeTabId === activeTabIn(termPane)?.id && String(activeTabId).startsWith("term:");
  // 브라우저 그룹의 툴바를 찍으면 그쪽으로 돌아온다.
  const bar = groups.get(browserPane)?.el?.querySelector(".browser-toolbar");
  bar.dispatchEvent(new PointerEvent("pointerdown", { bubbles: true }));
  await new Promise((done) => setTimeout(done, 30));
  seen.toolbarClickFocusesBrowser = focusedPane === browserPane;
  closeTab("browser:browser-f1");
  closeTab(`term:${term}`);
  await new Promise((done) => setTimeout(done, 120));
  delete window.__ANSWER__.open_browser_pane;
  delete window.__ANSWER__.browser_place;
  return seen;
});
ok(
  "the pointer's own group takes the keyboard, from the pane's body and not only its strip",
  bodyFocus.startsOnBrowser && bodyFocus.bodyClickFocusesTerm &&
    bodyFocus.bodyClickActivatesTab && bodyFocus.toolbarClickFocusesBrowser,
  JSON.stringify(bodyFocus),
);

ok(
  "the + palette's browser and terminal stand beside what is being read, and only they do",
  besides.browserBeside && besides.browserRightward && besides.joinedRight &&
    besides.richBrowserRebalanced &&
    besides.termBesideBrowser && besides.plainOpensTab &&
    besides.chassisHeld && besides.folded && besides.vaultAlive,
  JSON.stringify(besides),
);

const richStageWeights = await page.evaluate(() => {
  const sample = {
    type: "split",
    direction: "horizontal",
    ratio: 0.5,
    first: { type: "leaf", group: 0 },
    second: {
      type: "split",
      direction: "horizontal",
      ratio: 0.5,
      first: { type: "leaf", group: 1 },
      second: { type: "leaf", group: 2 },
    },
  };
  const weighted = stageTreePreferringGroup(sample, 2);
  const shares = {};
  const walk = (node, share) => {
    if (node.type === "leaf") {
      shares[node.group] = share;
      return;
    }
    walk(node.first, share * node.ratio);
    walk(node.second, share * (1 - node.ratio));
  };
  walk(weighted, 1);
  return {
    shares,
    browserWired: String(openBrowserTab).includes("optimizeRichStageGroup(stood)"),
    emulatorWired: String(openEmulatorTab).includes("optimizeRichStageGroup(stood)"),
  };
});
ok(
  "browser and iOS surfaces receive the wide share of a three-way stage",
  richStageWeights.browserWired && richStageWeights.emulatorWired &&
    richStageWeights.shares[2] > 0.44 &&
    richStageWeights.shares[0] > 0.26 && richStageWeights.shares[1] > 0.26,
  JSON.stringify(richStageWeights),
);

/* 빈 새시는 죽은 반쪽이 아니라 귀향이다(1-g21): 원초 그룹(0)의 마지막 탭이
 * 떠나면 — 새시는 문서의 #pane-0이라 떼어낼 수 없으니 — 무대 이웃의 탭들이
 * 판 0으로 돌아오고 이웃 리프가 접힌다. 복원이 남긴 빈 리프도 같은 문으로
 * 정착하고, 배치는 무대 사각형을 넘지 못하며, 무대 자신의 크기 변화도 판을
 * 다시 놓는다 (라이브 보고 2026-08-14 #64·#65). */
const homecoming = await page.evaluate(async () => {
  const seen = {};
  const placed = [];
  let minted = 0;
  // 앞선 테스트가 열어 둔 팝오버는 이 판들의 이야기가 아니다 — 덮개 검사가
  // 진짜 덮개만 보게 걷어 둔다.
  for (const one of document.querySelectorAll(".note-pop:not([hidden])")) {
    one.hidden = true;
  }
  window.__ANSWER__.open_browser_pane = () => `browser-h${(minted += 1)}`;
  window.__ANSWER__.browser_place = (args) => (placed.push(args), null);
  window.__ANSWER__.browser_navigate = () => null;
  const term = await openTermTab();
  await new Promise((done) => setTimeout(done, 60));
  const termTab =
    tabs.find((one) => one.id === `term:${term}`) ??
    tabs.filter((one) => one.kind === "term").at(-1);
  await openBrowserTab("https://example.com/away", { beside: true });
  await new Promise((done) => setTimeout(done, 60));
  const awayTab = tabs.find((one) => one.id === "browser:browser-h1");
  // 복원의 형상: 판 0에는 곧 닫힐 탭 하나만 — 창이 태어날 때 깔린 탭들과
  // 터미널은 이웃 그룹으로 옮겨 둔다(귀향이 도로 데려온다).
  setActiveTab(termTab.id);
  await openBrowserTab("https://example.com/last");
  await new Promise((done) => setTimeout(done, 60));
  const lastTab = tabs.find((one) => one.id === "browser:browser-h2");
  for (const one of paneTabs(0)) {
    if (one.id !== lastTab.id) one.pane = awayTab.pane;
  }
  renderTabs();
  updateStage();
  seen.split =
    stageGroups().length === 2 && awayTab?.pane !== 0 && lastTab?.pane === 0;
  // 새시의 마지막 탭이 떠난다 — 이웃의 탭 전부가 판 0으로 귀향하고 무대는
  // 하나다.
  closeTab(lastTab.id);
  await new Promise((done) => setTimeout(done, 140));
  seen.cameHome =
    stageGroups().length === 1 &&
    stageGroups()[0] === 0 &&
    awayTab.pane === 0 &&
    termTab.pane === 0;
  seen.chassisAlive = document.getElementById("vault-view") !== null;
  seen.eyeFollowed =
    focusedPane === 0 && paneTabs(0).some((one) => one.id === activeTabId);
  // 귀향한 판은 무대 폭을 다시 쓴다 — 죽은 반쪽 검사.
  setActiveTab(awayTab.id);
  await new Promise((done) => setTimeout(done, 140));
  const wide = placed.at(-1);
  const yard = stage.getBoundingClientRect();
  seen.paneFillsStage =
    wide?.shown === true &&
    wide.width > yard.width * 0.9 &&
    wide.x + wide.width <= yard.x + yard.width + 1;
  // 복원이 남기는 빈 리프(탭 없는 그룹)도 정착 스윕이 접는다.
  const empty = standBesideFocused();
  seen.leafStood = stageGroups().length === 2 && paneTabs(empty).length === 0;
  settleRestoredStage();
  await new Promise((done) => setTimeout(done, 60));
  seen.leafSettled = stageGroups().length === 1 && stageGroups()[0] === 0;
  // 몸이 무대보다 넓다고 말해도 배치는 무대 안에 갇힌다 (#64의 흰 면).
  const body = [...document.querySelectorAll(".browser-view")]
    .find((one) => !one.hidden)
    ?.querySelector(".browser-body");
  placed.length = 0;
  body.style.width = "2000px";
  await new Promise((done) => setTimeout(done, 260));
  const fencedYard = stage.getBoundingClientRect();
  const fenced = placed.at(-1);
  seen.fencedToStage =
    fenced?.shown === true &&
    fenced.width <= fencedYard.width + 1 &&
    fenced.x + fenced.width <= fencedYard.x + fencedYard.width + 1;
  // 몸 크기가 그대로여도 무대가 줄면 판은 다시 놓인다 — 무대 관찰자의 몫.
  placed.length = 0;
  stage.style.width = "480px";
  await new Promise((done) => setTimeout(done, 300));
  const shrunkYard = stage.getBoundingClientRect();
  const shrunk = placed.at(-1);
  seen.followsTheStage =
    shrunk?.shown === true &&
    shrunk.width <= shrunkYard.width + 1 &&
    shrunk.x + shrunk.width <= shrunkYard.x + shrunkYard.width + 1;
  stage.style.width = "";
  body.style.width = "";
  await new Promise((done) => setTimeout(done, 300));
  closeTab("browser:browser-h1");
  closeTab(termTab.id);
  await new Promise((done) => setTimeout(done, 120));
  for (const name of ["open_browser_pane", "browser_place", "browser_navigate"]) {
    delete window.__ANSWER__[name];
  }
  return seen;
});
ok(
  "an emptied chassis brings its neighbour home, and a pane never outgrows the stage",
  homecoming.split && homecoming.cameHome && homecoming.chassisAlive &&
    homecoming.eyeFollowed && homecoming.paneFillsStage && homecoming.leafStood &&
    homecoming.leafSettled && homecoming.fencedToStage && homecoming.followsTheStage,
  JSON.stringify(homecoming),
);

/* 브라우저를 여는 모든 문이 주소창의 사다리를 말한다: 민 호스트는 https를
 * 입고, 낱말은 검색이 되고, 스킴 있는 말은 그대로 — 홈페이지 설정에
 * "naver.com"이라 적어도 항해가 떠난다 (라이브 보고 2026-08-14 "http
 * 안붙여도 자동으로", #18 사이트 설정 안 먹힘의 홈페이지 단면). */
const bareOpens = await page.evaluate(async () => {
  const seen = {};
  const opened = [];
  let minted = 0;
  window.__ANSWER__.open_browser_pane = (args) => (opened.push(args.url), `browser-u${(minted += 1)}`);
  window.__ANSWER__.browser_place = () => null;
  window.__ANSWER__.browser_navigate = () => null;
  const prior = { ...browserPrefs };
  await openBrowserTab("naver.com");
  seen.bareHostGotScheme =
    opened.at(-1) === "https://naver.com/" &&
    tabs.find((one) => one.id === "browser:browser-u1")?.url === "https://naver.com/";
  browserPrefs = { ...browserPrefs, search_engine: "google" };
  await openBrowserTab("고양이 그림");
  seen.wordsBecameSearch =
    opened.at(-1)?.startsWith("https://www.google.com/search?q=") === true;
  browserPrefs = { ...browserPrefs, home_page: "daum.net" };
  await openBrowserTab();
  seen.bareHomePageSails = opened.at(-1) === "https://daum.net/";
  await openBrowserTab("http://localhost:5173/app");
  seen.schemeKept = opened.at(-1) === "http://localhost:5173/app";
  browserPrefs = prior;
  for (const label of ["browser-u1", "browser-u2", "browser-u3", "browser-u4"]) {
    closeTab("browser:" + label);
  }
  await new Promise((done) => setTimeout(done, 120));
  for (const name of ["open_browser_pane", "browser_place", "browser_navigate"]) {
    delete window.__ANSWER__[name];
  }
  return seen;
});
ok(
  "every browser-open door speaks the address ladder, so a bare host still sails",
  bareOpens.bareHostGotScheme && bareOpens.wordsBecameSearch &&
    bareOpens.bareHomePageSails && bareOpens.schemeKept,
  JSON.stringify(bareOpens),
);

/* + 팔레트(1-g23): 모바일 에뮬레이터 행은 뷰포트 상자를 입은 브라우저를
 * 세우고, 하나 있으면 "이동"이 되어 새 탭 없이 그 탭을 앞세운다(Orca의
 * new/goto 단독성). Claude Agent Teams 행은 팀의 이름으로 claude를 띄우고,
 * 팀 모드를 끈 창에는 행 자체가 없다. */
const palette = await page.evaluate(async () => {
  const seen = {};
  const placed = [];
  let streamStarts = 0;
  const streamStops = [];
  let readerSeen = null;
  let minted = 0;
  const fleet = [
    { udid: "U1", name: "iPhone 17", booted: false },
    { udid: "U2", name: "iPad Air", booted: true },
  ];
  window.__ANSWER__.mobile_emulators = () => fleet;
  window.__ANSWER__.android_emulators = () => [];
  window.__ANSWER__.start_emulator_stream = (args) => {
    streamStarts += 1;
    const device = fleet.find((one) => one.udid === (args?.udid ?? "U1")) ?? fleet[0];
    return { stream: `S${streamStarts}`, udid: device.udid, name: device.name };
  };
  window.__ANSWER__.stop_emulator_stream = (args) => (streamStops.push(args.stream), null);
  window.__ANSWER__.open_browser_pane = (args) => (
    (readerSeen = args.userAgent ?? null), `browser-p${(minted += 1)}`
  );
  window.__ANSWER__.browser_place = (args) => (placed.push(args), null);
  window.__ANSWER__.browser_navigate = () => null;
  mobileEmulators = null;
  tcInput.value = "";
  await paintTabCreate();
  const labels = tcActions.map((one) => one.label);
  const simulatorRow = tcActions.find(
    (one) => one.label === t("tabs.newSimulator", "새 모바일 에뮬레이터"),
  );
  seen.simulatorOffered = Boolean(simulatorRow) && simulatorRow.hint === "iOS";
  seen.teamsOffered = labels.includes("Claude Agent Teams");
  // 행을 실행하면 거울 판이 창 안에 선다 — 브라우저 탭이 아니라 (라이브
  // 보고 "orca는 창안에뜸").
  await simulatorRow?.run();
  await new Promise((done) => setTimeout(done, 80));
  // 탭은 스트림으로 찾는다 — 판이 먼저 서고 스트림이 뒤에 붙으므로 탭의
  // 이름은 스트림의 것이 아니고, 기기를 갈아타면 스트림만 바뀐다.
  const mirror = tabs.find((one) => one.kind === "emulator" && one.stream === "S1");
  seen.simulatorBoots =
    streamStarts === 1 && mirror?.kind === "emulator" && mirror?.deviceName === "iPhone 17";
  // 프레임이 오면 objectURL이 img에 앉고, 다음 프레임이 앞 것을 갈아치운다
  // (Orca useEmulatorFrameStream 관용구).
  setActiveTab(mirror.id);
  await new Promise((done) => setTimeout(done, 60));
  const mirrorHost = [...document.querySelectorAll(".emulator-view")].find((one) => !one.hidden);
  const frameImg = mirrorHost?.querySelector(".emulator-frame");
  for (const hear of window.__LISTENERS__["emulator:frame"] ?? []) {
    hear({ payload: { stream: "S1", bytes: btoa("first-frame") } });
  }
  const firstSrc = frameImg?.src ?? "";
  for (const hear of window.__LISTENERS__["emulator:frame"] ?? []) {
    hear({ payload: { stream: "S1", bytes: btoa("second-frame") } });
  }
  seen.framesLand =
    firstSrc.startsWith("blob:") &&
    (frameImg?.src ?? "").startsWith("blob:") &&
    frameImg.src !== firstSrc &&
    frameImg.hidden === false &&
    mirrorHost.querySelector(".emulator-note")?.hidden === true;
  // 멈춘 기기의 소식은 안내문이 된다.
  for (const hear of window.__LISTENERS__["emulator:note"] ?? []) {
    hear({ payload: { stream: "S1", note: "화면이 오지 않습니다" } });
  }
  seen.noteSpeaks =
    mirrorHost.querySelector(".emulator-note")?.hidden === false &&
    mirrorHost.querySelector(".emulator-note")?.textContent === "화면이 오지 않습니다";
  // 탭이 닫히면 펌프도 멈춘다.
  closeTab(mirror.id);
  await new Promise((done) => setTimeout(done, 80));
  seen.closeStopsThePump = streamStops.includes("S1");
  // 판의 치수가 백엔드로 간다 — CSS 상자가 아니라 판이 실제로 칠하는 픽셀로.
  // 배율을 빠뜨리면 레티나에서 정확히 절반 크기의 그림이 와서 판이 그것을 두
  // 배로 늘려 그린다. 그게 "화질이 떨어진다"의 정체다.
  const paintScale = window.devicePixelRatio || 1;
  const measured = emulatorViewportLongEdge({ shellWidth: 300, shellHeight: 660, bezel: 10 });
  seen.viewportMeasuresPaintedPixels =
    measured === Math.ceil(((660 - 20) * paintScale) / 64) * 64 && measured % 64 === 0;
  // 드래그가 눈금을 여럿 지나가도 IPC는 손이 멈춘 뒤 한 번이다 — 크기마다
  // 보내면 헬퍼가 VTCompressionSession을 그 횟수만큼 버리고 새로 만든다.
  const viewportCalls = [];
  window.__ANSWER__.set_emulator_stream_viewport = (args) => (viewportCalls.push(args), null);
  const dragged = { kind: "emulator", stream: "SV" };
  for (const shellHeight of [640, 720, 820, 920]) {
    reportEmulatorViewport(dragged, { shellWidth: 300, shellHeight, bezel: 10 });
  }
  await new Promise((done) => setTimeout(done, 260));
  seen.viewportSettlesToOneCall =
    viewportCalls.length === 1 &&
    viewportCalls[0].stream === "SV" &&
    viewportCalls[0].viewport.longEdgePx ===
      emulatorViewportLongEdge({ shellWidth: 300, shellHeight: 920, bezel: 10 });
  // 같은 눈금 안의 흔들림은 아무 말도 만들지 않는다.
  viewportCalls.length = 0;
  reportEmulatorViewport(dragged, { shellWidth: 300, shellHeight: 919, bezel: 10 });
  await new Promise((done) => setTimeout(done, 260));
  seen.viewportSaysNothingInsideTheQuantum = viewportCalls.length === 0;
  delete window.__ANSWER__.set_emulator_stream_viewport;
  // 실측된 툴바(EmulatorPaneToolbar): 기기 Select·상태·전원. 갈아타면 옛
  // 펌프가 멈추고 고른 기기의 스트림이 선다; 전원은 살아 있으면 끄기다.
  let shutdowns = [];
  window.__ANSWER__.shutdown_mobile_emulator = (args) => (shutdowns.push(args.udid), null);
  await openEmulatorTab();
  await new Promise((done) => setTimeout(done, 80));
  const mirror2 = tabs.filter((one) => one.kind === "emulator").at(-1);
  setActiveTab(mirror2.id);
  await new Promise((done) => setTimeout(done, 60));
  const host2 = [...document.querySelectorAll(".emulator-view")].find((one) => !one.hidden);
  const pick = host2.querySelector(".emulator-pick");
  seen.pickerListsTheFleet =
    pick && pick.options.length === 2 && pick.value === "ios:" + mirror2.udid;
  const streamWas = mirror2.stream;
  pick.value = "ios:U2";
  pick.dispatchEvent(new Event("change", { bubbles: true }));
  await new Promise((done) => setTimeout(done, 120));
  seen.switchRestreams =
    streamStops.includes(streamWas) &&
    mirror2.udid === "U2" &&
    mirror2.deviceName === "iPad Air" &&
    mirror2.stream !== streamWas &&
    host2.querySelector(".emulator-bezel").classList.contains("is-tablet");
  // 프레임이 오면 상태가 "연결됨"이 되고, 전원은 끄기가 된다.
  for (const hear of window.__LISTENERS__["emulator:frame"] ?? []) {
    hear({ payload: { stream: mirror2.stream, bytes: btoa("ipad-frame") } });
  }
  seen.framesSayConnected =
    host2.querySelector(".emulator-status").textContent ===
    t("emulator.connected", "연결됨");
  const streamAtPowerOff = mirror2.stream;
  host2.querySelector(".emulator-power").click();
  await new Promise((done) => setTimeout(done, 120));
  seen.powerShutsDown =
    shutdowns.includes("U2") && streamStops.includes(streamAtPowerOff);
  // 끈 자리는 비지 않는다 — 같은 칸에 빈 셸이 서고, 에뮬레이터 탭은 간다.
  const standIn = tabs.find((one) => one.id === `term:${window.__NEXT_TERM__}`);
  seen.powerLeavesAShell =
    !tabs.includes(mirror2) &&
    standIn?.kind === "term" &&
    standIn?.pane === mirror2.pane &&
    activeTabId === standIn?.id;
  closeTab(standIn?.id);
  await new Promise((done) => setTimeout(done, 80));
  // 실패한 끄기는 판을 갈아치우지 않는다 — 기기가 아직 살아 있고, 판이 그
  // 사실과 다시 시도할 전원 단추를 함께 든다.
  await openEmulatorTab();
  await new Promise((done) => setTimeout(done, 80));
  const mirror3 = tabs.filter((one) => one.kind === "emulator").at(-1);
  setActiveTab(mirror3.id);
  for (const hear of window.__LISTENERS__["emulator:frame"] ?? []) {
    hear({ payload: { stream: mirror3.stream, bytes: btoa("live-frame") } });
  }
  window.__FAIL__.add("shutdown_mobile_emulator");
  const shellsBefore = tabs.filter((one) => one.kind === "term").length;
  const host3 = [...document.querySelectorAll(".emulator-view")].find((one) => !one.hidden);
  host3.querySelector(".emulator-power").click();
  await new Promise((done) => setTimeout(done, 120));
  window.__FAIL__.delete("shutdown_mobile_emulator");
  seen.failedPowerKeepsThePane =
    tabs.includes(mirror3) &&
    tabs.filter((one) => one.kind === "term").length === shellsBefore &&
    host3.querySelector(".emulator-note").hidden === false;
  closeTab(mirror3.id);
  await new Promise((done) => setTimeout(done, 80));
  delete window.__ANSWER__.shutdown_mobile_emulator;
  // 부팅 자막(D6): 판이 서는 그 턴에 「부팅 중 · <기기> · n초」가 서고, 첫
  // 프레임이 오면 눕는다. 스트림은 일부러 늦게 답한다 — 콜드 부팅이 그렇고
  // (실측 42.3 s), 자막이 그 대답을 기다린다면 판은 그동안 빈칸이다.
  let letTheStreamAnswer = null;
  const wasAnswering = window.__ANSWER__.start_emulator_stream;
  window.__ANSWER__.start_emulator_stream = (args) =>
    new Promise((settle) => {
      streamStarts += 1;
      const device = fleet.find((one) => one.udid === (args?.udid ?? "U1")) ?? fleet[0];
      const stream = `S${streamStarts}`;
      letTheStreamAnswer = () => settle({ stream, udid: device.udid, name: device.name });
    });
  const openedAt = performance.now();
  const opening = openEmulatorTab("ios", "U1");
  const booting = tabs.filter((one) => one.kind === "emulator").at(-1);
  const bootHost = [...document.querySelectorAll(".emulator-view")].find(
    (one) => one._emulatorTab === booting,
  );
  const bootNote = bootHost?.querySelector(".emulator-note");
  seen.captionMs = Math.round(performance.now() - openedAt);
  seen.captionStandsBeforeTheStreamAnswers =
    bootNote?.hidden === false &&
    bootNote.textContent === t("emulator.booting", "부팅 중 · {{device}} · {{seconds}}초", {
      device: "U1",
      seconds: 0,
    }) &&
    seen.captionMs < 100;
  // 스트림은 아직 아무것도 답하지 않았다 — 자막이 먼저 섰다는 뜻.
  await new Promise((done) => setTimeout(done, 40));
  seen.captionStandsWhileTheDeviceBoots =
    typeof letTheStreamAnswer === "function" &&
    booting.stream === undefined &&
    bootNote.hidden === false;
  // 초는 흐른 시간에서 나온다 — 1초 타이머를 기다리지 않고 그 계산을 본다.
  seen.captionCountsTheSeconds =
    emulatorBootWords(booting, booting.bootingSince + 3_200).includes("3") &&
    emulatorBootWords({ bootingSince: booting.bootingSince }, booting.bootingSince + 1_000) ===
      t("emulator.bootingUnnamed", "부팅 중 · {{seconds}}초", { seconds: 1 });
  letTheStreamAnswer();
  await opening;
  await new Promise((done) => setTimeout(done, 40));
  // 기기가 대답해도 그림이 온 것은 아니다: 이름만 자막에 들어선다.
  seen.captionWearsTheDeviceName =
    bootNote.hidden === false && bootNote.textContent.includes("iPhone 17");
  for (const hear of window.__LISTENERS__["emulator:frame"] ?? []) {
    hear({ payload: { stream: booting.stream, bytes: btoa("boot-frame") } });
  }
  seen.captionGoesOnTheFirstFrame =
    bootNote.hidden === true && booting.bootCaptionAt === null && booting.bootingSince === null;
  closeTab(booting.id);
  await new Promise((done) => setTimeout(done, 80));
  window.__ANSWER__.start_emulator_stream = wasAnswering;
  // 한글로 물어도 행이 답한다.
  tcInput.value = t("tabs.simKeywordIphone", "아이폰");
  await paintTabCreate();
  seen.foundByKorean = tcActions.some(
    (one) => one.label === t("tabs.newSimulator", "새 모바일 에뮬레이터"),
  );
  tcInput.value = "";
  // 기계가 시뮬레이터를 답하지 못하면 행 자체가 없다 (Orca hasSimulator).
  window.__ANSWER__.mobile_emulators = () => [];
  mobileEmulators = null;
  await paintTabCreate();
  seen.simulatorHiddenWithout = !tcActions.some(
    (one) => one.label === t("tabs.newSimulator", "새 모바일 에뮬레이터"),
  );
  window.__ANSWER__.mobile_emulators = () => [
    { udid: "U1", name: "iPhone 17", booted: false },
  ];
  mobileEmulators = null;
  // 팀 모드를 끄면 행이 없다 — 없는 것은 없는 것.
  const modeWas = agentTeamsMode;
  agentTeamsMode = "off";
  await paintTabCreate();
  seen.teamsHidesWithMode = !tcActions.some((one) => one.label === "Claude Agent Teams");
  agentTeamsMode = modeWas === "off" ? "panes" : modeWas;
  // Teams 행: 팀의 이름으로 claude를 띄운다.
  let launched = null;
  window.__ANSWER__.launch_agent_tab = (args) => ((launched = args.agent), 991);
  await paintTabCreate();
  await tcActions.find((one) => one.label === "Claude Agent Teams")?.run();
  await new Promise((done) => setTimeout(done, 80));
  seen.teamsLaunchesClaude = launched === "claude";
  seen.teamsTabStood = tabs.some((one) => one.id === "term:991");
  // 독자(UA)를 입은 브라우저는 세션 기록에 그 독자 문자열로 적힌다 (1-g25
  // 기계; t-3043 부터 `mobile` 불리언 대신 `reader` 문자열).
  await openBrowserTab("https://example.com/dress", { userAgent: MOBILE_EMULATOR_UA });
  await new Promise((done) => setTimeout(done, 80));
  seen.recordRemembers =
    String(readerSeen ?? "").includes("iPhone") &&
    (browserPrefs.open_tabs ?? []).some(
      (one) => one && typeof one === "object" && one.reader === MOBILE_EMULATOR_UA
        && !("mobile" in one),
    );
  // 재시작 복원: 기록이 에뮬레이터 브라우저를 옷째 되살린다 — 넓은 단일
  // 그룹에서 잰다(좁은 조각에선 클램프가 폭을 가려 설계상 같아진다).
  const prefsWere = { ...browserPrefs };
  closeTab("term:991");
  for (const one of tabs.filter((held) => String(held.id).startsWith("browser:browser-p"))) {
    closeTab(one.id);
  }
  await new Promise((done) => setTimeout(done, 120));
  browserPrefs = {
    ...browserPrefs,
    restore_tabs: true,
    open_tabs: [{ url: "https://example.com/back", viewport: "mobile-m", mobile: true }],
  };
  readerSeen = null;
  placed.length = 0;
  await restoreBrowserTabs();
  await new Promise((done) => setTimeout(done, 260));
  const backTab = tabs.filter((one) => one.kind === "browser").at(-1);
  seen.restoreRedresses =
    backTab?.viewport === "mobile-m" &&
    String(readerSeen ?? "").includes("iPhone") &&
    placed.at(-1)?.width === 375;
  seen.restoreUsesDefaultZoom =
    backTab?.zoomLevel === browserPrefs.default_zoom_level &&
    Math.abs(backTab?.zoom - Math.pow(1.2, browserPrefs.default_zoom_level))
      < Number.EPSILON * 8;
  closeTab(backTab?.id);
  await new Promise((done) => setTimeout(done, 120));
  // 실패한 열기는 아무도 입히지 않는다 — 복원 루프의 가드.
  window.__ANSWER__.open_browser_pane = () => {
    throw new Error("판이 서지 않았습니다");
  };
  const lastBefore = tabs.at(-1);
  await restoreBrowserTabs();
  await new Promise((done) => setTimeout(done, 60));
  seen.failedOpenDressesNobody =
    tabs.at(-1) === lastBefore && (lastBefore?.viewport ?? null) === null;
  browserPrefs = prefsWere;
  mobileEmulators = null;
  for (const name of [
    "mobile_emulators",
    "android_emulators",
    "start_emulator_stream",
    "stop_emulator_stream",
    "open_browser_pane",
    "browser_place",
    "browser_navigate",
    "launch_agent_tab",
  ]) {
    delete window.__ANSWER__[name];
  }
  return seen;
});
ok(
  `the emulator pane's boot caption stands in ${palette.captionMs}ms, counts up, and goes on the first frame`,
  palette.captionStandsBeforeTheStreamAnswers && palette.captionStandsWhileTheDeviceBoots &&
    palette.captionCountsTheSeconds &&
    palette.captionWearsTheDeviceName && palette.captionGoesOnTheFirstFrame,
  `caption ${palette.captionMs}ms (≤100ms, D6)`,
);
ok(
  "the + palette's emulator row boots the real simulator, and the dressed records still restore",
  palette.simulatorOffered && palette.simulatorBoots && palette.framesLand &&
    palette.noteSpeaks && palette.closeStopsThePump && palette.pickerListsTheFleet &&
    palette.switchRestreams && palette.framesSayConnected && palette.powerShutsDown &&
    palette.powerLeavesAShell && palette.failedPowerKeepsThePane &&
    palette.simulatorHiddenWithout &&
    palette.foundByKorean && palette.teamsOffered && palette.teamsHidesWithMode &&
    palette.teamsLaunchesClaude && palette.teamsTabStood && palette.recordRemembers &&
    palette.restoreRedresses && palette.restoreUsesDefaultZoom && palette.failedOpenDressesNobody,
  JSON.stringify(palette),
);

/* 탭 복원 기록의 독자는 문자열이다(t-3043 §2.5): 사이트별·맞춤 에이전트가
 * 재시작을 건너고, 옛 파일의 `mobile: true` 는 여전히 아이폰 독자로 읽히며,
 * 기록은 새 철자로만 쓰인다. 표의 행을 입고 태어난 판은 기록에 독자가 없다
 * — 다음 부팅에도 표가 다시 입히므로, 기록이 그 이름을 굳히면 안 된다. */
const readerRecords = await page.evaluate(async () => {
  const seen = {};
  const opened = [];
  window.__ANSWER__.open_browser_pane = (args) => {
    opened.push(args.userAgent ?? null);
    return `browser-ua${opened.length}`;
  };
  const prefsWere = { ...browserPrefs };
  browserPrefs = {
    ...browserPrefs,
    restore_tabs: true,
    open_tabs: [
      { url: "https://example.com/old", viewport: "mobile-m", mobile: true },
      { url: "https://example.com/new", reader: "Custom/1" },
      "https://example.com/bare",
    ],
  };
  await restoreBrowserTabs();
  await new Promise((done) => setTimeout(done, 260));
  seen.oldBooleanRestoresTheIphone = String(opened[0] ?? "").includes("iPhone");
  seen.readerStringRestoresItself = opened[1] === "Custom/1";
  seen.bareAddressHasNoReader = opened[2] === null;
  const born = tabs.filter((one) => String(one.id).startsWith("browser:browser-ua"));
  seen.threeStood = born.length === 3;
  seen.tabsWearTheirReader =
    born[0]?.reader === MOBILE_EMULATOR_UA && born[1]?.reader === "Custom/1"
      && (born[2]?.reader ?? null) === null;
  // 다시 쓰는 기록은 새 철자뿐이다.
  const records = browserOpenTabRecords().filter((one) => one.url.startsWith("https://example.com/"));
  seen.writesTheReaderSpelling =
    records.length === 3
      && records.every((one) => !("mobile" in one) && "reader" in one)
      && records[0].reader === MOBILE_EMULATOR_UA
      && records[1].reader === "Custom/1"
      && records[2].reader === null;
  // 옛 철자와 새 철자는 같은 기록이다 — 부팅 직후 파일을 괜히 다시 쓰지 않는다.
  seen.oldAndNewCompareEqual =
    sameTabRecord(
      storedTabRecordOf({ url: "u", viewport: null, mobile: true, profile: null }),
      { url: "u", viewport: null, reader: MOBILE_EMULATOR_UA, profile: null },
    )
    && !sameTabRecord(
      storedTabRecordOf({ url: "u", reader: "Custom/1" }),
      { url: "u", viewport: null, reader: "Custom/2", profile: null },
    )
    && storedTabRecordOf("https://bare.example/").reader === null;
  for (const one of born) closeTab(one.id);
  await new Promise((done) => setTimeout(done, 120));
  browserPrefs = prefsWere;
  delete window.__ANSWER__.open_browser_pane;
  return seen;
});
ok(
  "a stored tab's reader survives a restart as a string — the old mobile boolean still restores the iPhone, and the record is written in the new spelling",
  readerRecords.oldBooleanRestoresTheIphone && readerRecords.readerStringRestoresItself &&
    readerRecords.bareAddressHasNoReader && readerRecords.threeStood &&
    readerRecords.tabsWearTheirReader && readerRecords.writesTheReaderSpelling &&
    readerRecords.oldAndNewCompareEqual,
  JSON.stringify(readerRecords),
);

/* file:// 탭은 복원 기록에 적지 않는다 (t-4088). 문(`set_browser_open_tabs`)은
 * 웹 주소만 받고, 한 행이 걸리면 저장 전체를 오류로 돌려 「브라우저 탭 주소를
 * 저장할 수 없습니다」가 떴다 — 아티팩트 발행 주소가 file://라 아티팩트를
 * 탭으로 여는 순간마다(Computer Use 중 13:14). 기록은 문이 받는 것만 싣고,
 * 옆의 웹 탭은 그대로 실리며, 탭 자체는 열린다. */
const fileTabRecord = await page.evaluate(async () => {
  const seen = {};
  let opened = 0;
  window.__ANSWER__.open_browser_pane = () => `browser-file${++opened}`;
  const prefsWere = { ...browserPrefs };
  await openBrowserTab("https://example.com/kept");
  await openBrowserTab(
    "file:///Users/dev/Library/Application%20Support/dev.zerocode.app/artifacts/pages/p-1/index.html",
  );
  await new Promise((done) => setTimeout(done, 160));
  const born = tabs.filter((one) => String(one.id).startsWith("browser:browser-file"));
  seen.bothStood = born.length === 2 && String(born[1]?.url ?? "").startsWith("file:");
  const records = browserOpenTabRecords();
  seen.fileTabNotRecorded = !records.some((one) => one.url.startsWith("file:"));
  seen.webTabStillRecorded = records.some((one) => one.url === "https://example.com/kept");
  // 문으로 간 것도 같다 — rememberBrowserOpenTabs 가 보낸 기록이 browserPrefs 에 선다.
  const remembered = (browserPrefs.open_tabs ?? []).map((one) => storedTabRecordOf(one).url);
  seen.doorNeverSeesTheFile = !remembered.some((url) => String(url).startsWith("file:"));
  seen.doorStillSeesTheWeb = remembered.includes("https://example.com/kept");
  for (const one of born) closeTab(one.id);
  await new Promise((done) => setTimeout(done, 120));
  browserPrefs = prefsWere;
  delete window.__ANSWER__.open_browser_pane;
  return seen;
});
ok(
  "a file:// tab is not written into the restore record, and the web tab beside it still is",
  fileTabRecord.bothStood && fileTabRecord.fileTabNotRecorded && fileTabRecord.webTabStillRecorded &&
    fileTabRecord.doorNeverSeesTheFile && fileTabRecord.doorStillSeesTheWeb,
  JSON.stringify(fileTabRecord),
);

/* iOS 입력도 같은 판의 손을 탄다. 공개 simctl 캡처와 별개로 백엔드가
 * interactive capability를 답했을 때만 터치·타이핑·Home·Rotate가 선다. */
const iosInput = await page.evaluate(async () => {
  const seen = {};
  const taps = [];
  const swipes = [];
  const texts = [];
  const buttons = [];
  const installs = [];
  const rotations = [];
  const multiTouches = [];
  const acknowledgements = [];
  const pauses = [];
  let frameChannel = null;
  window.__ANSWER__.mobile_emulators = () => [
    { udid: "IOS-HID", name: "iPhone Interactive", booted: true },
  ];
  window.__ANSWER__.android_emulators = () => [];
  window.__ANSWER__.start_emulator_stream = (args) => {
    frameChannel = args.onFrame;
    return {
      stream: "ios-hid-stream",
      udid: "IOS-HID",
      name: "iPhone Interactive",
      platform: "ios",
      interactive: true,
    };
  };
  window.__ANSWER__.stop_emulator_stream = () => null;
  window.__ANSWER__.acknowledge_emulator_payload = (args) =>
    (acknowledgements.push(args), null);
  window.__ANSWER__.set_emulator_stream_paused = (args) => (pauses.push(args), null);
  window.__ANSWER__.set_emulator_stream_engaged = () => null;
  const touches = [];
  window.__ANSWER__.ios_tap = (args) => (taps.push(args), null);
  window.__ANSWER__.ios_touch = (args) => (touches.push(args), null);
  window.__ANSWER__.ios_swipe = (args) => (swipes.push(args), null);
  window.__ANSWER__.ios_text = (args) => (texts.push(args), null);
  window.__ANSWER__.ios_button = (args) => (buttons.push(args), null);
  window.__ANSWER__.ios_rotate = (args) => (rotations.push(args), null);
  window.__ANSWER__.ios_multi_touch = (args) => (multiTouches.push(args), null);
  window.__ANSWER__.choose_emulator_app = () => "/tmp/Demo.app";
  window.__ANSWER__.ios_install_app = (args) => (installs.push(args), null);
  mobileEmulators = null;
  await openEmulatorTab("ios", "IOS-HID");
  await new Promise((done) => setTimeout(done, 80));
  const tab = tabs.find((one) => one.stream === "ios-hid-stream");
  setActiveTab(tab.id);
  await new Promise((done) => setTimeout(done, 50));
  const host = [...document.querySelectorAll(".emulator-view")].find((one) => !one.hidden);
  const rawFrame = new TextEncoder().encode("ios-frame");
  const packet = new Uint8Array(8 + rawFrame.length);
  new DataView(packet.buffer).setBigUint64(0, 42n);
  packet.set(rawFrame, 8);
  frameChannel.onmessage(packet.buffer);
  const frame = host.querySelector(".emulator-frame");
  frame.onload?.();
  frame.style.width = "200px";
  frame.style.height = "400px";
  const box = frame.getBoundingClientRect();
  const point = (type, x, y, pointerId = 91) => frame.dispatchEvent(new PointerEvent(type, {
    bubbles: true,
    pointerId,
    clientX: box.left + box.width * x,
    clientY: box.top + box.height * y,
  }));
  point("pointerdown", 0.25, 0.3);
  point("pointerup", 0.25, 0.3);
  point("pointerdown", 0.2, 0.8);
  point("pointerup", 0.8, 0.2);
  point("pointerdown", 0.35, 0.5, 101);
  point("pointerdown", 0.65, 0.5, 102);
  point("pointermove", 0.2, 0.5, 101);
  point("pointermove", 0.8, 0.5, 102);
  point("pointerup", 0.2, 0.5, 101);
  point("pointerdown", 0.4, 0.4, 103);
  tab.emulatorEpoch = (tab.emulatorEpoch ?? 0) + 1;
  point("pointerup", 0.4, 0.4, 103);
  tab.emulatorEpoch -= 1;
  frame.dispatchEvent(new WheelEvent("wheel", {
    bubbles: true,
    cancelable: true,
    clientX: box.left + box.width * 0.5,
    clientY: box.top + box.height * 0.5,
    deltaY: 120,
  }));
  host._emulatorKeydown({
    key: "한",
    metaKey: false,
    ctrlKey: false,
    preventDefault() {},
  });
  host._emulatorKeydown({
    key: "Enter",
    metaKey: false,
    ctrlKey: false,
    preventDefault() {},
  });
  host._emulatorKeydown({
    key: "ArrowLeft",
    metaKey: false,
    ctrlKey: false,
    preventDefault() {},
  });
  host.querySelector('.emulator-key[data-button="home"]').click();
  host.querySelector('.emulator-side-key[data-key="volume-up"]').click();
  host.querySelector('.emulator-side-key[data-key="power"]').click();
  host.querySelector('.emulator-side-key[data-key="action"]').click();
  host.querySelector(".emulator-install").click();
  host.querySelector(".emulator-rotate").click();
  await new Promise((done) => setTimeout(done, 120));
  seen.capabilityDrawsControls =
    host.querySelector(".emulator-keys").hidden === false &&
    host.querySelector('.emulator-key[data-button="home"]').hidden === false &&
    host.querySelector('.emulator-key[data-button="back"]').hidden === true &&
    host.querySelector(".emulator-outward").hidden === false;
  // 손가락이 흐른다: 탭도 끌기도 begin/end의 짝이고, 합성 tap/swipe는 이제
  // 휠에만 남는다. 두 손가락이 서는 순간 흐르던 손가락은 마지막 좌표에서
  // 들리고, 짝이 맞으므로 기기에 끼는 손가락이 없다.
  const phases = touches.map((one) => one.phase).join(",");
  const near = (value, want) => Math.abs(value - want) < 0.01;
  seen.touchReachesHid =
    taps.length === 0 &&
    touches.length === 8 &&
    touches.every((one) => one.udid === "IOS-HID") &&
    phases === "begin,end,begin,end,begin,end,begin,end" &&
    near(touches[0].x, 0.25) && near(touches[1].x, 0.25) &&
    near(touches[2].x, 0.2) && near(touches[3].x, 0.8) &&
    near(touches[4].x, 0.35) && near(touches[5].x, 0.35) &&
    swipes.length === 1 && swipes.every((one) => one.udid === "IOS-HID");
  seen.keyboardReachesHid =
    texts.some((one) => one.text === "한" && one.udid === "IOS-HID") &&
    buttons.some((one) => one.name === "enter" && one.udid === "IOS-HID") &&
    buttons.some((one) => one.name === "left" && one.udid === "IOS-HID");
  seen.toolbarReachesHid =
    buttons.some((one) => one.name === "home" && one.udid === "IOS-HID") &&
    buttons.some((one) => one.name === "volume-up" && one.udid === "IOS-HID") &&
    buttons.some((one) => one.name === "power" && one.udid === "IOS-HID") &&
    buttons.some((one) => one.name === "action" && one.udid === "IOS-HID") &&
    rotations.length === 1 && rotations[0].rotation === 1;
  seen.multiTouchReachesHid =
    multiTouches.length === 1 && multiTouches[0].udid === "IOS-HID" &&
    multiTouches[0].x1 < multiTouches[0].x2 && multiTouches[0].x3 < multiTouches[0].x4;
  // 기기를 갈아탄 채 놓아도 begin이 갔던 그 기기로 end가 간다 — 낀 손가락이
  // 반쯤 뽑힌 블러로 화면을 덮는 것이 문맥 불일치보다 나쁜 결과라서다.
  seen.gestureGenerationSafe =
    touches[6]?.phase === "begin" && touches[7]?.phase === "end" &&
    near(touches[7].x, 0.4) && touches[7].udid === "IOS-HID";
  seen.installUsesScopedPicker =
    installs.length === 1 && installs[0].udid === "IOS-HID" && installs[0].path === "/tmp/Demo.app";
  host.hidden = true;
  syncEmulatorStreamVisibility();
  host.hidden = false;
  syncEmulatorStreamVisibility();
  seen.payloadIsBounded = acknowledgements.some(
    (one) => one.stream === "ios-hid-stream" && one.sequence === 42,
  );
  seen.visibilityPausesWork =
    pauses.some((one) => one.stream === "ios-hid-stream" && one.paused === true) &&
    pauses.some((one) => one.stream === "ios-hid-stream" && one.paused === false);
  closeTab(tab.id);
  seen.binaryChannelReleased = frameChannel.cleaned === true;
  for (const name of [
    "mobile_emulators",
    "android_emulators",
    "start_emulator_stream",
    "stop_emulator_stream",
    "acknowledge_emulator_payload",
    "set_emulator_stream_paused",
    "set_emulator_stream_engaged",
    "ios_tap",
    "ios_touch",
    "ios_swipe",
    "ios_text",
    "ios_button",
    "ios_rotate",
    "ios_multi_touch",
    "choose_emulator_app",
    "ios_install_app",
  ]) delete window.__ANSWER__[name];
  return seen;
});
ok(
  "the iOS mirror exposes HID input only when its native capability is live",
  iosInput.capabilityDrawsControls && iosInput.touchReachesHid &&
    iosInput.keyboardReachesHid && iosInput.toolbarReachesHid &&
    iosInput.multiTouchReachesHid && iosInput.gestureGenerationSafe &&
    iosInput.installUsesScopedPicker &&
    iosInput.payloadIsBounded && iosInput.visibilityPausesWork && iosInput.binaryChannelReleased,
  JSON.stringify(iosInput),
);

/* 프로필(1-g26): 기어 메뉴 맨 위가 쿠키 단지들이다 — ✓ 기본과 이름들,
 * 그리고 "새 프로필…". 단지를 고르면 판이 같은 자리·같은 주소로 그 단지에서
 * 다시 서고(재생성 — 프로필·독자는 생성 시에만), 이름표를 아는 장부(본-순서·
 * 활성 탭)가 새 이름을 따라간다. */
const profiles = await page.evaluate(async () => {
  const seen = {};
  const opens = [];
  const closes = [];
  let minted = 0;
  window.__ANSWER__.browser_profiles = () => [{ id: "a".repeat(32), name: "일터" }];
  window.__ANSWER__.create_browser_profile = (args) => ({ id: "b".repeat(32), name: args.name });
  window.__ANSWER__.open_browser_pane = (args) => (
    opens.push(args), `browser-j${(minted += 1)}`
  );
  window.__ANSWER__.close_browser_pane = (args) => (closes.push(args.label), null);
  window.__ANSWER__.browser_place = () => null;
  window.__ANSWER__.browser_navigate = () => null;
  await openBrowserTab("https://example.com/jar");
  await new Promise((done) => setTimeout(done, 60));
  const tab = tabs.find((one) => one.id === "browser:browser-j1");
  setActiveTab(tab.id);
  await new Promise((done) => setTimeout(done, 60));
  const host = [...document.querySelectorAll(".browser-view")].find((one) => !one.hidden);
  host.querySelector(".browser-menu").click();
  await new Promise((done) => setTimeout(done, 120));
  const rows = [...document.querySelectorAll("#sidebar-menu .sidebar-menu-item .sidebar-menu-label")].map(
    (one) => one.textContent,
  );
  seen.menuLeadsWithJars =
    rows[0] === t("browser.profile", "프로필") &&
    rows[1] === "✓ " + t("browser.profileDefault", "기본") &&
    rows[2] === "일터" &&
    rows[3] === t("browser.newProfile", "새 프로필…");
  // 단지를 고른다: 새 판이 그 프로필로 서고, 옛 판은 닫히고, 이름표가 옮는다.
  const before = groupRecents.get(tab.pane) ? [...groupRecents.get(tab.pane)] : null;
  [...document.querySelectorAll("#sidebar-menu .sidebar-menu-item")]
    .find((one) => one.textContent === "일터")
    ?.click();
  await new Promise((done) => setTimeout(done, 160));
  seen.rebornInJar =
    opens.at(-1)?.profile === "a".repeat(32) &&
    opens.at(-1)?.url === "https://example.com/jar" &&
    closes.includes("browser-j1") &&
    tab.id === "browser:browser-j2" &&
    tab.profile === "a".repeat(32) &&
    activeTabId === "browser:browser-j2";
  seen.ledgerFollows = (groupRecents.get(tab.pane) ?? []).includes("browser:browser-j2");
  // 기록도 단지를 적는다.
  seen.recordCarriesJar = (browserPrefs.open_tabs ?? []).some(
    (one) => one && typeof one === "object" && one.profile === "a".repeat(32),
  );
  // 새 프로필…: 이름을 물어 만들고, 곧장 그 단지로 갈아입는다.
  host.querySelector(".browser-menu").click();
  await new Promise((done) => setTimeout(done, 120));
  [...document.querySelectorAll("#sidebar-menu .sidebar-menu-item")]
    .find((one) => one.textContent === t("browser.newProfile", "새 프로필…"))
    ?.click();
  await new Promise((done) => setTimeout(done, 60));
  const pop = document.querySelector(".profile-pop");
  seen.popAsks = pop && !pop.hidden;
  const field = pop.querySelector(".tc-input");
  field.value = "연구";
  field.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true, cancelable: true }));
  await new Promise((done) => setTimeout(done, 160));
  seen.newJarWornAtOnce =
    pop.hidden === true &&
    opens.at(-1)?.profile === "b".repeat(32) &&
    tab.id === "browser:browser-j3" &&
    closes.includes("browser-j2");
  closeTab(tab.id);
  await new Promise((done) => setTimeout(done, 120));
  for (const name of [
    "browser_profiles",
    "create_browser_profile",
    "open_browser_pane",
    "close_browser_pane",
    "browser_place",
    "browser_navigate",
  ]) {
    delete window.__ANSWER__[name];
  }
  return seen;
});
ok(
  "the gear menu's jars stand a pane back up in its chosen profile, ledgers following",
  profiles.menuLeadsWithJars && profiles.rebornInJar && profiles.ledgerFollows &&
    profiles.recordCarriesJar && profiles.popAsks && profiles.newJarWornAtOnce,
  JSON.stringify(profiles),
);

/* Android 미러(1-g30): iOS 시뮬레이터와 달리 진짜 인터랙티브 터널이다 —
 * 화면을 만지면 adb tap/swipe가, 타이핑은 adb text가, 하드웨어 버튼은
 * keyevent가 실제 기기로 흘러간다(라이브 보고 "실제로 터널과 통신하면서").
 * 좌표는 <img> 안에서 정규화(0..1)해 백엔드가 픽셀로 옮긴다. */
const android = await page.evaluate(async () => {
  const seen = {};
  const taps = [];
  const swipes = [];
  const texts = [];
  const buttons = [];
  const installs = [];
  let minted = 0;
  window.__ANSWER__.mobile_emulators = () => [];
  window.__ANSWER__.android_emulators = () => [{ avd: "pixel_7", serial: null, booted: false }];
  window.__ANSWER__.start_android_stream = (args) => (
    (minted += 1), { stream: `A${minted}`, udid: "emulator-5554", name: args?.avd ?? "pixel_7" }
  );
  window.__ANSWER__.android_tap = (args) => (taps.push(args), null);
  window.__ANSWER__.android_swipe = (args) => (swipes.push(args), null);
  window.__ANSWER__.android_text = (args) => (texts.push(args), null);
  window.__ANSWER__.android_button = (args) => (buttons.push(args.name), null);
  window.__ANSWER__.choose_emulator_app = () => "/tmp/demo.apk";
  window.__ANSWER__.android_install_app = (args) => (installs.push(args), null);
  const rotates = [];
  window.__ANSWER__.android_rotate = (args) => (rotates.push(args.rotation), null);
  window.__ANSWER__.stop_emulator_stream = () => null;
  // 팔레트에 Android 행이 선다(기계가 AVD를 답할 때만).
  androidEmulators = null;
  tcInput.value = "";
  await paintTabCreate();
  const row = tcActions.find((one) => one.label === t("tabs.newAndroid", "새 Android 에뮬레이터"));
  seen.androidOffered = Boolean(row) && row.hint === "Android";
  await row?.run();
  await new Promise((done) => setTimeout(done, 80));
  const mirror = tabs.filter((one) => one.kind === "emulator").at(-1);
  seen.mirrorStood =
    mirror?.platform === "android" && mirror?.udid === "emulator-5554" && mirror?.deviceName === "pixel_7";
  setActiveTab(mirror.id);
  await new Promise((done) => setTimeout(done, 60));
  const host = [...document.querySelectorAll(".emulator-view")].find((one) => !one.hidden);
  // 하드웨어 3버튼은 Android에서만 보인다.
  seen.keysShown = host.querySelector(".emulator-keys").hidden === false;
  // 프레임이 오면 살아 있는 것으로 표시되고, 화면이 만질 수 있게 된다.
  for (const hear of window.__LISTENERS__["emulator:frame"] ?? []) {
    hear({ payload: { stream: mirror.stream, bytes: btoa("android-frame") } });
  }
  const frame = host.querySelector(".emulator-frame");
  seen.frameInteractive = frame.classList.contains("is-interactive");
  // 가짜 프레임은 자연 크기가 없으니 레이아웃 크기를 준다 — 실제 판에선
  // 진짜 JPEG가 그 크기를 스스로 가진다.
  frame.style.width = "200px";
  frame.style.height = "400px";
  await new Promise((done) => setTimeout(done, 20));
  // 화면 가운데를 누르고 뗀다 — 탭이 정규화 좌표로 기기에 닿는다.
  const rect = frame.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  frame.dispatchEvent(new PointerEvent("pointerdown", { clientX: cx, clientY: cy, bubbles: true }));
  frame.dispatchEvent(new PointerEvent("pointerup", { clientX: cx, clientY: cy, bubbles: true }));
  await new Promise((done) => setTimeout(done, 40));
  seen.tapReachesDevice =
    taps.length === 1 &&
    taps[0].serial === "emulator-5554" &&
    Math.abs(taps[0].x - 0.5) < 0.05 &&
    Math.abs(taps[0].y - 0.5) < 0.05;
  // 멀리 끌면 스와이프가 된다.
  frame.dispatchEvent(new PointerEvent("pointerdown", { clientX: rect.left + 5, clientY: rect.top + 5, bubbles: true }));
  frame.dispatchEvent(new PointerEvent("pointerup", { clientX: rect.right - 5, clientY: rect.bottom - 5, bubbles: true }));
  await new Promise((done) => setTimeout(done, 40));
  seen.dragSwipes = swipes.length === 1 && swipes[0].serial === "emulator-5554";
  // 하드웨어 버튼이 keyevent로 간다.
  host.querySelector('.emulator-key[data-button="home"]').click();
  host.querySelector('.emulator-side-key[data-key="volume-up"]').click();
  host.querySelector('.emulator-side-key[data-key="power"]').click();
  host.querySelector(".emulator-install").click();
  await new Promise((done) => setTimeout(done, 40));
  seen.buttonPresses =
    buttons.includes("home") && buttons.includes("volume-up") && buttons.includes("power");
  seen.installsScopedApk =
    installs.length === 1 && installs[0].serial === "emulator-5554" &&
    installs[0].path === "/tmp/demo.apk" && installs[0].reinstall === true;
  // 회전은 세로↔가로를 오간다 — 첫 클릭이 1(가로), 다음이 0(세로).
  const rotateBtn = host.querySelector(".emulator-rotate");
  rotateBtn.click();
  await new Promise((done) => setTimeout(done, 30));
  rotateBtn.click();
  await new Promise((done) => setTimeout(done, 30));
  seen.rotateCycles = rotates.length === 2 && rotates[0] === 1 && rotates[1] === 0;
  // 타이핑은 그 기기로 흐른다 — 글자는 text, 엔터는 버튼.
  document.dispatchEvent(new KeyboardEvent("keydown", { key: "a", bubbles: true }));
  document.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true }));
  await new Promise((done) => setTimeout(done, 40));
  seen.typingReachesDevice =
    texts.some((one) => one.text === "a" && one.serial === "emulator-5554") &&
    buttons.includes("enter");
  // 선택기가 두 플랫폼을 함께 든다(여기선 Android만 있으니 Android 하나).
  const pick = host.querySelector(".emulator-pick");
  seen.pickerLabelsPlatform = [...pick.options].some((one) => one.textContent.includes("Android"));
  closeTab(mirror.id);
  await new Promise((done) => setTimeout(done, 80));
  for (const name of [
    "mobile_emulators",
    "android_emulators",
    "start_android_stream",
    "android_tap",
    "android_swipe",
    "android_text",
    "android_button",
    "android_rotate",
    "choose_emulator_app",
    "android_install_app",
    "stop_emulator_stream",
  ]) {
    delete window.__ANSWER__[name];
  }
  return seen;
});
ok(
  "the Android mirror is a real interactive tunnel — taps, swipes, typing and buttons reach the device",
  android.androidOffered && android.mirrorStood && android.keysShown &&
    android.frameInteractive && android.tapReachesDevice && android.dragSwipes &&
    android.buttonPresses && android.typingReachesDevice && android.pickerLabelsPlatform &&
    android.rotateCycles && android.installsScopedApk,
  JSON.stringify(android),
);

/* H264 터널(1-g35): 미러가 서면 screencap 폴링(~1.5fps)을 내려놓고 기기 인코더의
 * 스트림으로 갈아탄다 — 창이 WebCodecs를 가졌을 때만. 여기선 진짜 H264를 이 판에서
 * 만들어(VideoEncoder) 한 NAL 한가운데서 둘로 잘라 나눠 먹인다: 문이 경계 너머로
 * 이어붙이지 못하면 그림은 서지 않는다. 터널이 없는 기계에선 아무 일도 없었던 듯
 * screencap이 그대로 흐른다. */
const tunnel = await page.evaluate(async () => {
  const seen = {};
  const videoCalls = [];
  const stops = [];
  let videoChannel = null;
  window.__ANSWER__.mobile_emulators = () => [];
  window.__ANSWER__.android_emulators = () => [{ avd: "pixel_7", serial: null, booted: false }];
  window.__ANSWER__.start_android_stream = () => ({
    stream: "scap-1",
    udid: "emulator-5554",
    name: "pixel_7",
  });
  window.__ANSWER__.start_emulator_video = (args) => {
    videoCalls.push(args);
    videoChannel = args.onVideo;
    return { stream: "vid-1", udid: "emulator-5554", name: "pixel_7" };
  };
  window.__ANSWER__.stop_emulator_stream = (args) => (stops.push(args.stream), null);
  androidEmulators = null;
  tcInput.value = "";
  await paintTabCreate();
  const row = tcActions.find((one) => one.label === t("tabs.newAndroid", "새 Android 에뮬레이터"));
  await row?.run();
  await new Promise((done) => setTimeout(done, 100));
  const mirror = tabs.filter((one) => one.kind === "emulator").at(-1);
  setActiveTab(mirror.id);
  await new Promise((done) => setTimeout(done, 60));
  const host = [...document.querySelectorAll(".emulator-view")].find((one) => !one.hidden);
  // 판이 서자마자 그 기기 위에 터널을 두드린다.
  seen.prefersVideo = videoCalls.length === 1 && videoCalls[0].serial === "emulator-5554";
  // 그리고 폴링 스트림은 그 자리에서 내려간다 — 흐르는 것은 하나뿐이다.
  seen.screencapStoodDown =
    stops.includes("scap-1") && mirror.stream === "vid-1" && mirror.video === true;
  // 진짜 H264를 만든다 — 64x64 붉은 판 세 장, 첫 장이 키프레임.
  const packets = [];
  seen.encodeFell = "";
  try {
    const encoder = new VideoEncoder({
      output: (chunk) => {
        const held = new Uint8Array(chunk.byteLength);
        chunk.copyTo(held);
        packets.push(held);
      },
      error: (error) => (seen.encodeFell = String(error)),
    });
    encoder.configure({
      codec: "avc1.42001f",
      width: 64,
      height: 64,
      bitrate: 500000,
      framerate: 10,
      avc: { format: "annexb" },
    });
    const paper = new OffscreenCanvas(64, 64);
    const ink = paper.getContext("2d");
    for (let step = 0; step < 3; step += 1) {
      ink.fillStyle = "#ff2200";
      ink.fillRect(0, 0, 64, 64);
      const drawn = new VideoFrame(paper, { timestamp: step * 100000 });
      encoder.encode(drawn, { keyFrame: step === 0 });
      drawn.close();
    }
    await encoder.flush();
    encoder.close();
  } catch (error) {
    seen.encodeFell = String(error);
  }
  let held = new Uint8Array(packets.reduce((sum, one) => sum + one.length, 0));
  let at = 0;
  for (const one of packets) {
    held.set(one, at);
    at += one.length;
  }
  // 앞의 0 하나를 떨어뜨려 3바이트 시작 코드 길도 걷게 한다.
  if (held[0] === 0 && held[1] === 0 && held[2] === 0 && held[3] === 1) held = held.subarray(1);
  // NAL 한가운데서 자른다 — 앞 조각의 꼬리는 뒤 조각이 와야 말이 된다.
  const cuts = [held.subarray(0, 7), held.subarray(7)];
  for (let index = 0; index < cuts.length; index += 1) {
    const cut = cuts[index];
    const packet = new Uint8Array(8 + cut.length);
    new DataView(packet.buffer).setBigUint64(0, BigInt(100 + index));
    packet.set(cut, 8);
    videoChannel.onmessage(packet.buffer);
    await new Promise((done) => setTimeout(done, 20));
  }
  await new Promise((done) => setTimeout(done, 250));
  // canvas가 앞에 서고 <img>는 물러난다.
  const screen = host.querySelector(".emulator-canvas");
  seen.canvasLeads =
    screen.hidden === false && host.querySelector(".emulator-frame").hidden === true;
  // 그리고 그 위엔 진짜 픽셀이 앉아 있다 — 붉은 판이 붉게.
  const dot = screen.getContext("2d").getImageData(32, 32, 1, 1).data;
  seen.pixelsLanded = screen.width === 64 && dot[0] > 128;
  seen.carrySurvivedTheCut = seen.pixelsLanded && cuts.length === 2;
  // 탭이 가면 터널도 간다.
  closeTab(mirror.id);
  await new Promise((done) => setTimeout(done, 100));
  seen.closeStopsTheVideo = stops.includes("vid-1") && videoChannel.cleaned === true;
  // 터널이 없는 기계: 문이 거절해도 screencap이 그대로 흐른다.
  window.__ANSWER__.start_emulator_video = () => {
    throw new Error("no video");
  };
  window.__ANSWER__.start_android_stream = () => ({
    stream: "scap-2",
    udid: "emulator-5554",
    name: "pixel_7",
  });
  androidEmulators = null;
  tcInput.value = "";
  await paintTabCreate();
  const again = tcActions.find((one) => one.label === t("tabs.newAndroid", "새 Android 에뮬레이터"));
  await again?.run();
  await new Promise((done) => setTimeout(done, 100));
  const second = tabs.filter((one) => one.kind === "emulator").at(-1);
  setActiveTab(second.id);
  await new Promise((done) => setTimeout(done, 60));
  const other = [...document.querySelectorAll(".emulator-view")].find((one) => !one.hidden);
  for (const hear of window.__LISTENERS__["emulator:frame"] ?? []) {
    hear({ payload: { stream: second.stream, bytes: btoa("android-frame") } });
  }
  await new Promise((done) => setTimeout(done, 40));
  seen.fallsBackToScreencap =
    second.stream === "scap-2" && second.video !== true &&
    other.querySelector(".emulator-frame").hidden === false;
  seen.canvasStaysDown = other.querySelector(".emulator-canvas").hidden === true;
  closeTab(second.id);
  await new Promise((done) => setTimeout(done, 80));
  for (const name of [
    "mobile_emulators",
    "android_emulators",
    "start_android_stream",
    "start_emulator_video",
    "stop_emulator_stream",
  ]) {
    delete window.__ANSWER__[name];
  }
  return seen;
});
ok(
  "the android mirror upgrades to an H264 tunnel, splits carried NALs, and stands down with the tab",
  tunnel.prefersVideo && tunnel.screencapStoodDown && tunnel.canvasLeads &&
    tunnel.pixelsLanded && tunnel.carrySurvivedTheCut && tunnel.closeStopsTheVideo &&
    tunnel.fallsBackToScreencap && tunnel.canvasStaysDown,
  JSON.stringify(tunnel),
);

/* 미러 맞춤(1-g45): 화면은 판을 넘지 않는다 — CSS의 %가 아니라 잰 픽셀로.
 * 실기기 보고 두 건(Android 1080×2400, iOS)의 재현이다: 베젤은 가운데 정렬
 * flex 상자라 그 안 화면의 %max-height가 명세대로 무시되어(indefinite 순환)
 * 원본 크기로 넘쳤다. 기대 베젤은 구현을 부르지 않고 실측 수식을 여기서
 * 다시 계산한다 — 구현이 제 답을 채점하게 두면 뮤테이션이 죽지 않는다. */
const fitting = await page.evaluate(async () => {
  const seen = {};
  const raf2 = () =>
    new Promise((done) => requestAnimationFrame(() => requestAnimationFrame(done)));
  window.__ANSWER__.mobile_emulators = () => [];
  window.__ANSWER__.android_emulators = () => [{ avd: "pixel_7", serial: null, booted: false }];
  window.__ANSWER__.start_android_stream = () => ({
    stream: "scap-9",
    udid: "emulator-5554",
    name: "pixel_7",
  });
  window.__ANSWER__.start_emulator_video = () => ({
    stream: "vid-9",
    udid: "emulator-5554",
    name: "pixel_7",
  });
  window.__ANSWER__.stop_emulator_stream = () => null;
  androidEmulators = null;
  tcInput.value = "";
  await paintTabCreate();
  await tcActions
    .find((one) => one.label === t("tabs.newAndroid", "새 Android 에뮬레이터"))
    ?.run();
  await new Promise((done) => setTimeout(done, 100));
  const mirror = tabs.filter((one) => one.kind === "emulator").at(-1);
  setActiveTab(mirror.id);
  await new Promise((done) => setTimeout(done, 60));
  const host = [...document.querySelectorAll(".emulator-view")].find((one) => !one.hidden);
  const body = host.querySelector(".emulator-body");
  // 판을 240×512 화면보다 작게 죈다 — 넘침이 재현되던 그 조건.
  body.style.flex = "none";
  body.style.width = "200px";
  body.style.height = "320px";
  // 진짜 H264 두 장(240×512, 첫 장이 키프레임) — 터널 테스트와 같은 손.
  const packets = [];
  const encoder = new VideoEncoder({
    output: (chunk) => {
      const held = new Uint8Array(chunk.byteLength);
      chunk.copyTo(held);
      packets.push(held);
    },
    error: () => {},
  });
  encoder.configure({
    codec: "avc1.42001f",
    width: 240,
    height: 512,
    bitrate: 500000,
    framerate: 10,
    avc: { format: "annexb" },
  });
  const paper = new OffscreenCanvas(240, 512);
  const ink = paper.getContext("2d");
  for (let step = 0; step < 2; step += 1) {
    ink.fillStyle = "#2266ff";
    ink.fillRect(0, 0, 240, 512);
    const drawn = new VideoFrame(paper, { timestamp: step * 100000 });
    encoder.encode(drawn, { keyFrame: step === 0 });
    drawn.close();
  }
  await encoder.flush();
  encoder.close();
  let raw = "";
  for (const one of packets) for (const byte of one) raw += String.fromCharCode(byte);
  for (const hear of window.__LISTENERS__["emulator:video"] ?? []) {
    hear({ payload: { stream: "vid-9", bytes: btoa(raw) } });
  }
  await new Promise((done) => setTimeout(done, 250));
  await raf2();
  const screen = host.querySelector(".emulator-canvas");
  // 스트림이 실제로 앉았다 — 이후 단면들의 전제(공허 통과 방지).
  seen.streamLanded = screen.width === 240 && screen.hidden === false;
  const inPane = (box, pane) =>
    box.left >= pane.left - 1 &&
    box.right <= pane.right + 1 &&
    box.top >= pane.top - 1 &&
    box.bottom <= pane.bottom + 1;
  const shot = screen.getBoundingClientRect();
  const paneBox = body.getBoundingClientRect();
  seen.fitsPane = seen.streamLanded && inPane(shot, paneBox);
  // 화면만이 아니라 베젤까지가 fit의 정의다 — 되먹임(수렴)이 없으면 화면은
  // 우연히 안에 남고 베젤이 판을 넘는다.
  seen.bezelInPane =
    seen.streamLanded &&
    inPane(host.querySelector(".emulator-bezel").getBoundingClientRect(), paneBox);
  seen.keepsAspect =
    seen.streamLanded && Math.abs(shot.width / shot.height - 240 / 512) <= 0.02;
  // 기대 베젤·버튼 두께: 실측 수식 재계산 — 240/512 화면, 폰꼴.
  // 기기가 설 자리는 판의 사각형이 아니라 판이 입은 여백의 안쪽이다
  // (`--device-stage-inset-*` → `.emulator-body`의 padding). 시험도 그 자리를
  // 되읽어야 여백이나 판 크기가 바뀌어도 이 수식이 따라온다.
  const ar = 240 / 512;
  const squeeze = (value, low, high) => Math.min(high, Math.max(low, value));
  const worn = getComputedStyle(body);
  const inset = (side) => Number.parseFloat(worn.getPropertyValue(`padding-${side}`)) || 0;
  const room = {
    width: Math.floor(paneBox.width) - inset("left") - inset("right"),
    height: Math.floor(paneBox.height) - inset("top") - inset("bottom"),
  };
  const contain = (pane) =>
    pane.width / pane.height > ar
      ? { width: pane.height * ar, height: pane.height }
      : { width: pane.width, height: pane.width / ar };
  let want = contain(room);
  let hem = 0;
  let stick = 0;
  for (let pass = 0; pass < 4; pass += 1) {
    const short = Math.min(want.width, want.height);
    hem = squeeze(short * 0.021, 7, 15);
    const outset = squeeze(short * 0.012, 3, 7);
    stick = squeeze(short * 0.01, 3, 6);
    want = contain({
      width: room.width - outset * 2 - hem * 2 - 0.5,
      height: room.height - hem * 2 - 0.5,
    });
  }
  const bezelBox = host.querySelector(".emulator-bezel");
  seen.bezelMeasured =
    seen.streamLanded &&
    bezelBox.style.padding === `${hem}px` &&
    // 높이까지 수렴의 결과여야 한다 — 되먹임이 없으면 첫 contain의 큰
    // 껍데기가 그대로 남고, 그 넘침은 폴백 max-*가 우연히 가려 준다(위
    // bezelInPane이 그래서 못 잡는다). 같은 수식의 재계산이라 비트까지 같다.
    bezelBox.style.height === `${want.height + hem * 2}px`;
  const sideKeys = [...host.querySelectorAll(".emulator-side-key")];
  const visibleSideKeys = sideKeys.filter((one) => !one.hidden);
  seen.buttonsStand =
    seen.streamLanded &&
    sideKeys.length === 4 &&
    visibleSideKeys.length === 3 &&
    sideKeys.find((one) => one.dataset.key === "action")?.hidden === true &&
    visibleSideKeys.every((one) => one.style.width === `${stick}px`);
  // 죔을 풀면 화면이 도로 자란다 — 옵저버가 rAF 박자로 다시 잰다.
  body.style.removeProperty("flex");
  body.style.removeProperty("width");
  body.style.removeProperty("height");
  await raf2();
  await new Promise((done) => setTimeout(done, 120));
  seen.resizeRefits =
    seen.streamLanded && screen.getBoundingClientRect().height > shot.height + 4;
  closeTab(mirror.id);
  await new Promise((done) => setTimeout(done, 80));
  // iOS 길: 진짜 JPEG을 screencap 문으로 넣는다 — img의 원본 크기가 판을
  // 재고, 작은 그림도 판에 맞게 자란다(contain은 키우기도 한다).
  const fleet = [
    { udid: "F1", name: "iPhone 17", booted: true },
    { udid: "F2", name: "iPad Pro", booted: true },
  ];
  window.__ANSWER__.mobile_emulators = () => fleet;
  let sims = 0;
  window.__ANSWER__.start_emulator_stream = (args) => {
    sims += 1;
    const device = fleet.find((one) => one.udid === (args?.udid ?? "F1")) ?? fleet[0];
    return { stream: `sim-${sims}`, udid: device.udid, name: device.name };
  };
  mobileEmulators = null;
  tcInput.value = "";
  await paintTabCreate();
  await tcActions
    .find((one) => one.label === t("tabs.newSimulator", "새 모바일 에뮬레이터"))
    ?.run();
  await new Promise((done) => setTimeout(done, 80));
  const sim = tabs.filter((one) => one.kind === "emulator").at(-1);
  setActiveTab(sim.id);
  await new Promise((done) => setTimeout(done, 60));
  const simHost = [...document.querySelectorAll(".emulator-view")].find((one) => !one.hidden);
  // 그림이 오기 전: 기다리는 자리가 화면의 자리에 화면의 크기로 서 있고, 상태
  // 칩은 낱말만이 아니라 형태로도 말한다. 스켈레톤이 화면과 같은 인라인 치수를
  // 받는 것이 계약이다 — 그래야 첫 그림이 앉을 때 아무것도 움직이지 않는다.
  const waiting = simHost.querySelector(".emulator-skeleton");
  const beforeFrame = simHost.querySelector(".emulator-frame");
  seen.waitsInTheScreensPlace =
    waiting !== null &&
    waiting.hidden === false &&
    waiting.style.width === beforeFrame.style.width &&
    waiting.style.height === beforeFrame.style.height &&
    waiting.style.borderRadius === beforeFrame.style.borderRadius &&
    waiting.style.width !== "";
  seen.chipSaysItsShape =
    ["off", "working", "live"].includes(
      simHost.querySelector(".emulator-status").dataset.state,
    );
  // 컨텍스트 없는 캔버스는 blob을 거부한다 — 한 번 칠해서 그림으로 만든다.
  const sheet = new OffscreenCanvas(120, 256);
  sheet.getContext("2d").fillRect(0, 0, 120, 256);
  const jpeg = await (await sheet.convertToBlob({ type: "image/jpeg" })).arrayBuffer();
  let dot = "";
  for (const byte of new Uint8Array(jpeg)) dot += String.fromCharCode(byte);
  for (const hear of window.__LISTENERS__["emulator:frame"] ?? []) {
    hear({ payload: { stream: sim.stream, bytes: btoa(dot) } });
  }
  // 그림이 앉을 때까지 묻는다 — img의 onload는 셸의 손이라 빌릴 수 없다.
  const img = simHost.querySelector(".emulator-frame");
  for (let wait = 0; wait < 40 && img.naturalWidth === 0; wait += 1) {
    await new Promise((done) => setTimeout(done, 25));
  }
  await raf2();
  seen.imgLanded = img.naturalWidth === 120 && img.hidden === false;
  // 그림이 온 뒤: 기다리던 자리는 물러나고 칩은 살아 있다고 말한다.
  seen.waitingStandsDown =
    seen.imgLanded &&
    waiting.hidden === true &&
    simHost.querySelector(".emulator-status").dataset.state === "live";
  const imgBox = img.getBoundingClientRect();
  const simPane = simHost.querySelector(".emulator-body").getBoundingClientRect();
  seen.imgFitsPane = seen.imgLanded && inPane(imgBox, simPane);
  // contain은 키우기도 한다 — 판이 얼마나 크든 화면은 그 높이의 8할을
  // 넘긴다(베젤 몫을 빼고도). 원본 픽셀에 고정되던 버그는 큰 판에서
  // 여기 걸린다.
  seen.imgGrewToFit = seen.imgLanded && imgBox.height > simPane.height * 0.8;
  seen.imgKeepsAspect =
    seen.imgLanded && Math.abs(imgBox.width / imgBox.height - 120 / 256) <= 0.02;
  // iPad로 갈아타면 이름이 태블릿꼴을 입히고 폰 옆 버튼은 눕는다 — 그리고
  // 껍데기는 그 자리에서 태블릿의 치수를 입는다. 옛 기기의 잰 픽셀이 남아서도
  // 안 되지만, 치수를 잃고 사라져서도 안 된다: 새 기기의 첫 그림이 오기까지
  // 사람이 보는 것이 빈 사각형이 되기 때문이다. 그림이 오면 그 그림의 진짜
  // 비율로 다시 잰다.
  const phoneBezel = simHost.querySelector(".emulator-bezel");
  const phoneShape = { padding: phoneBezel.style.padding, height: phoneBezel.style.height };
  await switchEmulatorDevice(sim, "ios", "F2");
  await new Promise((done) => setTimeout(done, 80));
  const tabletBezel = simHost.querySelector(".emulator-bezel");
  seen.tabletTagged =
    tabletBezel.classList.contains("is-tablet") &&
    tabletBezel.style.padding !== "" &&
    tabletBezel.style.height !== phoneShape.height &&
    [...simHost.querySelectorAll(".emulator-side-key")].every((one) => one.hidden);
  closeTab(sim.id);
  await new Promise((done) => setTimeout(done, 80));
  for (const name of [
    "mobile_emulators",
    "android_emulators",
    "start_android_stream",
    "start_emulator_video",
    "start_emulator_stream",
    "stop_emulator_stream",
  ]) {
    delete window.__ANSWER__[name];
  }
  return seen;
});
ok(
  "the mirror fits its pane, waits in the screen's own place, and says its state by shape",
  fitting.streamLanded && fitting.fitsPane && fitting.bezelInPane && fitting.keepsAspect &&
    fitting.bezelMeasured && fitting.buttonsStand && fitting.resizeRefits && fitting.imgLanded &&
    fitting.imgFitsPane && fitting.imgGrewToFit && fitting.imgKeepsAspect && fitting.tabletTagged &&
    fitting.waitsInTheScreensPlace && fitting.chipSaysItsShape && fitting.waitingStandsDown,
  JSON.stringify(fitting),
);

const workspaceOpenIn = await page.evaluate(async () => {
  const settle = () => new Promise((done) => setTimeout(done, 220));
  const seen = { calls: [] };
  const before = openInApplications.map((application) => ({ ...application }));
  openInApplications = [
    { id: "vscode", label: "VS Code", command: "code" },
    { id: "custom", label: "Editor Preview", command: "editor-preview --reuse" },
  ];
  paintOpenInApplications();
  window.__ANSWER__.open_workspace_in_application = (args) => {
    seen.calls.push(JSON.parse(JSON.stringify(args)));
    return null;
  };
  const worktree = {
    path: "/tmp/zerocode-window-test",
    branch: "main",
    is_main: false,
    active: true,
    is_folder: false,
  };
  const menuLabels = () => [...document.querySelectorAll("#sidebar-menu .sidebar-menu-label")]
    .map((label) => label.textContent);
  const clickLabel = (label) => [...document.querySelectorAll("#sidebar-menu .sidebar-menu-item")]
    .find((row) => row.querySelector(".sidebar-menu-label")?.textContent === label)
    ?.click();

  worktreeMenuAt(worktree, 40, 40);
  const vscodeLabel = t("worktree.openIn", "{{app}}에서 열기", { app: "VS Code" });
  const customLabel = t("worktree.openIn", "{{app}}에서 열기", { app: "Editor Preview" });
  const fileManager = workspaceFileManagerName();
  const fileManagerLabel = t(
    "worktree.openInFileManager",
    "{{app}}에서 열기",
    { app: fileManager },
  );
  const customizeLabel = t("worktree.customizeApps", "앱 사용자화…");
  seen.menu = menuLabels();
  clickLabel(vscodeLabel);
  await settle();

  worktreeMenuAt(worktree, 40, 40);
  clickLabel(fileManagerLabel);
  await settle();

  worktreeMenuAt(worktree, 40, 40);
  clickLabel(customizeLabel);
  await settle();
  seen.customizes = !settingsView.hidden
    && settingsPane === "general"
    && settingsSection === "settings-open-in-apps"
    && document.activeElement?.id === "settings-open-in-apps";

  setSettingsOpen(false);
  openInApplications = before;
  paintOpenInApplications();
  delete window.__ANSWER__.open_workspace_in_application;
  return {
    ...seen,
    labels: { vscodeLabel, customLabel, fileManagerLabel, customizeLabel },
    fileManager,
  };
});
ok(
  "a worktree opens only configured apps or its platform file manager, and Customize returns to General",
  workspaceOpenIn.menu.includes(workspaceOpenIn.labels.vscodeLabel)
    && workspaceOpenIn.menu.includes(workspaceOpenIn.labels.customLabel)
    && workspaceOpenIn.menu.includes(workspaceOpenIn.labels.fileManagerLabel)
    && workspaceOpenIn.menu.includes(workspaceOpenIn.labels.customizeLabel)
    && workspaceOpenIn.calls.length === 2
    && workspaceOpenIn.calls[0]?.path === "/tmp/zerocode-window-test"
    && workspaceOpenIn.calls[0]?.applicationId === "vscode"
    && workspaceOpenIn.calls[1]?.path === "/tmp/zerocode-window-test"
    && workspaceOpenIn.calls[1]?.applicationId === null
    && workspaceOpenIn.customizes,
  JSON.stringify(workspaceOpenIn),
);

/* 클립보드의 이미지(1-g64): 글자가 없으면 그림을 본다 — 바이트가 요청 본문
 * 그대로(base64 없이) 백엔드로 건너 임시 파일이 되고, 종류는 헤더로 가며,
 * 터미널에는 그 경로가 기존 paste 문으로 붙는다. 글자가 있으면 글자가 이긴다. */
const imagePaste = await page.evaluate(async () => {
  const seen = {};
  const term = await openTermTab();
  const saved = [];
  const pastes = [];
  window.__ANSWER__.save_pasted_image = (args, options) => {
    saved.push({
      kind: options?.headers?.["x-image-kind"],
      raw: args instanceof Uint8Array,
      size: args?.length,
      first: args?.[0],
    });
    return "/tmp/zerocode-paste/paste-1755300000000.png";
  };
  window.__ANSWER__.term_paste = (args) => (pastes.push({ ...args }), null);
  const sink = document.getElementById("key-sink");
  const image = new DataTransfer();
  image.items.add(new File([new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10])], "shot.png", { type: "image/png" }));
  sink.dispatchEvent(new ClipboardEvent("paste", { clipboardData: image, bubbles: true, cancelable: true }));
  await new Promise((done) => setTimeout(done, 160));
  seen.imageLands =
    saved.length === 1 && saved[0].kind === "image/png" && saved[0].raw &&
    saved[0].size === 8 && saved[0].first === 137 &&
    pastes.at(-1)?.text === "/tmp/zerocode-paste/paste-1755300000000.png" &&
    pastes.at(-1)?.term === term;
  // 글자가 함께 온 붙여넣기는 글자의 길 그대로 — 그림 문은 열리지 않는다.
  const worded = new DataTransfer();
  worded.setData("text/plain", "echo hello");
  worded.items.add(new File([new Uint8Array([1])], "x.png", { type: "image/png" }));
  sink.dispatchEvent(new ClipboardEvent("paste", { clipboardData: worded, bubbles: true, cancelable: true }));
  await new Promise((done) => setTimeout(done, 120));
  seen.textStillWins =
    saved.length === 1 && pastes.at(-1)?.text === "echo hello";
  delete window.__ANSWER__.save_pasted_image;
  delete window.__ANSWER__.term_paste;
  closeTab(activeTabId);
  await new Promise((done) => setTimeout(done, 120));
  return seen;
});
ok(
  "a clipboard image lands as a temp-file path through the same paste door",
  imagePaste.imageLands && imagePaste.textStillWins,
  JSON.stringify(imagePaste),
);

/* 그림만 든 클립보드를 단축키로 붙일 때(포커스가 본문에 있을 때의 길): 글자
 * 길이 비거나 읽지 못하면 백엔드에 그림을 묻고 그 경로를 붙인다. 글자가
 * 있으면 글자가 이기고, 아무것도 없으면 조용히 물러난다. */
const imageShortcutPaste = await page.evaluate(async () => {
  const seen = {};
  const term = await openTermTab();
  const target = { kind: "term", term, key: `term:${term}` };
  const pastes = [];
  let asked = 0;
  window.__ANSWER__.term_paste = (args) => (pastes.push({ ...args }), null);
  window.__ANSWER__.save_clipboard_image = () =>
    (asked += 1, "/tmp/zerocode-paste/paste-1755300000001.png");
  const toasts = () => [...document.querySelectorAll(".toast")].map((node) => node.textContent);
  const toastsBefore = toasts().length;
  // A picture-only clipboard: the text road throws.
  window.__CLIPBOARD_READ_FAIL__ = true;
  seen.imageLands =
    (await pasteClipboardAt(target)) === true && asked === 1 &&
    pastes.at(-1)?.text === "/tmp/zerocode-paste/paste-1755300000001.png" &&
    pastes.at(-1)?.term === term;
  seen.noToast = toasts().length === toastsBefore;
  window.__CLIPBOARD_READ_FAIL__ = false;
  // Words win, and the picture is not even asked for.
  window.__CLIPBOARD_TEXT__ = "echo words";
  seen.textStillWins =
    (await pasteClipboardAt(target)) === true && asked === 1 && pastes.at(-1)?.text === "echo words";
  // Nothing at all: no paste, no toast.
  window.__CLIPBOARD_TEXT__ = "";
  window.__ANSWER__.save_clipboard_image = () => (asked += 1, null);
  seen.emptyIsQuiet =
    (await pasteClipboardAt(target)) === false && asked === 2 && toasts().length === toastsBefore;
  delete window.__ANSWER__.term_paste;
  delete window.__ANSWER__.save_clipboard_image;
  closeTab(activeTabId);
  await new Promise((done) => setTimeout(done, 120));
  return seen;
});
ok(
  "a picture-only clipboard pasted with the shortcut lands as a temp-file path",
  imageShortcutPaste.imageLands && imageShortcutPaste.noToast &&
    imageShortcutPaste.textStillWins && imageShortcutPaste.emptyIsQuiet,
  JSON.stringify(imageShortcutPaste),
);

/* ---- bold rides the bright half, and the bar the screen sets ------------ */

// Two xterm defaults Orca keeps, so the same program output has to paint the
// same pixels here. `drawBoldTextInBrightColors` lifts an ANSI 0-7 ink into its
// bright twin AFTER reverse has decided which colour is the ink — a reversed
// cell promotes what was its ground — and `minimumContrastRatio` is 4.5 on a
// light screen and 3 on a dark one, which is why a grey the dark screen can
// carry is left exactly as the program asked for it.
const boldBright = await page.evaluate(async () => {
  const seen = {};
  const term = await openTermTab();
  const view = termView(term);
  const cols = 20;
  // Five dressed cells and the padding the grid sends behind them. Adjacent
  // cells whose styles differ never share a run, so the spans stand 1:1 with
  // these five and the padding is the sixth.
  const cells = [
    { ch: "a", style: { bold: true, fg: { indexed: 1 } } },
    { ch: "b", style: { fg: { indexed: 1 } } },
    { ch: "c", style: { bold: true, fg: { rgb: [180, 140, 90] } } },
    { ch: "d", style: { bold: true, reverse: true, bg: { indexed: 4 } } },
    { ch: "e", style: { fg: { rgb: [128, 128, 128] } } },
    ...[..." ".repeat(cols - 5)].map((ch) => ({ ch })),
  ];
  const feed = () => window.__TERM_FEED__(term, {
        rows: [{ index: 0, cells }], scrolled_lines: 0, cursor: [0, 0], title: null,
        alt_screen: false, size: [4, cols], full: true, cursor_visible: true,
        mouse_tracking: "off", mouse_sgr: false, bell: false,
      });
  // What the CSSOM made of the string the painter wrote — the expected
  // spelling goes through the same parse rather than being guessed at.
  const probe = document.createElement("span");
  const spelled = (property, css) => {
    probe.style.setProperty(property, css);
    const said = probe.style.getPropertyValue(property);
    probe.style.removeProperty(property);
    return said;
  };
  const dressOf = (at) => {
    const span = view.pre.querySelector(".term-row").children[at];
    const style = getComputedStyle(span);
    return {
      className: span.className,
      color: style.color,
      background: style.backgroundColor,
      inlineColor: span.style.color,
      inlineBackground: span.style.background,
    };
  };

  await feed();
  seen.painted = [0, 1, 2, 3, 4].map(dressOf);
  seen.boldRodeBright = seen.painted[0].className.includes("term-fg-9") &&
    seen.painted[0].inlineColor === "";
  seen.plainKeptBase = seen.painted[1].className.includes("term-fg-1") &&
    seen.painted[1].inlineColor === "";
  seen.trueColorStoodStill = seen.painted[2].inlineColor === spelled("color", "rgb(180 140 90)");
  // The promoted colour is the one that was the GROUND, and the ink it was
  // swapped with is now behind it.
  seen.reverseLiftedTheGround =
    seen.painted[3].className.includes("term-fg-12") &&
    seen.painted[3].className.includes("term-bg-default") &&
    seen.painted[3].inlineColor === "" && seen.painted[3].inlineBackground === "";
  // About 3.5:1 on the default screen — over the dark bar, so it stays the
  // program's colour. A bar fixed at 4.5 would have rewritten it.
  const asked = spelled("color", "rgb(128 128 128)");
  seen.darkScreenLetLowContrastBe = seen.painted[4].inlineColor === asked;

  // The same pairing on a lit screen is under 4.5 and has to be lifted. The
  // palette is put back by hand: `--term-screen-bg` is an inline property the
  // terminal theme owns, so removing it outright would leave the window
  // wearing tokens.css instead of the theme it had.
  const held = document.documentElement.style.getPropertyValue("--term-screen-bg");
  document.documentElement.style.setProperty("--term-screen-bg", "#ffffff");
  forgetPalette();
  await feed();
  seen.lit = dressOf(4).inlineColor;
  seen.litScreenLiftsIt = seen.lit !== asked;
  if (held) document.documentElement.style.setProperty("--term-screen-bg", held);
  else document.documentElement.style.removeProperty("--term-screen-bg");
  forgetPalette();
  return seen;
});
ok(
  "bold ink rides the bright palette, and the contrast bar follows the screen",
  boldBright.boldRodeBright && boldBright.plainKeptBase &&
    boldBright.trueColorStoodStill && boldBright.reverseLiftedTheGround &&
    boldBright.darkScreenLetLowContrastBe && boldBright.litScreenLiftsIt,
  JSON.stringify(boldBright),
);

/* ---- 세션 행의 점과 시계 (1-g66) ---------------------------------------- */

// Orca's AgentStateDot is three marks, not one dot in three colours: a ring
// turning in twelve steps while it works, a check once it is done, a question
// mark when it wants a person. And the elapsed word rides EVERY row at the
// right edge — which is why the word has to be part of what the row says, or
// the 30초 박자가 두드려도 서명이 같아서 아무것도 다시 그려지지 않는다.
const agentDotClock = await page.evaluate(async () => {
  const seen = {};
  // The stage inherits earlier tests' launched tabs, and a launched pane now
  // stands a row BEFORE it speaks (the ledger fallback) — so this fixture
  // starts from its own clean stage, with the same sweep it already ends on.
  for (const tab of [...tabs]) dropTab(tab.id);
  for (const at of [...termViews.keys()]) dropTermView(at);
  const term = await openTermTab({ placement: "tab" });
  const owner = tabOfTerm(term);
  const path = owner.worktree;
  const card = () => document.querySelector(`.wt-agents[data-worktree-path="${CSS.escape(path)}"]`);
  const rows = () => [...(card()?.querySelectorAll(".wt-agent") ?? [])];
  const say = (at, state) => {
    for (const handler of window.__LISTENERS__["hook:agent"] ?? []) {
      handler({ payload: { term: at, state, agent: "claude", session: `s-${at}`, resumable: false } });
    }
  };
  // Three shells under one workspace, one per state — the mark is the only
  // thing that may differ between the rows.
  const mate = 9661;
  const asks = 9662;
  for (const handler of window.__LISTENERS__["term:split"] ?? []) {
    handler({ payload: { parent: term, term: mate, direction: "vertical", agent: "claude" } });
  }
  for (const handler of window.__LISTENERS__["term:split"] ?? []) {
    handler({ payload: { parent: term, term: asks, direction: "vertical", title: "asks" } });
  }
  say(term, "working");
  say(mate, "done");
  say(asks, "needs-attention");
  await window.__PAINTED__();
  const dotOf = (at) =>
    rows().find((one) => one.dataset.term === String(at))?.querySelector(".wt-agent-dot") ?? null;
  const marked = (at, id) =>
    dotOf(at)?.tagName.toLowerCase() === "svg" &&
    (dotOf(at)?.querySelector("use")?.getAttribute("href") ?? "").endsWith(id);

  // 도는 것은 아이콘이 아니라 고리다 — 잘린 테두리 하나를 CSS가 돌린다.
  const spinner = dotOf(term);
  seen.workingSpins =
    spinner?.tagName === "SPAN" && getComputedStyle(spinner).animationName === "wt-agent-spin";
  seen.doneWearsCheck = marked(mate, "#i-circle-check");
  seen.waitingAsks = marked(asks, "#i-msg-ask");

  const whens = rows().map((one) => one.querySelector(".wt-agent-when")?.textContent ?? "");
  seen.rows = rows().length;
  seen.everyRowHasWhen = whens.length === seen.rows && whens.every((word) => word.length > 0);
  // 태어난 시각은 손으로 넣어 준 것이 아니라 뷰가 처음 설 때 저절로 찍힌 것이어야
  // 한다 — 이 장부가 비면 시계는 상태 전이 시각으로 미끄러져 "방금"만 말한다.
  seen.bornStamped = [term, mate, asks].every((at) => paneBorn.has(at));
  const before = agentRowsSaid(worktreeAgentRows(path));
  seen.clockRidesSignature = before.includes(whens[0]);
  // 그리고 낱말이 넘어가면 서명도 넘어간다: 상태도 도구도 그대로인 그 변화가
  // 바로 30초 박자가 붙잡으라고 있는 것이다.
  paneBorn.set(term, Date.now() - 90_000);
  seen.signatureMoves = agentRowsSaid(worktreeAgentRows(path)) !== before;

  for (const tab of [...tabs]) dropTab(tab.id);
  for (const at of [...termViews.keys()]) dropTermView(at);
  for (const at of [term, mate, asks]) dropTermView(at);
  return seen;
});
ok(
  "a session row wears Orca's dot and its own clock",
  agentDotClock.workingSpins && agentDotClock.doneWearsCheck && agentDotClock.waitingAsks &&
    agentDotClock.rows === 3 && agentDotClock.everyRowHasWhen && agentDotClock.bornStamped &&
    agentDotClock.clockRidesSignature && agentDotClock.signatureMoves,
  JSON.stringify(agentDotClock),
);

/* ---- 작업판 Jira의 검색(1-g69) ----
 *
 * 프리셋 넷과 JQL 한 칸이 한 목록을 두고 번갈아 선다. 재는 것은 그 교대다:
 * 무엇을 물었는가(프리셋 이름이냐 친 그대로의 JQL이냐), 언제 물었는가(300ms
 * 뒤냐 Enter 즉시냐 — 조합 중이면 아예 아니냐), 그리고 답이 비었을 때 어느
 * 문장을 말하는가. 마지막이 특히 이 조각의 것이다: 같은 빈 화면이 검색
 * 뒤에서는 「질의를 고쳐 보라」이고 프리셋 뒤에서는 고칠 것이 없다는 뜻이다. */
const jiraSearch = await page.evaluate(async () => {
  const wait = (ms) => new Promise((done) => setTimeout(done, ms));
  const issue = (key, title, status, category) => ({
    key,
    title,
    status,
    category,
    priority: null,
    assignee: null,
    project: "ABC",
    updated: "2026-08-12T09:14:02.000+0900",
    url: `https://acme.atlassian.net/browse/${key}`,
  });
  let listAnswer = [issue("ABC-9", "로그인 리다이렉트가 깨진다", "In Progress", "doing")];
  let searchAnswer = [issue("ABC-77", "결제 화면이 비어 있다", "To Do", "todo")];
  const asked = { list: [], search: [] };
  window.__ANSWER__.jira_issues = (args) => {
    asked.list.push(args);
    return listAnswer;
  };
  window.__ANSWER__.jira_search_issues = (args) => {
    asked.search.push(args);
    return searchAnswer;
  };
  window.__JIRA_STATUS__ = {
    connected: true,
    sites: [{ id: "s1", site_url: "https://acme.atlassian.net", email: "hana@acme.com" }],
    credential_error: null,
  };
  setTaskOpen(true);
  await wait(250);

  const seen = {};
  const box = el("jira-search");
  const chips = () => [...el("jira-presets").querySelectorAll("[data-jira-preset]")];
  const chipFor = (name) => chips().find((chip) => chip.dataset.jiraPreset === name);
  const keys = () =>
    [...document.querySelectorAll("#jira-list .task-jira-key")].map((one) => one.textContent);
  const pressed = (name) => chipFor(name).getAttribute("aria-pressed") === "true";

  // 칩 하나는 그 프리셋을 묻고, 온 것을 그리고, 자기가 켜졌다고 말한다.
  chipFor("reported").click();
  await wait(200);
  seen.presetLoadsList =
    asked.list.at(-1)?.preset === "reported" && keys().join(",") === "ABC-9" && pressed("reported");

  // 타이핑은 300ms를 기다렸다가, 친 그대로의 JQL을 묻는다 — 양끝 공백만 빼고.
  const heldAt = asked.search.length;
  box.value = "  project = ABC AND statusCategory != Done  ";
  box.dispatchEvent(new Event("input", { bubbles: true }));
  seen.debounceHolds = asked.search.length === heldAt;
  await wait(350);
  seen.typingSearches =
    asked.search.length === heldAt + 1 &&
    asked.search.at(-1)?.jql === "project = ABC AND statusCategory != Done" &&
    keys().join(",") === "ABC-77";

  // A raw query that Jira could not parse is retried by the backend as a
  // quoted text query. The command still crosses the bridge once; its report
  // tells the window that the visible rows came from that interpretation.
  searchAnswer = {
    issues: [issue("ABC-78", "카드 본문에서 찾았다", "To Do", "todo")],
    failures: [],
    interpreted_as_text: true,
  };
  const fallbackAt = asked.search.length;
  box.value = "card";
  box.dispatchEvent(new Event("input", { bubbles: true }));
  await wait(350);
  const fallbackHint = el("jira-search-interpretation");
  seen.textFallbackState = {
    asks: asked.search.length - fallbackAt,
    keys: keys().join(","),
    hidden: fallbackHint.hidden,
    text: fallbackHint.textContent.trim(),
    expected: t("task.jira.textFallback", "JQL로 해석되지 않아 텍스트 검색으로 대체했습니다."),
  };
  seen.textFallbackExplainsItself =
    seen.textFallbackState.asks === 1 &&
    seen.textFallbackState.keys === "ABC-78" &&
    !seen.textFallbackState.hidden &&
    seen.textFallbackState.text === seen.textFallbackState.expected;
  searchAnswer = [issue("ABC-77", "결제 화면이 비어 있다", "To Do", "todo")];

  // 입력이 서 있는 동안 켜진 칩은 없다 — 목록을 만든 것은 칩이 아니므로.
  seen.chipsStepAside = chips().every(
    (chip) => chip.getAttribute("aria-pressed") === "false" && !chip.classList.contains("is-active"),
  );

  // 조합 중인 Enter는 IME의 것이고, 맨 Enter는 기다림을 건너뛴다. 아래의
  // 20ms는 디바운스 300ms보다 짧다 — 즉시 커밋이어야만 통과한다.
  const enterAt = asked.search.length;
  box.dispatchEvent(
    new KeyboardEvent("keydown", { key: "Enter", isComposing: true, bubbles: true }),
  );
  await wait(20);
  const imeSilent = asked.search.length === enterAt;
  box.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true }));
  await wait(20);
  seen.enterIsImeSafe = imeSilent && asked.search.length === enterAt + 1;

  // 지우기는 빈 화면이 아니라 고른 프리셋의 목록으로 돌아온다.
  const clearedAt = asked.list.length;
  el("jira-search-clear").click();
  await wait(250);
  seen.clearRestoresPreset =
    box.value === "" &&
    asked.list.length === clearedAt + 1 &&
    asked.list.at(-1)?.preset === "reported" &&
    keys().join(",") === "ABC-9" &&
    pressed("reported") &&
    el("jira-search-clear").hidden;

  // 빈 답에는 두 가지 뜻이 있고, 무엇이 물었는지가 문장을 고른다.
  searchAnswer = [];
  box.value = "project = NOPE";
  box.dispatchEvent(new Event("input", { bubbles: true }));
  await wait(350);
  seen.emptySaysJql =
    !el("jira-none").hidden &&
    el("jira-none-body").textContent ===
      t("task.jira.emptySearchHint", "다른 JQL 쿼리를 시도해 보세요.");
  listAnswer = [];
  chipFor("done").click();
  await wait(250);
  seen.emptySaysPreset =
    !el("jira-none").hidden &&
    el("jira-none-body").textContent ===
      t("task.jira.emptyPresetHint", "선택한 프리셋에 맞는 이슈가 없습니다.");

  // Connected Jira grows one native create road. It seeds the project from
  // the list, sends trimmed fields, refreshes that list, and every dismissal
  // peels only the dialog off the Tasks route.
  listAnswer = [issue("ABC-9", "로그인 리다이렉트가 깨진다", "In Progress", "doing")];
  chipFor("assigned").click();
  await wait(220);
  const created = [];
  const projectsAsked = [];
  window.__ANSWER__.jira_projects = (args) => {
    projectsAsked.push(args);
    return [
      { key: "OPS", name: "Operations" },
      { key: "ABC", name: "Application" },
    ];
  };
  window.__ANSWER__.jira_create_issue = (args) => {
    created.push(args);
    return { key: "ABC-88", url: "https://acme.atlassian.net/browse/ABC-88" };
  };
  el("jira-new").click();
  await wait(80);
  seen.createSeeds =
    !el("jira-create-scrim").hidden &&
    el("jira-create-site").value === "s1" &&
    el("jira-create-site-field").hidden &&
    el("jira-create-project").tagName === "SELECT" &&
    [...el("jira-create-project").options].map((option) => option.value).join(",") === "OPS,ABC" &&
    el("jira-create-project").value === "ABC" &&
    projectsAsked.at(-1)?.siteId === "s1" &&
    el("jira-create-type").value === "Task" &&
    document.activeElement === el("jira-create-summary");

  // Scrim dismissal.
  el("jira-create-scrim").dispatchEvent(new MouseEvent("mousedown", { bubbles: true }));
  seen.createScrimCancels = el("jira-create-scrim").hidden && !el("task-view").hidden;

  // Escape dismissal.
  el("jira-new").click();
  document.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
  await wait(40);
  seen.createEscapeCancels = el("jira-create-scrim").hidden && !el("task-view").hidden;

  // Every site owns its own project list. Switching the real site select asks
  // again and replaces the project options instead of reusing the first site.
  jiraStatus = normalizeJiraStatus({
    connected: true,
    selected_site_id: "all",
    sites: [
      { id: "s1", site_url: "https://acme.atlassian.net", standing: "connected" },
      { id: "s2", site_url: "https://jira.example.com", standing: "connected" },
    ],
  });
  window.__ANSWER__.jira_projects = (args) => {
    projectsAsked.push(args);
    return args.siteId === "s2"
      ? [{ key: "WEB", name: "Website" }]
      : [{ key: "ABC", name: "Application" }];
  };
  el("jira-new").click();
  await wait(80);
  el("jira-create-site").value = "s2";
  el("jira-create-site").dispatchEvent(new Event("change", { bubbles: true }));
  await wait(80);
  seen.createSiteRefreshes =
    projectsAsked.at(-1)?.siteId === "s2" &&
    el("jira-create-project").tagName === "SELECT" &&
    el("jira-create-project").value === "WEB";
  el("jira-create-scrim").dispatchEvent(new MouseEvent("mousedown", { bubbles: true }));

  // A project-list outage must not take issue creation down with it. The
  // select becomes the prior text field with the current issue's project seed.
  jiraStatus = normalizeJiraStatus({
    connected: true,
    selected_site_id: "s1",
    sites: [{ id: "s1", site_url: "https://acme.atlassian.net", standing: "connected" }],
  });
  window.__ANSWER__.jira_projects = (args) => {
    projectsAsked.push(args);
    throw new Error("project list unavailable");
  };
  el("jira-new").click();
  await wait(80);
  seen.createDegradesToText =
    el("jira-create-project").tagName === "INPUT" &&
    el("jira-create-project").value === "ABC" &&
    !el("jira-create-project").disabled;

  // Successful submit and list refresh still work through that degraded field.
  el("jira-create-project").value = " ABC ";
  el("jira-create-type").value = " Bug ";
  el("jira-create-summary").value = "  로그인 재시도 수리  ";
  el("jira-create-description").value = " 재현 절차 ";
  const listsBeforeCreate = asked.list.length;
  el("jira-create-form").dispatchEvent(new Event("submit", { bubbles: true, cancelable: true }));
  await wait(220);
  seen.createTravels =
    created.length === 1 &&
    created[0].siteId === "s1" && created[0].projectKey === "ABC" &&
    created[0].issueType === "Bug" && created[0].summary === "로그인 재시도 수리" &&
    created[0].description === "재현 절차" &&
    el("jira-create-scrim").hidden && asked.list.length === listsBeforeCreate + 1;

  // ⌘/Ctrl+F lands on the source's own query, then a focused Task query owns
  // the first Escape; the route owns the next.
  box.blur();
  document.dispatchEvent(new KeyboardEvent("keydown", {
    key: "f", ...window.__TEST_PRIMARY_EVENT__, bubbles: true, cancelable: true,
  }));
  seen.findFocusesQuery = document.activeElement === box;
  document.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
  await wait(40);
  seen.escapeBlursQuery = document.activeElement !== box && !el("task-view").hidden;
  document.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
  await wait(40);
  seen.escapeClosesTask = el("task-view").hidden;

  box.value = "";
  delete window.__ANSWER__.jira_issues;
  delete window.__ANSWER__.jira_search_issues;
  delete window.__ANSWER__.jira_projects;
  delete window.__ANSWER__.jira_create_issue;
  window.__JIRA_STATUS__ = undefined;
  return seen;
});
ok(
  "the Jira page searches by JQL, and its presets step aside while you type",
  jiraSearch.presetLoadsList && jiraSearch.debounceHolds && jiraSearch.typingSearches &&
    jiraSearch.textFallbackExplainsItself && jiraSearch.chipsStepAside &&
    jiraSearch.enterIsImeSafe && jiraSearch.clearRestoresPreset &&
    jiraSearch.emptySaysJql && jiraSearch.emptySaysPreset &&
    jiraSearch.createSeeds && jiraSearch.createScrimCancels &&
    jiraSearch.createEscapeCancels && jiraSearch.createSiteRefreshes &&
    jiraSearch.createDegradesToText && jiraSearch.createTravels &&
    jiraSearch.findFocusesQuery && jiraSearch.escapeBlursQuery && jiraSearch.escapeClosesTask,
  JSON.stringify(jiraSearch),
);

/* ---- 작업판 GitHub의 검색(1-g70·1-g77a) ----
 *
 * 검색칸 하나가 지금의 질문을 들고 있다(신판 실측: 칩이 그 칸에 써 넣는다).
 * 재는 것은 그 계약이다: 친 문장은 preset 없이 그대로 가지만, 빈 칸은 현재
 * 종류의 `issues`/`prs` preset을 보내 탭의 말과 목록이 갈리지 않는다. 그리고
 * 언제 물었는가(750ms 뒤냐 — Jira의 300이 아니다 — Enter 즉시냐, 조합
 * 중이면 아예 아니냐), 답이 비었을 때 어느 문장을 말하는가. */
const githubSearch = await page.evaluate(async () => {
  const wait = (ms) => new Promise((done) => setTimeout(done, ms));
  const seen = {};
  const wasGh = window.__GH__;
  window.__GH__ = "connected";
  githubStatusLoaded = false;
  let answer = [{
    kind: "issue", number: 7, title: "로그인이 두 번 튕김",
    url: "https://github.com/acme/app/issues/7", state: "open",
    author: "kim", branch: null, cross_repo: false,
  }];
  const asked = [];
  window.__ANSWER__.github_work_items = (args) => {
    asked.push({ preset: args.preset, query: args.query });
    return answer;
  };
  const box = el("task-gh-search");
  const chips = () => [...el("github-presets").querySelectorAll("[data-gh-preset]")];
  box.value = "";
  taskGithubChip = null;
  setTaskOpen(true);
  setTaskSource("github");
  await wait(200);
  box.blur();
  document.dispatchEvent(new KeyboardEvent("keydown", {
    key: "f", ...window.__TEST_PRIMARY_EVENT__, bubbles: true, cancelable: true,
  }));
  seen.findFocusesQuery = document.activeElement === box;
  // 빈 칸도 현재 종류의 것이다. Issues가 켜진 첫 프레임에 PR을 함께 묻는 것은
  // 선택된 탭과 목록이 서로 다른 말을 하는 상태다.
  seen.bootAsksRecent =
    asked[0]?.query === "" && asked.at(-1)?.preset === "issues" && asked.at(-1)?.query === "";

  // 실제 종류 버튼을 거쳐 PR로 간 다음 검색을 지우면 `prs`, 다시 Issues로
  // 돌아와 지우면 `issues`다. 직접 상태를 써 넣는 시험은 이벤트 배선을 못 잰다.
  el("github-kinds").querySelector('[data-value="pr"]').click();
  await wait(120);
  el("task-gh-search-clear").click();
  await wait(200);
  const prs = asked.at(-1)?.preset === "prs" && asked.at(-1)?.query === "";
  el("github-kinds").querySelector('[data-value="issue"]').click();
  await wait(120);
  el("task-gh-search-clear").click();
  await wait(200);
  seen.blankFollowsKind = prs && asked.at(-1)?.preset === "issues" && asked.at(-1)?.query === "";

  // 타이핑은 750ms를 기다린다 — Jira의 300이었다면 아래 400ms에서 이미
  // 나갔을 것이다. 나갈 때는 친 그대로, 양끝 공백만 빼고.
  const heldAt = asked.length;
  box.value = "  is:pr review-requested:@me  ";
  box.dispatchEvent(new Event("input", { bubbles: true }));
  await wait(400);
  seen.debounceHolds = asked.length === heldAt;
  await wait(500);
  seen.typingSearches =
    asked.length === heldAt + 1 && asked.at(-1)?.query === "is:pr review-requested:@me" &&
    // 프리셋은 ask에서도 비켜서야 한다 — 동승하면 백엔드가 둘을 이어 붙여
    // (search_plan은 preset을 앞에 둔다) is:issue와 PR 전용 한정자가 한 문자열에
    // 서고, 그 답은 언제나 빈 목록이다.
    asked.at(-1)?.preset === "";

  // 친 문장은 어느 칩의 것도 아니다 — 켜진 칩이 없고, 지우는 손이 선다.
  seen.typedOwnsTheBox =
    chips().length === 2 &&
    chips().every((one) => !one.classList.contains("is-active")) &&
    !el("task-gh-search-clear").hidden;

  // 조합 중인 Enter는 IME의 것이고, 맨 Enter는 기다림을 건너뛴다. 아래의
  // 20ms는 디바운스 750ms보다 한참 짧다 — 즉시 커밋이어야만 통과한다.
  const enterAt = asked.length;
  box.dispatchEvent(
    new KeyboardEvent("keydown", { key: "Enter", isComposing: true, bubbles: true }),
  );
  await wait(20);
  const imeSilent = asked.length === enterAt;
  box.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true }));
  await wait(20);
  seen.enterImeSafe = imeSilent && asked.length === enterAt + 1;

  // 지우기는 친 질의를 놓되 현재 종류는 놓지 않는다.
  const clearedAt = asked.length;
  el("task-gh-search-clear").click();
  await wait(200);
  seen.clearReleasesQuery =
    box.value === "" &&
    asked.length === clearedAt + 1 &&
    asked.at(-1)?.preset === "issues" &&
    asked.at(-1)?.query === "" &&
    chips().every((one) => !one.classList.contains("is-active")) &&
    el("task-gh-search-clear").hidden;

  // 빈 답에는 두 가지 뜻이 있고, 무엇이 물었는지가 문장을 고른다.
  answer = [];
  box.value = "없는 것";
  box.dispatchEvent(new Event("input", { bubbles: true }));
  await wait(900);
  const saidQuery =
    !el("github-none").hidden &&
    el("github-none-title").textContent ===
      t("task.github.noMatch", "일치하는 GitHub 작업이 없습니다") &&
    el("github-none-body").textContent ===
      t("task.github.noMatchHint", "쿼리를 변경하거나 지우세요.");
  el("task-gh-search-clear").click();
  await wait(200);
  seen.emptySaysQuery =
    saidQuery &&
    el("github-none-title").textContent === t("task.github.none", "항목이 없습니다") &&
    el("github-none-body").textContent ===
      t("task.github.noneBody", "이 프로젝트에서 이 조건에 맞는 열린 항목이 없습니다.");

  box.value = "";
  paintGithubTools();
  delete window.__ANSWER__.github_work_items;
  window.__GH__ = wasGh;
  githubStatusLoaded = false;
  setTaskOpen(false);
  return seen;
});
ok(
  "the GitHub tasks page searches through the same door, the box holding the question",
  githubSearch.bootAsksRecent && githubSearch.blankFollowsKind && githubSearch.findFocusesQuery &&
    githubSearch.debounceHolds && githubSearch.typingSearches &&
    githubSearch.typedOwnsTheBox && githubSearch.enterImeSafe &&
    githubSearch.clearReleasesQuery && githubSearch.emptySaysQuery,
  JSON.stringify(githubSearch),
);

/* ---- 작업판 GitHub의 필터(1-g70b) ----
 *
 * Orca에서는 고른 필터가 검색 문자열에 한정자로 합류한다 — 문자열 하나가 유일한
 * 진실이므로. 이 창은 그럴 수 없고(문법의 사본은 gh.rs 하나뿐), 그래서 이 시험이
 * 재는 첫째는 **값으로 갔는가**다: 상태를 고르면 `filters.state`가 실리고 질의
 * 문자열에는 `state:`가 한 자도 없어야 한다.
 *
 * 나머지는 그 값이 화면과 어긋나지 않는가다: 배지가 세는 수, 필 하나가 제 몫만
 * 걷는 것, 모두 지우기가 둘 다 걷는 것, 빈 답이 필터를 탓하는 것, 그리고 질의가
 * 같고 필터만 다른 두 질문이 서로를 잡아먹지 않는 것 — 물은 것의 이름이 필터를
 * 보지 못하면, 늦게 온 옛 답이 새 목록 위에 그려진다. */
const githubFilters = await page.evaluate(async () => {
  const wait = (ms) => new Promise((done) => setTimeout(done, ms));
  const seen = {};
  const wasGh = window.__GH__;
  window.__GH__ = "connected";
  githubStatusLoaded = false;
  const row = (number, title) => ({
    kind: "issue", number, title,
    url: `https://github.com/acme/app/issues/${number}`, state: "open",
    author: "kim", branch: null, cross_repo: false,
  });
  let answer = () => [row(7, "로그인이 두 번 튕김")];
  const asked = [];
  window.__ANSWER__.github_work_items = (args) => {
    // 값을 베껴 둔다: 창은 필터 객체 하나를 계속 들고 다니므로, 참조를 그대로
    // 적어 두면 나중의 한 번이 앞서 물은 것의 기록까지 고쳐 쓴다(진짜 다리는
    // 직렬화하므로 베끼는 쪽이 실제 모습이다).
    asked.push({
      preset: args.preset,
      query: args.query,
      filters: args.filters ? { ...args.filters } : args.filters,
    });
    return answer(args);
  };
  const box = el("task-gh-search");
  box.value = "";
  clearGithubFilters();
  setTaskOpen(true);
  setTaskSource("github");
  await wait(200);

  const menu = el("gh-filter-menu");
  const rows = () => [...el("gh-filter-menu-body").querySelectorAll(".note-pop-row")];
  const rowSaid = (said) =>
    rows().find((one) => one.querySelector(".note-pop-name")?.textContent === said);
  const badge = el("task-gh-filter-count");
  const pills = () => [...el("gh-filter-pills").querySelectorAll(".task-chip")];
  // 없는 줄을 누르려 들면 시험 파일 전체가 넘어진다 — 없으면 그 낱말만 거짓이
  // 되게 두고, 나머지 판정은 계속 서 있게 한다.
  const press = (node) => {
    node?.click();
    return Boolean(node);
  };

  // 상태를 하나 고른다. 나가는 것은 값이고, 질의 문자열은 그대로다.
  el("task-gh-filters").click();
  await wait(20);
  // 다섯 줄「이상」— 작성자·담당자 섹션(1-g70c)이 아래에 더 선다. 다섯이
  // 그 다섯인지는 rowSaid가 낱말로 짚는다.
  const opened = !menu.hidden && rows().length >= 5;
  const pickedClosed = press(rowSaid(t("task.github.stateClosed", "닫힘")));
  // 팝오버는 `--motion-fast`(150ms)만큼 나가는 길에 서 있다 — 그 뒤에야 감춰진다.
  await wait(260);
  seen.filtersRideAsValues =
    opened && pickedClosed &&
    asked.at(-1)?.filters?.state === "closed" &&
    asked.at(-1)?.filters?.draft === false &&
    !asked.at(-1)?.query.includes("state:") &&
    asked.every((one) => !one.query.includes("state:") && !one.query.includes("draft:"));
  // 고르면 팝오버는 물러난다 — 모션이 끝난 뒤에 감춰지므로 그만큼 기다린다.
  seen.pickClosesMenu = menu.hidden;

  // 배지는 켜진 수를 센다. 초안까지 켜면 둘.
  const oneUp = badge.textContent === "1" && !badge.hidden && pills().length === 1;
  el("task-gh-filters").click();
  await wait(20);
  const pickedDraft = press(rowSaid(t("task.github.filterDraft", "초안만")));
  await wait(260);
  seen.badgeCounts =
    oneUp && pickedDraft && badge.textContent === "2" && !badge.hidden && pills().length === 2 &&
    asked.at(-1)?.filters?.draft === true && asked.at(-1)?.filters?.state === "closed";

  // 필 하나는 제 몫만 걷는다 — 상태를 걷어도 초안은 서 있다.
  const pressedPill = press(pills().find((one) => one.dataset.filter === "state"));
  await wait(200);
  seen.pillRemoves =
    pressedPill &&
    asked.at(-1)?.filters?.state === null && asked.at(-1)?.filters?.draft === true &&
    badge.textContent === "1" && pills().length === 1 &&
    pills()[0].dataset.filter === "draft";

  // 모두 지우기는 지울 것이 있을 때에만 서고, 누르면 필 줄째 물러난다.
  el("task-gh-filters").click();
  await wait(20);
  const offersClear = press(rowSaid(t("task.github.filterClear", "필터 모두 지우기")));
  await wait(260);
  seen.clearAllResets =
    offersClear &&
    asked.at(-1)?.filters?.state === null && asked.at(-1)?.filters?.draft === false &&
    badge.hidden && el("gh-filter-pills").hidden && pills().length === 0;

  // 빈 답인데 친 글자는 없다 — 좁힌 것은 필터뿐이므로, 문장은 필터를 탓해야 한다.
  answer = () => [];
  el("task-gh-filters").click();
  await wait(20);
  const pickedOpen = press(rowSaid(t("task.github.stateOpen", "열림")));
  await wait(200);
  seen.emptyBlamesFilters =
    pickedOpen &&
    box.value === "" &&
    !el("github-none").hidden &&
    el("github-none-title").textContent ===
      t("task.github.noMatch", "일치하는 GitHub 작업이 없습니다") &&
    el("github-none-body").textContent ===
      t("task.github.noMatchHint", "쿼리를 변경하거나 지우세요.");

  // 그리고 물은 것의 이름. 프로젝트도 프리셋도 질의도 같고 필터만 다른 두 질문을
  // 앞의 것이 늦게 답하도록 세운다: 이름이 필터를 보지 못하면 그 옛 답이 새
  // 목록을 덮어쓴다.
  answer = (args) => {
    const late = args.filters?.draft !== true;
    const said = late ? [row(11, "늦게 오는 옛 답")] : [row(22, "방금 물은 답")];
    return late ? new Promise((done) => setTimeout(() => done(said), 400)) : said;
  };
  clearGithubFilters();
  await wait(60);
  taskGithubFilters.draft = true;
  loadTaskGithubNow();
  await wait(700);
  seen.signatureSeesFilters =
    el("github-list").querySelectorAll(".task-gh-row").length === 1 &&
    el("github-list").querySelector(".task-gh-row").dataset.number === "22";

  answer = () => [];
  clearGithubFilters();
  box.value = "";
  await wait(200);
  delete window.__ANSWER__.github_work_items;
  window.__GH__ = wasGh;
  githubStatusLoaded = false;
  setTaskOpen(false);
  return seen;
});
ok(
  "the GitHub filters ride as values, and pills take them off",
  githubFilters.filtersRideAsValues && githubFilters.pickClosesMenu &&
    githubFilters.badgeCounts && githubFilters.pillRemoves &&
    githubFilters.clearAllResets && githubFilters.emptyBlamesFilters &&
    githubFilters.signatureSeesFilters,
  JSON.stringify(githubFilters),
);

/* An installed but signed-out `glab` is its own face. It must not fall through
 * to a list request whose generic error gives no way to authenticate. */
const gitlabSignedOut = await page.evaluate(async () => {
  const wait = (ms) => new Promise((done) => setTimeout(done, ms));
  let listed = 0;
  window.__ANSWER__.gitlab_status = () => ({
    installed: true, authenticated: false, hosts: [],
  });
  window.__ANSWER__.gitlab_work_items = () => {
    listed += 1;
    return [];
  };
  gitlabStatusLoaded = false;
  setTaskOpen(true);
  setTaskSource("gitlab");
  await wait(200);
  const seen = {
    auth: !el("gitlab-auth").hidden,
    login: !el("gitlab-login").hidden,
    tools: !el("gitlab-tools").hidden,
    list: !el("gitlab-list").hidden,
    listed,
  };
  setTaskSource("jira");
  setTaskOpen(false);
  delete window.__ANSWER__.gitlab_status;
  delete window.__ANSWER__.gitlab_work_items;
  gitlabStatusLoaded = false;
  return seen;
});
ok(
  "a signed-out GitLab source shows the auth face and does not ask for work items",
  gitlabSignedOut.auth && gitlabSignedOut.login &&
    !gitlabSignedOut.tools && !gitlabSignedOut.list && gitlabSignedOut.listed === 0,
  JSON.stringify(gitlabSignedOut),
);

/* Starting an MR from the row's real action keeps the source and target
 * branches in the GitLab composer. A URL-only smart draft cannot resolve the
 * review head and would create unrelated work. */
const taskMrComposer = await page.evaluate(async () => {
  const wait = (ms) => new Promise((done) => setTimeout(done, ms));
  const mr = {
    kind: "mr", number: 84, title: "세션 복원 수리", state: "opened",
    url: "https://gitlab.com/acme/app/-/merge_requests/84",
    source_branch: "fix/session-restore", target_branch: "main",
    cross_repo: false, updated_at: "2026-08-21T11:00:00Z",
  };
  window.__ANSWER__.gitlab_status = () => ({
    installed: true, authenticated: true, hosts: ["gitlab.com"],
  });
  window.__ANSWER__.gitlab_work_items = () => [mr];
  gitlabStatusLoaded = false;
  taskGitlabView = "mrs";
  taskGitlabFilter = "opened";
  setTaskSource("jira");
  setTaskOpen(true);
  setTaskSource("gitlab");
  await wait(220);
  el("gitlab-list").querySelector(".task-gl-row .task-gl-act")?.click();
  await wait(220);
  const submission = worktreeFormSubmission();
  const seen = {
    taskClosed: el("task-view").hidden,
    composer: !el("wt-new-scrim").hidden,
    tab: worktreeFormTab,
    branch: submission?.branch,
    mr: submission?.mr,
    spec: submission?.spec,
  };
  setWorktreeForm(false);
  setTaskSource("jira");
  delete window.__ANSWER__.gitlab_status;
  delete window.__ANSWER__.gitlab_work_items;
  gitlabStatusLoaded = false;
  return seen;
});
ok(
  "an MR started from Tasks keeps its source and target in the GitLab composer",
  taskMrComposer.taskClosed && taskMrComposer.composer && taskMrComposer.tab === "gitlab" &&
    taskMrComposer.branch === "fix/session-restore" &&
    taskMrComposer.mr?.number === 84 && taskMrComposer.mr?.source === "fix/session-restore" &&
    taskMrComposer.mr?.target === "main" && taskMrComposer.mr?.crossRepo === false &&
    taskMrComposer.spec?.includes("https://gitlab.com/acme/app/-/merge_requests/84"),
  JSON.stringify(taskMrComposer),
);

/* 작업판의 GitLab(1-g56b): 탭이 서면 먼저 기계에 glab이 있는지를 묻고, 그 다음
 * 목록을 묻는다. 보기 셋은 하나의 목록을 나눠 쓰므로 — 물은 것이 무엇이었는지가
 * 칩과 함께 건너가야 한다: 보기를 옮기면 칩이 그 보기의 첫 칩으로 돌아가고,
 * 칩을 누르면 그 값 그대로 나간다(질의를 짓는 손은 Rust 하나뿐이다). */
const gitlabPanel = await page.evaluate(async () => {
  const seen = {};
  const wait = (ms) => new Promise((done) => setTimeout(done, ms));
  const asked = [];
  const opened = [];
  window.__ANSWER__.gitlab_status = () => {
    asked.push("status");
    return { installed: true, authenticated: true, hosts: ["gitlab.com"] };
  };
  let items = [
    {
      kind: "mr",
      number: 42,
      title: "리다이렉트 수리",
      state: "opened",
      updated_at: "2026-08-16T01:02:03Z",
      url: "https://gitlab.com/acme/app/-/merge_requests/42",
    },
    {
      kind: "issue",
      number: 7,
      title: "로그인이 두 번 튕김",
      state: "opened",
      updated_at: "2026-08-15T00:00:00Z",
      url: "https://gitlab.com/acme/app/-/issues/7",
    },
  ];
  let todos = [{
    action: "marked_for_review",
    target_type: "MergeRequest",
    target_number: 42,
    target_title: "리다이렉트 수리",
    project_path: "acme/app",
    target_url: "https://gitlab.com/acme/app/-/merge_requests/42",
    updated_at: "2026-08-16T02:00:00Z",
  }];
  window.__ANSWER__.gitlab_work_items = (args) => {
    asked.push(`items ${args.view} ${args.filter} ${args.project}`);
    return items;
  };
  window.__ANSWER__.gitlab_todos = (args) => {
    asked.push(`todos ${args.project}`);
    return todos;
  };
  window.__ANSWER__.open_url = (args) => (opened.push(args.url), null);
  // 이 판의 첫 물음이 실제로 나가도록: 설정 카드가 이미 물었을 수 있다.
  gitlabStatusLoaded = false;
  taskGitlabView = "mrs";
  taskGitlabFilter = "opened";

  setTaskSource("jira");
  setTaskOpen(true);
  el("task-tab-gitlab").click();
  await wait(200);
  // 설치 여부가 먼저다 — 없는 CLI에 던진 질문의 답은 사람이 할 일을 이름하지
  // 못한다. 그리고 첫 목록은 실측의 기본값(MR·열기)이다.
  seen.tabOpensAndAsks =
    asked[0] === "status" &&
    asked[1] === `items mrs opened ${activeWorktreePath}` &&
    el("gitlab-tools").hidden === false &&
    el("gitlab-list").hidden === false;

  // 두 종류의 행은 GitLab이 제 화면에서 쓰는 기호로 갈린다.
  const rows = [...el("gitlab-list").querySelectorAll(".task-gl-row")];
  seen.rowsPaint =
    rows.length === 2 &&
    rows[0].querySelector(".task-gl-id").textContent === "!42" &&
    rows[1].querySelector(".task-gl-id").textContent === "#7" &&
    rows[0].querySelector(".task-gl-title").textContent === "리다이렉트 수리" &&
    rows[0].querySelector(".task-gl-kind").textContent ===
      `${t("task.gitlab.kindMr", "MR")} · opened`;

  // 보기를 옮기면 칩은 그 보기의 첫 칩으로 돌아간다 — 이슈에 「병합됨」이 남아
  // 있으면 그 칩이 부를 목록이 없다.
  taskGitlabFilter = "merged";
  el("gitlab-views").querySelector('[data-value="issues"]').click();
  await wait(200);
  seen.viewSwitchAsksIssues =
    asked.at(-1) === `items issues opened ${activeWorktreePath}` &&
    [...el("gitlab-chips").querySelectorAll("[data-gitlab-filter]")]
      .map((chip) => chip.dataset.gitlabFilter).join("|") === "opened|assigned-to-me";

  // 이슈의 칩이 옮기는 것은 담당자다. 값 그대로 나가고, 이 창은 질의를 짓지
  // 않는다 — `scope=assigned_to_me`로 옮기는 손은 glab.rs 하나다.
  el("gitlab-chips").querySelector('[data-gitlab-filter="assigned-to-me"]').click();
  await wait(200);
  seen.chipAsksAssigned =
    asked.at(-1) === `items issues assigned-to-me ${activeWorktreePath}` &&
    el("gitlab-chips").querySelector('[data-gitlab-filter="assigned-to-me"]')
      .getAttribute("aria-pressed") === "true";

  // MR의 칩은 상태를 옮긴다.
  el("gitlab-views").querySelector('[data-value="mrs"]').click();
  await wait(200);
  el("gitlab-chips").querySelector('[data-gitlab-filter="merged"]').click();
  await wait(200);
  seen.mrChipMerged = asked.at(-1) === `items mrs merged ${activeWorktreePath}`;

  // 할 일에는 칩이 없고, 행은 그 페이지다(다이얼로그가 없다 — 실측).
  el("gitlab-views").querySelector('[data-value="todos"]').click();
  await wait(200);
  const todoRow = el("gitlab-list").querySelector(".task-gl-todo");
  const labelled = el("gitlab-refresh-label").textContent ===
    t("task.gitlab.refreshTodos", "내 할 일 새로 고침");
  todoRow?.click();
  await wait(80);
  seen.todosOpenWeb =
    asked.at(-1) === `todos ${activeWorktreePath}` &&
    el("gitlab-chips").hidden === true &&
    labelled &&
    todoRow?.querySelector(".task-gl-action").textContent === "marked for review" &&
    todoRow?.querySelector(".task-gl-project").textContent === "acme/app" &&
    opened.at(-1) === "https://gitlab.com/acme/app/-/merge_requests/42";

  // 빈 할 일은 나쁜 소식이 아니다 — 그 문장이 이 판의 것이라는 사실째로 잰다.
  todos = [];
  el("gitlab-refresh").click();
  await wait(200);
  seen.emptySaysCaughtUp =
    el("gitlab-none").hidden === false &&
    el("gitlab-list").hidden === true &&
    el("gitlab-none-title").textContent === t("task.gitlab.emptyTodos", "대기 중인 할 일 없음") &&
    el("gitlab-none-body").textContent ===
      t("task.gitlab.emptyTodosCaughtUp", "대기 중인 할 일이 없습니다. 모두 따라잡았네요!");

  items = [];
  todos = [];
  delete window.__ANSWER__.gitlab_status;
  delete window.__ANSWER__.gitlab_work_items;
  delete window.__ANSWER__.gitlab_todos;
  delete window.__ANSWER__.open_url;
  taskGitlabView = "mrs";
  taskGitlabFilter = "opened";
  gitlabStatusLoaded = false;
  setTaskSource("jira");
  setTaskOpen(false);
  return seen;
});
ok(
  "the GitLab tasks tab lists what glab answers, and each view keeps its own filters",
  gitlabPanel.tabOpensAndAsks && gitlabPanel.rowsPaint && gitlabPanel.viewSwitchAsksIssues &&
    gitlabPanel.chipAsksAssigned && gitlabPanel.mrChipMerged && gitlabPanel.todosOpenWeb &&
    gitlabPanel.emptySaysCaughtUp,
  JSON.stringify(gitlabPanel),
);

/* GitLab 항목 다이얼로그(1-g56c): 행 하나가 상세를 열고, 대화가 이 창의
 * 마크다운으로 그려지며, 댓글은 값 그대로 백엔드로 가서 성공 뒤 다시 읽히고,
 * 닫기가 상태를 실제로 뒤집는다.
 *
 * 「argv를 타지 않는다」는 규칙은 이 판에서 잴 수 없다 — 여기 기록되는 인자는
 * IPC의 것이고, 그 본문이 `glab`의 명령줄이 아니라 stdin으로 간다는 사실은
 * Rust 쪽 시험(`a_comment_travels_on_stdin_never_argv`)의 것이다. */
const glItemFaces = await page.evaluate(async () => {
  const seen = {};
  const wait = (ms) => new Promise((done) => setTimeout(done, ms));
  const asked = { detail: [], comment: [], state: [] };
  const opened = [];
  let itemState = "opened";
  // 시스템 노트는 백엔드가 이미 걸러 낸다 — 이 판이 재는 것은 걸러진 목록이
  // 그려지는지이고, 그 수가 곧 화면에 설 카드의 수다.
  const comments = [
    {
      author: "lee",
      created_at: "2026-08-02T10:00:00Z",
      body: "브랜치 **fix/redirect**에서 재현",
      resolved: true,
    },
    { author: "hana", created_at: "2026-08-03T09:00:00Z", body: "고쳤습니다", resolved: null },
  ];
  window.__ANSWER__.gitlab_status = () =>
    ({ installed: true, authenticated: true, hosts: ["gitlab.com"] });
  window.__ANSWER__.gitlab_work_items = () => [{
    kind: "mr",
    number: 42,
    title: "리다이렉트 수리",
    state: itemState,
    updated_at: "2026-08-16T01:02:03Z",
    url: "https://gitlab.com/acme/app/-/merge_requests/42",
  }];
  window.__ANSWER__.gitlab_item_detail = (args) => {
    asked.detail.push(args);
    return {
      kind: "mr",
      number: 42,
      title: "리다이렉트 수리",
      state: itemState,
      author: "hana",
      created_at: "2026-08-01T09:00:00Z",
      body: "재현: <script>alert(1)</script> 그리고 **굵게**",
      url: "https://gitlab.com/acme/app/-/merge_requests/42",
      labels: ["bug", "backend"],
      comments,
    };
  };
  window.__ANSWER__.gitlab_comment_item = (args) => {
    asked.comment.push(args);
    comments.push({
      author: "me",
      created_at: "2026-08-16T00:00:00Z",
      body: args.body,
      resolved: null,
    });
    return null;
  };
  window.__ANSWER__.gitlab_set_item_open = (args) => {
    asked.state.push(args);
    itemState = args.open ? "opened" : "closed";
    return null;
  };
  window.__ANSWER__.open_url = (args) => (opened.push(args.url), null);
  gitlabStatusLoaded = false;
  taskGitlabView = "mrs";
  taskGitlabFilter = "opened";

  setTaskOpen(true);
  el("task-tab-gitlab").click();
  await wait(200);
  el("gitlab-list").querySelector(".task-gl-row").click();
  await wait(200);
  seen.rowOpensDetail =
    el("gl-item-scrim").hidden === false &&
    asked.detail.at(-1)?.kind === "mr" &&
    asked.detail.at(-1)?.number === 42 &&
    el("gl-item-number").textContent === "!42" &&
    el("gl-item-title").textContent === "리다이렉트 수리" &&
    el("gl-item-state").textContent === "opened" &&
    el("gl-item-meta").textContent.includes("hana") &&
    [...el("gl-item-labels").querySelectorAll(".gl-item-label")]
      .map((chip) => chip.textContent).join("|") === "bug|backend" &&
    // 본문은 이 창의 마크다운으로 — 스크립트는 글자로 남는다.
    el("gl-item-body").textContent.includes("<script>alert(1)</script>") &&
    el("gl-item-body").querySelector("script") === null &&
    el("gl-item-body").querySelector("strong") !== null;

  const cards = [...el("gl-item-comments").querySelectorAll(".gl-item-comment")];
  seen.commentsPaint =
    cards.length === comments.length &&
    el("gl-item-comments-head").textContent ===
      t("task.gitlab.comments", "댓글 {{count}}", { count: comments.length }) &&
    cards[0].querySelector(".gl-item-comment-head").textContent.includes("lee") &&
    cards[0].querySelector(".gl-item-comment-body strong") !== null &&
    // 「해결됨」은 해결된 실타래에만 붙는다.
    cards[0].querySelector(".gl-item-resolved")?.textContent ===
      t("task.gitlab.resolved", "해결됨") &&
    cards[1].querySelector(".gl-item-resolved") === null;

  // 빈 댓글은 나가지 않는다.
  el("gl-item-comment-field").value = "   ";
  el("gl-item-comment-send").click();
  await wait(80);
  const emptyStayed = asked.comment.length === 0;
  el("gl-item-comment-field").value = "확인했습니다";
  el("gl-item-comment-send").click();
  await wait(200);
  seen.composerSends =
    emptyStayed &&
    asked.comment.at(-1)?.body === "확인했습니다" &&
    asked.comment.at(-1)?.number === 42 &&
    asked.comment.at(-1)?.kind === "mr" &&
    el("gl-item-comment-field").value === "" &&
    el("gl-item-comments").querySelectorAll(".gl-item-comment").length === cards.length + 1;

  // 닫기 — 상태가 실제로 뒤집히고, 단추는 다시 열기로 갈아입는다.
  el("gl-item-state-act").click();
  await wait(200);
  seen.stateToggles =
    asked.state.at(-1)?.open === false &&
    asked.state.at(-1)?.number === 42 &&
    // 뒤집힌 뒤 상세를 다시 읽었다는 증거: 새 상태가 카드에 서 있다.
    el("gl-item-state").textContent === "closed" &&
    el("gl-item-state").className.includes("is-closed") &&
    el("gl-item-state-act").textContent === t("task.gitlab.reopen", "다시 열기");

  el("gl-item-open-web").click();
  await wait(80);
  seen.openWeb = opened.at(-1) === "https://gitlab.com/acme/app/-/merge_requests/42";

  // 물러서는 것은 동작이다 — 모션이 다한 뒤에 사라진다.
  el("gl-item-shut").click();
  const stillUp = el("gl-item-scrim").hidden === false;
  await wait(260);
  const shutHid = el("gl-item-scrim").hidden === true;
  // 그리고 Escape도 같은 문이다.
  el("gitlab-list").querySelector(".task-gl-row").click();
  await wait(200);
  document.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
  await wait(260);
  seen.dismisses = stillUp && shutHid && el("gl-item-scrim").hidden === true;

  delete window.__ANSWER__.gitlab_status;
  delete window.__ANSWER__.gitlab_work_items;
  delete window.__ANSWER__.gitlab_item_detail;
  delete window.__ANSWER__.gitlab_comment_item;
  delete window.__ANSWER__.gitlab_set_item_open;
  delete window.__ANSWER__.open_url;
  taskGitlabView = "mrs";
  taskGitlabFilter = "opened";
  gitlabStatusLoaded = false;
  setTaskSource("jira");
  setTaskOpen(false);
  return seen;
});
ok(
  "a GitLab row opens its item — comments land off argv, and the state toggles",
  glItemFaces.rowOpensDetail && glItemFaces.commentsPaint && glItemFaces.composerSends &&
    glItemFaces.stateToggles && glItemFaces.openWeb && glItemFaces.dismisses,
  JSON.stringify(glItemFaces),
);

/* ---- 작업판 GitHub의 두 단(1-g77a) ----
 *
 * 신판 실측의 구조: 종류 세그먼트(이슈·PR) 아래 그 종류의 프리셋 칩이 서고,
 * 칩 하나가 검색칸에 제 질의를 **써 넣는다**. 문법의 사본은 여전히 gh.rs
 * 하나뿐이므로 그 문장은 지어지지 않고 물어서 온다 — 이 시험이 그 목을
 * 세우고 재는 것은 「받은 문장이 칸에 서고, 그 문장 그대로 다시 나가는가」다.
 *
 * 그리고 그 구조가 설 수 없는 사정 하나: 물어볼 저장소가 없으면 빈 목록이
 * 아니라 다시 찾아보는 손이 선다 — 「항목이 없습니다」와는 할 일이 다르다. */
const githubTiers = await page.evaluate(async () => {
  const wait = (ms) => new Promise((done) => setTimeout(done, ms));
  const seen = {};
  const wasGh = window.__GH__;
  window.__GH__ = "connected";
  githubStatusLoaded = false;
  const asked = [];
  const composed = [];
  const opened = [];
  window.__ANSWER__.github_work_items = (args) => {
    asked.push({ preset: args.preset, query: args.query });
    return [];
  };
  // 문법은 Rust의 것이다(`gh::preset_query`가 쌍마다 시험한다). 여기서 오는
  // 것은 알아볼 수 있는 표식이고, 창이 그것을 그대로 보여 주는지만 잰다.
  window.__ANSWER__.github_preset_query = (args) => {
    composed.push({ kind: args.kind, preset: args.preset });
    return `${args.kind} ${args.preset} query`;
  };
  window.__ANSWER__.github_web_urls = () => ({
    repo: "https://github.com/acme/app",
    issues: "https://github.com/acme/app/issues",
    pulls: "https://github.com/acme/app/pulls",
    new_issue: "https://github.com/acme/app/issues/new",
  });
  window.__ANSWER__.open_url = (args) => (opened.push(args.url), null);

  const box = el("task-gh-search");
  const chips = () =>
    [...el("github-presets").querySelectorAll("[data-gh-preset]")]
      .map((one) => one.dataset.ghPreset)
      .join(",");
  const kind = (word) => el("github-kinds").querySelector(`[data-value="${word}"]`);
  box.value = "";
  taskGithubChip = null;
  taskGithubKind = "issue";
  setTaskOpen(true);
  setTaskSource("github");
  await wait(200);

  // 종류가 칩을 정한다: 이슈에는 둘, PR에는 셋. 그리고 종류를 옮기는 것은 그
  // 종류의 첫 칩을 세우는 것이다 — 칸에 든 문장이 곧 화면의 목록이므로.
  const issueChips = chips();
  kind("pr").click();
  await wait(200);
  seen.kindSwapsChips =
    issueChips === "open,assigned" && chips() === "open,mine,review" &&
    kind("pr").classList.contains("is-active") &&
    box.value === "pr open query" && asked.at(-1)?.query === "pr open query";

  // 칩 하나가 칸을 채우고, 그 문장이 그대로 나간다 — preset은 빈 값으로.
  // 칩은 있으면 누르고 없으면 facet이 거짓으로 선다: 종류 전환이 죽은 판에서
  // null에 .click()을 하면 스위트 전체가 결과도 없이 쓰러진다(변이 배터리가
  // 실제로 그렇게 쓰러뜨렸다) — 시험은 죽지 말고 틀렸다고 말해야 한다.
  const filledAt = asked.length;
  const reviewChip = el("github-presets").querySelector('[data-gh-preset="review"]');
  reviewChip?.click();
  await wait(200);
  seen.chipFillsBox =
    reviewChip !== null &&
    box.value === "pr review query" &&
    asked.length === filledAt + 1 &&
    asked.at(-1)?.query === "pr review query" && asked.at(-1)?.preset === "" &&
    composed.at(-1)?.kind === "pr" && composed.at(-1)?.preset === "review" &&
    // is-active는 다시 찾아서 본다: 클릭이 칩 줄을 다시 그리므로, 클릭 전에
    // 잡아둔 노드는 그 순간 화면 밖의 옛 판이다.
    el("github-presets").querySelector('[data-gh-preset="review"]')
      ?.classList.contains("is-active") === true;

  // 필터는 검색칸 왼쪽에 선다(실측: 우리 것은 오른쪽이었다).
  const line = [...el("task-gh-filters").parentElement.children];
  seen.filterSitsLeft =
    line.indexOf(el("task-gh-filters")) >= 0 &&
    line.indexOf(el("task-gh-filters")) < line.indexOf(box.parentElement);

  // 새 이슈도, ↗도 저장소의 그 주소로 나간다 — 주소를 아는 것은 백엔드뿐이다.
  el("github-new-issue").click();
  await wait(120);
  const newIssue = opened.at(-1) === "https://github.com/acme/app/issues/new";
  el("github-open-web").click();
  await wait(120);
  seen.newIssueOpens = newIssue && opened.at(-1) === "https://github.com/acme/app/pulls";

  // 새로 고침은 같은 질문을 일부러 다시 묻는다.
  const refreshedAt = asked.length;
  el("github-refresh").click();
  await wait(200);
  seen.refreshReasks =
    asked.length === refreshedAt + 1 && asked.at(-1)?.query === "pr review query";

  // 물어볼 저장소가 없는 사정. 진단이 그렇게 말하면 목록도 도구 단도 서지
  // 않고, 다시 시도가 그 진단을 다시 돌린다.
  let probes = 0;
  window.__ANSWER__.github_status = () => {
    probes += 1;
    return {
      availability: "available",
      connected: true,
      credential_protection: "external_cli",
      repo_host: null,
      repo_standing: "not_repository",
      active_account_id: "gh-test",
      accounts: [{
        id: "gh-test",
        host: "github.com",
        login: "octocat",
        active: true,
        standing: "connected",
        selectable: true,
        disconnectable: true,
        credential_source: "gh",
        env_credential: null,
        scope_gaps: [],
      }],
    };
  };
  githubStatusLoaded = false;
  await paintGithubPanel();
  await wait(120);
  const saidNoSource =
    !el("github-nosource").hidden &&
    el("github-tools").hidden &&
    el("github-list").hidden &&
    // 첫 프레임의 말은 마크업이 든 그대로다(`applyLocale`은 언어가 바뀔 때
    // 다시 쓴다) — 들여쓰기만 걷어 내고 그 문장인지 본다.
    el("github-nosource").querySelector("p").textContent.trim() ===
      t(
        "task.github.noSource",
        "작업에 쓸 GitHub 소스가 없습니다 — 원격이 없거나 소스를 확인하지 못했습니다.",
      );
  const probedAt = probes;
  el("github-retry").click();
  await wait(240);
  seen.undetectedRetries =
    saidNoSource && probes === probedAt + 1 && !el("github-nosource").hidden;

  delete window.__ANSWER__.github_status;
  delete window.__ANSWER__.github_work_items;
  delete window.__ANSWER__.github_preset_query;
  delete window.__ANSWER__.github_web_urls;
  delete window.__ANSWER__.open_url;
  box.value = "";
  taskGithubChip = null;
  taskGithubKind = "issue";
  window.__GH__ = wasGh;
  githubStatusLoaded = false;
  setTaskOpen(false);
  return seen;
});
ok(
  "the GitHub page stands in two tiers — a chip writes the query into the box, and the undetected source offers retry",
  githubTiers.kindSwapsChips && githubTiers.chipFillsBox && githubTiers.filterSitsLeft &&
    githubTiers.newIssueOpens && githubTiers.refreshReasks && githubTiers.undetectedRetries,
  JSON.stringify(githubTiers),
);

/* 워크트리 행의 라이브포트 핀(U02, Orca `WorktreeCardPortsTrigger`): 포트를
 * 가진 행에만 플러그가 서고, 클릭은 행 활성화를 삼킨 채 같은 포트 팝오버를
 * 그 체크아웃으로 좁혀 연다 — "라이브 포트 (n)" 머리에, 그 밖 절 없이.
 * 상태바의 문은 여전히 전체 목록이다. */
const portPin = await page.evaluate(async () => {
  const seen = {};
  const wired = "/tmp/pin-wired";
  const bare = "/tmp/pin-bare";
  const heldCatalog = window.__ANSWER__.project_catalog;
  window.__ANSWER__.project_catalog = () => [{
    name: "pin-project",
    path: wired,
    worktrees: [
      { path: wired, branch: "main", is_main: true, active: false, is_folder: false },
      { path: bare, branch: "quiet", is_main: false, active: false, is_folder: false },
    ],
  }];
  window.__ANSWER__.listening_ports = () => ({
    platform: "macos",
    unavailable: null,
    ports: [
      { port: 5173, connect_host: "localhost", bind_host: "[::1]", pid: 4242,
        process: "node", owner: "zerocode", owner_path: wired },
      { port: 5555, connect_host: "localhost", bind_host: "[::1]", pid: 4243,
        process: "qemu", owner: "zerocode", owner_path: wired },
      { port: 6001, connect_host: "localhost", bind_host: "[::1]", pid: 4244,
        process: "node", owner: "zerocode", owner_path: "/tmp/pin-other" },
      { port: 8022, connect_host: "localhost", bind_host: "*", pid: 9911,
        process: "sshd", owner: null, owner_path: null },
    ],
  });
  await refreshWorktrees();
  await refreshPorts();
  await new Promise((done) => setTimeout(done, 80));
  const pinOf = (path) =>
    document.querySelector(`.wt-row[data-worktree-path="${CSS.escape(path)}"] .wt-ports`);
  seen.standsOnWired = pinOf(wired)?.hidden === false;
  seen.hidesOnBare = pinOf(bare)?.hidden === true;
  seen.saysCount = pinOf(wired)?.getAttribute("aria-label") ?? "";
  // 클릭: 행은 조용하고(활성 워크스페이스 불변), 팝오버는 좁혀서 선다.
  const activeWas = activeWorktreePath;
  pinOf(wired).click();
  await new Promise((done) => setTimeout(done, 120));
  seen.rowStaysQuiet =
    activeWorktreePath === activeWas && !selectedWorktreePaths.has(wired);
  seen.popOpen = !document.getElementById("ports-pop").hidden;
  seen.scopedRows = document.querySelectorAll("#ports-body .port-row").length;
  seen.noExternalSection = document.querySelector("#ports-body .ports-external") === null;
  seen.scopedHead = document.getElementById("ports-tally").textContent;
  // 상태바의 문은 전체 목록으로 돌아간다 — 그 밖 절까지.
  setPortsOpen(true);
  seen.barRows = document.querySelectorAll("#ports-body .port-row").length;
  seen.barHasExternal = document.querySelector("#ports-body .ports-external") !== null;
  setPortsOpen(false);
  if (heldCatalog) window.__ANSWER__.project_catalog = heldCatalog;
  else delete window.__ANSWER__.project_catalog;
  delete window.__ANSWER__.listening_ports;
  await refreshWorktrees();
  await refreshPorts();
  return seen;
});
ok(
  "the worktree row's plug opens the ports popover scoped to that checkout",
  portPin.standsOnWired && portPin.hidesOnBare &&
    portPin.saysCount.includes("2") && portPin.rowStaysQuiet && portPin.popOpen &&
    portPin.scopedRows === 2 && portPin.noExternalSection &&
    portPin.scopedHead.includes("2") && portPin.barRows === 4 && portPin.barHasExternal,
  JSON.stringify(portPin),
);

// Every file wears its own face — Orca's resolver, ported whole
// (file-type-icons-Uuu7rMFP.js): the exact-name map outranks the extension,
// the four filename rules sit between them, and a name nothing claims falls
// back to the plain file glyph the sprite already had.
const fileFaces = await page.evaluate(() => {
  const seen = {};
  seen.byExtension = fileTypeIcon("src/main.rs");
  // package.json is in the NAME map (FileBox) while bare .json is in the
  // EXTENSION map (FileBraces) — this pair is what proves the lookup order.
  seen.exactBeatsExtension = fileTypeIcon("app/package.json");
  seen.plainJson = fileTypeIcon("app/data.json");
  seen.envRule = fileTypeIcon(".env.local");
  seen.dockerRule = fileTypeIcon("Dockerfile.dev");
  seen.makeRule = fileTypeIcon("Makefile.am");
  seen.caseBlind = fileTypeIcon("shot.PNG");
  seen.archive = fileTypeIcon("backup.tar.gz");
  seen.trailingDot = fileTypeIcon("notes.");
  // README carries no extension and still resolves — it is in the name map.
  seen.bareName = fileTypeIcon("README");
  seen.unclaimed = fileTypeIcon("Justfile");
  seen.spriteHolds = ["i-ft-file-code", "i-ft-file-box", "i-ft-file-lock", "i-ft-smartphone"]
    .every((id) => document.getElementById(id) !== null);
  // A file tab wears the file's glyph, not the generic one.
  const probe = buildTabNode({ id: "ft-probe", kind: "file", path: "src/probe.rs" }, null);
  seen.tabFace = probe.querySelector(".tab-kind use")?.getAttribute("href");
  return seen;
});
ok(
  "a file's own glyph resolves the way Orca's explorer does, and a file tab wears it",
  fileFaces.byExtension === "ft-file-code" &&
    fileFaces.exactBeatsExtension === "ft-file-box" &&
    fileFaces.plainJson === "ft-file-braces" &&
    fileFaces.envRule === "ft-file-lock" &&
    fileFaces.dockerRule === "ft-file-cog" &&
    fileFaces.makeRule === "ft-file-terminal" &&
    fileFaces.caseBlind === "ft-file-image" &&
    fileFaces.archive === "ft-file-archive" &&
    fileFaces.trailingDot === "file" &&
    fileFaces.bareName === "ft-file-text" &&
    fileFaces.unclaimed === "file" &&
    fileFaces.spriteHolds &&
    fileFaces.tabFace === "#i-ft-file-code",
  JSON.stringify(fileFaces),
);

/* ---- the card's dress and the header's counts (1-g78a) ---------------------
 *
 * Orca's dashboard card wears a ReviewPill for the pull request its checkout
 * is on and says how many subagents it started; its header carries the total,
 * and while a search narrows something, what that search is showing.
 *
 * The four review words, their case-insensitive mapping and the one-minute
 * cache are Rust's (`gh::review_word`, `review_states`, tested there). What is
 * asserted here is the JOIN and the dress: the answer is keyed by checkout
 * path and a card is not, so the window pairs them — and asks about each
 * checkout once however many agents are standing in it. */
const boardDress = await page.evaluate(async () => {
  const settle = () => new Promise((done) => setTimeout(done, 180));
  const seen = {};
  {
    if (activeTabId !== "board") document.getElementById("nav-agents").click();
    await settle();
    const view = [...document.querySelectorAll("#board-view, .file-view")]
      .find((one) => one.querySelector(".agent-graph-layout") && !one.hidden);
    return {
      summaryButtons: view?.querySelectorAll("[data-graph-bucket]").length ?? 0,
      summaryCounts: [...(view?.querySelectorAll("[data-graph-count]") ?? [])]
        .map((one) => one.textContent),
      inspector: view?.querySelector(".agent-inspector") !== null,
      legacySettings: document.getElementById("board-settings-pop") !== null,
      legacyFilters: view?.querySelector(".board-filters") !== null,
      modes: [...view.querySelectorAll("[data-board-mode]")].map((button) => button.dataset.boardMode),
    };
  }
  const where = activeWorktreePath;
  // 두 셸이 같은 체크아웃에 선다 — 리뷰는 체크아웃의 것이므로 둘 다 같은
  // 알약을 두르고, 질문은 그래도 하나여야 한다.
  const reviewed = await openTermTab();
  const alongside = await openTermTab();
  // 그리고 이 창이 자리를 모르는 셸 하나. 체크아웃이 없으면 물어볼 것도 없다.
  window.__PANES__ = [
    { term: reviewed, agent: "claude", state: "working", at: 1, resumable: false },
    { term: alongside, agent: "claude", state: "working", at: 2, resumable: false },
    { term: 777, agent: "codex", state: "working", at: 3, resumable: false },
  ];
  window.__REVIEWS__ = [{ worktree: where, number: 12, state: "open" }];
  const base = [
    { bucket: "working", cards: [
      { pane: `term:${reviewed}`, agent: "claude", state: "working", heading: "리뷰 있는 카드",
        worktree: "feature/parse", project: "/p", task: "", unseen: false, changed_at: 1, at: 1,
        lineage: { depth: 0, is_first_sibling: true, is_last_sibling: true, child_count: 3 } },
      { pane: "term:777", agent: "codex", state: "working", heading: "리뷰 없는 카드",
        worktree: "main", project: "/p", task: "", unseen: false, changed_at: 3, at: 3 }] },
    { bucket: "done", cards: [] },
  ];
  const idleColumn = { bucket: "idle", cards: [
    { pane: "term:778", agent: "codex", state: "idle", heading: "쉬는 카드",
      worktree: "main", project: "/p", task: "", unseen: false, changed_at: 4, at: 4 }] };
  // `board_columns`가 답하는 규칙 하나를 그 자리에 세운다: idle 열은
  // `show_idle`일 때에만 돌아온다. 계보 기본값을 채우는 것도 그쪽 규칙의
  // 대역이므로 함께 선다 — 위쪽 보드 시험들의 스텁과 같은 손이다.
  window.__ANSWER__.board_columns = (args) => {
    window.__ASKED_BOARD__ = args;
    return (args.query.show_idle ? [...base, idleColumn] : base).map((column) => ({
      ...column,
      cards: column.cards.map((one) => ({
        lineage: { depth: 0, is_first_sibling: true, is_last_sibling: true, child_count: 0 },
        ...one,
      })),
    }));
  };
  boardQuery = "";
  boardShowIdle = false;
  boardMode = "board";
  if (activeTabId === "board") dropTab("board");
  document.getElementById("nav-agents").click();
  await settle();
  // 리뷰의 답은 그림 뒤에 도착해 스스로 한 번 더 그린다 — 그 두 번째 그림까지
  // 기다린다.
  await settle();

  const view = () => [...document.querySelectorAll("#board-view, .file-view")]
    .find((one) => one.querySelector(".agent-graph-layout") && !one.hidden);
  const card = (pane) => view().querySelector(`.board-card[data-pane="${pane}"]`);

  // ---- the pill, joined by the checkout the card's shell stands in ----
  const pill = card(`term:${reviewed}`)?.querySelector(".board-card-review");
  seen.pillWords = pill?.querySelector(".board-card-review-words")?.textContent ?? "";
  seen.pillTone = pill ? pill.className : "";
  // 톤은 클래스 이름이 아니라 색이다 — 열린 리뷰는 제 색을 쓰고, 그 색은
  // 알약이 앉은 줄의 muted가 아니다.
  seen.pillPainted = pill
    ? getComputedStyle(pill).color !== getComputedStyle(pill.parentElement).color
    : false;
  seen.pillInFoot = pill?.parentElement?.className === "board-card-foot";
  seen.noPillWithoutReview = card("term:777")?.querySelector(".board-card-review") === null;
  // 같은 체크아웃에 선 셸이 둘이어도 물음은 하나, 자리를 모르는 셸은 빠진다.
  seen.asked = window.__ASKED_REVIEWS__?.worktrees ?? [];
  seen.where = where;

  // ---- the subagent count, in Orca's words ----
  seen.subagents =
    card(`term:${reviewed}`)?.querySelector(".board-card-kids-words")?.textContent ?? "";

  // ---- the header's total, and the empty bucket's word ----
  seen.total = view().querySelector(".board-count").textContent;
  seen.cardsSent = window.__ASKED_BOARD__?.cards?.length ?? 0;
  seen.resultsHiddenUnsearched = view().querySelector(".board-results").hidden;
  seen.emptyWord =
    view().querySelector('[data-bucket="done"] .board-column-none')?.textContent ?? "";

  // ---- the results line, only while a search narrows something ----
  const query = view().querySelector(".board-query");
  query.value = "리뷰";
  query.dispatchEvent(new Event("input", { bubbles: true }));
  await settle();
  const results = view().querySelector(".board-results");
  seen.resultsShown = !results.hidden;
  seen.resultsWords = results.textContent;
  query.value = "";
  query.dispatchEvent(new Event("input", { bubbles: true }));
  await settle();

  // ---- the settings popover, and the switch that moved into it ----
  const pop = document.getElementById("board-settings-pop");
  seen.popShutAtRest = pop.hidden;
  seen.noBareCheckbox = view().querySelector(".board-idle") === null;
  view().querySelector(".board-settings").click();
  seen.popOpens = !pop.hidden;
  seen.gearSaysOpen = view().querySelector(".board-settings").getAttribute("aria-expanded");
  seen.popTitle = pop.querySelector(".settings-label").textContent;
  seen.popCopy = pop.querySelector(".settings-hint").textContent;
  seen.idleBefore = [...view().querySelectorAll(".board-column")].map((one) => one.dataset.bucket);
  const idle = pop.querySelector("input");
  idle.checked = true;
  idle.dispatchEvent(new Event("change", { bubbles: true }));
  await settle();
  seen.idleAsked = window.__ASKED_BOARD__?.query?.show_idle;
  seen.idleAfter = [...view().querySelectorAll(".board-column")].map((one) => one.dataset.bucket);
  // 그리고 바깥을 누르면 물러난다 — 이 창의 다른 팝오버들과 같은 손.
  document.dispatchEvent(new PointerEvent("pointerdown", { bubbles: true }));
  seen.popDismisses = pop.hidden || pop.classList.contains("is-closing");

  delete window.__ANSWER__.board_columns;
  delete window.__REVIEWS__;
  delete window.__ASKED_REVIEWS__;
  boardShowIdle = false;
  window.__PANES__ = [];
  window.__COLUMNS__ = [];
  closeTab(termTabId(reviewed));
  closeTab(termTabId(alongside));
  await settle();
  return seen;
});
ok(
  "the relations header keeps status actions and the inspector beside the task/relations switch",
  boardDress.summaryButtons === 3 && boardDress.summaryCounts.length === 3 &&
    boardDress.inspector && !boardDress.legacySettings &&
    !boardDress.legacyFilters && boardDress.modes.join() === "tasks,graph",
  JSON.stringify(boardDress),
);

/* ---- the two axes the board narrows on (1-g78b) ----------------------------
 *
 * Orca's `dashboardPopout.filters`: one 「필터」 button holding a project
 * section and a PR·MR status section, and what was picked comes down as a chip
 * row under the header where each chip takes off its own narrowing.
 *
 * What is asserted here is the PIPELINE, because that is what splits: the
 * project axis rides `BoardQuery.projects`, which Rust already accepts, so the
 * proof is what arrives in `board_columns`; the review axis is a fact only this
 * window holds, so the proof is that the cards are already narrowed when they
 * leave. Both together narrow the same list the columns draw — Orca filters
 * before it groups, and so does this. */
const boardFilters = await page.evaluate(async () => {
  const settle = () => new Promise((done) => setTimeout(done, 180));
  const seen = {};
  {
    const view = [...document.querySelectorAll("#board-view, .file-view")]
      .find((one) => one.querySelector(".agent-graph-layout") && !one.hidden);
    const query = view?.querySelector(".board-query");
    if (query) {
      query.value = "graph-search-contract";
      query.dispatchEvent(new Event("input", { bubbles: true }));
      await settle();
    }
    const asked = window.__ASKED_BOARD__?.query ?? null;
    if (query) {
      query.value = "";
      query.dispatchEvent(new Event("input", { bubbles: true }));
      await settle();
    }
    return {
      asked,
      filterButton: view?.querySelector(".board-filters") !== null,
      filterChips: view?.querySelector(".board-chips") !== null,
      searchKept: view?.querySelector(".board-query")?.value === "",
    };
  }
  const where = activeWorktreePath;
  // 두 셸이 같은 체크아웃에 선다(그래서 같은 리뷰·같은 프로젝트), 그리고 자리를
  // 모르는 셸 하나 — 그 하나가 「리뷰 없음」이자 프로젝트 없는 카드다.
  const merged = await openTermTab();
  const alongside = await openTermTab();
  window.__PANES__ = [
    { term: merged, agent: "claude", state: "working", at: 1, resumable: false },
    { term: alongside, agent: "claude", state: "working", at: 2, resumable: false },
    { term: 777, agent: "codex", state: "working", at: 3, resumable: false },
  ];
  window.__REVIEWS__ = [{ worktree: where, number: 7, state: "merged" }];
  // 이 스텁은 Rust의 그룹핑 대역이므로 **프로젝트 축은 저쪽에서** 걸러야 한다:
  // 이 창이 보내는 것은 값뿐이고(`query.projects`), 그 값으로 좁히는 일은
  // `zerocode_core::board`의 몫이다. 리뷰 축은 이미 걸러져서 도착한다.
  window.__ANSWER__.board_columns = (args) => {
    window.__ASKED_BOARD__ = args;
    const kept = args.cards.filter((card) =>
      args.query.projects.length === 0 || args.query.projects.includes(card.project));
    return [
      {
        bucket: "working",
        cards: kept.map((card) => ({
          lineage: { depth: 0, is_first_sibling: true, is_last_sibling: true, child_count: 0 },
          ...card,
        })),
      },
      { bucket: "done", cards: [] },
    ];
  };
  boardQuery = "";
  boardShowIdle = false;
  boardMode = "board";
  if (activeTabId === "board") dropTab("board");
  document.getElementById("nav-agents").click();
  await settle();
  // 리뷰의 답은 그림 뒤에 도착해 스스로 한 번 더 그린다 — 그 두 번째 그림까지.
  await settle();

  const view = () => [...document.querySelectorAll("#board-view, .file-view")]
    .find((one) => one.querySelector(".agent-graph-layout") && !one.hidden);
  const drawn = () => [...view().querySelectorAll(".board-card")].map((one) => one.dataset.pane);
  const sent = () => (window.__ASKED_BOARD__?.cards ?? []).map((one) => one.pane);
  const chips = () =>
    [...view().querySelectorAll(".board-chips .task-gh-pill-off")].map((one) => one.textContent);
  const results = () => view().querySelector(".board-results");

  seen.allDrawn = drawn();
  seen.cardProject = window.__ASKED_BOARD__?.cards?.find((one) => one.pane === `term:${merged}`)
    ?.project ?? "";
  seen.projectName = projectNameAt(seen.cardProject);

  // ---- the popover: a section per axis, the project vocabulary from the cards
  const pop = document.getElementById("board-filter-pop");
  seen.popShutAtRest = pop.hidden;
  view().querySelector(".board-filters").click();
  seen.popOpens = !pop.hidden;
  seen.buttonSaysOpen = view().querySelector(".board-filters").getAttribute("aria-expanded");
  seen.sections = [...pop.querySelectorAll(".note-pop-label")].map((one) => one.textContent);
  // 프로젝트 줄은 카드가 정한다: 같은 프로젝트에 선 셸이 둘이어도 줄은 하나,
  // 자리를 모르는 셸은 줄을 만들지 않는다.
  seen.rows = [...pop.querySelectorAll(".settings-check .settings-label")]
    .map((one) => one.textContent);

  const tick = (said) => {
    const box = [...pop.querySelectorAll(".settings-check")]
      .find((one) => one.querySelector(".settings-label").textContent === said)
      .querySelector("input");
    box.checked = !box.checked;
    box.dispatchEvent(new Event("change", { bubbles: true }));
  };

  // ---- the review axis narrows BEFORE the grouping ----
  tick("병합됨");
  await settle();
  seen.mergedDrawn = drawn();
  seen.mergedSent = sent();
  seen.mergedProjects = window.__ASKED_BOARD__?.query?.projects ?? [];
  tick("병합됨");
  await settle();

  // ---- and 「리뷰 없음」 is the absence, not a fifth state ----
  tick("리뷰 없음");
  await settle();
  seen.noneDrawn = drawn();
  seen.noneSent = sent();
  tick("리뷰 없음");
  await settle();

  // ---- the project axis rides the query Rust already accepts ----
  tick(seen.projectName);
  await settle();
  seen.projectsSent = window.__ASKED_BOARD__?.query?.projects ?? [];
  seen.projectDrawn = drawn();
  // 검색이 비어 있어도 결과 줄은 선다 — 좁히고 있는 것은 필터다.
  seen.filterResultsShown = !results().hidden;
  seen.filterResults = results().textContent;

  // ---- chips: what was narrowed, and the hand that takes one off ----
  tick("리뷰 없음");
  await settle();
  seen.chips = chips();
  seen.chipAria = view()
    .querySelector(".board-chips .task-gh-pill-off")
    ?.getAttribute("aria-label");
  seen.badge = view().querySelector(".board-filter-count").textContent;
  seen.bothDrawn = drawn();
  seen.bothResults = results().textContent;
  view().querySelector(".board-chips .task-gh-pill-off").click();
  await settle();
  seen.afterChip = chips();
  seen.afterChipDrawn = drawn();
  seen.afterChipResults = results().textContent;

  // ---- and the one hand that takes them all off ----
  // 걷을 것이 남았을 때만 서는 손이다 — 변이가 칩 하나로 전부를 걷어 버리면
  // 이 손도 함께 사라지므로, null에 손대면 시험이 답 없이 쓰러진다(1-g77a의
  // 그 무늬). 없으면 빈말로 남겨 facet이 거짓으로 서게 한다.
  const all = view().querySelector(".board-chips-clear");
  seen.clearWords = all?.textContent ?? "";
  all?.click();
  await settle();
  seen.chipRowGone = view().querySelector(".board-chips").hidden;
  seen.chipRowEmpty = view().querySelector(".board-chips").childElementCount;
  seen.badgeGone = view().querySelector(".board-filter-count").hidden;
  seen.resultsGone = results().hidden;
  seen.clearedDrawn = drawn();
  // 그리고 바깥을 누르면 팝오버가 물러난다 — 이 창의 다른 팝오버들과 같은 손.
  document.dispatchEvent(new PointerEvent("pointerdown", { bubbles: true }));
  seen.popDismisses = pop.hidden || pop.classList.contains("is-closing");

  delete window.__ANSWER__.board_columns;
  delete window.__REVIEWS__;
  delete window.__ASKED_REVIEWS__;
  window.__PANES__ = [];
  window.__COLUMNS__ = [];
  closeTab(termTabId(merged));
  closeTab(termTabId(alongside));
  await settle();
  return seen;
});
ok(
  "the graph keeps one Rust-backed search and ships no duplicate filter surface",
  boardFilters.asked?.query === "" &&
    boardFilters.asked?.show_idle === true &&
    !boardFilters.filterButton && !boardFilters.filterChips && boardFilters.searchKept,
  JSON.stringify(boardFilters),
);

// The session history, docked — Orca's AiVaultPanel as a right-column
// activity: arriving scans, the header counts shown-of-recent, the scope
// narrows the ASK (not the paint), the search rides the same ask, and a card
// wears the title, the LATEST turn with its speaker named, and the muted
// meta line — agent, count, age, model — with the hands only where a resume
// command exists.
const vaultDock = await page.evaluate(async () => {
  const seen = {};
  const settle = () => new Promise((done) => setTimeout(done, 30));
  const iso = (msAgo) => new Date(Date.now() - msAgo).toISOString();
  const session = (id, over = {}) => ({
    id,
    agent: "claude",
    session_id: id,
    title: `말한 것 ${id}`,
    cwd: activeWorktreePath,
    branch: null,
    model: "claude-fable-5",
    file_path: `/tmp/vault/${id}.jsonl`,
    codex_home: null,
    created_at: iso(9_000_000),
    updated_at: iso(300_000),
    modified_at: iso(300_000),
    message_count: 12,
    preview: [
      { role: "user", text: "the first ask" },
      { role: "assistant", text: "the last word" },
    ],
    resume: "claude --resume s1",
    ...over,
  });
  window.__VAULT__ = {
    groups: [
      {
        key: "p1",
        label: "zerocode",
        sessions: [
          session("s1"),
          session("s2", {
            updated_at: iso(3 * 86_400_000 + 3_600_000),
            modified_at: iso(3 * 86_400_000 + 3_600_000),
            preview: [],
            resume: null,
            model: null,
            message_count: 0,
          }),
        ],
      },
    ],
    agents: [{ slug: "claude", count: 2 }],
    issues: [],
    shown: 2,
    total: 5,
    truncated: false,
  };
  window.__ASKED_VAULT__ = null;

  document.getElementById("activity-vault-tab").click();
  await settle();
  seen.panelShows = !document.getElementById("activity-vault").hidden;
  seen.tabLit = document.getElementById("activity-vault-tab").getAttribute("aria-selected");
  // The default scope is the workspace (DEFAULT_AI_VAULT_SCOPE), and it must
  // reach the backend as this checkout's path — a filter applied only to the
  // paint would lie the moment the ledger grows.
  seen.askedScope = window.__ASKED_VAULT__?.query?.scope_paths;
  seen.activePath = activeWorktreePath;
  seen.sub = document.getElementById("vdock-sub").textContent;
  const cards = [...document.querySelectorAll(".vdock-card")];
  seen.cards = cards.length;
  seen.title = cards[0]?.querySelector(".vdock-card-title")?.textContent;
  seen.preview = cards[0]?.querySelector(".vdock-card-preview")?.textContent;
  seen.meta = cards[0]?.querySelector(".vdock-meta-words")?.textContent;
  seen.bareMeta = cards[1]?.querySelector(".vdock-meta-words")?.textContent;
  seen.noPreview = cards[1]?.querySelector(".vdock-card-preview")?.textContent;
  seen.groupLabel = document.querySelector(".vdock-group-label")?.textContent;
  seen.groupCount = document.querySelector(".vdock-group-count")?.textContent;
  seen.acts = cards.map((card) => card.querySelectorAll(".vdock-act").length);
  // 헤더의 두 도구와 카드 제목줄의 늘 보이는 손 — 원본의 크롬.
  seen.hostChip = document.getElementById("vdock-host")?.textContent.trim();
  seen.twists = cards.map((card) => card.querySelectorAll(".vdock-twist").length);

  document.getElementById("vdock-scope-all").click();
  await settle();
  seen.askedAll = window.__ASKED_VAULT__?.query?.scope_paths;
  seen.allLit = document.getElementById("vdock-scope-all").classList.contains("is-on");

  const box = document.getElementById("vdock-query");
  box.value = "needle";
  box.dispatchEvent(new Event("input", { bubbles: true }));
  await settle();
  seen.askedQuery = window.__ASKED_VAULT__?.query?.query;

  // 카드 몸이 문이다(라이브 보고 "세션창 클릭 orca처럼"): 클릭이 인라인
  // 상세를 연다 — 손의 띠, 첫 프롬프트, 미리보기의 턴들, worktree 줄.
  // 손 위의 클릭은 여닫지 않고, 다시 클릭하면 닫힌다.
  const cardNow = () => [...document.querySelectorAll(".vdock-card")];
  cardNow()[0].click();
  await settle();
  const opened = cardNow()[0];
  const detail = opened.querySelector(".vdock-detail");
  seen.detailStands = Boolean(detail) && opened.getAttribute("aria-expanded") === "true";
  seen.detailActs = [...(detail?.querySelectorAll(".vdock-detail-act") ?? [])]
    .map((one) => one.textContent);
  seen.detailLabels = [...(detail?.querySelectorAll(".vdock-receipt-label") ?? [])]
    .map((one) => one.textContent);
  seen.detailTurns = [...(detail?.querySelectorAll(".vdock-turn") ?? [])]
    .map((one) => one.dataset.role);
  seen.detailWorktree = detail?.querySelector(".vdock-receipt-line")?.textContent;
  // ⋯ 메뉴: 카드 위의 손 클릭은 여닫지 않고, 메뉴가 세 동작을 쥔다.
  const menu = document.getElementById("sidebar-menu");
  opened.querySelector(".vdock-more").click();
  await settle();
  seen.detailHeldThroughAct = Boolean(cardNow()[0].querySelector(".vdock-detail"));
  seen.moreRows = [...menu.querySelectorAll(".sidebar-menu-item .sidebar-menu-label")]
    .map((one) => one.textContent);
  closeSidebarMenu();
  await settle();
  cardNow()[0].click();
  await settle();
  seen.detailFolded = !cardNow()[0].querySelector(".vdock-detail");
  // 검색 지우개(실측 "Clear search"): 글자가 서면 ✕가 서고, ✕가 물음을
  // 비워 같은 길로 다시 묻는다.
  seen.clearShown = !document.getElementById("vdock-clear").hidden;
  document.getElementById("vdock-clear").click();
  await settle();
  seen.clearedQuery = window.__ASKED_VAULT__?.query?.query;
  seen.clearHidden = document.getElementById("vdock-clear").hidden;

  const fold = document.querySelector(".vdock-group-head");
  fold.click();
  seen.folded = document.querySelector(".vdock-group-body").hidden;
  seen.foldSaid = fold.getAttribute("aria-expanded");

  // ≡ 보기 메뉴 — 벤더 끄기와 빈 세션 숨김이 진짜 물음으로 나간다.
  document.getElementById("vdock-view").click();
  await settle();
  seen.viewRows = [...menu.querySelectorAll(".sidebar-menu-item .sidebar-menu-label")]
    .map((one) => one.textContent);
  const viewRow = (said) => [...menu.querySelectorAll(".sidebar-menu-item")]
    .find((one) => one.querySelector(".sidebar-menu-label")?.textContent === said);
  viewRow("빈 세션 숨기기").click();
  await settle();
  seen.askedHideEmpty = window.__ASKED_VAULT__?.query?.hide_empty;
  viewRow("Claude (2)").click();
  await settle();
  seen.askedOff = window.__ASKED_VAULT__?.query?.disabled_agents;
  closeSidebarMenu();
  await settle();

  // The two silences are different sentences: nothing on disk, and nothing
  // through the filters.
  window.__VAULT__ = { groups: [], issues: [], shown: 0, total: 0, truncated: false };
  document.getElementById("vdock-refresh").click();
  await settle();
  seen.emptySays = document.querySelector(".vdock-empty")?.textContent;
  window.__VAULT__ = { groups: [], issues: [], shown: 0, total: 5, truncated: false };
  document.getElementById("vdock-refresh").click();
  await settle();
  seen.noMatchSays = document.querySelector(".vdock-empty")?.textContent;

  delete window.__VAULT__;
  delete window.__ASKED_VAULT__;
  vaultDockAnswer = null;
  vaultDockScope = "workspace";
  vaultDockQuery = "";
  box.value = "";
  vaultDockShut.clear();
  vaultDockOpen.clear();
  vaultDockOff.clear();
  vaultDockHideEmpty = false;
  document.getElementById("activity-files-tab").click();
  return seen;
});
ok(
  "the docked session history scans on arrival, scopes the ask, and a card wears turn, age and hands",
  vaultDock.panelShows && vaultDock.tabLit === "true" &&
    Array.isArray(vaultDock.askedScope) &&
    vaultDock.askedScope.length === 1 && vaultDock.askedScope[0] === vaultDock.activePath &&
    vaultDock.sub === "5개 중 2개 표시" &&
    vaultDock.cards === 2 && vaultDock.title === "말한 것 s1" &&
    vaultDock.preview === "에이전트: the last word" &&
    vaultDock.meta.includes("메시지 12개") && vaultDock.meta.includes("5분 전") &&
    vaultDock.meta.includes("claude-fable-5") &&
    vaultDock.bareMeta.includes("3일 전") && !vaultDock.bareMeta.includes("메시지") &&
    vaultDock.noPreview === "대화 미리보기를 사용할 수 없습니다" &&
    vaultDock.groupLabel === "zerocode" && vaultDock.groupCount === "2" &&
    JSON.stringify(vaultDock.acts) === "[2,1]" &&
    vaultDock.hostChip === "Local Mac" &&
    JSON.stringify(vaultDock.twists) === "[1,1]" &&
    JSON.stringify(vaultDock.moreRows) ===
      JSON.stringify(["다시 열기", "명령 복사", "파일 보기"]) &&
    vaultDock.viewRows.includes("모두") && vaultDock.viewRows.includes("Claude (2)") &&
    vaultDock.viewRows.includes("빈 세션 숨기기") &&
    vaultDock.viewRows.includes("보기 초기화") &&
    vaultDock.askedHideEmpty === true &&
    JSON.stringify(vaultDock.askedOff) === JSON.stringify(["claude"]) &&
    Array.isArray(vaultDock.askedAll) && vaultDock.askedAll.length === 0 && vaultDock.allLit &&
    vaultDock.askedQuery === "needle" &&
    vaultDock.detailStands &&
    JSON.stringify(vaultDock.detailActs) === JSON.stringify(["다시 열기", "명령 복사", "파일 보기"]) &&
    JSON.stringify(vaultDock.detailLabels) === JSON.stringify(["첫 프롬프트", "최근 대화", "worktree"]) &&
    JSON.stringify(vaultDock.detailTurns) === JSON.stringify(["user", "user", "assistant"]) &&
    vaultDock.detailWorktree === vaultDock.activePath &&
    vaultDock.detailHeldThroughAct && vaultDock.detailFolded &&
    vaultDock.clearShown && vaultDock.clearedQuery === "" && vaultDock.clearHidden &&
    vaultDock.folded && vaultDock.foldSaid === "false" &&
    vaultDock.emptySays === "agent 세션을 찾을 수 없습니다" &&
    vaultDock.noMatchSays === "현재 필터와 일치하는 세션이 없습니다",
  JSON.stringify(vaultDock),
);

/* ---- the third picture: 실시간 포함 관계 맵 (1-g78c) -------------------------
 *
 * Orca의 `AgentDashboardMapView`: 같은 카드를 상태로도 계보로도 아닌 **자리**로
 * 묶은 중첩 상자 — 프로젝트 ⊃ 작업 공간 ⊃ 에이전트.
 *
 * 카드는 픽스처가 아니라 **진짜 조립**이다: 목이 돌려주는 열은 창이 보낸 카드를
 * 상태로 나눈 것뿐이라(그리고 `show_idle`이면 유휴 열도), 여기서 재는 담김은
 * 창이 탭에서 읽어 낸 프로젝트·체크아웃·호스트 그대로다. 지도가 그 셋을 스스로
 * 다시 찾아 나서면 이 시험이 먼저 무너진다.
 *
 * 재는 것은 여섯이다 — ① 스위치가 셋째 그림을 세우고 칸반을 접고 비우는가,
 * ② 담김이 진짜 중첩된 DOM이고 상자의 수와 그 줄이 말하는 수가 같은가,
 * ③ **유휴가 이 그림에서만 남는가**(칸반은 접는 그 카드), ④ 호스트 칩이 양쪽으로
 * 좁히는가, ⑤ 줌이 표면을 실제로 늘리고 맞춤이 되돌리며 바닥에서 멈추는가,
 * ⑥ 아무것도 남지 않으면 그 문장을 말하는가. */
const boardMapView = await page.evaluate(async () => {
  const settle = () => new Promise((done) => setTimeout(done, 180));
  const seen = {};
  {
    const heldProjects = projects;
    const main = activeWorktreePath;
    const second = "/tmp/zerocode-graph-second";
    projects = [{
      name: "zerocode",
      path: main,
      worktrees: [
        { path: main, branch: "main", is_main: true, active: true, is_folder: false },
        { path: second, branch: "feature/parse", is_main: false, active: false, is_folder: false },
      ],
    }];
    const opened = [];
    const seat = async (where, parent = null) => {
      const term = await openTermTab({ placement: "tab" });
      const tab = tabOfTerm(term);
      if (tab) tab.worktree = where;
      opened.push(term);
      return { term, agent: "claude", state: "working", at: Date.now(), resumable: false, parent };
    };
    const leader = await seat(main);
    const worker = await seat(main, leader.term);
    const other = await seat(second);
    window.__PANES__ = [leader, worker, other];
    window.__ANSWER__.board_columns = (args) => {
      window.__ASKED_BOARD__ = args;
      const wanted = (args.cards ?? []).filter((card) =>
        args.query.query === ""
        || `${card.heading} ${card.worktree} ${card.project}`.includes(args.query.query));
      return [{ bucket: "working", cards: wanted.map((card) => ({
        lineage: { depth: 0, is_first_sibling: true, is_last_sibling: true, child_count: 0 },
        ...card,
      })) }];
    };
    boardQuery = "";
    if (activeTabId === "board") dropTab("board");
    document.getElementById("nav-agents").click();
    await settle();
    const view = [...document.querySelectorAll("#board-view, .file-view")]
      .find((one) => one.querySelector(".agent-graph-layout") && !one.hidden);
    const agentNodes = () => [...view.querySelectorAll(".agent-graph-node.is-agent")];
    const result = {
      // A project is the BAND its workspaces sit in, named on a rail pinned to
      // the left edge of the scroll — not a node in a fourth column.
      projects: [...view.querySelectorAll(".agent-graph-band-name strong")]
        .map((one) => one.textContent),
      workspaces: [...view.querySelectorAll(".agent-graph-node.is-workspace .agent-graph-node-title")]
        .map((one) => one.textContent),
      agents: agentNodes().length,
      spawned: view.querySelectorAll(".agent-graph-edge.is-spawned").length,
      edgesDrawn: [...view.querySelectorAll(".agent-graph-edge")]
        .every((edge) => edge.getAttribute("d")?.startsWith("M ")),
      layers: agentNodes().map((one) => one.style.gridColumn),
    };
    agentNodes().find((node) => node.dataset.graphKey === `agent:term:${leader.term}`)?.click();
    await settle();
    result.inspector = view.querySelector(".agent-inspector-title")?.textContent ?? "";
    result.hasBreadcrumb = view.querySelector(".agent-inspector-breadcrumb") !== null;
    view.querySelector(".agent-graph-band-name")?.click();
    await settle();
    result.hasSummaryCard = view.querySelector(".agent-inspector-summary-card") !== null;
    result.hasFitButton = [...view.querySelectorAll(".agent-inspector-context-actions button")]
      .some((btn) => btn.textContent.includes(t("board.graph.fit", "화면에 맞추기")));
    agentNodes().find((node) => node.dataset.graphKey === `agent:term:${leader.term}`)?.click();
    await settle();
    view.querySelector(".agent-inspector-preview")?.click();
    await settle();
    result.peekTerm = peekTerm;
    closeBoardPeek();
    const query = view.querySelector(".board-query");
    query.value = "없는이름";
    query.dispatchEvent(new Event("input", { bubbles: true }));
    await settle();
    result.empty = view.querySelector(".agent-graph-empty")?.hidden === false;
    result.searchKept = agentNodes().length;
    result.searchDimmed = view.querySelectorAll(
      ".agent-graph-node.is-search-dimmed, .agent-graph-band-head.is-search-dimmed",
    ).length;
    query.value = "";
    query.dispatchEvent(new Event("input", { bubbles: true }));
    await settle();
    delete window.__ANSWER__.board_columns;
    window.__PANES__ = [];
    projects = heldProjects;
    boardQuery = "";
    for (const term of opened) closeTab(termTabId(term));
    await settle();
    return result;
  }
  const heldProjects = projects;
  const main = activeWorktreePath;
  const second = "/tmp/zerocode-map-second";
  const other = "/tmp/zerocode-map-atlas";
  // 두 프로젝트, 그중 하나에 작업 공간 둘. 이 창이 카드의 자리를 읽는 곳은
  // 목록 하나뿐이므로(`projectOfWorktree`·`worktreeAt`) 세우는 곳도 하나다.
  projects = [
    {
      name: "zerocode",
      path: main,
      worktrees: [
        { path: main, branch: "main", is_main: true, active: true, is_folder: false },
        { path: second, branch: "feature/parse", is_main: false, active: false, is_folder: false },
      ],
    },
    {
      name: "atlas",
      path: other,
      worktrees: [
        { path: other, branch: "main", is_main: true, active: false, is_folder: false },
      ],
    },
  ];

  // 다섯 개의 진짜 셸. 자리는 탭이 들고 있는 그 두 필드이고(`worktree`,
  // `remoteHost`), 호스트 축의 스텁도 그 필드다 — SSH 터미널과 원격 워크스페이스가
  // 실제로 적는 바로 그것.
  const opened = [];
  const place = async (where, remote) => {
    const term = await openTermTab({ placement: "tab" });
    const tab = tabOfTerm(term);
    if (tab) {
      tab.worktree = where;
      if (remote) tab.remoteHost = remote;
    }
    opened.push(term);
    return term;
  };
  const busy = await place(main);
  const finished = await place(main);
  const resting = await place(second);
  const away = await place(other);
  const remote = await place("ssh://deploy@srv:22", "srv-1");
  window.__PANES__ = [
    { term: busy, agent: "claude", state: "working", at: 4, resumable: false },
    { term: finished, agent: "claude", state: "done", at: 3, resumable: false },
    { term: resting, agent: "codex", state: "idle", at: 2, resumable: false },
    { term: away, agent: "claude", state: "working", at: 1, resumable: false },
    { term: remote, agent: "codex", state: "working", at: 5, resumable: false },
  ];
  // `zerocode_core::board::columns`의 두 규칙만 세운 대역: 검색·프로젝트로
  // 좁히고, 유휴 열은 `show_idle`일 때만 돌려준다. 카드 자체는 창이 보낸 것을
  // 그대로 되돌려 준다 — 이 시험이 보는 것은 그 조립이다.
  window.__ANSWER__.board_columns = (args) => {
    window.__ASKED_BOARD__ = args;
    const bucketOf = (card) =>
      card.state === "idle" ? "idle" : card.state === "done" ? "done" : "working";
    const wanted = (args.cards ?? []).filter((card) =>
      (args.query.projects.length === 0 || args.query.projects.includes(card.project))
      && (args.query.query === ""
        || `${card.heading} ${card.worktree}`.includes(args.query.query)));
    return (args.query.show_idle ? ["working", "done", "idle"] : ["working", "done"]).map(
      (bucket) => ({
        bucket,
        cards: wanted.filter((card) => bucketOf(card) === bucket).map((card) => ({
          lineage: { depth: 0, is_first_sibling: true, is_last_sibling: true, child_count: 0 },
          ...card,
        })),
      }),
    );
  };
  boardQuery = "";
  boardShowIdle = false;
  boardMode = "board";
  boardMapHost = "all";
  boardMapZoom = 1;
  if (activeTabId === "board") dropTab("board");
  document.getElementById("nav-agents").click();
  await settle();

  const view = () => [...document.querySelectorAll("#board-view, .file-view")]
    .find((one) => one.querySelector(".agent-graph-layout") && !one.hidden) ?? null;
  const columns = () => view()?.querySelector(".board-columns") ?? null;
  const surface = () => view()?.querySelector(".board-map") ?? null;
  const canvas = () => surface()?.querySelector(".board-map-canvas") ?? null;
  const boxes = () => [...(canvas()?.querySelectorAll(".board-map-project") ?? [])];
  const tiles = () =>
    [...(canvas()?.querySelectorAll(".board-map-agent") ?? [])].map((one) => one.dataset.pane);
  const named = (host, selector, name) =>
    [...(host?.querySelectorAll(selector) ?? [])].find(
      (one) => one.querySelector(`${selector}-name`)?.textContent === name) ?? null;
  const chip = (kind) => surface()?.querySelector(`[data-map-host="${kind}"]`) ?? null;

  // ① 스위치. 셋 중 하나만 서고, 물러난 그림은 비워진다.
  seen.columnsFirst = columns()?.hidden === false;
  seen.mapFirst = surface()?.hidden === true;
  view()?.querySelector('[data-board-mode="map"]')?.click();
  await settle();
  seen.mapShown = surface()?.hidden === false;
  seen.columnsHidden = columns()?.hidden === true;
  seen.columnsEmptied = columns()?.childElementCount ?? -1;
  seen.modeLit = view()?.querySelector('[data-board-mode="map"]')?.getAttribute("aria-pressed");
  seen.canvasSays = canvas()?.getAttribute("aria-label") ?? "";
  seen.titleSays = surface()?.querySelector(".board-map-title")?.textContent ?? "";

  // ② 담김. 상자 안의 상자 안의 칸이고, 줄이 말하는 수는 그려진 수다.
  seen.projectNames = boxes().map(
    (one) => one.querySelector(".board-map-project-name")?.textContent ?? "");
  const here = named(canvas(), ".board-map-project", "zerocode");
  seen.hereCount =
    here?.querySelector(".board-map-project-head .board-map-count")?.textContent ?? "";
  seen.hereSpaces = [...(here?.querySelectorAll(".board-map-space") ?? [])].map(
    (one) => one.querySelector(".board-map-space-name")?.textContent ?? "");
  const home = named(here, ".board-map-space", "main");
  seen.homeCount = home?.querySelector(".board-map-count")?.textContent ?? "";
  seen.homeTiles = [...(home?.querySelectorAll(".board-map-agent") ?? [])].map(
    (one) => one.dataset.pane);
  // 중첩은 클래스가 아니라 **포함 관계**다: 칸은 작업 공간 상자 안에 있고, 그
  // 상자는 프로젝트 상자 안에 있다.
  const deep = home?.querySelector(".board-map-agents .board-map-agent") ?? null;
  seen.nested = deep !== null && here !== null
    && here.contains(deep) && deep.closest(".board-map-space") === home;
  // 그리고 자리를 모르는 셸은 상자를 짓지 않고 상자들 뒤에 그대로 선다.
  seen.looseTiles = [...(canvas()?.querySelectorAll(".board-map-loose .board-map-agent") ?? [])]
    .map((one) => one.dataset.pane);
  // 칸을 누르면 카드가 여는 그 문이 열린다 — 같은 `openBoardCard`, 같은 미리보기.
  canvas()?.querySelector(`.board-map-agent[data-pane="term:${busy}"]`)?.click();
  await settle();
  seen.peekOpened = document.getElementById("peek-scrim")?.hidden === false;
  seen.peekTerm = peekTerm;
  document.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
  await settle();

  // ②b 상자 머리는 문이다(실측 WorktreeDetails: 에이전트 행들 + "새 에이전트
  // 시작" 목록, 각 시작 행이 +를 입는다). 시작은 launch_agent_tab의 그 길.
  const heldAgents = agentRows;
  agentRows = [{ id: "claude", name: "Claude Code", installed: true }];
  window.__ANSWER__.launch_agent_tab = (args) => {
    seen.spawnAsked = args.agent;
    return 7777;
  };
  home?.querySelector(".board-map-space-head")?.click();
  await settle();
  const spacePop = document.getElementById("board-map-space-pop");
  const popRows = [...(spacePop?.querySelectorAll(".note-pop-row") ?? [])];
  seen.popStands = spacePop?.hidden === false &&
    popRows.length === 3 &&
    spacePop?.querySelector(".board-map-pop-spawn") !== null &&
    popRows.at(-1)?.querySelector("use")?.getAttribute("href") === "#i-plus";
  popRows.at(-1)?.click();
  await settle();
  seen.spawnTravels = seen.spawnAsked === "claude" &&
    spacePop?.hidden === true && tabOfTerm(7777) !== undefined;
  closeTab(termTabId(7777));
  agentRows = heldAgents;
  delete window.__ANSWER__.launch_agent_tab;
  await settle();

  // ③ 유휴는 이 그림에서만 남는다.
  seen.mapAskedIdle = window.__ASKED_BOARD__?.query?.show_idle;
  seen.idleDrawn = tiles().includes(`term:${resting}`);
  seen.mapTiles = tiles().length;

  // ④ 호스트 축. SSH만, 그리고 로컬만 — 양쪽으로 좁힌다.
  chip("ssh")?.click();
  await settle();
  seen.sshTiles = tiles();
  seen.sshLit = chip("ssh")?.getAttribute("aria-pressed");
  seen.sshBoxes = boxes().length;
  chip("local")?.click();
  await settle();
  seen.localTiles = tiles();
  seen.localHasRemote = tiles().includes(`term:${remote}`);
  chip("all")?.click();
  await settle();
  seen.allTiles = tiles().length;

  // ⑤ 줌. 잰 폭으로 — 스타일 문자열만 보면 변환이 그려지지 않아도 통과한다.
  const scaleOf = () => {
    const drawn = canvas() ? getComputedStyle(canvas()).transform : "none";
    if (drawn === "none") return 1;
    const parts = /matrix\(([^,]+),/.exec(drawn);
    return parts ? Number.parseFloat(parts[1]) : 0;
  };
  seen.scaleBase = scaleOf();
  seen.widthBase = canvas()?.getBoundingClientRect().width ?? 0;
  surface()?.querySelector(".board-map-in")?.click();
  await settle();
  seen.scaleBigger = scaleOf();
  seen.widthBigger = canvas()?.getBoundingClientRect().width ?? 0;
  surface()?.querySelector(".board-map-fit")?.click();
  await settle();
  seen.scaleFit = scaleOf();
  // 그리고 바닥에서 멈춘다 — 0.5 밑으로 더 눌러도 그대로다.
  for (let press = 0; press < 4; press += 1) {
    surface()?.querySelector(".board-map-out")?.click();
    await settle();
  }
  seen.scaleFloor = scaleOf();
  surface()?.querySelector(".board-map-fit")?.click();
  await settle();

  // ⑥ 좁혀서 아무것도 남지 않으면, 그 문장.
  const query = view()?.querySelector(".board-query") ?? null;
  if (query) {
    query.value = "없는이름";
    query.dispatchEvent(new Event("input", { bubbles: true }));
  }
  await settle();
  seen.emptySays = canvas()?.querySelector(".board-map-none")?.textContent ?? "";
  seen.emptyTiles = tiles().length;
  if (query) {
    query.value = "";
    query.dispatchEvent(new Event("input", { bubbles: true }));
  }
  await settle();

  // ③의 나머지 반쪽 — 칸반으로 돌아오면 그 유휴 카드는 다시 접힌다.
  view()?.querySelector('[data-board-mode="board"]')?.click();
  await settle();
  seen.boardAskedIdle = window.__ASKED_BOARD__?.query?.show_idle;
  seen.boardPanes = [...(view()?.querySelectorAll(".board-card") ?? [])].map(
    (one) => one.dataset.pane);
  seen.mapEmptiedOnLeave = canvas()?.childElementCount ?? -1;

  seen.panes = { busy, resting, remote };
  delete window.__ANSWER__.board_columns;
  window.__PANES__ = [];
  window.__COLUMNS__ = [];
  projects = heldProjects;
  boardMapHost = "all";
  boardMapZoom = 1;
  boardQuery = "";
  for (const term of opened) closeTab(termTabId(term));
  await settle();
  return seen;
});
ok(
  "the ontology graph connects projects, workspaces and spawned agents, then acts in one inspector",
  boardMapView.projects.join("|") === "zerocode" &&
    // Top to bottom, which is the order the graph draws them in.
    boardMapView.workspaces.join("|") === "feature/parse|main" &&
    boardMapView.agents === 3 && boardMapView.spawned === 1 && boardMapView.edgesDrawn &&
    new Set(boardMapView.layers).size === 2 &&
    boardMapView.inspector !== "" && boardMapView.peekTerm !== null && !boardMapView.empty &&
    boardMapView.searchKept === 3 && boardMapView.searchDimmed > 0 &&
    boardMapView.hasSummaryCard && boardMapView.hasBreadcrumb && boardMapView.hasFitButton,
  JSON.stringify(boardMapView),
);

/* ---- 대시보드 헤더 (1-g92c) — 실측 AgentKanbanBoard:397~425 ----
 *
 * h1이 먼저 서고, 토글은 role=group의 aria-pressed 버튼들이 아이콘을 입는다.
 * ⌘K는 보드 검색으로 손을 옮기되 글자를 받는 자리(터미널 포함) 위에서는
 * 비켜선다 — 터미널의 ⌘K는 화면 지우기라는 선약이 있다. */
const boardHeader = await page.evaluate(async () => {
  const settle = () => new Promise((done) => setTimeout(done, 120));
  const seen = {};
  if (activeTabId === "board") dropTab("board");
  document.getElementById("nav-agents").click();
  await settle();
  const view = [...document.querySelectorAll("#board-view, .file-view")]
    .find((one) => one.querySelector(".agent-graph-layout") && !one.hidden) ?? null;
  seen.headingSays = view?.querySelector("h1.board-title")?.textContent
    === t("board.graph.heading", "에이전트 그래프");
  const summary = view?.querySelector(".agent-graph-summary") ?? null;
  seen.groupSpeaks = summary?.getAttribute("role") === "group"
    && summary?.getAttribute("aria-label") === t("board.graph.summary", "에이전트 상태 요약");
  seen.summaryCount = summary?.querySelectorAll("[data-graph-bucket]").length ?? 0;
  seen.activeMode = view?.querySelector('[data-board-mode][aria-pressed="true"]')?.dataset.boardMode;

  // ⌘K — 검색으로. 터미널 위에서는 조용히.
  const query = view?.querySelector(".board-query") ?? null;
  query?.blur();
  document.dispatchEvent(new KeyboardEvent("keydown",
    { key: "k", metaKey: true, ctrlKey: true, bubbles: true, cancelable: true }));
  await settle();
  seen.cmdKFocuses = document.activeElement === query;
  query?.blur();
  const term = document.querySelector(".term");
  term?.dispatchEvent(new KeyboardEvent("keydown",
    { key: "k", metaKey: true, ctrlKey: true, bubbles: true, cancelable: true }));
  await settle();
  seen.cmdKYieldsToTerm = document.activeElement !== query;
  return seen;
});
ok(
  "the relations header selects its mode, retains status actions, and ⌘K reaches search",
  boardHeader.headingSays && boardHeader.groupSpeaks && boardHeader.summaryCount === 3 &&
    boardHeader.activeMode === "graph" &&
    boardHeader.cmdKFocuses && boardHeader.cmdKYieldsToTerm,
  JSON.stringify(boardHeader),
);

/* The board is one ontology rather than a bag of dashboard widgets. Project,
 * checkout, agent and spawned agent are the nodes; containment and lineage are
 * the only edges; all agent surfaces share five state words. The information
 * hierarchy below pins the compact card and the long inspector at the same
 * time, including the two regressions that are easiest to miss visually:
 * "running" accidentally counting tool calls instead of runs, and a stale
 * tool error becoming the headline of an agent that is currently working. */
/* 이 판의 그림을 파일로 남기는 문 (t-1853). 켤 때만 열린다:
 *
 *   CAPTURE_AGENT_BOARD=1 CAPTURE_AGENT_BOARD_PATH=<png> node ui/tests/window.mjs
 *
 * 그림의 증거는 렌더된 픽셀이라고 온톨로지 문서가 못 박아 두었는데, 여태 그
 * 픽셀은 손으로 띄운 창에서 나왔다 — 그래서 before/after에 온보딩 코치마크가
 * 얹혀 찍혔다. 시험이 이미 세우는 이 합성 모델이 그 그림의 정본이다. */
const captureAgentBoard = process.env.CAPTURE_AGENT_BOARD === "1";
const captureAgentBoardOnly = process.env.CAPTURE_AGENT_BOARD_ONLY === "1";
if (captureAgentBoard) {
  const width = Number(process.env.CAPTURE_AGENT_BOARD_WIDTH) || 1998;
  const height = Number(process.env.CAPTURE_AGENT_BOARD_HEIGHT) || 1069;
  await page.setViewportSize({ width, height });
}
