  window.__ANSWER__.gitlab_update_mr = (args) => (asked.update.push(args), null);
  window.__ANSWER__.gitlab_merge_mr = (args) => (asked.merge.push(args), null);
  gitlabStatusLoaded = false;
  taskGitlabView = "mrs";
