const treeDoors = await page.evaluate(async () => {
  const seen = {};
  // P0-15의 남은 세 문: 파일 보기 = 행 클릭과 같은 문(원본 onViewFile은
  // 행의 handleClick), 로컬 파일의 file:// 브라우저 탭, 그리고 열린
  // 폴더에만 서는 서브트리 접기(shouldShowCollapseFolderAction:
  // isDirectory && isExpanded — 접힌 폴더에는 문이 없다).
  window.__ANSWER__.list_dir = (args) =>
    args.path === ""
      ? [
        { name: "src", is_dir: true },
        { name: "notes.md", is_dir: false },
      ]
      : [{ name: "inner", is_dir: true }];
  const reads = [];
  window.__ANSWER__.read_text_file = (args) =>
    (reads.push(args.path), { text: "x", version: "1" });
  const stood = [];
  window.__ANSWER__.open_browser_pane = (args) => (stood.push(args.url), "browser-td1");
  window.__ANSWER__.browser_place = () => null;
  window.__ANSWER__.browser_navigate = () => null;
  await loadTree(el("file-tree"), "");
  const rowAt = (word) =>
    [...document.querySelectorAll("#file-tree .tree-row")].find(
      (row) => row.querySelector(".tree-name")?.textContent === word,
    );
  const pick = async (row, label) => {
    row.dispatchEvent(
      new MouseEvent("contextmenu", { bubbles: true, cancelable: true, clientX: 40, clientY: 40 }),
    );
    const item = [...el("sidebar-menu").querySelectorAll(".sidebar-menu-item")].find(
      (one) => one.querySelector(".sidebar-menu-label")?.textContent === label,
    );
    if (!item) {
      closeSidebarMenu();
      return false;
    }
    item.click();
    await new Promise((done) => setTimeout(done, 30));
    return true;
  };
  const file = rowAt("notes.md");
  await pick(file, t("tree.menu.viewFile", "파일 보기"));
  seen.viewOpensTheRow = reads.some((one) => one.endsWith("notes.md"));
  await pick(file, t("tree.menu.openInBrowser", "ZeroCode 브라우저에서 열기"));
  seen.browserGetsFileUrl = stood.at(-1) === `file://${activeWorktreePath}/notes.md`;
  const dir = rowAt("src");
  seen.foldedOffersNoCollapse =
    (await pick(dir, t("tree.menu.collapseFolder", "폴더 접기"))) === false;
  await dir._treeUnfold(true);
  await new Promise((done) => setTimeout(done, 30));
  const inner = rowAt("inner");
  await inner._treeUnfold(true);
  await new Promise((done) => setTimeout(done, 30));
  await pick(dir, t("tree.menu.collapseFolder", "폴더 접기"));
  seen.collapseFoldsSubtree =
    dir.getAttribute("aria-expanded") === "false" &&
    inner.getAttribute("aria-expanded") === "false" &&
    dir.nextElementSibling.hidden === true;
  closeTab("browser:browser-td1");
  // read_text_file 스텁은 남긴다 — 열린 문서의 신선도 재읽기가 이 블록
  // 뒤에도 올 수 있고, 걷힌 스텁의 null에서 .text를 꺼내면 창의 에러
  // 게이트가 운다(fs_* 스텁을 남기는 위 블록들과 같은 관용).
  for (const name of ["open_browser_pane", "browser_place", "browser_navigate"]) {
    delete window.__ANSWER__[name];
  }
  return seen;
});
ok(
  "the tree's last three doors — view, a file:// browser tab, and a fold only an open folder offers",
  treeDoors.viewOpensTheRow &&
    treeDoors.browserGetsFileUrl &&
    treeDoors.foldedOffersNoCollapse &&
    treeDoors.collapseFoldsSubtree,
  JSON.stringify(treeDoors),
);

