  const writesBefore = window.__UI_ZOOM_WRITES__.length;
  document.dispatchEvent(
    new KeyboardEvent("keydown", {
      key: "=", code: "Equal", metaKey: true, bubbles: true, cancelable: true,
    }),
  );
  await new Promise((done) => setTimeout(done, 30));
