const tokensScreen = await page.evaluate(async (fixture) => {
  const seen = {};
  window.__ANSWER__.claude_token_usage = (args) => {
    seen.askedOffset = args.offsetMinutes;
    return fixture.claude;
  };
  openTokensTab();
  await new Promise((done) => setTimeout(done, 200));
  const tab = tabs.find((one) => one.id === "tokens");
  seen.opened = Boolean(tab) && activeTabId === "tokens";
  // 창이 자기 자정을 넘겼는가 — 하루는 사람의 단위다.
  seen.offsetSent = seen.askedOffset === -new Date().getTimezoneOffset();
  // 기본 구간은 30일이고 픽스처는 그보다 오래된 날짜다 — 이 판을 재려면
  // 전체 기간으로 열어야 한다. 필터가 디스크를 다시 걷지 않는다는 것도
  // 여기서 처음 확인된다.
  const reads = () => window.__COUNTS__.claude_token_usage ?? 0;
  const before = reads();
  setTokensRange(tab, "all");
  setTokensScope(tab, "all");
  seen.noReReadOnFilter = reads() === before;
  const view = document.querySelector("#tokens-view");
  // 판이 실제로 보이는가. `querySelector` 는 숨은 판도 찾아 준다 — worker 판이
  // 그렇게 세 번의 신고를 지나갔다.
  seen.onScreen = Boolean(view && !view.hidden && view.offsetParent !== null);
  const cards = [...view.querySelectorAll(".tokens-card")];
  seen.cardCount = cards.length;
  const cardSaid = (word) => cards
    .find((one) => one.querySelector(".tokens-card-label").textContent === word)
    ?.querySelector(".tokens-card-value").textContent ?? "";
  seen.wantReuse = t("tokens.cacheReuse", "캐시 재사용률");
  seen.wantCold = t("tokens.coldMessages", "캐시 미사용 메시지");
  seen.wantPair = t("tokens.sessionsMessages", "대화 / 메시지");
  seen.wantCost = t("tokens.estimatedCost", "추정 비용");
  // 3005 / (1015 + 3005) = 74.75% → 75%
  seen.reuseSaid = cardSaid(seen.wantReuse);
  // 캐시를 안 읽은 메시지 셋 / 일곱 = 42.86% → 43%
  seen.coldSaid = cardSaid(seen.wantCold);
  seen.pairSaid = cardSaid(seen.wantPair);
  seen.costSaid = cardSaid(seen.wantCost);
  // 금액이 추정치라고 말하는가 — 구독은 토큰당 청구가 아니다.
  seen.saysEstimate = (view.querySelector(".tokens-note")?.textContent ?? "").length > 0;
  const quiet = [...view.querySelectorAll(".tokens-quiet")].map((one) => one.textContent).join(" | ");
  seen.saysUnpriced = quiet.includes("<synthetic>");
  seen.saysUndated = quiet.includes("3");
  // 목록에서 잘려 나간 대화가 있으면 그 말도 한다(본 것 5, 실은 것 3).
  seen.saysLeftOut = quiet.includes(t("tokens.sessionsLeftOut", "오래된 대화 {{count}}개는 목록에서 뺐습니다", { count: 2 }));
  seen.status = view.querySelector(".tokens-status")?.textContent ?? "";
  delete window.__ANSWER__.claude_token_usage;
  for (const one of [...tabs]) dropTab(one.id);
  return seen;
}, tokensFixture());
