  // 막는 유일한 핀이다.
  const slice = tokensSlice(held, TOKEN_PROVIDERS[0], "all", "all");
  seen.sameInput = slice.sum.input === held.total.input;
  seen.sameOutput = slice.sum.output === held.total.output;
  seen.sameCacheRead = slice.sum.cacheRead === held.total.cache_read;
  seen.sameCacheWrite = slice.sum.cacheWrite === held.total.cache_create;
  seen.sameCost = Math.abs(slice.sum.cost - held.cost_usd) < 1e-9;
  seen.sameUnpriced = slice.unpriced.join(",") === held.unpriced.join(",");
