  seen.recentRows = recent.querySelectorAll("tbody tr").length;
  setTokensScope(tab, "ours");
  const mine = [...view.querySelectorAll(".tokens-table")][2];
  seen.oursRows = mine.querySelectorAll("tbody tr").length;
