    await tick();
    seen.noAssetStatus = document.getElementById("update-status").textContent
      === t("settings.update.status.noAssetForPlatform", "이 플랫폼의 자산이 아직 없습니다.");
    window.__ANSWER__.update_check = () => report({ phase: "nothing_published" });
    document.getElementById("update-check-now").click();
    await tick();
    seen.nothingStatus = document.getElementById("update-status").textContent
      === t("settings.update.status.nothingPublished", "아직 공개된 버전이 없습니다.");
    window.__ANSWER__.update_check = () => report({ phase: "dev_build", reason: "unstamped" });
    document.getElementById("update-check-now").click();
