/* 판의 대화 뷰 (2026-09-15 승인 디자인): 탭 줄 오른쪽 세그먼트가 활성 에이전트
 * 판의 화면과 대화를 같은 슬롯 안에서 바꾼다. pty와 탭은 그대로, 숨은 쪽은
 * 그리지 않고(hidden), 턴은 판 자신의 전사(`pane_log`)에서 오며, 프로그램이
 * 화면에 물음을 띄우면(needs-attention) 화면이 돌아온다. 에이전트가 없는
 * 판에는 토글이 없다. */
/* The composer's chips and its `/` palette (unit 5 of the Claude Code
 * grammar): the agent chip opens the model menu and a pick walks the CLI's
 * own road; the permission chip reads the hook's word and cycles with the
 * CLI's own key; `/` opens the palette the CLI itself would show, from the
 * window's catalog road, with the source named on its head. */
suite("composer-chips", async ({ browser, origin, ok }) => {
  const { page } = await openWindowTestPage(browser, origin);
  try {
    const seen = await page.evaluate(async () => {
      const tell = (name, payload) => {
        for (const handler of window.__LISTENERS__[name] ?? []) handler({ payload });
      };
      const settle = (ms = 60) => new Promise((done) => setTimeout(done, ms));
      const seen = {};
      const calls = [];
      window.__ANSWER__.term_paste = (args) => (calls.push(["paste", args.term, args.text]), null);
      window.__ANSWER__.term_key = (args) => (calls.push(["key", args.term, args.press.key, args.press.shift === true]), null);
      window.__ANSWER__.agent_models = (args) => args.agent === "claude"
        ? [{ id: "claude-fable-5-1", display_name: "Fable 5.1", provider: "claude" },
           { id: "claude-opus-5", display_name: "Opus 5", provider: "claude" }]
        : [{ id: "gpt-6-astra", display_name: "GPT-6-Astra", provider: "openai" }];
      let asked = [];
      window.__ANSWER__.slash_commands = (args) => {
        asked.push(args);
        return {
          agent: args.agent, source: args.agent === "claude" ? "session" : "docs",
          version: args.agent === "claude" ? "2.1.272" : "0.154.0",
          commands: [
            { name: "/compact", about: "Free up context by summarizing the conversation", args: "[instructions]", kind: "builtin" },
            { name: "/context", about: "Visualize current context usage", kind: "builtin" },
            { name: "/codex:review", about: "Review with Codex", kind: "plugin" },
            { name: "/clear", about: "Start a new session", kind: "builtin" },
          ],
        };
      };
      // A Claude pane wearing its conversation, its model and mode from the hook.
      // At REST between turns: what a composer says and does while a turn is
      // out is the queue's business (`composer-queue`), and a box that says
      // 「대기열에 추가」 would hide the two words this suite is about.
      const term = await openTermTab({ placement: "tab" });
      tell("hook:agent", { term, state: "idle", agent: "claude", session: "s-chips", resumable: false, model: "claude-fable-5-1", permission_mode: "bypassPermissions" });
      await window.__PAINTED__();
      window.__ANSWER__.pane_log = () => ({ found: true, next: 2, turns: [
        { role: "user", text: "hi" }, { role: "assistant", text: "hello" },
      ] });
      el("view-toggle-chat").click();
      await settle(150);
      const chat = document.querySelector(`.pane-slot[data-term="${term}"] .pane-chat`);
      const composer = chat?.querySelector(".worker-composer");
      const box = composer?.querySelector(".worker-composer-box");
      seen.placeholder = box?.placeholder;
      seen.wantPlaceholder = t("worker.sayTo", "{{name}}에게 보내기…", { name: agentName("claude") });
      seen.noDoorOnOwnPane = composer?.querySelector(".worker-composer-door") === null;
      // The tool row, left to right: + · agent chip · mode chip … / · send.
      const tools = composer?.querySelector(".worker-composer-tools");
      seen.rowOrder = [...(tools?.children ?? [])].map((node) => node.className.split(" ").pop());
      // The agents pill stands in the row but says nothing while no helper
      // is out — it is the roster's count, not a permanent chip.
      seen.agentsPillQuiet = composer?.querySelector(".worker-composer-agents")?.hidden === true;
      const agentChip = composer?.querySelector(".worker-composer-agent");
      seen.chipMark = agentChip?.querySelector(".worker-composer-mark")?.textContent;
      seen.chipName = agentChip?.querySelector(".worker-composer-pill-words")?.textContent;
      seen.chipModelRaw = agentChip?.querySelector(".worker-composer-model-words")?.textContent;
      const modeChip = composer?.querySelector(".worker-composer-mode");
      seen.modeShown = modeChip ? !modeChip.hidden : false;
      seen.modeWords = modeChip?.querySelector(".worker-composer-pill-words")?.textContent;
      // The menu: models (current ticked, display names) and the other CLIs.
      agentChip?.click();
      await settle(120);
      const menu = composer?.querySelector(".composer-menu");
      seen.menuOpen = Boolean(menu) && agentChip?.getAttribute("aria-expanded") === "true";
      seen.menuModels = [...(menu?.querySelectorAll(".composer-menu-item") ?? [])]
        .map((row) => `${row.querySelector(".composer-menu-name")?.textContent}${row.getAttribute("aria-current") === "true" ? "*" : ""}`);
      seen.chipModelNamed = agentChip?.querySelector(".worker-composer-model-words")?.textContent;
      // A pick: the CLI takes the id, so `/model <id>` travels the send road.
      const opus = [...menu.querySelectorAll(".composer-menu-item")].find((row) => row.querySelector(".composer-menu-name")?.textContent === "Opus 5");
      opus?.click();
      await settle(700);
      seen.modelSent = JSON.stringify(calls.slice(-2));
      seen.wantModelSent = JSON.stringify([["paste", term, "/model claude-opus-5"], ["key", term, "Enter", false]]);
      seen.menuClosed = composer?.querySelector(".composer-menu") === null;
      // The mode chip cycles with the CLI's own key.
      modeChip?.click();
      await settle(30);
      seen.modeKey = JSON.stringify(calls.at(-1));
      seen.wantModeKey = JSON.stringify(["key", term, "Tab", true]);
      // Another CLI opens a fresh pane in the same checkout.
      agentChip?.click();
      await settle(120);
      const codexRow = [...composer.querySelectorAll(".composer-menu-item")].find((row) => row.querySelector(".composer-menu-name")?.textContent === "Codex");
      window.__LAUNCHED__ = null;
      codexRow?.click();
      await settle(80);
      seen.launched = window.__LAUNCHED__?.agent ?? null;
      // The palette: `/` shows the CLI's list with its source on the head,
      // filters as typed, and Enter runs the highlighted command.
      box.value = "/";
      box.dispatchEvent(new Event("input", { bubbles: true }));
      await settle(120);
      const pane = composer.querySelector(".composer-slash");
      seen.paletteShown = pane ? !pane.hidden : false;
      seen.paletteHead = pane?.querySelector(".composer-slash-head")?.textContent;
      seen.wantHead = `${agentName("claude")} 2.1.272 · ${t("composer.slash.sourceSession", "이 세션")}`;
      seen.paletteRows = [...(pane?.querySelectorAll(".composer-slash-row .composer-slash-name") ?? [])].map((n) => n.textContent);
      seen.copyAbout = [...(pane?.querySelectorAll(".composer-slash-row") ?? [])]
        .find((row) => row.querySelector(".composer-slash-name")?.textContent === "/copy")
        ?.querySelector(".composer-slash-about")?.textContent ?? null;
      seen.wantCopyAbout = t("composer.slash.copy", "마지막 답을 클립보드에 복사한다");
      seen.askedCwd = asked[0]?.cwd ?? null;
      seen.wantCwd = tabOfTerm(term)?.worktree ?? null;
      box.value = "/co";
      box.dispatchEvent(new Event("input", { bubbles: true }));
      await settle(30);
      seen.filtered = [...pane.querySelectorAll(".composer-slash-row .composer-slash-name")].map((n) => n.textContent);
      seen.hot = pane.querySelector(".composer-slash-row.is-hot .composer-slash-name")?.textContent;
      // A word inside the name matches too (`codex:review` by `rev`).
      box.value = "/rev";
      box.dispatchEvent(new Event("input", { bubbles: true }));
      await settle(30);
      seen.innerWord = [...pane.querySelectorAll(".composer-slash-row .composer-slash-name")].map((n) => n.textContent);
      // A typo lists nothing and says so in the window's words.
      box.value = "/zzz";
      box.dispatchEvent(new Event("input", { bubbles: true }));
      await settle(30);
      seen.none = pane.querySelector(".composer-slash-none")?.textContent;
      seen.wantNone = t("composer.slash.none", "「/{{typed}}」에 맞는 명령이 없습니다", { typed: "zzz" });
      // Arrow keys move the highlight; Tab fills without sending; Enter runs.
      box.value = "/c";
      box.dispatchEvent(new Event("input", { bubbles: true }));
      await settle(30);
      const press = (key, init = {}) => box.dispatchEvent(new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true, ...init }));
      press("ArrowDown");
      seen.hotAfterDown = pane.querySelector(".composer-slash-row.is-hot .composer-slash-name")?.textContent;
      const before = calls.length;
      press("Tab");
      seen.tabFilled = box.value;
      seen.tabSentNothing = calls.length === before;
      seen.paletteClosedAfterTab = pane.hidden;
      // `/clear` takes no argument: Enter on it runs it through the send road.
      box.value = "/cle";
      box.dispatchEvent(new Event("input", { bubbles: true }));
      await settle(30);
      press("Enter");
      await settle(700);
      seen.enterRan = JSON.stringify(calls.slice(-2));
      seen.wantEnterRan = JSON.stringify([["paste", term, "/clear"], ["key", term, "Enter", false]]);
      seen.boxClearedAfterRun = box.value === "";
      // The window's own command only fills the box.
      box.value = "/art";
      box.dispatchEvent(new Event("input", { bubbles: true }));
      await settle(30);
      const artifactRow = pane.querySelector('.composer-slash-row[data-kind="window"]');
      seen.artifactListed = artifactRow?.querySelector(".composer-slash-name")?.textContent;
      const sentBefore = calls.length;
      press("Enter");
      await settle(30);
      seen.artifactFilled = box.value.startsWith(t("artifacts.newDraft", "HTML").slice(0, 8)) && calls.length === sentBefore;
      box.value = "";
      box.dispatchEvent(new Event("input", { bubbles: true }));
      // `/copy` acts where it stands: the last answer to the clipboard, the
      // box emptied, and nothing sent to the CLI (2.1.275).
      window.__CLIPBOARD_WRITES__.length = 0;
      box.value = "/cop";
      box.dispatchEvent(new Event("input", { bubbles: true }));
      await settle(30);
      const copiedBefore = calls.length;
      press("Enter");
      await settle(60);
      seen.copied = window.__CLIPBOARD_WRITES__.at(-1) ?? null;
      seen.copySentNothing = calls.length === copiedBefore;
      seen.copyClearedBox = box.value === "";
      // A Codex pane: its picker lives on its own screen, so a pick sends the
      // bare command and turns the pane back to its terminal.
      const codexTerm = await openTermTab({ placement: "tab" });
      tell("hook:agent", { term: codexTerm, state: "working", agent: "codex", session: "s-codex", resumable: false, model: "gpt-6-astra" });
      await window.__PAINTED__();
      el("view-toggle-chat").click();
      await settle(150);
      const codexChat = document.querySelector(`.pane-slot[data-term="${codexTerm}"] .pane-chat`);
      const codexChip = codexChat?.querySelector(".worker-composer-agent");
      codexChip?.click();
      await settle(120);
      const astra = [...(codexChat?.querySelectorAll(".composer-menu-item") ?? [])].find((row) => row.querySelector(".composer-menu-name")?.textContent === "GPT-6-Astra");
      astra?.click();
      await settle(700);
      seen.codexPick = JSON.stringify(calls.slice(-2));
      seen.wantCodexPick = JSON.stringify([["paste", codexTerm, "/model"], ["key", codexTerm, "Enter", false]]);
      seen.codexScreenBack = paneChatOn(codexTerm) === false;
      // The palette head names a documented list as such.
      seen.codexHead = null;
      el("view-toggle-chat").click();
      await settle(150);
      const codexBox = codexChat?.querySelector(".worker-composer-box");
      if (codexBox) { codexBox.value = "/"; codexBox.dispatchEvent(new Event("input", { bubbles: true })); }
      await settle(120);
      seen.codexHead = codexChat?.querySelector(".composer-slash-head")?.textContent ?? null;
      seen.wantCodexHead = `${agentName("codex")} 0.154.0 · ${t("composer.slash.sourceDocs", "문서 기준")}`;
      // A helper's page keeps the door to its parent and speaks of the parent.
      const owner = tabOfTerm(term);
      tell("hook:subagent", { term, rows: [{ id: "helper-1", name: "@helper", state: "done" }] });
      window.__ANSWER__.subagent_log = () => ({ found: true, next: 1, turns: [{ role: "user", text: "go" }] });
      await openHelperPage({ term, agent: "claude", worktree: owner.worktree, tab: owner }, { id: "helper-1", name: "@helper", state: "done" });
      await settle(120);
      const helperComposer = document.querySelector("#worker-view .worker-composer");
      seen.helperDoor = Boolean(helperComposer?.querySelector(".worker-composer-door"));
      seen.helperPlaceholder = helperComposer?.querySelector(".worker-composer-box")?.placeholder;
      seen.wantHelperPlaceholder = t("worker.say", "부모 에이전트에게 보내기…");
      // A page nobody has been answered on does not list `/copy` — a row
      // that would do nothing when it is pressed is not drawn at all.
      const helperBox = helperComposer?.querySelector(".worker-composer-box");
      if (helperBox) { helperBox.value = "/"; helperBox.dispatchEvent(new Event("input", { bubbles: true })); }
      await settle(120);
      const helperRows = [...document.querySelectorAll("#worker-view .composer-slash-row .composer-slash-name")]
        .map((one) => one.textContent);
      seen.helperRows = helperRows;
      seen.copyUnlisted = helperRows.length > 0 && !helperRows.includes("/copy");
      delete window.__ANSWER__.term_paste; delete window.__ANSWER__.term_key;
      delete window.__ANSWER__.agent_models; delete window.__ANSWER__.slash_commands;
      delete window.__ANSWER__.pane_log; delete window.__ANSWER__.subagent_log;
      for (const tab of [...tabs]) dropTab(tab.id);
      for (const at of [...termViews.keys()]) dropTermView(at);
      return seen;
    });
    ok(
      "the composer wears the extension's row — `+`, the agent chip (mark · name · model), the mode chip, then `/` and send — a pane's own conversation speaks to the pane without a door, and a helper's page keeps its door and speaks of the parent",
      seen.placeholder === seen.wantPlaceholder && seen.noDoorOnOwnPane &&
        JSON.stringify(seen.rowOrder) === JSON.stringify(["composer-attach-plus", "worker-composer-agent", "worker-composer-mode", "worker-composer-context", "worker-composer-agents", "worker-composer-right"]) &&
        seen.agentsPillQuiet &&
        seen.chipMark === "✻" && seen.chipName === "Claude" && seen.chipModelRaw === " · claude-fable-5-1" &&
        seen.helperDoor && seen.helperPlaceholder === seen.wantHelperPlaceholder,
      JSON.stringify(seen),
    );
    ok(
      "the agent chip's menu lists the CLI's models with the current one ticked and names them as the catalog does, a pick sends `/model <id>` down the send road where the CLI takes the id, the mode chip shows the hook's word and cycles with Shift+Tab, and another CLI opens a fresh pane",
      // Claude Code can be opened on its wire too now (a GUI session of the
      // same CLI), so the menu's wire section names it after the other CLIs.
      seen.menuOpen && JSON.stringify(seen.menuModels) === JSON.stringify(["Fable 5.1*", "Opus 5", "Codex", "Claude"]) &&
        seen.chipModelNamed === " · Fable 5.1" &&
        seen.modelSent === seen.wantModelSent && seen.menuClosed &&
        // The chip says the mode in Claude Code's own word — the catalog row's
        // label (t-6323 A3), not the spelling opened up.
        seen.modeShown && seen.modeWords === "Bypass permissions" && seen.modeKey === seen.wantModeKey &&
        seen.launched === "codex",
      JSON.stringify(seen),
    );
    ok(
      "`/` opens the palette the CLI itself would show — its list with the source on the head, asked for this checkout — filtering by the start of a name or a word inside it, saying so on a typo, arrows moving the highlight, Tab filling, Enter running an argument-less command through the send road, the window's own /artifact only filling",
      seen.paletteShown && seen.paletteHead === seen.wantHead && seen.askedCwd === seen.wantCwd &&
        JSON.stringify(seen.paletteRows) === JSON.stringify(["/compact", "/context", "/codex:review", "/clear", "/artifact", "/copy"]) &&
        JSON.stringify(seen.filtered) === JSON.stringify(["/compact", "/context", "/codex:review", "/copy"]) && seen.hot === "/compact" &&
        JSON.stringify(seen.innerWord) === JSON.stringify(["/codex:review"]) &&
        seen.none === seen.wantNone &&
        seen.hotAfterDown === "/context" && seen.tabFilled === "/context " && seen.tabSentNothing && seen.paletteClosedAfterTab &&
        seen.enterRan === seen.wantEnterRan && seen.boxClearedAfterRun &&
        seen.artifactListed === "/artifact" && seen.artifactFilled,
      JSON.stringify(seen),
    );
    ok(
      "`/copy` puts the page's last answer on the clipboard from the palette — nothing sent to the CLI, the box emptied — and a page that has been answered nothing does not list it",
      seen.copied === "hello" && seen.copySentNothing && seen.copyClearedBox &&
        seen.copyAbout === seen.wantCopyAbout && seen.copyUnlisted,
      JSON.stringify(seen),
    );
    ok(
      "a CLI whose picker lives on its own screen gets the bare command and the screen back, and a documented list is named as such on the palette's head",
      seen.codexPick === seen.wantCodexPick && seen.codexScreenBack && seen.codexHead === seen.wantCodexHead,
      JSON.stringify(seen),
    );
  } finally {
    await page.close();
  }
});

/* Where that menu stands: on the chip that opened it, inside the window,
 * flipped to the chip's other side when its own has no room, and still on the
 * chip after the window is resized under it. Measured, not eyeballed. */
suite("composer-menu-position", async ({ browser, origin, ok }) => {
  const { page } = await openWindowTestPage(browser, origin);
  try {
    await testComposerMenuPosition(page, ok);
  } finally {
    await page.close();
  }
});

suite("pane-conversation-view", async ({ browser, origin, ok }) => {
  const { page } = await openWindowTestPage(browser, origin);
  try {
    await page.emulateMedia({ reducedMotion: "no-preference" });
    const seen = await page.evaluate(async () => {
      const tell = (name, payload) => {
        for (const handler of window.__LISTENERS__[name] ?? []) handler({ payload });
      };
      const settle = () => new Promise((done) => setTimeout(done, 60));
      const seen = {};
      const term = await openTermTab({ placement: "tab" });
      await window.__PAINTED__();
      const toggle = el("view-toggle");
      seen.hiddenBeforeAgent = toggle.hidden;
      tell("hook:agent", { term, state: "working", agent: "claude", session: "s-view", resumable: false });
      await window.__PAINTED__();
      seen.shownForAgent = !toggle.hidden;
      window.__ANSWER__.pane_log = () => ({
        found: true,
        next: 3,
        turns: [
          { role: "user", text: "Wallet 결제 레시피 만들어줘" },
          { role: "tool", text: "Bash · zerocode-browser open http://admin.internal.example/login" },
          { role: "assistant", text: "저장했습니다." },
        ],
      });
      const view = termViews.get(term);
      const slot = document.querySelector(`.pane-slot[data-term="${term}"]`);
      const t0 = performance.now();
      el("view-toggle-chat").click();
      seen.toggleMs = +(performance.now() - t0).toFixed(2);
      await settle();
      const chat = slot?.querySelector(".pane-chat");
      seen.screenHidden = view.host.hidden;
      seen.chatShown = Boolean(chat) && !chat.hidden;
      seen.chatArrived = Boolean(chat) && chat.classList.contains("is-arriving");
      seen.turns = chat?.querySelectorAll(".helper-turn").length ?? 0;
      seen.composer = Boolean(chat?.querySelector(".worker-composer"));
      seen.chatPressed = el("view-toggle-chat").getAttribute("aria-pressed");
      seen.name = chat?.querySelector(".worker-name")?.textContent ?? "";
      // The hooks are the transcript's own events: a state or a tool call on
      // this pane makes the page read now, not on its next tick — and only
      // the pane on screen, not another's.
      let polled = 0;
      const answerLog = window.__ANSWER__.pane_log;
      // 이 판의 읽기만 센다. 통이 창 전체를 세면 다른 판의 폴러가 늦게
      // 닿은 것까지 「이 대화가 읽었다」로 읽히고, 그 지각은 부하가 정한다.
      window.__ANSWER__.pane_log = (args) => {
        if (args.term === term) polled += 1;
        return answerLog(args);
      };
      tell("hook:agent", { term, state: "working", agent: "claude", session: "s-view", resumable: false });
      await settle();
      seen.hookPolled = polled === 1;
      // The page's pulse follows the hook: the status line breathes while the
      // turn is out and is gone when it ends ("대화창이 계속 움직이는건" —
      // a page born "running" never stopped).
      seen.busyWhileWorking = chat.querySelector(".helper-status")?.hidden === false;
      tell("hook:agent", { term, state: "done", agent: "claude", session: "s-view", resumable: false });
      await window.__PAINTED__();
      await settle();
      seen.quietWhenDone = chat.querySelector(".helper-status")?.hidden === true &&
        chat.querySelector(".worker-state")?.textContent === t("worker.idle", "대기 중");
      tell("hook:agent", { term, state: "working", agent: "claude", session: "s-view", resumable: false });
      await window.__PAINTED__();
      await settle();
      seen.busyAgain = chat.querySelector(".helper-status")?.hidden === false;
      // 쫓아 읽기를 멈춘 뒤에 센다. 일하는 판은 읽은 뒤 160 ms에 또 읽도록
      // 예약하므로(`quickFollow`), 그 예약이 기다림 안에 들어오면 세는 것이
      // 「이 사건이 시킨 읽기」가 아니라 「그 사이 몇 번 쫓아 읽었나」가 된다.
      tell("hook:agent", { term, state: "idle", agent: "claude", session: "s-view", resumable: false });
      await settle();
      await settle();
      await settle();
      const beforeMine = polled;
      tell("hook:activity", { pane: `term:${term}`, activities: [{ verb: "Read", target: "a.rs", phase: "start" }] });
      await settle();
      // 「지금 읽었나」만 묻는다 — 몇 번 읽었는지는 쫓아 읽기가 정하고,
      // 그 수는 기계의 속도다. 남의 판 쪽은 아래에서 0으로 못 박는다.
      seen.activityPolled = polled > beforeMine;
      // 이 판의 읽기가 예약한 쫓아 읽기(160 ms)가 다 지나간 뒤에야 남의 판을
      // 센다 — 그 예약이 아래 기다림 안에 떨어지면 「남의 판이 시킨 읽기」로
      // 잘못 세어지고, 그 시각은 기계의 부하가 정한다(2026-09-21 세 레인이
      // 기계를 같이 쓰는 동안 붉었다 푸르렀다 했다).
      await settle();
      await settle();
      await settle();
      const beforeOther = polled;
      tell("hook:activity", { pane: `term:${term + 1}`, activities: [{ verb: "Read", target: "b.rs", phase: "start" }] });
      await window.__PAINTED__();
      await settle();
      seen.otherPaneQuiet = polled === beforeOther;
      window.__ANSWER__.pane_log = answerLog;
      // A question the hook DESCRIBED stays in the conversation as the
      // extension's card: the tool, its edit as a diff, allow / deny / say
      // what to do instead — answered down the board's own road.
      tell("hook:agent", { term, state: "awaiting-permission", agent: "claude", session: "s-view", resumable: false,
        approval: { tool: "Edit", summary: "/repo/a.rs", edits: [{ path: "/repo/a.rs", lines: [
          { kind: "del", text: "a", old: null, new: null }, { kind: "add", text: "b", old: null, new: null }] }] } });
      await window.__PAINTED__();
      const card = chat.querySelector(".pane-chat-ask");
      seen.cardShown = Boolean(card) && !chat.hidden && view.host.hidden;
      seen.cardTool = card?.querySelector(".board-approve-title")?.textContent ?? "";
      seen.wantCardTool = t("board.approve.title", "{{tool}} 허용할까요?", { tool: "Edit" });
      seen.cardDiff = card?.querySelectorAll(".helper-tool-diff .diff-line").length ?? 0;
      seen.cardBeforeComposer = card?.nextElementSibling?.classList.contains("worker-composer") === true;
      seen.cardActs = [...(card?.querySelectorAll(".board-approve-act") ?? [])].map((act) => act.className.replace("board-approve-act ", "")).join(",");
      // The card stands in the dock with the composer, as the extension's
      // does in its `inputContainer` — no accent rail of its own.
      seen.cardInDock = card?.parentElement?.classList.contains("chat-dock") === true;
      // The poll's paint leaves the card alone.
      const watch = new MutationObserver(() => {});
      watch.observe(card, { childList: true, subtree: true, attributes: true, characterData: true });
      paintPaneChat(term);
      seen.cardQuietPaint = watch.takeRecords().length;
      watch.disconnect();
      window.__APPROVED__ = null;
      card?.querySelector(".board-approve-act.is-allow")?.click();
      await settle();
      seen.approved = JSON.stringify(window.__APPROVED__);
      seen.wantApproved = JSON.stringify({ term, allow: true });
      seen.cardQuietAfter = card?.querySelector(".board-approve-act.is-allow")?.disabled === true;
      // The agent moving on takes the card away.
      tell("hook:agent", { term, state: "working", agent: "claude", session: "s-view", resumable: false });
      await window.__PAINTED__();
      seen.cardGone = chat.querySelector(".pane-chat-ask") === null;
      // "Say what to do instead": the refusing key, and the composer takes the words.
      tell("hook:agent", { term, state: "awaiting-permission", agent: "claude", session: "s-view", resumable: false,
        approval: { tool: "Bash", summary: "rm -rf build" } });
      await window.__PAINTED__();
      window.__APPROVED__ = null;
      chat.querySelector(".pane-chat-ask .board-approve-act.is-instead")?.click();
      await settle();
      seen.insteadDenied = JSON.stringify(window.__APPROVED__) === JSON.stringify({ term, allow: false });
      seen.insteadFocus = document.activeElement?.classList.contains("worker-composer-box") === true;
      tell("hook:agent", { term, state: "working", agent: "claude", session: "s-view", resumable: false });
      await window.__PAINTED__();
      // A question the hook only SIGNALLED is on the screen alone, so the screen comes back.
      tell("hook:agent", { term, state: "needs-attention", agent: "claude", session: "s-view", resumable: false });
      await window.__PAINTED__();
      seen.backOnQuestion = !view.host.hidden && chat.hidden;
      seen.termPressed = el("view-toggle-term").getAttribute("aria-pressed");
      // And back to the conversation by hand, then to the screen by hand.
      el("view-toggle-chat").click();
      await settle();
      seen.againChat = view.host.hidden && !chat.hidden;
      el("view-toggle-term").click();
      await settle();
      seen.backByHand = !view.host.hidden && chat.hidden;
      // A pane whose agent named no transcript says so instead of guessing.
      window.__ANSWER__.pane_log = () => ({ found: false, next: 0, turns: [], skipped: false });
      const quiet = await openTermTab({ placement: "tab" });
      tell("hook:agent", { term: quiet, state: "working", agent: "codex", session: "s-quiet", resumable: false });
      await window.__PAINTED__();
      el("view-toggle-chat").click();
      await settle();
      const quietChat = document.querySelector(`.pane-slot[data-term="${quiet}"] .pane-chat`);
      seen.noticeSaid = Boolean(quietChat?.querySelector('.pane-chat-notice[data-says="worker.noPaneTranscript"]'));
      // A long transcript is read to its end the moment the view opens — the
      // backend says the file goes on (`more`) and the page reads on at once,
      // not one chunk a beat — and the head counts THIS turn from the state
      // change's stamp, not the pane's age.
      const chunks = [
        { found: true, next: 1, more: true, folded: true, skipped: false, turns: [{ role: "user", text: "first" }] },
        { found: true, next: 2, more: true, skipped: false, turns: [{ role: "assistant", text: "second" }] },
        { found: true, next: 3, more: false, skipped: false, turns: [{ role: "assistant", text: "third" }] },
      ];
      let reads = 0;
      let firstAfter;
      window.__ANSWER__.pane_log = (args) => {
        // 같은 이유로 이 판의 읽기만 본다: 앞 판의 폴러는 아직 살아 있고,
        // 그 폴이 먼저 닿으면 「이 판의 첫 읽기」가 남의 커서를 들고 온다.
        if (args.term !== long) return answerLog(args);
        if (reads === 0) firstAfter = args.after;
        reads += 1;
        return chunks[Math.min(args.after ?? 0, 2)];
      };
      const long = await openTermTab({ placement: "tab" });
      const bornAgo = 60 * 60 * 1000;
      paneBorn.set(long, Date.now() - bornAgo);
      tell("hook:agent", { term: long, state: "working", agent: "claude", session: "s-long", resumable: false });
      await window.__PAINTED__();
      el("view-toggle-chat").click();
      await settle(150);
      const longChat = document.querySelector(`.pane-slot[data-term="${long}"] .pane-chat`);
      seen.caughtUp = longChat?.querySelectorAll(".helper-turn").length === 3 && reads >= 3;
      // The first read asked for the tail (no cursor), and a folded answer
      // says so on the page in the catalog's words.
      seen.openedAtTail = firstAfter === null &&
        longChat?.querySelector('.pane-chat-notice[data-says="worker.historyFolded"]')?.textContent ===
          t("worker.historyFolded", "긴 기록의 끝부분만 보입니다 — 이전 턴은 판의 화면과 세션 기록에 있습니다.");
      seen.turnClock = paneChats.get(long)?.run.startedAt === hookStamps.get(long) &&
        Date.now() - paneChats.get(long).run.startedAt < bornAgo / 2;
      // The permission mode's reach colours the send and the spinner's mark
      // (the extension's `[data-permission-mode]`): edits taken without
      // asking invert the send; the asking mode wears nothing.
      tell("hook:agent", { term: long, state: "idle", agent: "claude", resumable: false, permission_mode: "acceptEdits" });
      await window.__PAINTED__();
      await settle();
      const longForm = longChat?.querySelector(".worker-composer");
      const reachColor = (name) => {
        const span = document.createElement("span");
        span.style.color = `var(${name})`;
        longChat.appendChild(span);
        const value = getComputedStyle(span).color;
        span.remove();
        return value;
      };
      seen.reachWorn = longForm?.dataset.permissionReach === "edits" &&
        longChat?.querySelector(".helper-status")?.dataset.permissionReach === "edits";
      // Read once the button's colour has finished easing from the agent's
      // colour to the reach's — mid-transition it is an interpolated oklab.
      await new Promise((done) => setTimeout(done, 400));
      seen.sendInverted = longForm
        ? getComputedStyle(longForm.querySelector(".worker-composer-send")).backgroundColor === reachColor("--chat-reach-edits")
        : false;
      tell("hook:agent", { term: long, state: "idle", agent: "claude", resumable: false, permission_mode: "default" });
      await window.__PAINTED__();
      await settle();
      seen.askWearsNothing = longForm?.hasAttribute("data-permission-reach") === false;
      // A plain shell has no conversation to show.
      const plain = await openTermTab({ placement: "tab" });
      await window.__PAINTED__();
      seen.hiddenOnPlain = el("view-toggle").hidden;
      void plain;
      for (const tab of [...tabs]) dropTab(tab.id);
      for (const at of [...termViews.keys()]) dropTermView(at);
      seen.forgotten = paneChats.size === 0;
      return seen;
    });
    ok(
      "the active agent pane's toggle swaps its screen for its conversation in the same slot — turns from the pane's own transcript, a composer, the screen hidden, a described question standing as the extension's card (tool, diff, allow · deny · instead, on the agent's accent, quiet under the poll, gone when the agent moves on), an undescribed one bringing the screen back, and no toggle on a plain shell",
      seen.hiddenBeforeAgent && seen.shownForAgent && seen.screenHidden && seen.chatShown && seen.chatArrived &&
        seen.turns === 3 && seen.composer && seen.chatPressed === "true" && seen.name !== "" &&
        seen.hookPolled && seen.activityPolled && seen.otherPaneQuiet &&
        seen.busyWhileWorking && seen.quietWhenDone && seen.busyAgain &&
        seen.cardShown && seen.cardTool === seen.wantCardTool && seen.cardDiff === 2 && seen.cardBeforeComposer &&
        seen.cardActs === "is-allow,is-deny,is-instead" && seen.cardInDock &&
        seen.cardQuietPaint === 0 && seen.approved === seen.wantApproved && seen.cardQuietAfter && seen.cardGone &&
        seen.insteadDenied && seen.insteadFocus &&
        seen.backOnQuestion && seen.termPressed === "true" && seen.againChat && seen.backByHand &&
        seen.reachWorn && seen.sendInverted && seen.askWearsNothing &&
        seen.noticeSaid && seen.caughtUp && seen.openedAtTail && seen.turnClock && seen.hiddenOnPlain && seen.forgotten &&
        seen.toggleMs < 50,
      JSON.stringify(seen),
    );
  } finally {
    await page.close();
  }
});

/* Focus view(확장 2.1.221; 발주서 `docs/plans/conversation-panel-wave2-20260921.md`
 * 레인 A): 한 턴의 도구 일이 요약 한 줄 뒤로 접힌다.
 *
 * 묶음은 연속한 활동 행 — 도구 호출과 생각 — 의 최대 구간이라 답이 오면
 * 닫히고, 구성원은 목록의 직계 자식으로 남은 채 숨는다(옮기면 `data-turn`
 * 회계가 무너진다). 계수는 폴마다 다시 세지 않고 상태가 움직인 행 하나만
 * 옮기므로, 같은 묶음 노드가 제 수를 갈아입고 조용한 폴은 아무것도 쓰지
 * 않는다. 기본은 꺼짐이고, 머리의 토글이 전역 설정을 쓴다. */
suite("focus-view", async ({ browser, origin, ok }) => {
  const { page } = await openWindowTestPage(browser, origin);
  try {
    await page.emulateMedia({ reducedMotion: "no-preference" });
    const seen = await page.evaluate(async () => {
      const seen = {};
      const tell = (name, payload) => {
        for (const handler of window.__LISTENERS__[name] ?? []) handler({ payload });
      };
      const saved = [];
      window.__ANSWER__.set_conversation_focus_view = (args) => {
        saved.push(args);
        return null;
      };
      const term = await openTermTab({ placement: "tab" });
      const owner = tabOfTerm(term);
      tell("hook:agent", { term, state: "working", agent: "claude", session: "s-focus" });
      tell("hook:subagent", { term, rows: [{ id: "focus", name: "@focus", state: "running" }] });
      await window.__PAINTED__();
      // `[user, tool(Read), tool(Grep 실패), thinking, assistant, tool(Edit 살아 있음)]`
      // — 결과는 제 호출 행에 합류하므로 행은 여섯이다.
      window.__ANSWER__.subagent_log = () => ({
        found: true,
        next: 8,
        turns: [
          { role: "user", text: "둘을 읽고 하나를 고쳐라" },
          { role: "tool", text: "Read · /repo/a.rs", tool: { call_id: "a", name: "Read", is_error: false } },
          { role: "tool_result", text: "12 lines", tool: { call_id: "a", is_error: false } },
          { role: "tool", text: "Grep · needle in /repo", tool: { call_id: "b", name: "Grep", is_error: false } },
          { role: "tool_result", text: "no match", tool: { call_id: "b", is_error: true } },
          { role: "thinking", text: "**계획**\n먼저 고친다." },
          { role: "assistant", text: "고치겠습니다." },
          { role: "tool", text: "Edit · /repo/b.rs", tool: { call_id: "c", name: "Edit", is_error: false } },
        ],
      });
      await openHelperPage(
        { term, agent: "claude", worktree: owner.worktree, tab: owner },
        { id: "focus", name: "@focus", state: "running" },
      );
      await new Promise((done) => setTimeout(done, 120));
      const face = document.querySelector("#worker-view");
      const list = face.querySelector(".helper-turns");
      const tab = tabs.find((one) => one.id === `helper:${term}:focus`);
      const groups = () => [...list.querySelectorAll(":scope > .helper-group")];
      const keys = () => [...list.querySelectorAll(":scope > [data-turn]")]
        .map((row) => row.dataset.turn).join(",");
      const hiddenRows = () => list.querySelectorAll(":scope > .helper-turn[hidden]").length;
      const capOf = (group) => group.querySelector(":scope > .helper-group-cap");
      const wordsOf = (group) => capOf(group).querySelector(".helper-group-words").textContent;
      const liveOf = (group) => {
        const live = capOf(group).querySelector(".helper-group-live");
        return live.hidden ? "" : `${live.querySelector(".helper-tool-name").textContent} ${live.querySelector(".helper-tool-arg").textContent}`;
      };

      // (a) 기본은 꺼짐: 묶음도 없고 숨은 행도 없다.
      seen.offGroups = groups().length;
      seen.offHidden = hiddenRows();
      seen.keysBefore = keys();
      const button = face.querySelector(".worker-head .worker-focus");
      seen.buttonNamed = button?.dataset.tip === t("worker.focusView", "집중 보기") &&
        button?.getAttribute("aria-label") === t("worker.focusView", "집중 보기");
      seen.offPressed = button?.getAttribute("aria-pressed");

      // (b) 머리 단추 하나가 전역 설정을 쓰고, 그 자리에서 묶음이 선다.
      button.click();
      await new Promise((done) => setTimeout(done, 80));
      seen.saved = JSON.stringify(saved);
      seen.onPressed = button.getAttribute("aria-pressed");
      const standing = groups();
      seen.onGroups = standing.length;
      seen.firstWords = standing[0] ? wordsOf(standing[0]) : "";
      seen.wantFirstWords = t("worker.focusCalls", "도구 호출 {{n}}회", { n: 2 }) +
        t("worker.focusFailed", " · 실패 {{n}}", { n: 1 });
      seen.firstFailed = standing[0]?.classList.contains("is-failed") === true &&
        !standing[0]?.classList.contains("is-live");
      seen.secondWords = standing[1] ? wordsOf(standing[1]) : "";
      seen.wantSecondWords = t("worker.focusCalls", "도구 호출 {{n}}회", { n: 1 });
      seen.secondLive = standing[1]?.classList.contains("is-live") === true;
      seen.secondLiveWords = standing[1] ? liveOf(standing[1]) : "";
      // 구성원은 전부 숨고, 목록의 열쇠와 정체성은 그대로다. 숨은 행은
      // 자리도 갖지 않는다 — `[hidden]`이 행의 display를 이겨야 한다.
      seen.onHidden = hiddenRows();
      seen.hiddenTakeNoRoom = [...list.querySelectorAll(":scope > .helper-turn[hidden]")]
        .every((row) => getComputedStyle(row).display === "none");
      seen.capsStand = standing.every((group) => getComputedStyle(group).display !== "none");
      seen.keysAfter = keys();
      seen.capExpanded = standing[0] ? capOf(standing[0]).getAttribute("aria-expanded") : "";
      seen.capNamed = standing[0]
        ? capOf(standing[0]).getAttribute("aria-label") === t("worker.focusExpand", "도구 호출 펼치기")
        : false;
      // 점은 묶음의 상태다 — 도구 행과 같은 규칙에서 온다.
      const probe = (name) => {
        const span = document.createElement("span");
        span.style.backgroundColor = `var(${name})`;
        document.body.appendChild(span);
        const value = getComputedStyle(span).backgroundColor;
        span.remove();
        return value;
      };
      seen.firstDot = standing[0]
        ? getComputedStyle(standing[0], "::before").backgroundColor === probe("--chat-dot-failed")
        : false;
      seen.secondDot = standing[1]
        ? getComputedStyle(standing[1], "::before").backgroundColor === probe("--agent-accent-claude")
        : false;

      // (c) 캡을 누르면 그 묶음의 구성원만 보인다.
      capOf(standing[0]).click();
      seen.openedExpanded = capOf(standing[0]).getAttribute("aria-expanded");
      seen.openedNamed = capOf(standing[0]).getAttribute("aria-label") ===
        t("worker.focusCollapse", "도구 호출 접기");
      seen.openedHidden = hiddenRows();
      capOf(standing[0]).click();
      seen.closedHidden = hiddenRows();

      // (d) 폴로 도구 턴이 더 오면 **같은 노드**가 제 수를 갈아입는다.
      const secondNode = standing[1];
      holdHelperTurns(tab.worker.helper, [
        { role: "tool", text: "Bash · cargo test", tool: { call_id: "d", name: "Bash", is_error: false } },
        { role: "tool", text: "Read · /repo/c.rs", tool: { call_id: "e", name: "Read", is_error: false } },
      ]);
      paintWorkerView(tab);
      seen.grewSameNode = groups()[1] === secondNode;
      seen.grewWords = wordsOf(secondNode);
      seen.wantGrewWords = t("worker.focusCalls", "도구 호출 {{n}}회", { n: 3 });
      seen.grewHidden = hiddenRows();
      // 조용한 폴은 아무것도 쓰지 않는다.
      const watch = new MutationObserver(() => {});
      watch.observe(list, { childList: true, subtree: true, characterData: true, attributes: true });
      paintWorkerView(tab);
      seen.quietMutations = watch.takeRecords().length;
      watch.disconnect();

      // 결과가 합류하면 그 묶음의 계수가 살아 있는 쪽에서 끝난 쪽으로 옮겨 간다.
      holdHelperTurns(tab.worker.helper, [
        { role: "tool_result", text: "done", tool: { call_id: "c", is_error: false } },
        { role: "tool_result", text: "ok", tool: { call_id: "d", is_error: false } },
        { role: "tool_result", text: "boom", tool: { call_id: "e", is_error: true } },
      ]);
      paintWorkerView(tab);
      seen.settledWords = wordsOf(secondNode);
      seen.wantSettledWords = t("worker.focusCalls", "도구 호출 {{n}}회", { n: 3 }) +
        t("worker.focusFailed", " · 실패 {{n}}", { n: 1 });
      seen.settledLive = secondNode.classList.contains("is-live");

      // (e) 답이 오면 묶음이 닫히고, 다음 도구 턴은 새 묶음이다.
      holdHelperTurns(tab.worker.helper, [
        { role: "assistant", text: "끝났습니다." },
        { role: "tool", text: "Read · /repo/d.rs", tool: { call_id: "f", name: "Read", is_error: false } },
      ]);
      paintWorkerView(tab);
      seen.afterAnswerGroups = groups().length;
      seen.thirdWords = wordsOf(groups()[2]);
      seen.wantThirdWords = t("worker.focusCalls", "도구 호출 {{n}}회", { n: 1 });

      // (f) 상한을 넘겨 앞이 잘려도 계수가 맞고 빈 묶음이 남지 않는다.
      const flood = [];
      for (let at = 0; at < 420; at += 1) {
        flood.push({ role: "tool", text: `Read · /repo/${at}.rs`,
          tool: { call_id: `x${at}`, name: "Read", is_error: false } });
        flood.push({ role: "tool_result", text: "ok", tool: { call_id: `x${at}`, is_error: false } });
      }
      holdHelperTurns(tab.worker.helper, flood);
      paintWorkerView(tab);
      const capped = groups();
      seen.cappedRows = list.querySelectorAll(":scope > [data-turn]").length;
      seen.cappedTurns = tab.worker.helper.turns.length;
      // 남은 묶음은 저마다 구성원을 갖고, 계수는 그 구성원 수와 같다.
      seen.cappedHonest = capped.length > 0 && capped.every((group) => {
        let members = 0;
        let calls = 0;
        let failed = 0;
        let live = 0;
        let row = group.nextElementSibling;
        while (row && row.__group === group) {
          members += 1;
          if (row.classList.contains("is-tool")) {
            calls += 1;
            if (row.classList.contains("is-failed")) failed += 1;
            if (row.classList.contains("is-live")) live += 1;
          }
          row = row.nextElementSibling;
        }
        return members > 0 && group.__calls === calls &&
          group.__failed === failed && group.__live === live;
      });
      seen.cappedWords = wordsOf(capped.at(-1));
      seen.wantCappedWords = t("worker.focusCalls", "도구 호출 {{n}}회", { n: capped.at(-1).__calls });
      seen.cappedAllHidden = hiddenRows() === list.querySelectorAll(":scope > .helper-turn.is-grouped").length;

      // (g) 끄면 묶음도 숨은 행도 없다 — 목록의 열쇠는 그대로.
      const keysWhileOn = keys();
      button.click();
      await new Promise((done) => setTimeout(done, 80));
      seen.savedBack = JSON.stringify(saved);
      seen.backGroups = groups().length;
      seen.backHidden = hiddenRows();
      seen.backKeys = keys() === keysWhileOn;
      seen.backPressed = button.getAttribute("aria-pressed");

      tell("hook:subagent", { term, rows: [] });
      tell("term:exited", { term });
      await new Promise((done) => setTimeout(done, 40));
      window.__PANES__ = [];
      for (const one of [...tabs]) dropTab(one.id);
      for (const at of [...termViews.keys()]) dropTermView(at);
      return seen;
    });
    ok(
      "focus view is off until the head's toggle writes the one global setting; on, a turn's tool work stands behind one summary — `n tool calls · m failed` with the group's own dot, the live call named beside it — its members hidden in place with every `data-turn` and its identity untouched, the cap opens and closes that group alone, a poll that brings more calls grows the SAME node and a quiet poll writes nothing, an answer closes the group and the next call opens a new one, the 400 cap leaves no empty group behind, and turning it off returns the whole transcript",
      seen.offGroups === 0 && seen.offHidden === 0 && seen.offPressed === "false" &&
        seen.buttonNamed &&
        seen.saved === JSON.stringify([{ on: true }]) && seen.onPressed === "true" &&
        seen.onGroups === 2 &&
        seen.firstWords === seen.wantFirstWords && seen.firstFailed && seen.firstDot &&
        seen.secondWords === seen.wantSecondWords && seen.secondLive && seen.secondDot &&
        seen.secondLiveWords === "Edit /repo/b.rs" &&
        seen.onHidden === 4 && seen.hiddenTakeNoRoom && seen.capsStand &&
        seen.keysAfter === seen.keysBefore &&
        seen.capExpanded === "false" && seen.capNamed &&
        seen.openedExpanded === "true" && seen.openedNamed &&
        seen.openedHidden === 1 && seen.closedHidden === 4 &&
        seen.grewSameNode && seen.grewWords === seen.wantGrewWords && seen.grewHidden === 6 &&
        seen.quietMutations === 0 &&
        seen.settledWords === seen.wantSettledWords && !seen.settledLive &&
        seen.afterAnswerGroups === 3 && seen.thirdWords === seen.wantThirdWords &&
        seen.cappedTurns === 400 && seen.cappedRows === 400 && seen.cappedHonest &&
        seen.cappedWords === seen.wantCappedWords && seen.cappedAllHidden &&
        seen.savedBack === JSON.stringify([{ on: true }, { on: false }]) &&
        seen.backGroups === 0 && seen.backHidden === 0 && seen.backKeys &&
        seen.backPressed === "false",
      JSON.stringify(seen),
    );
  } finally {
    await page.close();
  }
});

/* 단위 6(docs/design/agent-wire-sessions-20260915.md): 선(wire) 위의 세션 — 화면 없는
 * CLI(Codex app-server)를 창이 JSON-RPC로 몰고, 그 탭은 대화 그 자체다. 턴은
 * `wire_log`로 오고, 입력줄은 `wire_send`로 보내고, 물음은 선이 준 선택지를 단추로
 * 세워 `wire_answer`에 option id를 실어 보낸다. 모델 메뉴는 `wire_models`, 팔레트
 * 머리는 세션의 버전과 「이 세션」, 탭을 닫으면 `wire_stop`. */
suite("wire-session", async ({ browser, origin, ok }) => {
  const { page } = await openWindowTestPage(browser, origin);
  try {
    const seen = await page.evaluate(async () => {
      const settle = () => new Promise((done) => setTimeout(done, 60));
      const seen = {};
      const calls = [];
      let log = {
        found: true, skipped: false, next: 0, turns: [], status: "idle", asks: [], agent: "codex",
        protocol: "app-server", model: "gpt-5.6-sol", models: [], mode: "on-request", modes: [], commands: [],
        version: "0.154.0",
      };
      window.__ANSWER__.wire_start = (args) => {
        calls.push(["start", args]);
        return { id: 7, agent: args.agent, protocol: "app-server", version: "0.154.0", model: "gpt-5.6-sol" };
      };
      window.__ANSWER__.wire_log = (args) => ({ ...log, turns: log.turns.slice(args.after), next: log.turns.length });
      window.__ANSWER__.wire_send = (args) => { calls.push(["send", args]); return null; };
      window.__ANSWER__.wire_answer = (args) => { calls.push(["answer", args]); return null; };
      window.__ANSWER__.wire_models = () => [
        { id: "gpt-5.6-sol", display_name: "GPT-5.6 Sol" },
        { id: "gpt-6-astra", display_name: "GPT-6 Astra" },
      ];
      window.__ANSWER__.wire_set_model = (args) => { calls.push(["model", args]); return null; };
      window.__ANSWER__.wire_stop = (args) => { calls.push(["stop", args]); return null; };
      const spec = installedAgents().find((row) => row.id === "codex");
      const tabId = await openWirePage("codex", "/tmp/zerocode-window-test");
      await window.__PAINTED__();
      await settle();
      const tab = tabs.find((one) => one.id === tabId);
      seen.opened = Boolean(tab) && tab.kind === "worker" && tab.worker.wire === 7 && activeTabId === tabId;
      seen.startArgs = JSON.stringify(calls.find((call) => call[0] === "start")?.[1]);
      seen.wantStartArgs = JSON.stringify({ agent: "codex", cwd: "/tmp/zerocode-window-test", resume: null, from_pane: null });
      const face = document.querySelector("#worker-view");
      seen.head = face?.querySelector(".worker-name")?.textContent ?? "";
      seen.wantHead = agentName("codex");
      seen.composer = Boolean(face?.querySelector(".worker-composer"));
      seen.placeholder = face?.querySelector(".worker-composer-box")?.placeholder ?? "";
      seen.wantPlaceholder = t("worker.sayTo", "{{name}}에게 보내기…", { name: agentName("codex") });
      seen.noDoor = !face?.querySelector(".worker-composer-door");
      seen.chipModel = face?.querySelector(".worker-composer-model-words")?.textContent ?? "";
      seen.idleWords = face?.querySelector(".worker-state")?.textContent ?? "";
      seen.wantIdleWords = t("worker.idle", "대기 중");
      // Sending goes down the wire — one request, no pty.
      const box = face.querySelector(".worker-composer-box");
      box.value = "probe.txt를 만들어";
      box.dispatchEvent(new Event("input", { bubbles: true }));
      face.querySelector(".worker-composer").requestSubmit();
      await settle();
      seen.sent = JSON.stringify(calls.find((call) => call[0] === "send")?.[1]);
      seen.wantSent = JSON.stringify({ id: 7, text: "probe.txt를 만들어" });
      seen.boxCleared = box.value === "";
      // Turns arrive through the poll; a question stands as the card with the
      // wire's own options, worded by the window for a decision's kind.
      log = {
        ...log,
        status: "asking",
        turns: [
          { role: "user", text: "probe.txt를 만들어" },
          { role: "tool", text: "shell · printf hello > probe.txt",
            tool: { call_id: "c1", name: "shell", input: "printf hello > probe.txt", is_error: false, edits: [] } },
        ],
        asks: [{
          id: 3, kind: "approval", method: "item/commandExecution/requestApproval", tool: "shell",
          summary: "printf hello > probe.txt",
          options: [
            { id: "accept", kind: "allow_once" }, { id: "acceptForSession", kind: "allow_always" },
            { id: "decline", kind: "reject_once" },
          ],
        }],
      };
      await pollHelperPages();
      await window.__PAINTED__();
      await settle();
      seen.turns = face.querySelectorAll(".helper-turn").length;
      seen.liveDot = face.querySelector(".helper-turn.is-tool.is-live") !== null;
      seen.busyLine = face.querySelector(".helper-status")?.hidden === false;
      const card = face.querySelector(".pane-chat-ask");
      seen.card = Boolean(card);
      seen.cardTool = card?.querySelector(".board-approve-title")?.textContent ?? "";
      seen.wantCardTool = t("board.approve.title", "{{tool}} 허용할까요?", { tool: "shell" });
      seen.cardActs = [...(card?.querySelectorAll(".board-approve-act") ?? [])].map((act) => act.textContent).join("|");
      seen.wantCardActs = [t("wire.allowOnce", "허용"), t("wire.allowAlways", "이 세션에서 항상 허용"), t("wire.rejectOnce", "거부")].join("|");
      seen.cardKinds = [...(card?.querySelectorAll(".board-approve-act") ?? [])].map((act) => act.className.replace("board-approve-act ", "")).join("|");
      // A quiet poll leaves the card alone.
      const watch = new MutationObserver(() => {});
      if (card) watch.observe(card, { childList: true, subtree: true, attributes: true, characterData: true });
      await pollHelperPages();
      seen.cardQuietPoll = watch.takeRecords().length;
      watch.disconnect();
      card?.querySelectorAll(".board-approve-act")[1]?.click();
      await settle();
      seen.answered = JSON.stringify(calls.find((call) => call[0] === "answer")?.[1]);
      seen.wantAnswered = JSON.stringify({ id: 7, ask: 3, option: "acceptForSession" });
      // The result joins its row; the agent finishes: idle words, no busy line, no card.
      log = {
        ...log, status: "idle", asks: [],
        turns: [...log.turns,
          { role: "tool_result", text: "", tool: { call_id: "c1", name: "shell", input: "", is_error: false } },
          { role: "assistant", text: "done" }],
      };
      await pollHelperPages();
      await window.__PAINTED__();
      await settle();
      seen.cardGone = face.querySelector(".pane-chat-ask") === null;
      seen.doneRow = face.querySelector(".helper-turn.is-tool.is-done") !== null;
      seen.busyGone = face.querySelector(".helper-status")?.hidden === true;
      seen.idleAgain = face.querySelector(".worker-state")?.textContent === seen.wantIdleWords;
      // The words stream: the wire's live text stands as rows under the last
      // turn — a thought's fold open, the answer's row — grows in place, and
      // closes into turns in the same paint that brings them.
      seen.rowsBeforeStream = face.querySelectorAll(".helper-turn").length;
      const until = async (test) => {
        for (let n = 0; n < 60 && !test(); n += 1) await new Promise((done) => requestAnimationFrame(done));
        return test();
      };
      log = { ...log, status: "working", live: [{ role: "thinking", text: "Look at it." }, { role: "assistant", text: "Reading " }] };
      await pollHelperPages();
      await window.__PAINTED__();
      await settle();
      const streaming = face.querySelectorAll(".helper-turn.is-streaming");
      seen.streamingRows = [...streaming].map((row) => row.dataset.role).join("|");
      seen.streamingThought = streaming[0]?.querySelector(".helper-thought-body")?.textContent ?? "";
      seen.streamingCue = streaming[0]?.querySelector(".helper-cue")?.textContent ?? "";
      seen.streamingOpen = streaming[0]?.open === true;
      const liveRow = streaming[1];
      // What arrived is on screen by the next frame, as the terminal draws it.
      seen.streamingText = (await until(() => liveRow?.textContent.trim() === "Reading")) ? liveRow.textContent.trim() : (liveRow?.textContent ?? "");
      seen.streamingBelowTurns = streaming[0]?.previousElementSibling?.dataset.turn !== undefined;
      log = { ...log, live: [{ role: "thinking", text: "Look at it." }, { role: "assistant", text: "Reading it now." }] };
      await pollHelperPages();
      await window.__PAINTED__();
      // The same row grows in place with everything that arrived — nothing
      // waits for a word boundary or for the close.
      seen.streamingGrewInPlace = (await until(() => liveRow.textContent.trim() === "Reading it now.")) &&
        face.querySelectorAll(".helper-turn.is-streaming")[1] === liveRow;
      // The session's own news (`wire:update`) reads at once — this wire's,
      // not another's — and news during a read is read right after it.
      let polled = 0;
      const answerLog = window.__ANSWER__.wire_log;
      window.__ANSWER__.wire_log = (args) => { polled += 1; return answerLog(args); };
      for (const l of window.__LISTENERS__["wire:update"] ?? []) l({ payload: { id: 7 } });
      await settle();
      seen.eventPolled = polled === 1;
      for (const l of window.__LISTENERS__["wire:update"] ?? []) l({ payload: { id: 8 } });
      await settle();
      seen.otherWireIgnored = polled === 1;
      const first = pollHelperPages();
      for (const l of window.__LISTENERS__["wire:update"] ?? []) l({ payload: { id: 7 } });
      await first;
      await settle();
      seen.newsDuringReadReadAgain = polled === 3;
      window.__ANSWER__.wire_log = answerLog;
      log = {
        ...log, status: "idle", live: [],
        turns: [...log.turns, { role: "thinking", text: "Look at it." }, { role: "assistant", text: "Reading it now." }],
      };
      await pollHelperPages();
      // The close: the answer's row stands at once, shown, in the paint that
      // took the streaming row away — no hidden row waiting on a reveal.
      const closedAnswer = () => [...face.querySelectorAll(".helper-turn.is-assistant:not(.is-streaming)")].at(-1);
      seen.closedAtOnce = closedAnswer()?.hidden === false;
      seen.streamingGone = await until(() => face.querySelectorAll(".helper-turn.is-streaming").length === 0);
      seen.closedShown = closedAnswer()?.hidden === false && closedAnswer()?.textContent.includes("Reading it now.");
      seen.closedRows = face.querySelectorAll(".helper-turn").length - seen.rowsBeforeStream;
      seen.closedThoughtShut = face.querySelector(".helper-turn.is-thinking")?.open === false;
      // The model menu lists the wire's models; a pick goes down the wire.
      face.querySelector(".worker-composer-agent").click();
      await settle();
      const items = [...document.querySelectorAll(".composer-menu-item")];
      seen.menuModels = items.map((node) => node.querySelector(".composer-menu-name")?.textContent).slice(0, 2).join(",");
      items[1]?.click();
      await settle();
      seen.modelSet = JSON.stringify(calls.find((call) => call[0] === "model")?.[1]);
      seen.wantModelSet = JSON.stringify({ id: 7, model: "gpt-6-astra" });
      // The palette's head names the session and its version; the wire's own
      // commands (ACP announces them) stand above the window's.
      log = { ...log, commands: [{ name: "/help", about: "Show help" }] };
      await pollHelperPages();
      await settle();
      face.querySelector(".worker-composer-slash").click();
      await settle();
      seen.paletteHead = face.querySelector(".composer-slash-head")?.textContent ?? "";
      seen.wantPaletteHead = `${spec.name} 0.154.0 · ${t("composer.slash.sourceSession", "이 세션")}`;
      seen.paletteRows = [...face.querySelectorAll(".composer-slash-row .composer-slash-name")].map((node) => node.textContent).join(",");
      // Closing the tab stops the wire.
      closeTab(tabId);
      await settle();
      seen.stopped = JSON.stringify(calls.find((call) => call[0] === "stop")?.[1]) === JSON.stringify({ id: 7 });
      seen.tabGone = !tabs.some((one) => one.id === tabId);
      for (const name of ["wire_start", "wire_log", "wire_send", "wire_answer", "wire_models", "wire_set_model", "wire_stop"]) {
        delete window.__ANSWER__[name];
      }
      for (const held of [...tabs]) dropTab(held.id);
      return seen;
    });
    ok(
      "a CLI driven on its wire is a conversation tab: opened for the checkout with the CLI's name, a composer that sends down the wire and no parent door, turns arriving through the poll with the live dot and the busy line, a question standing as the card with the wire's own options (the window's words for their kinds) and the pick going back with its id, the card left alone by a quiet poll and gone when the agent moves on, idle words between turns, the live text streaming as a thought's open fold and the answer's row that grow in place under the last turn with everything that arrived and close into turns in one paint, the session's own news read at once and read again when it came mid-read, the wire's models in the chip menu and a pick sent down the wire, the palette naming the session and its commands, and the tab's close stopping the wire",
      seen.opened && seen.startArgs === seen.wantStartArgs && seen.head === seen.wantHead && seen.composer &&
        seen.placeholder === seen.wantPlaceholder && seen.noDoor && seen.chipModel === " · gpt-5.6-sol" &&
        seen.idleWords === seen.wantIdleWords && seen.sent === seen.wantSent && seen.boxCleared &&
        seen.turns === 2 && seen.liveDot && seen.busyLine && seen.card && seen.cardTool === seen.wantCardTool &&
        seen.cardActs === seen.wantCardActs && seen.cardKinds === "is-allow|is-allow|is-deny" && seen.cardQuietPoll === 0 &&
        seen.answered === seen.wantAnswered && seen.cardGone && seen.doneRow && seen.busyGone && seen.idleAgain &&
        seen.streamingRows === "thinking|assistant" && seen.streamingThought === "Look at it." &&
        seen.streamingCue === "Look at it." && seen.streamingOpen && seen.streamingText === "Reading" &&
        seen.streamingBelowTurns && seen.streamingGrewInPlace && seen.eventPolled && seen.otherWireIgnored &&
        seen.newsDuringReadReadAgain && seen.closedAtOnce && seen.streamingGone && seen.closedShown &&
        seen.closedRows === 2 && seen.closedThoughtShut &&
        seen.menuModels === "GPT-5.6 Sol,GPT-6 Astra" && seen.modelSet === seen.wantModelSet &&
        seen.paletteHead === seen.wantPaletteHead && seen.paletteRows === "/help,/artifact,/copy" &&
        seen.stopped && seen.tabGone,
      JSON.stringify(seen),
    );
  } finally {
    await page.close();
  }
});

/* 실행 중에 친 글은 창이 들고 있다가 턴이 끝나면 나간다 — 판이든 선이든 같은
 * 그림(항목·순서·×)이고, 같은 길(`composerDeliver`)로 도착한다. 한 턴에
 * 하나: 보낸 직후의 짧은 idle 창에 대기열이 통째로 쏟아지지 않는다. */
suite("composer-queue", async ({ browser, origin, ok }) => {
  const { page } = await openWindowTestPage(browser, origin);
  try {
    const seen = await page.evaluate(async () => {
      const tell = (name, payload) => {
        for (const handler of window.__LISTENERS__[name] ?? []) handler({ payload });
      };
      const settle = (ms = 80) => new Promise((done) => setTimeout(done, ms));
      const seen = {};
      const calls = [];
      window.__ANSWER__.term_paste = (args) => (calls.push(["paste", args.term, args.text]), null);
      window.__ANSWER__.term_key = (args) => (calls.push(["key", args.term, args.press.key]), null);
      window.__ANSWER__.pane_log = () => ({ found: true, next: 1, turns: [{ role: "user", text: "go" }] });
      const type = (box, words) => {
        box.value = words;
        box.dispatchEvent(new Event("input", { bubbles: true }));
        box.closest(".worker-composer").requestSubmit();
      };
      // ---- 판의 길 ----
      const term = await openTermTab({ placement: "tab" });
      tell("hook:agent", { term, state: "working", agent: "claude", session: "s-queue", resumable: false });
      await window.__PAINTED__();
      el("view-toggle-chat").click();
      await settle(150);
      const chat = document.querySelector(`.pane-slot[data-term="${term}"] .pane-chat`);
      const composer = chat?.querySelector(".worker-composer");
      const box = composer?.querySelector(".worker-composer-box");
      const items = () => [...(composer?.querySelectorAll(".composer-queue-item") ?? [])]
        .map((item) => item.querySelector(".composer-queue-words")?.textContent);
      // 실행 중에는 상자가 대기열이라고 말한다.
      seen.workingPlaceholder = box?.placeholder;
      seen.wantWorkingPlaceholder = t("composer.queue.placeholder", "다음 메시지 대기열에 추가…");
      const before = calls.length;
      type(box, "첫째");
      await settle();
      seen.sentNothing = calls.length === before;
      seen.queued = JSON.stringify(items());
      seen.boxCleared = box.value === "";
      seen.count = composer?.querySelector(".composer-queue-count")?.textContent;
      seen.wantCount = t("composer.queue.count", "대기 {{n}}", { n: 1 });
      // 둘을 쌓는다 — 셋째는 × 로 지운다.
      type(box, "둘째");
      await settle();
      type(box, "버릴 것");
      await settle();
      seen.stacked = JSON.stringify(items());
      composer?.querySelectorAll(".composer-queue-drop")[2]?.click();
      await settle();
      seen.afterDrop = JSON.stringify(items());
      // 턴이 끝나면 첫째가 그 길로 — 붙여넣기 한 번, Enter 한 번. 한 턴에 하나.
      tell("hook:agent", { term, state: "idle", agent: "claude", session: "s-queue", resumable: false });
      await window.__PAINTED__();
      await settle(800);
      seen.firstOut = JSON.stringify(calls.slice(-2));
      seen.wantFirstOut = JSON.stringify([["paste", term, "첫째"], ["key", term, "Enter"]]);
      seen.oneAtATime = JSON.stringify(items());
      // 상태가 working 으로 올랐다가 다시 끝나야 둘째가 나간다.
      tell("hook:agent", { term, state: "working", agent: "claude", session: "s-queue", resumable: false });
      await window.__PAINTED__();
      await pollHelperPages();
      await settle();
      seen.stillHeld = JSON.stringify(items());
      tell("hook:agent", { term, state: "idle", agent: "claude", session: "s-queue", resumable: false });
      await window.__PAINTED__();
      await settle(800);
      seen.secondOut = JSON.stringify(calls.slice(-2));
      seen.wantSecondOut = JSON.stringify([["paste", term, "둘째"], ["key", term, "Enter"]]);
      seen.queueEmpty = JSON.stringify(items());
      // 턴 사이에 친 글은 기다리지 않는다 — 곧바로 그 길로.
      const straight = calls.length;
      type(box, "지금");
      await settle(800);
      seen.straightOut = JSON.stringify(calls.slice(straight));
      seen.wantStraightOut = JSON.stringify([["paste", term, "지금"], ["key", term, "Enter"]]);
      seen.idlePlaceholder = box?.placeholder;
      seen.wantIdlePlaceholder = t("worker.sayTo", "{{name}}에게 보내기…", { name: agentName("claude") });
      // 훅만으로 입력줄이 옷을 갈아입는다 — 제출 없이도 중지↔보내기, 자리말도
      // 제 것으로. 상태가 움직인 뒤에 그려야 옛 낱말을 입지 않는다.
      const send = () => composer?.querySelector(".worker-composer-send");
      tell("hook:agent", { term, state: "working", agent: "claude", session: "s-queue", resumable: false });
      await window.__PAINTED__();
      seen.stopWhileWorking = send()?.classList.contains("is-stop") === true &&
        box?.placeholder === seen.wantWorkingPlaceholder;
      tell("hook:agent", { term, state: "idle", agent: "claude", session: "s-queue", resumable: false });
      await window.__PAINTED__();
      seen.sendWhenIdle = send()?.classList.contains("is-stop") === false &&
        box?.placeholder === seen.wantIdlePlaceholder;
      // 대화를 잊으면 기다리던 글도 같이 사라진다.
      const paneRun = paneChats.get(term)?.run;
      paneRun.queue = ["남은 것"];
      forgetPaneChat(term);
      seen.forgotten = paneRun.queue === null;
      // ---- 선의 길 ----
      let log = {
        found: true, skipped: false, next: 0, turns: [], status: "working", asks: [], agent: "codex",
        protocol: "app-server", model: "gpt-5.6-sol", models: [], mode: "on-request", modes: [], commands: [],
        version: "0.154.0", live: [],
      };
      window.__ANSWER__.wire_start = () => ({ id: 11, agent: "codex", protocol: "app-server", version: "0.154.0", model: "gpt-5.6-sol" });
      window.__ANSWER__.wire_log = (args) => ({ ...log, turns: log.turns.slice(args.after), next: log.turns.length });
      window.__ANSWER__.wire_send = (args) => { calls.push(["wire", args.id, args.text]); return null; };
      window.__ANSWER__.wire_stop = () => null;
      const tabId = await openWirePage("codex", "/tmp/zerocode-window-test");
      // 선의 상태는 첫 `wire_log` 읽기가 실어 온다(`holdWireState`) — 시계가
      // 아니라 그 읽기를 기다린다(부하 아래 120 ms가 모자라 보내기가 먼저 나갔다).
      await pollHelperPages();
      const wireTab = () => tabs.find((tab) => tab.id === tabId);
      for (let i = 0; i < 50 && wireTab()?.worker.status !== "running"; i++) await settle(20);
      await window.__PAINTED__();
      await settle(120);
      const face = document.querySelector("#worker-view");
      const wireBox = face?.querySelector(".worker-composer-box");
      const wireItems = () => [...(face?.querySelectorAll(".composer-queue-item") ?? [])]
        .map((item) => item.querySelector(".composer-queue-words")?.textContent);
      const wireBefore = calls.length;
      type(wireBox, "선에서 기다릴 글");
      await settle();
      seen.wireSentNothing = calls.length === wireBefore;
      seen.wireQueued = JSON.stringify(wireItems());
      log = { ...log, status: "idle" };
      await pollHelperPages();
      await window.__PAINTED__();
      await settle(120);
      seen.wireOut = JSON.stringify(calls.slice(-1));
      seen.wantWireOut = JSON.stringify([["wire", 11, "선에서 기다릴 글"]]);
      seen.wireQueueEmpty = JSON.stringify(wireItems());
      closeTab(tabId);
      await settle();
      for (const name of ["term_paste", "term_key", "pane_log", "wire_start", "wire_log", "wire_send", "wire_stop"]) {
        delete window.__ANSWER__[name];
      }
      for (const tab of [...tabs]) dropTab(tab.id);
      for (const at of [...termViews.keys()]) dropTermView(at);
      return seen;
    });
    ok(
      "a message typed while the turn is out is held by the window — the box says so, the words stand as a queue item that an × takes back, and nothing reaches the pane",
      seen.workingPlaceholder === seen.wantWorkingPlaceholder && seen.sentNothing &&
        seen.queued === JSON.stringify(["첫째"]) && seen.boxCleared &&
        seen.count === seen.wantCount &&
        seen.stacked === JSON.stringify(["첫째", "둘째", "버릴 것"]) &&
        seen.afterDrop === JSON.stringify(["첫째", "둘째"]),
      JSON.stringify(seen),
    );
    ok(
      "the turn's end sends the first held message down the pane's own road — paste, a breath, Enter — one per turn: the second waits for the state to rise to working and fall again, a message typed between turns goes straight out, and forgetting the conversation forgets what it held",
      seen.firstOut === seen.wantFirstOut && seen.oneAtATime === JSON.stringify(["둘째"]) &&
        seen.stillHeld === JSON.stringify(["둘째"]) &&
        seen.secondOut === seen.wantSecondOut && seen.queueEmpty === JSON.stringify([]) &&
        seen.straightOut === seen.wantStraightOut &&
        seen.idlePlaceholder === seen.wantIdlePlaceholder &&
        seen.stopWhileWorking && seen.sendWhenIdle && seen.forgotten,
      JSON.stringify(seen),
    );
    ok(
      "a wire's page holds the same way and sends down the wire when its own status says the turn ended",
      seen.wireSentNothing && seen.wireQueued === JSON.stringify(["선에서 기다릴 글"]) &&
        seen.wireOut === seen.wantWireOut && seen.wireQueueEmpty === JSON.stringify([]),
      JSON.stringify(seen),
    );
  } finally {
    await page.close();
  }
});

/* 컨텍스트 미터 — 세션이 준 두 수로 서는 고리 하나와, 그것을 비울 문. 창을
 * 아는 읽기는 백분율과 고리, 모르는 읽기는 상태바와 같은 낱말에 고리 없음,
 * 읽기가 없으면 알약도 없다. 문은 그 CLI의 명령을 그 길이 나를 수 있을
 * 때만 산다. */
suite("context-meter", async ({ browser, origin, ok }) => {
  const { page } = await openWindowTestPage(browser, origin);
  try {
    const seen = await page.evaluate(async () => {
      const tell = (name, payload) => {
        for (const handler of window.__LISTENERS__[name] ?? []) handler({ payload });
      };
      const settle = (ms = 80) => new Promise((done) => setTimeout(done, ms));
      const seen = {};
      const calls = [];
      // ---- 선의 길: 두 수를 다 아는 세션 ----
      let log = {
        found: true, skipped: false, next: 0, turns: [], status: "idle", asks: [], agent: "codex",
        protocol: "app-server", model: "gpt-5.6-sol", models: [], mode: "on-request", modes: [],
        commands: [{ name: "/compact", about: "" }], version: "0.154.0", live: [],
        usage: { tokens: 34000, window: 100000 },
      };
      window.__ANSWER__.wire_start = () => ({ id: 21, agent: "codex", protocol: "app-server", version: "0.154.0", model: "gpt-5.6-sol" });
      window.__ANSWER__.wire_log = (args) => ({ ...log, turns: log.turns.slice(args.after), next: log.turns.length });
      window.__ANSWER__.wire_send = (args) => { calls.push(["wire", args.id, args.text]); return null; };
      window.__ANSWER__.wire_stop = () => null;
      const tabId = await openWirePage("codex", "/tmp/zerocode-window-test");
      await window.__PAINTED__();
      await pollHelperPages();
      await settle(120);
      const face = document.querySelector("#worker-view");
      const chip = face?.querySelector(".worker-composer-context");
      seen.chipShown = chip ? !chip.hidden : false;
      seen.words = chip?.querySelector(".worker-composer-pill-words")?.textContent;
      seen.ring = chip?.querySelector(".worker-composer-meter .is-fill")?.getAttribute("stroke-dasharray");
      seen.ringShown = chip?.querySelector(".worker-composer-meter")?.hidden === false;
      seen.tip = chip?.dataset.tip;
      seen.wantTip = t("composer.context.tip", "컨텍스트 {{tokens}} / {{window}} — 눌러서 압축 ({{command}})",
        { tokens: (34000).toLocaleString(), window: (100000).toLocaleString(), command: "/compact" });
      seen.aria = chip?.getAttribute("aria-label");
      seen.enabled = chip?.disabled === false;
      // 조용한 폴은 이 알약에 아무것도 쓰지 않는다.
      const watch = new MutationObserver(() => {});
      if (chip) watch.observe(chip, { childList: true, subtree: true, attributes: true, characterData: true });
      await pollHelperPages();
      await settle();
      seen.quietMutations = watch.takeRecords().length;
      watch.disconnect();
      // 누르면 그 세션이 이름한 명령이 선으로.
      chip?.click();
      await settle();
      seen.compacted = JSON.stringify(calls.slice(-1));
      seen.wantCompacted = JSON.stringify([["wire", 21, "/compact"]]);
      // 세션이 그 명령을 이름하지 않으면 문은 없다 — 읽기는 그대로.
      log = { ...log, commands: [{ name: "/help", about: "" }], usage: { tokens: 90000, window: 100000 } };
      await pollHelperPages();
      await window.__PAINTED__();
      await settle();
      seen.mute = chip?.disabled === true;
      seen.muteWords = chip?.querySelector(".worker-composer-pill-words")?.textContent;
      seen.muteTip = chip?.dataset.tip;
      seen.wantMuteTip = t("composer.context.tipPlain", "컨텍스트 {{tokens}} / {{window}}",
        { tokens: (90000).toLocaleString(), window: (100000).toLocaleString() });
      // 읽기가 없으면 알약도 없다.
      log = { ...log, usage: undefined };
      await pollHelperPages();
      await window.__PAINTED__();
      await settle();
      seen.goneWithoutUsage = chip?.hidden === true;
      closeTab(tabId);
      await settle();
      // ---- 판의 길: 전사만 아는 읽기(창 크기는 없다) ----
      window.__ANSWER__.term_paste = (args) => (calls.push(["paste", args.term, args.text]), null);
      window.__ANSWER__.term_key = (args) => (calls.push(["key", args.term, args.press.key]), null);
      window.__ANSWER__.pane_log = () => ({
        found: true, next: 1, turns: [{ role: "assistant", text: "done" }],
        usage: { tokens: 24000, window: 0 },
      });
      const term = await openTermTab({ placement: "tab" });
      tell("hook:agent", { term, state: "idle", agent: "claude", session: "s-meter", resumable: false });
      await window.__PAINTED__();
      el("view-toggle-chat").click();
      await settle(200);
      const chat = document.querySelector(`.pane-slot[data-term="${term}"] .pane-chat`);
      const paneChip = chat?.querySelector(".worker-composer-context");
      seen.paneShown = paneChip ? !paneChip.hidden : false;
      seen.paneWords = paneChip?.querySelector(".worker-composer-pill-words")?.textContent;
      seen.wantPaneWords = usageCtxWord({ tokens: 24000, window: 0 });
      seen.paneRingHidden = paneChip?.querySelector(".worker-composer-meter")?.hidden === true;
      seen.paneTip = paneChip?.dataset.tip;
      seen.wantPaneTip = t("composer.context.tip", "컨텍스트 {{tokens}} / {{window}} — 눌러서 압축 ({{command}})",
        { tokens: (24000).toLocaleString(), window: t("composer.context.unknownWindow", "?"), command: "/compact" });
      const paneBefore = calls.length;
      paneChip?.click();
      await settle(800);
      seen.paneCompacted = JSON.stringify(calls.slice(paneBefore));
      seen.wantPaneCompacted = JSON.stringify([["paste", term, "/compact"], ["key", term, "Enter"]]);
      // 판이 떠나면 그 읽기도 떠난다.
      seen.heldBeforeExit = paneUsage.has(term);
      tell("term:exited", { term });
      await settle();
      seen.forgotten = paneUsage.has(term) === false;
      for (const name of ["wire_start", "wire_log", "wire_send", "wire_stop", "term_paste", "term_key", "pane_log"]) {
        delete window.__ANSWER__[name];
      }
      for (const tab of [...tabs]) dropTab(tab.id);
      for (const at of [...termViews.keys()]) dropTermView(at);
      return seen;
    });
    ok(
      "a wire that names both numbers wears the ring and the percentage, says both in its tip, and stays untouched by a poll that brought no new reading",
      seen.chipShown && seen.words === "34%" && seen.ring === "34.0 100" && seen.ringShown &&
        seen.tip === seen.wantTip && seen.aria === seen.wantTip && seen.enabled &&
        seen.quietMutations === 0,
      JSON.stringify(seen),
    );
    ok(
      "the chip IS the compact button — a press sends the CLI's own word down the wire that announced it, a session that never announced it leaves a reading with no door, and no reading leaves no chip",
      seen.compacted === seen.wantCompacted && seen.mute && seen.muteWords === "90%" &&
        seen.muteTip === seen.wantMuteTip && seen.goneWithoutUsage,
      JSON.stringify(seen),
    );
    ok(
      "a pane whose only source is its transcript says the count in the status bar's own words with no ring over a window nobody gave, compacts down its own road, and is forgotten with the shell",
      seen.paneShown && seen.paneWords === seen.wantPaneWords && seen.paneRingHidden &&
        seen.paneTip === seen.wantPaneTip &&
        seen.paneCompacted === seen.wantPaneCompacted &&
        seen.heldBeforeExit && seen.forgotten,
      JSON.stringify(seen),
    );
  } finally {
    await page.close();
  }
});

/* A Claude Code pane's 「대화」 is the same conversation on its wire: the toggle
 * resumes the pane's session as a wire tab in the pane's seat, carrying the
 * turns already said, and the backend tells the pane's CLI to exit; the wire
 * tab's 「화면」 launches the CLI's own screen on the same session in a new pane
 * that takes the seat back. A pane mid-turn keeps its transcript view and is
 * handed over when the turn ends. */
suite("pane-hands-over-to-wire", async ({ browser, origin, ok }) => {
  const { page } = await openWindowTestPage(browser, origin);
  try {
    const seen = await page.evaluate(async () => {
      const tell = (name, payload) => {
        for (const handler of window.__LISTENERS__[name] ?? []) handler({ payload });
      };
      const settle = () => new Promise((done) => setTimeout(done, 60));
      const until = async (test) => {
        for (let n = 0; n < 40 && !test(); n += 1) await settle();
        return test();
      };
      const seen = {};
      const calls = [];
      window.__ANSWER__.pane_log = () => ({
        found: true, next: 2, skipped: false,
        turns: [{ role: "user", text: "probe.txt를 만들어" }, { role: "assistant", text: "만들었습니다." }],
      });
      window.__ANSWER__.wire_start = (args) => {
        calls.push(["start", args]);
        return { id: 11, agent: args.agent, protocol: "claude-stream", version: "2.1.273", model: null, session: args.resume ?? null };
      };
      window.__ANSWER__.wire_log = (args) => ({
        found: true, skipped: false, next: 0, turns: [], status: "idle", asks: [], live: [], agent: "claude",
        protocol: "claude-stream", models: [], modes: [], commands: [], version: "2.1.273",
      });
      window.__ANSWER__.wire_stop = (args) => { calls.push(["stop", args]); return null; };
      const term = await openTermTab({ placement: "tab" });
      await window.__PAINTED__();
      const paneTab = tabOfTerm(term);
      const at = tabs.indexOf(paneTab);
      tell("hook:agent", { term, state: "working", agent: "claude", session: { key: "session_id", id: "s-hand" }, resumable: true });
      tell("hook:agent", { term, state: "done", agent: "claude", session: { key: "session_id", id: "s-hand" }, resumable: true });
      await window.__PAINTED__();
      el("view-toggle-chat").click();
      seen.handed = await until(() => tabs.some((tab) => tab.worker?.wire === 11));
      await window.__PAINTED__();
      await settle();
      const started = calls.find((call) => call[0] === "start")?.[1];
      seen.startArgs = JSON.stringify(started);
      seen.wantStartArgs = JSON.stringify({ agent: "claude", cwd: paneTab.worktree, resume: "s-hand", from_pane: term });
      const wireTab = tabs.find((tab) => tab.worker?.wire === 11);
      seen.seat = tabs.indexOf(wireTab) === at;
      seen.active = activeTabId === wireTab?.id;
      seen.session = wireTab?.worker.session === "s-hand";
      seen.label = wireTab?.worker.name === tabLabel(paneTab);
      const face = document.querySelector("#worker-view");
      seen.history = face?.querySelectorAll(".helper-turn").length ?? 0;
      seen.toggleShown = el("view-toggle").hidden === false;
      seen.chatPressed = el("view-toggle-chat").getAttribute("aria-pressed") === "true";
      seen.paneChatOff = !paneChatOn(term);
      // The pane's CLI exits (the backend typed its exit command): the pane
      // goes, the wire tab keeps the seat.
      tell("term:exited", { term });
      await settle();
      seen.paneGone = !tabs.some((tab) => tab.id === paneTab.id);
      seen.seatKept = tabs.indexOf(wireTab) === at;
      // 「화면」: the CLI's own screen on the same session, in the seat, and
      // the wire closes.
      window.__LAUNCHED__ = null;
      el("view-toggle-term").click();
      seen.relaunched = await until(() => window.__LAUNCHED__ !== null && !tabs.some((tab) => tab.worker?.wire === 11));
      await settle();
      seen.launchArgs = JSON.stringify({ agent: window.__LAUNCHED__?.agent, resume: window.__LAUNCHED__?.resume, prompt: window.__LAUNCHED__?.prompt });
      seen.wantLaunchArgs = JSON.stringify({ agent: "claude", resume: "s-hand", prompt: "" });
      seen.stopped = JSON.stringify(calls.find((call) => call[0] === "stop")?.[1]) === JSON.stringify({ id: 11 });
      const back = tabs.find((tab) => tab.kind === "term" && tab.agent === agentName("claude"));
      seen.backInSeat = Boolean(back) && tabs.indexOf(back) === at && activeTabId === back.id;
      // Mid-turn: the transcript view stands, and the hand-over waits for the
      // turn's end.
      const busy = await openTermTab({ placement: "tab" });
      await window.__PAINTED__();
      tell("hook:agent", { term: busy, state: "working", agent: "claude", session: { key: "session_id", id: "s-busy" }, resumable: true });
      await window.__PAINTED__();
      const startsBefore = calls.filter((call) => call[0] === "start").length;
      el("view-toggle-chat").click();
      await settle();
      await settle();
      seen.midTurnTranscript = paneChatOn(busy) && calls.filter((call) => call[0] === "start").length === startsBefore;
      seen.midTurnPending = paneChats.get(busy)?.pendingWire === true;
      seen.midTurnNotice = await until(
        () =>
          document.querySelector(`.pane-chat[data-term="${busy}"] .pane-chat-notice[data-says="worker.handoverPending"]`)
            ?.textContent === t("worker.handoverPending", "이 턴이 끝나면 대화가 실시간 세션(선)으로 이어집니다 — 그때부터 답이 낱말 단위로 흐릅니다."),
      );
      tell("hook:agent", { term: busy, state: "done", agent: "claude", session: { key: "session_id", id: "s-busy" }, resumable: true });
      seen.handedAfterTurn = await until(() => calls.filter((call) => call[0] === "start").length === startsBefore + 1);
      seen.afterTurnArgs = JSON.stringify(calls.filter((call) => call[0] === "start").at(-1)?.[1]?.resume);
      // The backend refused the hand-over (the screen kept the conversation;
      // the wire it started was stopped there): the page keeps the transcript
      // view, opens no wire tab, and does not wait on a turn that is over.
      const kept = await openTermTab({ placement: "tab" });
      await window.__PAINTED__();
      tell("hook:agent", { term: kept, state: "done", agent: "claude", session: { key: "session_id", id: "s-kept" }, resumable: true });
      await window.__PAINTED__();
      const startsKept = calls.filter((call) => call[0] === "start").length;
      window.__ANSWER__.wire_start = (args) => {
        calls.push(["start", args]);
        throw new Error("the pane's CLI kept its screen 8s after `/exit` — the conversation stays on the screen");
      };
      el("view-toggle-chat").click();
      await until(() => calls.filter((call) => call[0] === "start").length === startsKept + 1);
      await settle();
      seen.refusedKeepsTranscript = paneChatOn(kept) && !tabs.some((tab) => tab.worker?.session === "s-kept") &&
        paneChats.get(kept)?.pendingWire !== true && tabOfTerm(kept) !== undefined;
      // The refusal stands on the page in the backend's words, and 「대화」
      // pressed again asks the wire again — the transcript view is not a
      // dead end (2026-09-21: a pane that once fell to it never retried).
      seen.refusalSaid = await until(() =>
        (document.querySelector(`.pane-chat[data-term="${kept}"] .pane-chat-notice[data-says="worker.wireRefused"]`)?.textContent ?? "")
          .includes("kept its screen 8s"));
      let nextWire = 12;
      window.__ANSWER__.wire_start = (args) => {
        calls.push(["start", args]);
        return { id: nextWire++, agent: args.agent, protocol: "claude-stream", version: "2.1.273", model: null, session: args.resume ?? null };
      };
      el("view-toggle-chat").click();
      seen.retriedOnPress = await until(() => tabs.some((tab) => tab.worker?.wire === 12));
      seen.retryResumed = calls.filter((call) => call[0] === "start").at(-1)?.[1]?.resume === "s-kept";
      // A conversation opened before the hooks named a session waits as the
      // transcript view and is handed over the moment the session id arrives.
      const early = await openTermTab({ placement: "tab" });
      await window.__PAINTED__();
      tell("hook:agent", { term: early, state: "done", agent: "claude", resumable: false });
      await window.__PAINTED__();
      const startsEarly = calls.filter((call) => call[0] === "start").length;
      el("view-toggle-chat").click();
      await settle();
      seen.earlyTranscript = paneChatOn(early) && calls.filter((call) => call[0] === "start").length === startsEarly;
      tell("hook:agent", { term: early, state: "done", agent: "claude", session: { key: "session_id", id: "s-early" }, resumable: true });
      seen.handedOnSession = await until(() => calls.filter((call) => call[0] === "start").at(-1)?.[1]?.resume === "s-early");
      for (const name of ["pane_log", "wire_start", "wire_log", "wire_stop"]) delete window.__ANSWER__[name];
      for (const held of [...tabs]) dropTab(held.id);
      return seen;
    });
    ok(
      "a Claude Code pane's 「대화」 hands the conversation to its wire — the wire resumes the pane's session from the pane's seat with the turns already said, the toggle shows it as the conversation, the pane's exit leaves the seat to it — and the wire tab's 「화면」 launches the CLI's own screen on the same session in that seat and stops the wire; a pane mid-turn keeps its transcript view and is handed over when the turn ends",
      seen.handed && seen.startArgs === seen.wantStartArgs && seen.seat && seen.active && seen.session && seen.label &&
        seen.history === 2 && seen.toggleShown && seen.chatPressed && seen.paneChatOff && seen.paneGone && seen.seatKept &&
        seen.relaunched && seen.launchArgs === seen.wantLaunchArgs && seen.stopped && seen.backInSeat &&
        seen.midTurnTranscript && seen.midTurnPending && seen.midTurnNotice && seen.handedAfterTurn &&
        seen.afterTurnArgs === JSON.stringify("s-busy") && seen.refusedKeepsTranscript &&
        seen.refusalSaid && seen.retriedOnPress && seen.retryResumed && seen.earlyTranscript && seen.handedOnSession,
      JSON.stringify(seen),
    );
  } finally {
    await page.close();
  }
});

/* The plan card (the extension's "Claude's Plan", 2.1.268-275) and the agents
 * pill (2.1.269). A permission whose tool is the CLI's own plan tool is not
 * an ordinary approval: the plan itself stands on the card as prose, the two
 * answers are approve and send-feedback, and the refusal carries the words
 * the person typed. On a pane the composer is that third road, as it already
 * is for every other permission. */
suite("plan-card", async ({ browser, origin, ok }) => {
  const { page } = await openWindowTestPage(browser, origin);
  try {
    const seen = await page.evaluate(async () => {
      const tell = (name, payload) => {
        for (const handler of window.__LISTENERS__[name] ?? []) handler({ payload });
      };
      const settle = (ms = 60) => new Promise((done) => setTimeout(done, ms));
      const seen = {};
      const calls = [];
      const plan = "## 계획\n\n1. `ask.rs`를 읽는다\n2. 카드를 세운다";
      // ---- the wire: the plan rides the ask, the refusal rides the words.
      const log = {
        found: true, skipped: false, next: 1, status: "asking", agent: "claude",
        protocol: "claude-stream", model: null, models: [], mode: null, modes: [], commands: [],
        version: "2.1.278", live: [],
        turns: [{ role: "user", text: "계획을 세워줘" }],
        asks: [{
          id: "cd1", kind: "approval", method: "can_use_tool", tool: "ExitPlanMode",
          plan, options: [
            { id: "allow", kind: "allow_once" },
            { id: "allow_always", kind: "allow_always" },
            { id: "deny", kind: "reject_once" },
          ],
        }],
      };
      window.__ANSWER__.wire_start = (args) => ({ id: 31, agent: args.agent, protocol: "claude-stream", version: "2.1.278", model: null, session: null });
      window.__ANSWER__.wire_log = (args) => ({ ...log, turns: log.turns.slice(args.after), next: log.turns.length });
      window.__ANSWER__.wire_answer = (args) => { calls.push(["answer", args]); return null; };
      window.__ANSWER__.wire_stop = () => null;
      await openWirePage("claude", "/tmp/zerocode-window-test");
      await pollHelperPages();
      await window.__PAINTED__();
      await settle();
      const face = document.querySelector("#worker-view");
      const card = face?.querySelector(".pane-chat-ask");
      seen.cardShown = Boolean(card);
      seen.title = card?.querySelector(".board-approve-title")?.textContent ?? null;
      seen.wantTitle = t("board.approve.planTitle", "계획을 승인할까요?");
      // The plan is the answer's own prose: a heading is a heading, a list a list.
      const well = card?.querySelector(".board-approve-plan");
      seen.planHeading = well?.querySelector("h2")?.textContent ?? null;
      seen.planSteps = well?.querySelectorAll("li").length ?? 0;
      seen.planChip = Boolean(well?.querySelector("code"));
      seen.planScrolls = well ? getComputedStyle(well).overflowY === "auto" && getComputedStyle(well).maxHeight !== "none" : false;
      // The plan wears the conversation's prose measures, not the card's
      // small print — every length a token.
      const probe = (name, property) => {
        const span = document.createElement("span");
        span.style[property] = `var(${name})`;
        document.body.appendChild(span);
        const value = getComputedStyle(span)[property];
        span.remove();
        return value;
      };
      seen.planProse = well
        ? getComputedStyle(well).fontSize === probe("--chat-prose-size", "fontSize") &&
          getComputedStyle(well).whiteSpace === "normal"
        : false;
      // No summary line beside it — the plan IS what this asks about.
      seen.noSummary = card?.querySelector(".board-approve-detail") === null;
      seen.acts = [...(card?.querySelectorAll(".board-approve-act") ?? [])].map((act) => act.textContent);
      seen.wantActs = [t("board.approve.planAllow", "승인하고 진행"), t("board.approve.planFeedback", "피드백 보내기")];
      const field = card?.querySelector(".board-approve-feedback");
      seen.fieldHint = field?.placeholder ?? null;
      seen.wantFieldHint = t("board.approve.feedbackHint", "계획에서 고칠 점을 적어 주세요");
      if (field) field.value = "2번은 빼 주세요";
      card?.querySelectorAll(".board-approve-act")[1]?.click();
      await settle();
      seen.refused = JSON.stringify(calls.at(-1));
      seen.wantRefused = JSON.stringify(["answer", { id: 31, ask: "cd1", option: "deny", message: "2번은 빼 주세요" }]);
      for (const name of ["wire_start", "wire_log", "wire_answer", "wire_stop"]) delete window.__ANSWER__[name];
      for (const held of [...tabs]) dropTab(held.id);
      // ---- the pane: the same card, answered down the pane's own road.
      window.__ANSWER__.pane_log = () => ({ found: true, next: 1, skipped: false, turns: [{ role: "user", text: "계획을 세워줘" }] });
      const term = await openTermTab({ placement: "tab" });
      tell("hook:agent", { term, state: "working", agent: "claude", session: "s-plan", resumable: false });
      await window.__PAINTED__();
      el("view-toggle-chat").click();
      await settle(150);
      const chat = document.querySelector(`.pane-slot[data-term="${term}"] .pane-chat`);
      tell("hook:agent", { term, state: "awaiting-permission", agent: "claude", session: "s-plan", resumable: false,
        approval: { tool: "ExitPlanMode", summary: `{"plan":"…"}`, plan } });
      await window.__PAINTED__();
      const paneCard = chat?.querySelector(".pane-chat-ask");
      seen.paneTitle = paneCard?.querySelector(".board-approve-title")?.textContent ?? null;
      seen.panePlan = paneCard?.querySelector(".board-approve-plan h2")?.textContent ?? null;
      seen.paneNoField = paneCard?.querySelector(".board-approve-feedback") === null;
      seen.paneActs = [...(paneCard?.querySelectorAll(".board-approve-act") ?? [])]
        .map((act) => act.className.replace("board-approve-act ", "")).join(",");
      window.__APPROVED__ = null;
      paneCard?.querySelector(".board-approve-act.is-instead")?.click();
      await settle();
      seen.paneInstead = JSON.stringify(window.__APPROVED__) === JSON.stringify({ term, allow: false });
      seen.paneInsteadFocus = document.activeElement?.classList.contains("worker-composer-box") === true;
      // An ordinary permission is untouched by any of this.
      tell("hook:agent", { term, state: "working", agent: "claude", session: "s-plan", resumable: false });
      await window.__PAINTED__();
      tell("hook:agent", { term, state: "awaiting-permission", agent: "claude", session: "s-plan", resumable: false,
        approval: { tool: "Bash", summary: "rm -rf build" } });
      await window.__PAINTED__();
      const plainCard = chat?.querySelector(".pane-chat-ask");
      seen.plainTitle = plainCard?.querySelector(".board-approve-title")?.textContent ?? null;
      seen.wantPlainTitle = t("board.approve.title", "{{tool}} 허용할까요?", { tool: "Bash" });
      seen.plainNoPlan = plainCard?.querySelector(".board-approve-plan") === null;
      seen.plainSummary = plainCard?.querySelector(".board-approve-detail")?.textContent ?? null;
      // ---- the agents pill: the roster's count, its list, its failure ink.
      const composer = chat?.querySelector(".worker-composer");
      const pill = composer?.querySelector(".worker-composer-agents");
      seen.pillHiddenAtRest = pill?.hidden === true;
      tell("hook:subagent", { term, rows: [
        { id: "one", name: "@reader", state: "running" },
        { id: "two", name: "@writer", state: "failed" },
      ] });
      await settle();
      seen.pillWords = pill?.querySelector(".worker-composer-pill-words")?.textContent ?? null;
      seen.wantPillWords = t("composer.agents", "에이전트 {{n}}", { n: 2 });
      seen.pillShown = pill?.hidden === false;
      seen.pillFailed = pill?.classList.contains("is-failed") === true;
      seen.pillTip = pill?.dataset.tip === t("composer.agentsTip", "하위 에이전트 보기") &&
        pill?.getAttribute("aria-label") === t("composer.agentsTip", "하위 에이전트 보기");
      pill?.click();
      await settle();
      const menu = composer?.querySelector(".composer-menu");
      seen.menuRows = [...(menu?.querySelectorAll(".composer-menu-item") ?? [])]
        .map((row) => `${row.querySelector(".composer-menu-name")?.textContent} · ${row.querySelector(".composer-menu-sub")?.textContent}`);
      seen.wantMenuRows = [
        `@reader · ${t("board.working", "작업 중")}`,
        `@writer · ${t("worker.endedFailed", "실패")}`,
      ];
      let askedLog = null;
      window.__ANSWER__.subagent_log = (args) => {
        askedLog = args;
        return { found: true, next: 1, skipped: false, turns: [{ role: "user", text: "read it" }] };
      };
      menu?.querySelector(".composer-menu-item")?.click();
      await settle(150);
      seen.openedHelper = askedLog?.id ?? null;
      seen.helperTabStands = tabs.some((tab) => tab.id === `helper:${term}:one`) && activeTabId === `helper:${term}:one`;
      // The last helper stopping empties the pill, as the roster empties.
      tell("hook:subagent", { term, rows: [] });
      await settle();
      seen.pillGone = pill?.hidden === true;
      delete window.__ANSWER__.pane_log;
      delete window.__ANSWER__.subagent_log;
      tell("term:exited", { term });
      window.__PANES__ = [];
      for (const held of [...tabs]) dropTab(held.id);
      for (const at of [...termViews.keys()]) dropTermView(at);
      return seen;
    });
    ok(
      "a wire's plan permission stands as the plan review card — the plan as prose in a well of its own, no summary line, approve and send-feedback for answers — and the feedback rides the refusal down the wire",
      seen.cardShown && seen.title === seen.wantTitle &&
        seen.planHeading === "계획" && seen.planSteps === 2 && seen.planChip && seen.planScrolls &&
        seen.planProse &&
        seen.noSummary && JSON.stringify(seen.acts) === JSON.stringify(seen.wantActs) &&
        seen.fieldHint === seen.wantFieldHint && seen.refused === seen.wantRefused,
      JSON.stringify(seen),
    );
    ok(
      "a pane's plan permission wears the same card with the composer as its third road, and an ordinary permission is untouched — its tool in the question, its summary under it, no plan",
      seen.paneTitle === seen.wantTitle && seen.panePlan === "계획" && seen.paneNoField &&
        seen.paneActs === "is-allow,is-instead" && seen.paneInstead && seen.paneInsteadFocus &&
        seen.plainTitle === seen.wantPlainTitle && seen.plainNoPlan && seen.plainSummary === "rm -rf build",
      JSON.stringify(seen),
    );
    ok(
      "the composer's agents pill counts the helpers still out, wears the failure ink when one failed, lists them with the board's own state words, opens a row's transcript — and goes quiet when the roster empties",
      seen.pillHiddenAtRest && seen.pillShown && seen.pillWords === seen.wantPillWords &&
        seen.pillFailed && seen.pillTip &&
        JSON.stringify(seen.menuRows) === JSON.stringify(seen.wantMenuRows) &&
        seen.openedHelper === "one" && seen.helperTabStands && seen.pillGone,
      JSON.stringify(seen),
    );
  } finally {
    await page.close();
  }
});

/* The reveal's pace, measured on the path the person sees (Paseo's two numbers:
 * the coefficient of variation of characters painted per frame is the
 * smoothness, the longest the text sits still mid-stream is the stall). Deltas
 * are delivered in lumps as real models arrive; the page must paint them as a
 * steady front of single words, and hand over to the closed turn only after
 * the reveal has drained. */
suite("wire-live-stream", async ({ browser, origin, ok }) => {
  const { page } = await openWindowTestPage(browser, origin);
  try {
    const seen = await page.evaluate(async () => {
      const settle = (ms = 30) => new Promise((done) => setTimeout(done, ms));
      const frame = () => new Promise((done) => requestAnimationFrame(() => done(performance.now())));
      const flat = (text) => text.replace(/\s+/g, " ").trim();
      const seen = {};
      let live = "";
      const log = () => ({
        found: true, skipped: false, next: 1, turns: [{ role: "user", text: "go" }], status: "working", asks: [],
        live: live ? [{ role: "assistant", text: live }] : [], agent: "claude", protocol: "claude-stream",
        models: [], modes: [], commands: [], version: "2.1.278",
      });
      window.__ANSWER__.wire_start = (args) => ({ id: 21, agent: args.agent, protocol: "claude-stream", version: "2.1.278", model: null, session: null });
      window.__ANSWER__.wire_log = (args) => { const held = log(); return { ...held, turns: held.turns.slice(args.after), next: held.turns.length }; };
      window.__ANSWER__.wire_stop = () => null;
      await openWirePage("claude", "/tmp/zerocode-window-test");
      await pollHelperPages();
      await window.__PAINTED__();
      const face = document.querySelector("#worker-view");
      const streaming = () => face.querySelector('.is-streaming[data-role="assistant"]');
      const words = ("the quick brown fox jumps over the lazy dog while every delta that lands is on the page by the " +
        "next frame the way the terminal and the extension both draw it").split(" ");
      const bursts = [3, 9, 1, 12, 2, 7, 5];
      // Each burst is the wire's news; the page must show all of it by the
      // frame after the poll that brought it — never a word held back.
      const lags = [];
      let taken = 0;
      for (const count of bursts) {
        const chunk = `${words.slice(taken, taken + count).join(" ")} `;
        taken += count;
        live += chunk;
        await pollHelperPages();
        let frames = 0;
        while (flat(streaming()?.textContent ?? "") !== flat(live) && frames < 6) {
          await frame();
          frames += 1;
        }
        lags.push(frames);
        await settle();
      }
      seen.lags = lags;
      seen.everyBurstWithinAFrame = lags.every((frames) => frames <= 1);
      seen.shownWhole = flat(streaming()?.textContent ?? "") === flat(live);
      seen.noFade = face.querySelectorAll(".is-streaming .helper-word").length === 0;
      seen.onRail = streaming()?.classList.contains("is-step") === true;
      // The closed block and the open one are both the answer's own markdown.
      live += "\n\n**bold** tail";
      await pollHelperPages();
      await frame();
      seen.settledIsMarkdown = streaming()?.querySelector(".helper-said-settled p") !== null;
      seen.tailIsMarkdown = streaming()?.querySelector(".helper-said-tail strong")?.textContent === "bold";
      // The close: the turn's row stands and the streaming row goes in one
      // paint — never both, never a hidden row waiting on a reveal.
      const closed = { ...log(), status: "idle", live: [], turns: [{ role: "user", text: "go" }, { role: "assistant", text: live.trim() }] };
      window.__ANSWER__.wire_log = (args) => ({ ...closed, turns: closed.turns.slice(args.after), next: closed.turns.length });
      await pollHelperPages();
      const committed = [...face.querySelectorAll(".helper-turn.is-assistant:not(.is-streaming)")].at(-1) ?? null;
      seen.swappedInOnePaint = committed !== null && committed.hidden === false && streaming() === null;
      seen.committedWhole = committed?.textContent.includes("bold") === true && flat(committed?.textContent ?? "").startsWith("the quick brown");
      seen.saidOnce = face.querySelector(".helper-turns").innerText.split("the quick brown").length - 1 === 1;
      for (const name of ["wire_start", "wire_log", "wire_stop"]) delete window.__ANSWER__[name];
      for (const held of [...tabs]) dropTab(held.id);
      return seen;
    });
    ok(
      "a streaming answer is on screen by the frame after its delta arrives — every burst within one frame, whole, nothing held back and nothing faded in, on the rail, the closed blocks and the open one both drawn as markdown, and when the answer closes the turn's row replaces the streaming row in one paint with the words shown once",
      seen.everyBurstWithinAFrame && seen.shownWhole && seen.noFade && seen.onRail &&
        seen.settledIsMarkdown && seen.tailIsMarkdown &&
        seen.swappedInOnePaint && seen.committedWhole && seen.saidOnce,
      JSON.stringify(seen),
    );
  } finally {
    await page.close();
  }
});

await run({ browser, origin, faults });
await browser.close();
files.close();
process.exit(report() ? 1 : 0);
